/* إجابات المساعد الذكي المحددة مسبقا: اختبر نفسك (FXQ) وأزرار السبورة (FXB) */
window.FXQ={"0-1":[{"h":["السرعة مشتقة لأنها تحسب من طول مقسوم على زمن.","المساحة مشتقة لأنها طول مضروب في طول.",null,"القوة مشتقة لأنها تحسب من قانون نيوتن `F = m·a`."],"g":"ابحث عن الكمية التي لا تحتاج قانونا لتعريفها، فهي معرفة بذاتها ولا تشتق من غيرها."},{"h":["الدرجة المئوية شائعة في الحياة اليومية لكنها ليست الوحدة الأساسية في SI.",null,"الفهرنهايت وحدة تستخدم في بعض الدول وليست من وحدات SI.","الجول وحدة الشغل والطاقة لا درجة الحرارة."],"g":"راجع جدول الكميات الأساسية السبع في SI وابحث عن وحدة درجة الحرارة فيه."},{"h":["هذه وحدة السرعة، والتسارع تغير السرعة في كل ثانية.",null,"هذه الوحدة لا تمثل التسارع، فالمتر فيها مربع والثانية غير مربعة.","النيوتن وحدة القوة لا التسارع."],"g":"التسارع = تغير السرعة ÷ الزمن، فاقسم وحدة السرعة على وحدة الزمن."},{"h":["هذه وحدة القوة (النيوتن)، والجول قوة مضروبة في مسافة.",null,"هذه وحدة الكثافة لا الطاقة.","هذه وحدة السرعة لا الشغل."],"g":"الشغل = القوة × المسافة، فاضرب وحدة النيوتن في وحدة المتر."},{"h":["الكثافة ليست ضمن الكميات الأساسية السبع، فهي تحسب من الكتلة والحجم.",null,"الكثافة تقاس بعدد ووحدة، فهي كمية فيزيائية.","الكثافة تعرف بقانون في كل الأنظمة، وليست أساسية في أي منها."],"g":"اكتب قانون الكثافة `ρ = m / V`، وانظر هل تحتاج كميات أخرى لتعريفها."},{"h":["العدد أكبر من ذلك؛ عد الطول والكتلة والزمن ثم أكمل بالتيار ودرجة الحرارة وغيرها.","ما زال العدد ناقصا؛ لا تنس كمية المادة وشدة الإضاءة.",null,"هذا عدد كبير؛ يبدو أنك عددت معها كميات مشتقة مثل السرعة والقوة."],"g":"عد صفوف جدول الكميات الأساسية في SI، وتذكر أن لكل كمية منها وحدة خاصة مثل `m` و `kg` و `s`."},{"h":["الفولت وحدة الجهد الكهربائي.",null,"الأوم وحدة المقاومة الكهربائية.","الكولوم وحدة الشحنة الكهربائية، وهي وحدة مشتقة."],"g":"شدة التيار من الكميات الأساسية السبع، فابحث عن وحدتها في جدول الكميات الأساسية في SI."},{"h":["الكتلة كمية أساسية لا مشتقة.","الزمن كمية أساسية لا مشتقة.",null,"شدة التيار من الكميات الأساسية السبع لا من المشتقة."],"g":"الكمية المشتقة تعرف بقانون من كميات أخرى، فابحث عن الكمية التي ليست في جدول الكميات الأساسية السبع."},{"h":["هذه وحدة كمية التحرك، وينقصها القسمة على الثانية مرة أخرى.",null,"هذه وحدة الجول، أي قوة مضروبة في متر.","هذه وحدة الضغط، أي قوة مقسومة على مساحة."],"g":"عوض في `F = m·a`: وحدة الكتلة `kg` مضروبة في وحدة التسارع."},{"h":["الكيلوجرام وحدة الكتلة لا كمية المادة.","الكلفن وحدة درجة الحرارة.","الشمعة وحدة شدة الإضاءة.",null],"g":"كمية المادة من الكميات الأساسية السبع، ووحدتها تستخدم كثيرا في الكيمياء لعد الجسيمات."},{"h":[null,"هذا رمز اللكس، وهو وحدة مشتقة وليس من الوحدات الأساسية السبع.","هذا رمز اللومن، وهو وحدة مشتقة وليس من الوحدات الأساسية السبع.","هذا رمز الواط، وهو وحدة القدرة."],"g":"وحدة شدة الإضاءة الأساسية هي الشمعة (الكانديلا)، فابحث عن رمزها المختصر في جدول الكميات الأساسية."},{"h":["اللون صفة أو ظاهرة لا تقاس بعدد ووحدة مباشرة.","الحركة ظاهرة، أما ما يصفها مثل السرعة فهو كمية فيزيائية.",null,"الصوت ظاهرة، أما شدته أو تردده فكميات فيزيائية."],"g":"الكمية الفيزيائية تقاس بعدد ووحدة، فاسأل نفسك: أي اختيار يمكن أن تقيسه بأداة وتكتب له عددا ووحدة؟"},{"h":["إذا لم يمكن قياسها فليست كمية فيزيائية، فالقياس شرط أساسي.",null,"الوحدة جزء من القياس فقط، والكمية نفسها هي ما يقاس.","العدد بلا وحدة لا يكفي، فكل قياس عدد ووحدة."],"g":"ركز على كلمة «قياس»: الكمية الفيزيائية شيء يمكن أن تعبر عنه بعدد ووحدة."},{"h":["النظام البريطاني يستخدم في بعض الدول لكنه ليس المعتمد عالميا في العلوم.","النظام الجاوسي نظام قديم يعتمد السنتيمتر والجرام، ولم يعد هو المعتمد.",null,"يوجد نظام موحد اتفقت عليه الدول للقياسات العلمية."],"g":"تذكر النظام الذي اعتمدت فيه الحقيبة التدريبية المتر والكيلوجرام والثانية وحدات أساسية."}],"0-2":[{"h":["يبدو أنك قسمت على 10 بدلا من 100.",null,"يبدو أنك قسمت على 1000 بدلا من 100.","يبدو أنك ضربت في 10، والتحويل إلى وحدة أكبر يكون بالقسمة."],"g":"المتر أكبر من السنتيمتر، فاقسم على عدد السنتيمترات في المتر الواحد."},{"h":[null,"يبدو أنك ضربت في 4 بدلا من 3.6.","يبدو أنك قسمت على 3.6، والتحويل من m/s إلى km/h يكون بالضرب.","يبدو أنك ضربت في 10، والمعامل الصحيح 3.6."],"g":"من m/s إلى km/h اضرب في 3.6."},{"h":["يبدو أنك ضربت في 10 بدلا من 1000.","يبدو أنك ضربت في 100 بدلا من 1000.",null,"يبدو أنك قسمت على 1000، والتحويل إلى وحدة أصغر يكون بالضرب."],"g":"الكيلوجرام ألف جرام، ومن الوحدة الكبيرة إلى الصغيرة نضرب."},{"h":["الضرب في 100 يكون من المتر إلى السنتيمتر، أي في الاتجاه المعاكس.",null,"العدد 1000 معامل البادئة كيلو، والسنتيمتر جزء من مئة من المتر.","الضرب في 0.1 يناسب وحدتين بينهما عشرة أضعاف فقط، لا مئة."],"g":"السنتيمتر جزء من مئة من المتر، والقسمة على 100 تساوي الضرب في مقلوبها."},{"h":["وحدة الطرف الأيمن `(m/s) ÷ s = m/s²`، وهي وحدة تسارع لا مسافة.",null,"وحدة الطرف الأيمن `(m/s) × s² = m·s`، وليست وحدة مسافة.","وحدة الطرف الأيمن `s ÷ (m/s) = s²/m`، وليست وحدة مسافة."],"g":"عوض وحدات `v` و `t` في كل اختيار، واختر ما يعطي وحدة المسافة `m`."},{"h":[null,"يبدو أنك ضربت في 3.6، والتحويل من km/h إلى m/s يكون بالقسمة.","يبدو أنك قسمت على 10 بدلا من 3.6.","يبدو أنك قسمت على 6 بدلا من 3.6."],"g":"من km/h إلى m/s اقسم على 3.6."},{"h":["يبدو أنك ضربت في 10 بدلا من 1000.","يبدو أنك ضربت في 100 بدلا من 1000.",null,"يبدو أنك قسمت على 1000، والتحويل من الكيلومتر إلى المتر يكون بالضرب."],"g":"الكيلومتر ألف متر، فاضرب في معامل التحويل."},{"h":["يبدو أنك ضربت في 3.6 بدلا من القسمة عليه.",null,"يبدو أنك قسمت على 10 بدلا من 3.6.","يبدو أنك قسمت على 100 بدلا من 3.6."],"g":"حول km إلى m بالضرب في 1000، و h إلى s بالقسمة على 3600، أو اقسم مباشرة على 3.6."},{"h":["يبدو أنك قسمت على 60، والتحويل من الدقيقة إلى الثانية يكون بالضرب.","يبدو أنك ضربت في 10 بدلا من 60.","يبدو أنك ضربت في 100 بدلا من 60.",null],"g":"في الدقيقة الواحدة `60 s`، فاضرب عدد الدقائق في 60."},{"h":[null,"هذه وحدة كمية التحرك؛ النيوتن فيه قسمة على مربع الثانية، ثم تضربه في متر.","هذه وحدة الكثافة، ولا علاقة لها بضرب قوة في مسافة.","هذه وحدة النيوتن وحده، ونسيت ضربه في المتر."],"g":"اكتب `N = kg·m/s²` ثم اضربه في `m`، وانظر أي وحدة تنتج."},{"h":["وحدة `a·t` هي `(m/s²) × s = m/s`، وهي وحدة السرعة، فهذا القانون صحيح.","وحدة `v·t` هي `(m/s) × s = m`، وهي وحدة المسافة، فهذا القانون صحيح.","وحدة الطرفين `m²/s²`، فهذا القانون صحيح.",null],"g":"عوض الوحدات في كل قانون، والقانون غير الصحيح هو الذي تختلف فيه وحدتا الطرفين."}],"0-3":[{"h":[null,"عوض الوحدات: الطرف الأيمن `m·s` والطرف الأيسر `m/s`، فلا يتساويان.","الجمع بين مسافة وزمن غير مقبول، فلا يمكن جمع `m` مع `s`.","`m·s` لا تساوي `m/s`، فالضرب غير القسمة."],"g":"عوض وحدة كل رمز في الطرفين وقارن، ثم فكر في العلاقة الصحيحة بين المسافة والزمن والسرعة."},{"h":["هذه وحدة الطول.","هذه وحدة المساحة، والحجم يحتاج بعدا ثالثا.",null,"اللتر وحدة حجم شائعة لكنه ليس الوحدة الدولية للحجم."],"g":"الحجم = طول × عرض × ارتفاع، فاضرب وحدة الطول في نفسها ثلاث مرات."},{"h":["يبدو أنك ضربت في 10 بدلا من 100.",null,"يبدو أنك ضربت في 1000 بدلا من 100.","يبدو أنك قسمت على 100، والتحويل إلى وحدة أصغر يكون بالضرب."],"g":"المتر فيه `100 cm`، ومن الوحدة الكبيرة إلى الصغيرة نضرب."},{"h":[null,"يبدو أنك قسمت على 10 بدلا من 3.6.","يبدو أنك ضربت في 3.6، ومن km/h إلى m/s نقسم.","يبدو أنك قسمت على 0.36 بدلا من 3.6."],"g":"من km/h إلى m/s اقسم على 3.6."},{"h":["يبدو أنك قسمت على 10 بدلا من 100.",null,"يبدو أنك قسمت على 1000 بدلا من 100.","يبدو أنك ضربت في 10، ومن السنتيمتر إلى المتر نقسم."],"g":"المتر أكبر من السنتيمتر بمئة مرة، فاقسم على 100."},{"h":["هذه وحدة كمية التحرك، والتسارع فيه مربع الثانية.",null,"هذه وحدة الجول، أي قوة مضروبة في متر.","هذه وحدة الكثافة."],"g":"استخدم `F = m·a`: اضرب وحدة الكتلة في وحدة التسارع."},{"h":["يبدو أنك ضربت في 10 بدلا من 1000.","يبدو أنك ضربت في 100 بدلا من 1000.",null,"يبدو أنك قسمت على 1000، ومن الكيلوجرام إلى الجرام نضرب."],"g":"الكيلوجرام ألف جرام، فاضرب في 1000."},{"h":[null,"يبدو أنك قسمت على 3.6، ومن m/s إلى km/h نضرب.","يبدو أنك ضربت في 1000 فقط ونسيت القسمة على 3600.","يبدو أنك ضربت في 10 بدلا من 3.6."],"g":"من m/s إلى km/h اضرب في 3.6."},{"h":["الحجم وحدته متر مكعب لأن له ثلاثة أبعاد.",null,"التسارع وحدته متر لكل ثانية تربيع، وليس فيها متر مربع.","السرعة وحدتها متر لكل ثانية."],"g":"الأس 2 على المتر يعني طولا مضروبا في طول، فما الكمية التي تحسب هكذا؟"},{"h":["الجهد الكهربائي وحدته الفولت.","المقاومة الكهربائية وحدتها الأوم.","القدرة الكهربائية وحدتها الواط.",null],"g":"الأمبير من الوحدات الأساسية السبع في SI، فتذكر الكمية الكهربائية الوحيدة بين الكميات الأساسية."}],"0-4":[{"h":["الكتلة تتحدد بالمقدار والوحدة فقط، فهي قياسية.","الزمن ليس له اتجاه، فهو قياسي.",null,"درجة الحرارة لا اتجاه لها، فهي قياسية."],"g":"ابحث عن الكمية التي لا يكتمل وصفها إلا إذا ذكرت اتجاهها."},{"h":["هذا مجموع المتجهين، وهو يصح فقط إذا كانا في الاتجاه نفسه.","هذا فرق المتجهين، وهو يصح فقط إذا كانا متعاكسين.",null,"يبدو أنك ضربت المتجهين، والمحصلة لا تحسب بالضرب."],"g":"عند الزاوية `90°` يكون `cos θ = 0`، فاستخدم `C = √(A² + B²)`."},{"h":["هذا مجموعهما، ويصح إذا كانا في الاتجاه نفسه لا متعاكسين.",null,"يبدو أنك قسمت المتجهين، والمحصلة لا تحسب بالقسمة.","يبدو أنك ضربت المتجهين، والمحصلة لا تحسب بالضرب."],"g":"عند التعاكس `θ = 180°` تكون المحصلة `|A − B|`، أي اطرح الأصغر من الأكبر."},{"h":[null,"الإشارة السالبة تستخدم في وضع رأس عند ذيل مع الزاوية الداخلية للمثلث.","الحد `2AB·cos θ` موجود دائما في القانون، ولا يصير صفرا إلا عند التعامد.","الإشارة لا علاقة لها بالوحدة، بل بطريقة رسم المتجهين."],"g":"في وضع ذيل على ذيل نستخدم الزاوية بين المتجهين نفسها، وقيمة `cos θ` هي التي تتغير إشارتها وحدها."},{"h":["هذه أقل محصلة ممكنة، عندما يتعاكس المتجهان.","هذه المحصلة عند التعامد تقريبا، وليست أكبر قيمة.",null,"يبدو أنك ضربت المتجهين، والمحصلة لا تحسب بالضرب."],"g":"أكبر محصلة عندما يكون المتجهان في الاتجاه نفسه `θ = 0°`، فاجمعهما."},{"h":["هذا مجموع المتجهين، ويصح فقط إذا كانا في الاتجاه نفسه.","هذا فرق المتجهين، ويصح فقط إذا كانا متعاكسين.",null,"يبدو أنك ضربت المتجهين، والمحصلة لا تحسب بالضرب."],"g":"المتجهان متعامدان، فاستخدم `C = √(A² + B²)`."},{"h":["هذه أكبر محصلة، عندما يكون المتجهان في الاتجاه نفسه.",null,"يبدو أنك ضربت المتجهين، والمحصلة لا تحسب بالضرب.","المحصلة صفر فقط إذا تساوى المتجهان وتعاكسا، وهما هنا غير متساويين."],"g":"أقل محصلة عند التعاكس `θ = 180°`، فاطرح الأصغر من الأكبر."},{"h":["الإزاحة لها اتجاه، فهي متجهة.","القوة لها اتجاه، فهي متجهة.",null,"التسارع له اتجاه، فهو متجه."],"g":"الكمية القياسية يكفيها مقدار ووحدة، فابحث عن الكمية التي لا معنى لاتجاهها."},{"h":[null,"يبدو أنك اعتبرت `cos 120°` موجبا، وهو سالب لأن الزاوية منفرجة.","هذا مجموع المتجهين، ويصح فقط إذا كانت الزاوية بينهما صفرا.","هذا فرق المتجهين، ويصح فقط إذا كانت الزاوية بينهما `180°`."],"g":"استخدم `C² = A² + B² + 2AB·cos θ` مع `cos 120° = −0.5`، ثم خذ الجذر التربيعي."},{"h":["يبدو أنك استخدمت الإشارة الموجبة، وفي وضع رأس عند ذيل تكون الإشارة سالبة.",null,"هذا مجموع المربعين فقط، ونسيت الحد الثالث.","هذا مربع مجموع المتجهين، ويصح فقط إذا كانا في الاتجاه نفسه."],"g":"في وضع رأس عند ذيل استخدم `C² = A² + B² − 2AB·cos θ` مع `cos 60° = 0.5`."},{"h":["الكتلة كمية قياسية بنفسها، وليست ما يضاف لوصف المتجه.","الزمن كمية قياسية، وليس ما يميز المتجه.","درجة الحرارة كمية قياسية، وليست جزءا من وصف المتجه.",null],"g":"فكر في السهم الذي يمثل المتجه: طوله يمثل المقدار، فماذا يمثل رأسه؟"}],"0-5":[{"h":["هذه المركبة الصادية، فالجيب يعطي الضلع المقابل للزاوية.",null,"الظل نسبة بين المركبتين وليس مركبة، فلا يعطي طولا على المحور.","القسمة على جيب التمام تعطي قيمة أكبر من المتجه نفسه، والمركبة لا تزيد على مقدار المتجه."],"g":"المركبة السينية هي الضلع المجاور للزاوية في المثلث القائم، فاختر الدالة المثلثية التي تربط المجاور بالوتر."},{"h":[null,"يبدو أنك استخدمت `sin 60°` بدل `cos 60°`، فحسبت المركبة الصادية.","هذا مقدار المتجه نفسه، والمركبة أصغر منه عند هذه الزاوية.","هذه قيمة `cos 60°` وحدها، ونسيت ضربها في مقدار المتجه."],"g":"استخدم `Ax = A·cos θ` وعوض بقيمة `cos 60°` من جدول القيم المهمة."},{"h":["هذه المركبة السينية، فقد استخدمت `cos 60°` بدل `sin 60°`.",null,"يبدو أنك أخطأت في الضرب، فأعد حساب حاصل ضرب 4 في `0.866`.","هذه قيمة `sin 60°` وحدها، ونسيت ضربها في مقدار المتجه."],"g":"المركبة الصادية تحسب من `Ay = A·sin θ`، و `sin 60° ≈ 0.866`."},{"h":["جمعت المركبتين مباشرة، لكنهما متعامدتان فلا تجمعان جمعا عاديا.","طرحت المركبتين، والمقدار يحسب من الجذر لا من الفرق.",null,"ضربت المركبتين، والصواب جمع مربعيهما ثم أخذ الجذر."],"g":"استخدم فيثاغورس `A = √(Ax² + Ay²)`: اجمع مربعي المركبتين ثم خذ الجذر التربيعي."},{"h":["هذا مقدار المتجه كله، ويكون كذلك فقط إذا كان المتجه على المحور السيني نفسه.",null,"هذا نصف المقدار، وجيب تمام الزاوية القائمة لا يساوي النصف.","يبدو أنك استخدمت قيمة جيب الزاوية القائمة بدل جيب تمامها، والمطلوب مركبة لا قيمة دالة."],"g":"المتجه الذي يصنع زاوية قائمة مع المحور السيني يقع على المحور الصادي تماما، ففكر: كم يمتد على المحور السيني؟"},{"h":["عند `30°` تكون المركبة الصادية أصغر من السينية، وهنا المركبتان متساويتان.",null,"عند `60°` تكون المركبة الصادية أكبر من السينية، وهنا المركبتان متساويتان.","عند `90°` تنعدم المركبة السينية، وهنا المركبة السينية تساوي 3."],"g":"احسب `tan θ = Ay / Ax`، ثم ابحث عن الزاوية التي يتساوى عندها الجيب وجيب التمام."},{"h":["هذا مقدار المتجه نفسه، والمركبة أصغر منه عند أي زاوية بين المحورين.","قسمت المقدار على 2، وهذا يصح لو كان جيب التمام `0.5` أي عند `60°`.",null,"يبدو أنك قسمت على `0.707` بدل الضرب فيه، فخرجت النتيجة أكبر من المتجه."],"g":"استخدم `Ax = A·cos θ` مع `cos 45° ≈ 0.707`."},{"h":[null,"هذه المركبة السينية، فقد ضربت في `cos 30°` بدل `sin 30°`.","هذا مقدار المتجه كله، والمركبة الصادية جزء منه فقط.","يبدو أنك استخدمت `tan 30°` بدل `sin 30°`."],"g":"المركبة الصادية تحسب من `Ay = A·sin θ`، وتذكر أن `sin 30° = 0.5`."},{"h":["المركبة الصادية صفر، فلا يمكن أن يتجه المتجه على المحور الصادي.",null,"إشارة المركبة السينية سالبة، والاتجاه الموجب يحتاج إشارة موجبة.","المركبة الصادية صفر، فالمتجه لا يميل نحو المحور الصادي أصلا."],"g":"انظر إلى المركبة غير الصفرية وإشارتها، فهي وحدها تحدد اتجاه المتجه."},{"h":["في الربع الأول تكون المركبتان موجبتين، وهنا المركبة السينية سالبة.","في الربع الرابع تكون المركبة الصادية سالبة، وهنا هي موجبة.","في الربع الثالث تكون المركبتان سالبتين، وهنا المركبة الصادية موجبة.",null],"g":"ارسم المحورين وحدد الجهة: x سالب يعني اليسار، و y موجب يعني الأعلى."}],"0-6":[{"h":["الناتج المتجه يأتي من الضرب الاتجاهي `A × B`، لا من الضرب القياسي.",null,"متجه الوحدة له اتجاه، أما ناتج `A·B` فعدد بلا اتجاه.","يكون صفرا فقط عندما يتعامد المتجهان، لا دائما."],"g":"انظر إلى القانون `A·B = |A||B|·cos θ`: هل في طرفه الأيمن أي اتجاه؟"},{"h":["الناتج 1 يخص الضرب القياسي لمتجه وحدة في نفسه، وهذا ضرب اتجاهي.","الضرب الاتجاهي يكون صفرا لمتجهين متوازيين، و `î` و `ĵ` متعامدان.",null,"الإشارة السالبة تظهر عند عكس الترتيب، وهنا الترتيب دوري صحيح."],"g":"ناتج الضرب الاتجاهي لمتجهي وحدة متعامدين هو متجه الوحدة الثالث، فاتبع الترتيب الدوري x ثم y ثم z."},{"h":["الصفر يكون للضرب القياسي بين متجهين متعامدين، و `î` يوازي نفسه.",null,"الضرب القياسي ناتجه عدد لا متجه، فلا يمكن أن يكون `î`.","هذا متجه، وناتج الضرب القياسي عدد، كما أن `k̂` يأتي من ضرب اتجاهي."],"g":"عوض في `A·B = |A||B|·cos θ`: مقدار متجه الوحدة واحد، والزاوية بينه وبين نفسه صفر."},{"h":["هذا حاصل ضرب المقدارين فقط، ونسيت الضرب في `cos 60°`.","استخدمت `sin 60°` فحسبت مقدار الضرب الاتجاهي، لا الضرب القياسي.",null,"جمعت المقدارين بدل ضربهما، والقانون فيه ضرب."],"g":"استخدم `A·B = |A||B|·cos θ` مع `cos 60° = 0.5`."},{"h":["جمعت القيمتين `3 + 4` مباشرة، والمقدار يحسب بالجذر.","جمعت المركبتين بإشارتيهما `3 + (−4)`، والمقدار لا يكون سالبا أبدا.",null,"هذا مجموع المربعين قبل أخذ الجذر التربيعي."],"g":"استخدم `|A| = √(Ax² + Ay²)`، والتربيع يلغي الإشارة السالبة."},{"h":["هذا ناتج `î × ĵ` بالترتيب الدوري، وهنا الترتيب معكوس.",null,"الصفر يكون للمتجهين المتوازيين، و `ĵ` و `î` متعامدان.","الضرب الاتجاهي ناتجه متجه لا عدد."],"g":"قارن الترتيب بالترتيب الدوري x ثم y ثم z، وتذكر أن `A × B = −B × A`."},{"h":["المتوازيان زاويتهما صفر، و `cos 0° = 1`، فلا يكون ضربهما القياسي صفرا.",null,"المتجهان المتساويان زاويتهما صفر، فضربهما القياسي يساوي مربع المقدار لا صفرا.","المتعاكسان زاويتهما `180°`، فضربهما القياسي سالب لا صفر."],"g":"اسأل نفسك: عند أي زاوية يكون `cos θ = 0`؟"},{"h":[null,"الإشارة السالبة تظهر عند عكس الترتيب، و `k̂ × î` يتبع الترتيب الدوري الصحيح.","الصفر يكون لمتجهين متوازيين، و `k̂` و `î` متعامدان.","الضرب الاتجاهي ناتجه متجه لا عدد."],"g":"اتبع الترتيب الدوري للمحاور x ثم y ثم z ثم x من جديد: ضرب z في x يعطي متجه وحدة المحور الباقي."},{"h":["المتجه الصفري لا اتجاه له، ومتجه الوحدة وظيفته تحديد اتجاه.",null,"متجه الوحدة لا يحمل مقدار المتجه الأصلي، بل اتجاهه فقط.","كل متجهات الوحدة لها المقدار نفسه مهما كان اتجاهها."],"g":"تذكر معنى كلمة «الوحدة» في اسمه: مقداره ثابت ووظيفته تحديد الاتجاه."},{"h":["يبدو أنك أهملت الإشارة السالبة في `−2ĵ`، فجمعت `6 + 10`.","هذا حاصل ضرب المركبتين السينيتين فقط، ونسيت المركبتين الصاديتين.",null,"هذا حاصل ضرب المركبتين الصاديتين فقط، ونسيت المركبتين السينيتين."],"g":"استخدم `A·B = AxBx + AyBy` وضع العدد السالب بين قوسين."},{"h":["الناتج 1 يخص الضرب القياسي `ĵ·ĵ`، وهذا ضرب اتجاهي.","هذا ناتج `î × ĵ`، أما هنا فالمتجه مضروب في نفسه.","هذا ناتج `ĵ × k̂`، أما هنا فالمتجه مضروب في نفسه.",null],"g":"الزاوية بين المتجه ونفسه منعدمة، فعوض في `|A × B| = |A||B|·sin θ`."}],"0-7":[{"h":["جمعت المقدارين `2 + 3` مباشرة، وهذا يصح فقط إذا كانت الزاوية بينهما صفرا.",null,"هذا ناتج زاوية قائمة `√(4 + 9)`، ونسيت الحد `2AB·cos θ`.","طرحت المقدارين، وهذا يصح فقط إذا كان المتجهان متعاكسين."],"g":"عوض في `C² = A² + B² + 2AB·cos θ` ثم خذ الجذر التربيعي."},{"h":["هذه المركبة الصادية، فقد استخدمت `sin 30°` بدل `cos 30°`.",null,"هذا مقدار المتجه نفسه لا مركبته.","يبدو أنك استخدمت `cos 45°` بدل `cos 30°`."],"g":"استخدم `Ax = A·cos θ` مع `cos 30° ≈ 0.866`."},{"h":[null,"هذا حاصل ضرب المركبتين السينيتين فقط، ونسيت المركبتين الصاديتين.","هذا ناتج الضرب الاتجاهي، لا الضرب القياسي.","هذا حاصل ضرب المركبتين الصاديتين فقط، ونسيت المركبتين السينيتين."],"g":"استخدم `A·B = AxBx + AyBy` وضع المركبة السالبة بين قوسين."},{"h":[null,"يبدو أنك أهملت إشارة السالب في `Bx` فطرحت بدل أن تجمع.","هذا ناتج الضرب القياسي، والمطلوب الضرب الاتجاهي.","الضرب الاتجاهي يكون صفرا فقط للمتجهين المتوازيين، وهذان غير متوازيين."],"g":"بما أن `Az = Bz = 0` يبقى الحد `(AxBy − AyBx) k̂` فقط، فانتبه لإشارة `Bx`."},{"h":["الضرب الاتجاهي يكون صفرا عند التوازي، وهنا الزاوية قائمة.","جمعت المقدارين بدل ضربهما.",null,"هذه قيمة `sin 90°` وحدها، ونسيت ضربها في المقدارين."],"g":"استخدم `|A × B| = |A||B|·sin θ` مع `sin 90° = 1`."},{"h":["جمعت المركبتين مباشرة، والمقدار يحسب بالجذر.",null,"ضربت المركبتين، والصواب جمع مربعيهما ثم أخذ الجذر.","طرحت المركبتين، والمقدار يحسب من الجذر لا من الفرق."],"g":"استخدم `|A| = √(Ax² + Ay²)`."},{"h":[null,"جمعت المركبتين `2 + 3` مباشرة، والمقدار يحسب بالجذر.","هذا مجموع المربعين قبل أخذ الجذر التربيعي.","يبدو أنك أخذت `√5` أي جذر مجموع المركبتين لا مجموع مربعيهما."],"g":"استخدم `|A| = √(Ax² + Ay²)` ثم احسب الجذر بالآلة."},{"h":["جمعت المركبتين بإشارتيهما، والمقدار لا يكون صفرا إلا لمتجه صفري.","جمعت القيمتين دون إشارة ودون جذر، والمقدار يحسب بالجذر.",null,"هذا مجموع المربعين قبل أخذ الجذر التربيعي."],"g":"ارفع كل مركبة للمربع فتختفي الإشارة السالبة، ثم اجمع وخذ الجذر."},{"h":["عند `30°` يكون جيب التمام كبيرا (حوالي `0.866`)، والقيمة هنا أصغر بكثير.",null,"الزاوية القائمة تحتاج ضربا قياسيا يساوي صفرا، والضرب هنا لا يساوي صفرا.","الضرب القياسي موجب، فالزاوية حادة لا منفرجة."],"g":"احسب `cos θ = A·B ÷ (|A||B|)` ثم استخدم `cos⁻¹` بالآلة."},{"h":["هذه المركبة السينية، فقد استخدمت `cos 30°` بدل `sin 30°`.","هذا مقدار المتجه نفسه لا مركبته.","ضربت المقدار في 2 بدل ضربه في `sin 30°`.",null],"g":"استخدم `Ay = A·sin θ`، وتذكر أن `sin 30° = 0.5`."}],"0-8":[{"h":["هذه كتلة لكل وحدة مساحة، والكثافة تقسم على الحجم لا على المساحة.",null,"الجرام والسنتيمتر ليسا وحدتي النظام الدولي، والسنتيمتر هنا طول لا حجم.","هذه قوة لكل وحدة طول، ولا علاقة لها بالكتلة أو الحجم."],"g":"تذكر أن `ρ = m ÷ V`، ثم اقسم وحدة الكتلة في النظام الدولي على وحدة الحجم."},{"h":["هذه وحدة الكتلة، والوزن قوة وليس كتلة.","هذه وحدة الشغل والطاقة لا وحدة القوة.",null,"هذه وحدة كتلة صغيرة، والوزن قوة وليس كتلة."],"g":"الوزن قوة جذب الأرض للجسم، فاختر وحدة القوة في النظام الدولي."},{"h":["يبدو أنك حولت الطول فقط ونسيت تربيع معامل التحويل في المساحة.","يبدو أنك خلطت مع تحويل المتر المربع إلى سنتيمتر مربع، والكيلومتر ألف متر.",null,"يبدو أنك رفعت معامل التحويل للقوة الثالثة كأنها وحدة حجم، والمساحة تربيع فقط."],"g":"اكتب `1 km = 10³ m` ثم ربع الطرفين، لأن المساحة طول في طول."},{"h":["هذا عدد الثواني في دقيقة واحدة، والساعة فيها ستون دقيقة.","يبدو أنك ضربت ستين في عشرة بدلا من ستين في ستين.",null,"الناتج أكبر من الصحيح بعشر مرات، فراجع الأصفار في عملية الضرب."],"g":"حول الساعة إلى دقائق ثم الدقائق إلى ثوان، واضرب المعاملين معا."},{"h":[null,"درجة الحرارة لا تعرف بدلالة كميات أخرى، فهي ليست مشتقة.","درجة الحرارة لها مقدار فقط ولا اتجاه لها.","درجة الحرارة تقاس بمقدار ووحدة، فهي كمية فيزيائية."],"g":"تذكر الكميات السبع التي اعتمدها النظام الدولي وتعرف بذاتها، وهل درجة الحرارة منها؟"},{"h":["المساحة تعرف بدلالة الطول، فليست من الكميات السبع المستقلة.",null,"المساحة تحدد عادة بمقدار ووحدة، فلا توصف بأنها متجهة دائما.","للمساحة وحدة في النظام الدولي هي المتر المربع."],"g":"اسأل نفسك: هل تعرف المساحة بذاتها أم نحسبها من ضرب طولين؟"},{"h":["سرعة الرياح تقاس بمقدار ووحدة `m/s`، فهي كمية فيزيائية.","قوة الجاذبية تقاس بالنيوتن، فهي كمية فيزيائية.",null,"شدة التيار كمية أساسية تقاس بالأمبير."],"g":"الكمية الفيزيائية تعطى بمقدار ووحدة، فابحث عن الخيار الذي يمثل ظاهرة لا قيمة مقيسة."},{"h":["هذه قيمة كيلو `k`.",null,"هذه قيمة جيجا `G`.","هذه قيمة ميكرو `µ`، وهي بادئة صغيرة لا كبيرة."],"g":"ميجا أعلى من كيلو بدرجة واحدة على سلم البادئات، وكل درجة تعني الضرب في ألف."},{"h":[null,"إشارة الأس خطأ؛ المليمتر أصغر من المتر فيجب أن يصغر الرقم لا أن يكبر.","يبدو أنك قسمت على عشرة فقط، والميلي جزء من ألف.","هذه قيمة الميكرومتر لا المليمتر."],"g":"استبدل البادئة ميلي بقوة العشرة المقابلة لها، ثم اضربها في العدد المعطى."},{"h":[null,"هذه قيمة كيلو، وميلي بادئة صغيرة.","هذه قيمة ميكرو، وهي أصغر من ميلي بألف مرة.","هذه قيمة سنتي، أي جزء من مئة."],"g":"ميلي تعني جزءا من ألف، فاكتب هذا الجزء على شكل قوة للعشرة."},{"h":["يبدو أنك غيرت الوحدة دون أي معامل تحويل.","يبدو أنك ضربت في مئة فقط، لكن السنتيمتر المكعب أصغر من المتر المكعب بمليون مرة.",null,"يبدو أنك ضربت في عشرة فقط، فراجع معاملي تحويل الكتلة والحجم."],"g":"حول الكتلة من `g` إلى `kg` بالقسمة على ألف، والحجم من `cm³` إلى `m³` بالقسمة على مليون، ثم اقسم."},{"h":["هذا الطول بالمتر لا بالسنتيمتر، فلم تكمل التحويل.",null,"ينقصك صفر؛ في المتر مئة سنتيمتر لا عشرة.","يبدو أنك قسمت بدلا من الضرب، والسنتيمتر أصغر فيجب أن يكبر الرقم."],"g":"حول الكيلومتر إلى متر بالضرب في ألف، ثم المتر إلى سنتيمتر بالضرب في مئة."},{"h":["هذا مقدار الضرب عند التعامد، لأن جيب `90°` يساوي واحدا.","الضرب الاتجاهي لا يجمع المقدارين، بل يضربهما في جيب الزاوية.","الناتج يعتمد على المقدارين والزاوية، وليس قيمة ثابتة تساوي واحدا.",null],"g":"استخدم `|A × B| = AB sinθ` وعوض بقيمة جيب الزاوية `0°`."}],"1-1":[{"h":["القياسية لها مقدار فقط، والإزاحة لها اتجاه أيضا.",null,"الإزاحة تقاس بالمتر، فهي كمية فيزيائية.","هذا تصنيف من نوع آخر، والسؤال هنا عن وجود الاتجاه مع المقدار."],"g":"اسأل نفسك: هل تحتاج الإزاحة إلى اتجاه إضافة إلى المقدار؟"},{"h":["يبدو أنك ضربت الإزاحة في الزمن بدلا من القسمة.",null,"يبدو أنك قسمت على `100` بدلا من الزمن المعطى.","يبدو أنك جمعت الإزاحة والزمن، والسرعة قسمة لا جمع."],"g":"استخدم `v = x / t` وعوض بالإزاحة والزمن."},{"h":["هذه وحدة السرعة، والتسارع تغير السرعة لكل ثانية.",null,"هذه وحدة الطول أو الإزاحة.","هذه وحدة القوة (النيوتن)."],"g":"التسارع تغير السرعة مقسوما على الزمن، فاقسم وحدة السرعة على الثانية."},{"h":["يبدو أنك ضربت السرعة في الزمن بدلا من القسمة.",null,"يبدو أنك طرحت الزمن من السرعة، والتسارع قسمة لا طرح.","يبدو أنك جمعت السرعة والزمن."],"g":"الجسم بدأ من السكون فسرعته الابتدائية صفر، ثم استخدم `a = (Vf − Vi) / t`."},{"h":["هذا طول المسار كله، أي المسافة لا الإزاحة.","هذا طول الذهاب فقط، ونسيت أن الشخص عاد بالقدر نفسه.",null,"يبدو أنك ضربت الطولين، والإزاحة تجمع مع مراعاة الاتجاه."],"g":"قارن نقطة النهاية بنقطة البداية، وتذكر أن الحركة جنوبا عكس الحركة شمالا."},{"h":["الإزاحة تحتاج اتجاها وتقارن نقطتي البداية والنهاية، والعداد يجمع كل ما قطعته السيارة.",null,"التسارع تغير السرعة مع الزمن، والعداد لا يقيس تغير السرعة.","العداد لا يقيس سرعة أصلا، بل يجمع أطوال الطريق المقطوع."],"g":"العداد يزيد مع كل متر تقطعه السيارة مهما غيرت اتجاهها، فأي كمية تجمع طول المسار؟"},{"h":["هذا مجموع الطولين، والإزاحة تطرح الحركة المعاكسة.",null,"المقدار صحيح لكن الاتجاه خطأ، فالحركة الأكبر كانت نحو الغرب.","يبدو أنك ضربت الطولين، والإزاحة تجمع مع مراعاة الإشارة."],"g":"اعتبر الغرب موجبا والشرق سالبا، واجمع الإزاحتين بإشارتيهما."},{"h":["هذا طول المضمار، أي المسافة لا الإزاحة.","هذا نصف الدورة، والعداء أكمل الدورة كلها.",null,"هذا ضعف طول المضمار، والعداء أكمل دورة واحدة فقط."],"g":"الإزاحة تعتمد على نقطتي البداية والنهاية فقط، فأين انتهى العداء؟"},{"h":["المقدار صحيح لكن الإشارة خطأ، فالسرعة تقل.",null,"يبدو أنك قسمت مجموع السرعتين لا فرقهما.","يبدو أنك استخدمت مجموع السرعتين بدلا من الفرق `Vf − Vi`."],"g":"عوض في `a = (Vf − Vi) / t` بالترتيب الصحيح، وانتبه للإشارة عندما تقل السرعة."},{"h":["هذا مجموع الطولين، أي المسافة لا الإزاحة.","يبدو أنك طرحت الطولين، والاتجاهان متعامدان لا متعاكسان.","يبدو أنك ضربت الطولين.",null],"g":"الحركتان متعامدتان، فالإزاحة وتر مثلث قائم الزاوية: استخدم نظرية فيثاغورس."},{"h":[null,"السرعة تقاس بوحدة طول على زمن مثل `m/s`، لا بوحدة طول فقط.","السرعة المتجهة تتغير إذا تغير مقدارها أو اتجاهها.","السرعة قسمة على الزمن لا ضرب فيه."],"g":"تذكر الفرق بين الكمية القياسية والكمية المتجهة، وطبقه على نوعي السرعة."},{"h":["المقذوف لا يتحرك أفقيا فقط، بل يرتفع وينخفض أيضا.",null,"حركة المقذوف تقع في مستوى واحد، فلا يحتاج محورا ثالثا.","المقذوف يغير موضعه، فهو جسم متحرك."],"g":"اسأل: في كم اتجاه يتغير موضع المقذوف أثناء طيرانه؟ وكل اتجاه يمثل بعدا."},{"h":[null,"الطريق مستقيم، فلا يتغير الموضع في اتجاهين.","السيارة لا تطير ولا تنعطف هنا، فلا تحتاج ثلاثة محاور.","السيارة تتحرك، فلا بد أن يتغير موضعها على محور ما."],"g":"كم مركبة يحتاج متجه موضع جسم يسير على خط مستقيم؟"},{"h":["قانون كولوم يخص الشحنات الكهربائية، لا الحركة والقوة.",null,"المقاومة النوعية من موضوعات الكهرباء.","الحرارة النوعية من موضوعات الحرارة."],"g":"الوحدة عن الحركة والقوة والشغل والطاقة، فاختر الموضوع الذي يربط القوة بالحركة."}],"1-2":[{"h":["راجع الحساب: اضرب التسارع في الزمن المعطى بدقة، ثم أضف السرعة الابتدائية.",null,"يبدو أنك حسبت الزيادة `a·t` فقط ونسيت إضافة السرعة الابتدائية.","لا تصل إلى هذا الناتج عملية صحيحة، فعوض في القانون خطوة خطوة."],"g":"استخدم `Vf = Vi + a·t`: احسب الزيادة في السرعة ثم أضفها إلى السرعة الابتدائية."},{"h":["يبدو أنك ضربت التسارع في الزمن فقط دون تربيع الزمن ودون النصف.",null,"يبدو أنك نسيت الضرب في النصف.","يبدو أنك لم تربع الزمن، بل ضربت النصف في التسارع في الزمن."],"g":"الجسم ساكن فسرعته الابتدائية صفر، فاستخدم `x = ½·a·t²` ولا تنس تربيع الزمن."},{"h":[null,"السرعة الابتدائية صفر تعني البدء من السكون، لا التباطؤ.","التباطؤ قد لا ينتهي بالتوقف، فالسرعة النهائية ليست صفرا دائما.","التسارع الصفري يعني سرعة ثابتة، والسرعة هنا تقل."],"g":"التباطؤ يعني أن السرعة تقل، ففكر في إشارة `Vf − Vi` عندما تكون السرعة النهائية أصغر."},{"h":["هذا مربع السرعة، ونسيت أخذ الجذر التربيعي.","يبدو أنك قسمت على اثنين بدلا من أخذ الجذر التربيعي.",null,"يبدو أنك ضربت التسارع في اثنين فقط ولم تستخدم الإزاحة."],"g":"الزمن غير معطى، فاستخدم `Vf² = Vi² + 2·a·x` ثم خذ الجذر التربيعي."},{"h":["هذه المعادلة تحتوي الزمن `t`.","هذه المعادلة تحتوي الزمن `t` في حديها.",null,"هذه المعادلة تحتوي الزمن، لأن الإزاحة فيها متوسط السرعة مضروبا في `t`."],"g":"ابحث عن المعادلة التي لا يظهر فيها الرمز `t` أبدا."},{"h":["يبدو أنك ضربت السرعة في التباطؤ بدلا من القسمة.",null,"يبدو أنك طرحت التباطؤ من السرعة.","يبدو أنك جمعت السرعة والتباطؤ."],"g":"السيارة توقفت فالسرعة النهائية صفر، فاستخدم `Vf = Vi + a·t` مع تسارع سالب."},{"h":["يبدو أنك جمعت التسارع والزمن بدلا من ضربهما.",null,"الناتج ضعف المطلوب، فتأكد أنك لم تضرب في اثنين.","يبدو أنك قسمت التسارع على الزمن بدلا من الضرب."],"g":"الجسم بدأ من السكون، فاستخدم `Vf = Vi + a·t` مع `Vi = 0`."},{"h":["يبدو أنك ضاعفت المقام، والمقام الصحيح هو `2·a` فقط.","يبدو أنك ضربت السرعة في التباطؤ، والقانون فيه مربع السرعة.","يبدو أنك قسمت على التباطؤ فقط ونسيت العدد `2` في المقام.",null],"g":"الزمن غير معطى، فاستخدم `Vf² = Vi² + 2·a·x` مع `Vf = 0` وتسارع سالب."},{"h":["يبدو أنك قسمت الإزاحة على مربع الزمن ونسيت الضرب في اثنين.",null,"يبدو أنك قسمت الإزاحة على الزمن، وهذا يعطي سرعة متوسطة لا تسارعا.","يبدو أنك قسمت على ضعف الزمن بدلا من نصف مربعه."],"g":"الجسم بدأ من السكون، فاستخدم `x = ½·a·t²` وحل المعادلة لإيجاد `a`."},{"h":["هذه المعادلة تحتوي `Vf` في طرفها الأيسر.","هذه المعادلة تحتوي مربع السرعة النهائية.",null,"هذه المعادلة تحتوي `Vf` داخل القوسين."],"g":"افحص كل معادلة وابحث عن التي لا يظهر فيها الرمز `Vf`."},{"h":["المسافة لا تتناسب طرديا مع السرعة، بل مع مربعها.","مع ثبات التباطؤ تحتاج السرعة الأكبر مسافة أطول لتتوقف.",null,"السرعة زادت، فلا يمكن أن تقل مسافة التوقف."],"g":"من `Vf² = Vi² + 2·a·x` مع `Vf = 0` تجد أن المسافة تتناسب مع `Vi²`، فماذا يحدث عند تربيع الضعف؟"}],"1-3":[{"h":["يبدو أنك جمعت الكتلة والتسارع، والقانون يضربهما.",null,"يبدو أنك قسمت الكتلة على التسارع، والقانون يضربهما.","يبدو أنك قسمت التسارع على الكتلة، والقانون يضربهما."],"g":"استخدم `F = m·a` واضرب الكتلة في التسارع."},{"h":["يبدو أنك ضربت القوة في الكتلة، والمطلوب قسمة القوة على الكتلة.",null,"راجع موضع الفاصلة العشرية: القسمة على `0.25` تساوي الضرب في 4.","هذه قيمة القوة نفسها، ولم تقسمها على الكتلة."],"g":"استخدم `a = F / m`، وتذكر أن القسمة على عدد أصغر من 1 تكبر الناتج."},{"h":[null,"القانون الثاني صيغته `F = m·a` ويصف جسما له تسارع.","القانون الثالث يتحدث عن قوتين متبادلتين بين جسمين `F_AB = −F_BA`.","حفظ الطاقة ليس من قوانين نيوتن، ولا يتحدث عن محصلة القوى."],"g":"ابحث عن القانون الذي يصف جسما ساكنا أو يتحرك بسرعة ثابتة دون قوة محصلة."},{"h":["هذه قيمة الكتلة، والوزن يحتاج الضرب في تسارع الجاذبية.","هذه قيمة تسارع الجاذبية وحدها، ولم تضربها في الكتلة.",null,"يبدو أنك قسمت `9.8` على الكتلة بدل أن تضربها فيها."],"g":"استخدم `W = m·g` مع `g = 9.8 m/s²`."},{"h":[null,"الوزن هو قوة جذب الأرض للجسم `W = m·g`، وليس ممانعة لتغير الحركة.","الاحتكاك قوة بين سطحين متلامسين تعيق الانزلاق، وليس خاصية للجسم نفسه.","التسارع هو معدل تغير السرعة، أي نتيجة تغير الحالة الحركية لا ممانعتها."],"g":"ارجع إلى قانون نيوتن الأول: ما اسم ميل الجسم إلى المحافظة على حالته الحركية؟"},{"h":["التسارع يتناسب طرديا مع القوة لا عكسيا، فلا يقل.",null,"التسارع يتغير مع القوة عند ثبات الكتلة، فلا يبقى كما هو.","العلاقة خطية لا تربيعية، فمضاعفة القوة لا تجعله أربعة أضعاف."],"g":"اكتب `a = F / m` وانظر ماذا يحدث للتسارع إذا ضربت F في 2 وبقيت m ثابتة."},{"h":["القانون الثالث يتحدث عن قوتين متبادلتين بين جسمين، ولا يفسر اندفاع الراكب.",null,"الاحتكاك يعيق الانزلاق، ولا يدفع الراكب للأمام.","الجاذبية تشد الراكب إلى الأسفل لا إلى الأمام."],"g":"الحافلة توقفت لكن جسم الراكب يميل للمحافظة على حركته؛ فكر في قانون نيوتن الأول."},{"h":[null,"يبدو أنك جمعت القوتين، وهما متعاكستان فتطرح إحداهما من الأخرى.","يبدو أنك أخذت القوة الغربية وحدها `4 ÷ 2`، والقوة الشرقية أكبر.","يبدو أنك أخذت القوة الشرقية وحدها `10 ÷ 2`، كما أن المحصلة تتجه نحو القوة الأكبر شرقا."],"g":"احسب المحصلة أولا بطرح القوتين المتعاكستين، ثم قسمها على الكتلة، واتجاه التسارع هو اتجاه المحصلة."},{"h":["هذا وزنه على الأرض باستخدام `9.8`، والمطلوب على القمر.","الكتلة لا تتغير بتغير المكان، فلا يصح أن تقل على القمر.",null,"يبدو أنك قسمت الكتلة على `1.6` وجعلت الكتلة وزنا، والصحيح ضرب الكتلة في g."],"g":"الكتلة ثابتة في كل مكان، أما الوزن فاحسبه من `W = m·g` بتسارع جاذبية القمر."},{"h":["الوزن قوة واحدة، والجسم تؤثر فيه قوى أخرى تعادلها.","لو كانت المحصلة في اتجاه الحركة لتسارع الجسم ولم تبق سرعته ثابتة.","لو زادت المحصلة لتغيرت السرعة، والسرعة هنا ثابتة.",null],"g":"السرعة الثابتة تعني أن التسارع منعدم، فطبق `ΣF = m·a`."},{"h":["هذه الوحدة ينقصها تربيع الثانية، والتسارع وحدته `m/s²`.",null,"هنا المتر مربع، والتسارع وحدته متر واحد لكل ثانية مربعة.","المتر هنا في المقام، لكن في `F = m·a` تضرب الكتلة في المتر لكل ثانية مربعة."],"g":"عوض وحدة الكتلة ووحدة التسارع في `F = m·a`."},{"h":["القانون الأول يصف جسما محصلة القوى عليه منعدمة.","القانون الثاني يربط القوة بالكتلة والتسارع `F = m·a`.",null,"قانون كولوم يحسب القوة بين شحنتين كهربائيتين."],"g":"النص يتحدث عن قوتين متبادلتين بين جسمين؛ أي قوانين نيوتن يصف هذا الزوج؟"},{"h":["القصور الذاتي يفسر بقاء الجسم على حالته، لا ارتداد البندقية بسبب الرصاصة.",null,"الاحتكاك يعيق الانزلاق بين سطحين، ولا علاقة له بالارتداد.","حفظ الكتلة لا يفسر سبب حركة البندقية للخلف."],"g":"البندقية تدفع الرصاصة للأمام، فبماذا تؤثر الرصاصة في البندقية؟ تذكر قانون نيوتن الثالث."},{"h":["القوتان لا تؤثران في جسم واحد، لذلك لا تلغي إحداهما الأخرى.",null,"القوتان متساويتان في المقدار حسب قانون نيوتن الثالث.","القوتان متعاكستان في الاتجاه دائما."],"g":"تذكر `F_AB = −F_BA`: قوة A على B وقوة B على A، فأين تؤثر كل منهما؟"},{"h":["الهواء ليس هو ما يرفع الصاروخ، فالصاروخ يندفع حتى حيث يقل الهواء.",null,"الوزن قوة للأسفل دائما، ونقصه لا يصنع قوة دافعة للأعلى.","الجاذبية موجودة وتشد الصاروخ للأسفل، ومع ذلك يرتفع."],"g":"فكر في الزوج المتبادل: الصاروخ يدفع الغازات في اتجاه، فما اتجاه دفع الغازات له؟"},{"h":["دفع قدمك يؤثر في الأرض لا فيك، فلا يحركك أنت.",null,"الوزن قوة للأسفل، ولا يدفعك للأمام.","مقاومة الهواء تعاكس حركتك ولا تدفعك للأمام."],"g":"القوة التي تحرك جسمك يجب أن تؤثر عليك أنت، فابحث عن القوة التي يؤثر بها جسم آخر عليك."},{"h":["رد الفعل لا ينقص إلى النصف، بل يساوي الفعل في المقدار.","المقدار صحيح، لكن رد الفعل لا يكون في اتجاه الفعل.",null,"رد الفعل لا يتضاعف، بل يساوي الفعل في المقدار."],"g":"طبق `F_AB = −F_BA`: انتبه للمقدار وللإشارة السالبة التي تدل على الاتجاه."},{"h":["قوة الطاولة تؤثر في الكتاب وتعادل وزنه، لكنها ليست زوجه في القانون الثالث.",null,"وزن الطاولة قوة تؤثر في الطاولة، ولا علاقة له بالزوج بين الأرض والكتاب.","الاحتكاك لا يظهر هنا لأن الكتاب ساكن ولا يدفعه أحد أفقيا."],"g":"قوة الفعل هي قوة الأرض على الكتاب، فرد الفعل يكون بين الجسمين نفسيهما مع تبديل الأدوار."},{"h":["القوتان متساويتان في المقدار دائما.","القوتان متعاكستان في الاتجاه دائما.",null,"القوتان تظهران معا في اللحظة نفسها."],"g":"لا تجمع إلا القوى المؤثرة في الجسم نفسه؛ فاسأل: على أي جسم تؤثر كل قوة؟"},{"h":[null,"كبر كتلة الشاحنة لا يجعل قوتها أكبر، فالقوتان زوج فعل ورد فعل.","صغر السيارة يجعل تسارعها أكبر، لا قوتها أصغر.","حدث تصادم وتأثير متبادل، فلا يمكن أن تكون القوة منعدمة."],"g":"طبق قانون نيوتن الثالث على القوتين، ثم فرق بين القوة والتسارع."},{"h":["يبدو أنك قسمت على كتلة الزميل `100 kg`، والمطلوب تسارع المتزلج الأول.","المتزلج الأول يتلقى رد فعل من زميله، والجليد أملس فلا احتكاك يمنعه من الحركة.","يبدو أنك ضاعفت القوة أو قسمت على نصف الكتلة؛ رد الفعل يساوي `200 N` نفسها.",null],"g":"رد فعل الزميل على المتزلج الأول يساوي قوة دفعه، فقسم هذه القوة على كتلة المتزلج الأول."}],"1-5":[{"h":["لو كان الاحتكاك في اتجاه الحركة لساعد عليها، وهو يعيقها.",null,"القوة العمودية هي العمودية على السطح، أما الاحتكاك فيكون موازيا للسطح.","الاحتكاك قوة، والقوة كمية متجهة لها اتجاه."],"g":"تذكر أن الاحتكاك يعيق انزلاق السطحين، فكيف يكون اتجاه قوة تعيق الحركة؟"},{"h":["يبدو أنك قسمت الوزن على المعامل، والقانون يضربهما.",null,"يبدو أنك جمعت المعامل والوزن، والقانون يضربهما.","يبدو أنك قسمت المعامل على الوزن، والقانون يضربهما."],"g":"على السطح الأفقي القوة العمودية تساوي الوزن، ثم استخدم `fk = μk·N`."},{"h":["يبدو أنك قسمت القوة العمودية على المعامل، والقانون يضربهما.",null,"يبدو أنك جمعت المعامل والقوة العمودية، والقانون يضربهما.","يبدو أنك قسمت المعامل على القوة العمودية، والقانون يضربهما."],"g":"عوض مباشرة في `fk = μk·N` بضرب المعامل في القوة العمودية."},{"h":["يبدو أنك قسمت القوة العمودية على قوة الاحتكاك، والصحيح العكس.",null,"يبدو أنك ضربت القوتين، والمعامل ناتج قسمة.","يبدو أنك جمعت القوتين، والمعامل ناتج قسمة."],"g":"من `fk = μk·N` يكون `μk = fk ÷ N`، أي قوة الاحتكاك مقسومة على القوة العمودية."},{"h":[null,"الماء على الطريق لا يغير وزن السيارة.","كتلة السيارة لا تتغير بسبب بلل الطريق.","لو زاد تباطؤ السيارة لقصرت مسافة التوقف لا طالت."],"g":"فكر فيما يفعله الماء بين الإطار والطريق، وأثر ذلك على قوة الاحتكاك التي توقف السيارة."},{"h":["يبدو أنك ضربت المعامل في الكتلة، ونسيت تحويل الكتلة إلى وزن بالضرب في `g`.",null,"يبدو أنك قسمت الكتلة على المعامل، والقانون يضرب المعامل في القوة العمودية.","هذا وزن الصندوق فقط، ولم تضربه في معامل الاحتكاك."],"g":"احسب القوة العمودية أولا `N = m·g`، ثم اضربها في معامل الاحتكاك الحركي."},{"h":[null,"العكس هو الصحيح عادة، ولو كان كذلك لكان إبقاء الصندوق متحركا أصعب من تحريكه.","الوزن لا يتغير بحركة الصندوق.","الصندوق يبقى ضاغطا على السطح أثناء حركته، فالقوة العمودية لا تنعدم."],"g":"قارن بين معامل الاحتكاك السكوني ومعامل الاحتكاك الحركي للسطحين نفسيهما."},{"h":["يبدو أنك ضربت المعامل في الكتلة ونسيت الضرب في `g`.",null,"هذا وزن الصندوق، ولم تضربه في معامل الاحتكاك.","يبدو أنك قسمت الكتلة على المعامل بدل الضرب."],"g":"السرعة الثابتة تعني أن المحصلة منعدمة، فقوة السحب تساوي قوة الاحتكاك الحركي `μk·m·g`."},{"h":["النيوتن وحدة القوة، والمعامل ناتج قسمة قوة على قوة.","الكيلوجرام وحدة الكتلة، والمعامل ليس كتلة.",null,"هذه وحدة التسارع، والمعامل ليس تسارعا."],"g":"اكتب `μ = f ÷ N` وانظر إلى وحدتي البسط والمقام: ماذا يبقى بعد القسمة؟"},{"h":["الخشونة تزيد الاحتكاك، ولهذا تصنع نعال الأحذية الرياضية خشنة.","زيادة القوة العمودية تزيد الاحتكاك لأن `f = μ·N`.","زيادة الوزن تزيد القوة العمودية فيزيد الاحتكاك.",null],"g":"تذكر ما يوضع في المحركات ليفصل بين الأجزاء المتلامسة فيقلل التآكل والحرارة."}],"1-6":[{"h":["يبدو أنك جمعت الكتلة والتسارع بدل ضربهما.",null,"يبدو أنك قسمت الكتلة على التسارع بدل ضربهما.","يبدو أنك قسمت التسارع على الكتلة بدل ضربهما."],"g":"استخدم قانون نيوتن الثاني `F = m·a` واضرب الكتلة في التسارع."},{"h":["يبدو أنك ضربت القوة في التسارع، والمطلوب قسمتها عليه.",null,"يبدو أنك جمعت القوة والتسارع، ولا يصح جمع كميتين بوحدتين مختلفتين.","يبدو أنك طرحت التسارع من القوة، والقانون فيه ضرب لا طرح."],"g":"من `F = m·a` اعزل الكتلة بقسمة القوة على التسارع."},{"h":["يبدو أنك جمعت التسارع والزمن بدل ضربهما.",null,"يبدو أنك قسمت التسارع على الزمن، والصحيح ضربهما.","يبدو أنك حسبت المسافة `½·a·t²` لا السرعة، ثم كتبت وحدة السرعة."],"g":"بدأ من السكون يعني `Vi = 0`، ثم استخدم `Vf = Vi + a·t`."},{"h":[null,"راجع المقارنة بين العددين جيدا قبل أن تحكم.","يمكن الحكم بحساب أقصى احتكاك سكوني ومقارنته بقوة الدفع.","لا يشترط قوة معينة، بل يكفي أن تزيد قوة الدفع على أقصى احتكاك سكوني."],"g":"احسب أقصى احتكاك سكوني `fs(max) = μs·m·g` ثم قارنه بقوة الدفع."},{"h":["يبدو أنك ضربت المسافة في الزمن بدل القسمة.",null,"يبدو أنك طرحت الزمن من المسافة، والقانون قسمة.","يبدو أنك قسمت الزمن على المسافة، والصحيح العكس."],"g":"السرعة المتوسطة تساوي الإزاحة مقسومة على الزمن `v = x / t`."},{"h":["هذه قيمة الكتلة نفسها، والوزن يحتاج الضرب في `g`.",null,"يبدو أنك قسمت الكتلة على `g` بدل ضربهما.","يبدو أنك جمعت الكتلة و `g` بدل ضربهما."],"g":"الوزن قوة تحسب من `W = m·g` مع `g = 9.8 m/s²`."},{"h":["يبدو أنك أهملت قوة الاحتكاك وقسمت قوة السحب وحدها على الكتلة.","يبدو أنك قسمت قوة الاحتكاك على الكتلة، والمطلوب القوة المحصلة.",null,"قوة السحب أكبر من قوة الاحتكاك، فالمحصلة ليست صفرا ويتسارع الصندوق."],"g":"احسب الاحتكاك `f = μ·m·g`، ثم المحصلة `F − f`، ثم اقسمها على الكتلة."},{"h":["هذا الرقم نفسه دون تحويل، والوحدة تغيرت من `km/h` إلى `m/s`.","يبدو أنك قسمت على 2، والتحويل يكون بالقسمة على `3.6`.","يبدو أنك ضربت في `3.6` بدل القسمة عليه.",null],"g":"للتحويل من `km/h` إلى `m/s` اقسم على `3.6`، لأن `1 km = 1000 m` و `1 h = 3600 s`."},{"h":[null,"راجع حساب التسارع: قسمة `24` على `8` لا تعطي `2 m/s²`.","يبدو أنك ضربت الكتلة في الزمن بدل التسارع.","يبدو أنك قسمت الكتلة على الزمن، والمطلوب ضرب الكتلة في التسارع."],"g":"احسب التسارع أولا `a = (Vf − Vi) / t` ثم القوة `F = m·a`."},{"h":["لو كان الشد أكبر من الوزن لتسارع المصعد للأعلى، والسرعة هنا ثابتة.","لو كان الشد أصغر من الوزن لتباطأ المصعد أثناء صعوده.",null,"لو انعدم الشد لسقط المصعد بتأثير وزنه."],"g":"السرعة الثابتة تعني تسارعا صفريا، وحسب `F = m·a` تكون القوة المحصلة صفرا."}],"1-7":[{"h":["يبدو أنك قسمت القوة على الإزاحة، والشغل حاصل ضربهما.","يبدو أنك جمعت القوة والإزاحة بدل ضربهما.",null,"يبدو أنك قسمت الإزاحة على القوة، والصحيح ضربهما."],"g":"القوة أفقية في اتجاه الحركة، فاستخدم `W = F·x`."},{"h":["يبدو أنك نسيت الضرب في `cos 60°`.",null,"يبدو أنك استخدمت `sin 60°` أو `cos 30°` بدل `cos 60°`.","يبدو أنك ضربت القوة في `cos 60°` ونسيت الإزاحة."],"g":"استخدم `W = F·x·cos θ`، وتذكر أن `cos 60° = 0.5`."},{"h":["هذه قيمة القوة وحدها، والشغل يحتاج إزاحة أيضا.",null,"يبدو أنك أخذت نصف القوة، ولا يوجد في السؤال ما يبرر ذلك.","يمكن حسابه، فكل المعطيات اللازمة موجودة ومنها أن الجدار لم يتحرك."],"g":"الشغل يحتاج إزاحة، فاسأل نفسك: كم تحرك الجدار؟"},{"h":["الشغل ليس له اتجاه، فهو ناتج ضرب مقادير ولا يوصف باتجاه.",null,"الكميات الأساسية مثل الطول والكتلة والزمن، والشغل كمية مشتقة منها.","للشغل وحدة هي الجول `J`."],"g":"اسأل نفسك: هل للشغل اتجاه، أم هو مقدار فقط يقاس بالجول؟"},{"h":["هذه صيغة الوزن، والرمز `W` فيها يعني الوزن لا الشغل.",null,"هذا قانون نيوتن الثاني، وهو يحسب القوة لا الشغل.","الشغل حاصل ضرب القوة في الإزاحة لا قسمتها عليها."],"g":"الشغل يعتمد على القوة والإزاحة والزاوية بينهما، فابحث عن صيغة تجمع الثلاثة."},{"h":["الشغل الموجب يحتاج قوة لها مركبة في اتجاه الحركة، وقوة الحمل رأسية والحركة أفقية.","الشغل السالب يكون لقوة تعاكس الحركة، وقوة الحمل لا تعاكس المشي.",null,"الشغل يقاس بالجول لا بالنيوتن، فلا يمكن أن يساوي الوزن."],"g":"حدد الزاوية بين قوة الحمل الرأسية واتجاه المشي الأفقي، ثم احسب جيب تمامها."},{"h":["الشغل حاصل ضرب القوة في المسافة لا قسمتها عليها.",null,"هذه وحدة قوة مضروبة في زمن، والشغل قوة مضروبة في مسافة.","هذه وحدة كتلة مضروبة في سرعة، وليست قوة مضروبة في مسافة."],"g":"الشغل قوة مضروبة في إزاحة، فاضرب وحدة القوة في وحدة الإزاحة."},{"h":["الشغل يكون موجبا عندما تكون القوة في اتجاه الحركة، والاحتكاك ليس كذلك.",null,"الشغل ينعدم عندما تكون القوة عمودية على الحركة، والاحتكاك ليس عموديا عليها.","يمكن حسابه بمعرفة قوة الاحتكاك والإزاحة والزاوية بينهما."],"g":"الاحتكاك يعاكس اتجاه الحركة فتكون `θ = 180°`، فما إشارة `cos 180°`؟"},{"h":["يبدو أنك ضربت الكتلة في الارتفاع ونسيت `g`.","هذا وزن الصندوق بالنيوتن، ولم تضربه في الارتفاع.",null,"يبدو أنك ضربت في الارتفاع مرتين، أي استخدمت مربعه."],"g":"بسرعة ثابتة تساوي قوة الرفع الوزن `m·g`، فالشغل يساوي الوزن مضروبا في الارتفاع."},{"h":["يبدو أنك استخدمت `cos 60°` أو `sin 30°` بدل `cos 30°`.","يبدو أنك نسيت الضرب في `cos 30°`.","الناتج أكبر من `F·x` نفسه، و `cos θ` لا يزيد على 1، فراجع التعويض.",null],"g":"استخدم `W = F·x·cos θ` مع `cos 30° ≈ 0.866`."}],"1-8":[{"h":["يبدو أنك لم تربع السرعة، والقانون فيه `v²`.","يبدو أنك ضربت الكتلة في السرعة دون تربيع ودون قسمة على 2.",null,"يبدو أنك نسيت القسمة على 2."],"g":"استخدم `KE = mv²/2`: ربع السرعة أولا ثم اضرب في الكتلة واقسم على 2."},{"h":["يبدو أنك نسيت تسارع الجاذبية `g`.",null,"هذا وزن الجسم فقط، ولم تضربه في الارتفاع.","الناتج صغير جدا، فالقانون يضرب الكميات الثلاث ولا يقسم أيا منها."],"g":"استخدم `PE = m·g·h` مع `g = 9.8 m/s²`."},{"h":["هذا يصح لو كانت الطاقة تتناسب مع السرعة نفسها، لكنها تتناسب مع مربعها.",null,"الطاقة الحركية تعتمد على السرعة، فلا تبقى ثابتة إذا تغيرت السرعة.","زيادة السرعة تزيد الطاقة الحركية ولا تنقصها."],"g":"لاحظ أن السرعة مربعة في `KE = mv²/2`، فماذا يحدث لمربع العدد إذا ضاعفته؟"},{"h":["يبدو أنك نسيت الضرب في 2 قبل القسمة على مربع السرعة.",null,"يبدو أنك قسمت الطاقة على السرعة دون تربيع ودون الضرب في 2.","يبدو أنك ضربت في 2 لكنك قسمت على السرعة لا على مربعها."],"g":"أعد ترتيب `KE = mv²/2` لتصبح `m = 2·KE / v²`."},{"h":["هذا يصح لو كانت الطاقة تتناسب مع السرعة، لكنها تتناسب مع مربعها.",null,"زيادة السرعة تزيد الطاقة الحركية ولا تنقصها.","الطاقة الحركية تتغير بتغير السرعة، فلا تبقى كما هي."],"g":"مضاعفة السرعة تضرب `v²` في `2²`، فاضرب الطاقة الأصلية في هذا العدد."},{"h":["الماء خلف السد محجوز وساكن تقريبا، والطاقة الحركية تحتاج حركة.",null,"الطاقة الكيميائية مخزنة في مواد مثل الوقود والطعام، وليست بسبب ارتفاع الماء.","الطاقة النووية مخزنة في أنوية الذرات، ولا علاقة لها بحجز الماء خلف السد."],"g":"الماء خلف السد مرتفع عن مستوى الإسناد، فأي طاقة تعتمد على الارتفاع `h`؟"},{"h":[null,"هذا يحدث مع السرعة في الطاقة الحركية، أما الارتفاع فليس مربعا في قانون طاقة الوضع.","طاقة الوضع تعتمد على الارتفاع، فلا تبقى ثابتة إذا تغير.","زيادة الارتفاع تزيد طاقة الوضع ولا تنقصها."],"g":"في `PE = m·g·h` يظهر الارتفاع بلا تربيع، أي أن العلاقة طردية مباشرة."},{"h":["يبدو أنك لم تربع السرعة.",null,"يبدو أنك نسيت القسمة على 2.","يبدو أنك قسمت على 2 لكنك لم تربع السرعة."],"g":"عوض في `KE = mv²/2`، وانتبه إلى تربيع السرعة `20²` قبل الضرب في الكتلة."},{"h":["يبدو أنك قسمت على 2 بدل الضرب فيه عند عزل `v²`.","يبدو أنك قسمت الطاقة على الكتلة فقط ولم تأخذ الجذر.","هذه قيمة `v²` لا `v`، فلا تنس أخذ الجذر التربيعي.",null],"g":"من `KE = mv²/2` نجد `v² = 2·KE / m`، ثم خذ الجذر التربيعي."},{"h":["تكون الطاقة الحركية صفرا عندما يكون الجسم ساكنا، وهذا ممكن.","الجسم الثقيل السريع يملك طاقة حركية كبيرة جدا، وهذا ممكن.",null,"الطاقة الحركية تقاس فعلا بالجول مثل كل أنواع الطاقة."],"g":"انظر إلى إشارة كل من `m` و `v²` في `KE = mv²/2`، ثم فكر في إشارة حاصل ضربهما."}],"1-9":[{"h":["يبدو أنك طرحت الطاقتين بدل جمعهما.",null,"يبدو أنك ضربت الطاقتين بدل جمعهما.","يبدو أنك قسمت طاقة الوضع على الطاقة الحركية."],"g":"الطاقة الميكانيكية هي مجموع الطاقتين `ME = KE + PE`."},{"h":["طاقة الوضع تعتمد على الارتفاع، والارتفاع ينخفض أثناء السقوط.",null,"الارتفاع يتغير أثناء السقوط، فلا تبقى طاقة الوضع ثابتة.","طاقة الوضع تقاس من مستوى الإسناد، ولا تكون سالبة ما دام الجسم فوقه."],"g":"تذكر أن `PE = m·g·h`، فماذا يحدث لقيمة `h` أثناء السقوط؟"},{"h":[null,"الشغل يعرف بأنه القوة مضروبة في الإزاحة، ولا يتحدث عن بقاء الطاقة.","قانون نيوتن الأول يتحدث عن بقاء الجسم على حالته من السكون أو الحركة، لا عن الطاقة.","العبارة لا تعرف كمية جديدة، بل تصف ما يحدث لمقدار الطاقة."],"g":"العبارة تقول إن مقدار الطاقة يبقى كما هو ويتحول فقط من صورة إلى أخرى، فابحث عن المبدأ الذي يحمل هذا المعنى."},{"h":["يبدو أنك قسمت السرعة على `g` دون تربيعها.",null,"يبدو أنك نسيت القسمة على 2 في الطاقة الحركية.","هذا رقم السرعة نفسه، والارتفاع يحسب من تساوي الطاقتين."],"g":"ساو الطاقة الحركية على الأرض بطاقة الوضع في الأعلى: `v²/2 = g·h`، فالكتلة تختصر."},{"h":["الكرة عند أعلى نقطة تكون في أكبر ارتفاع، فلا تكون طاقتها حركية فقط.",null,"للكرة ارتفاع عن الأرض عند هذه النقطة، فطاقتها لا تنعدم.","الطاقة الحرارية لا تعبر عن ارتفاع الكرة، والسؤال عن الطاقة الميكانيكية."],"g":"عند أعلى نقطة يكون الارتفاع `h` أكبر ما يمكن، فأي طاقة تعتمد على الارتفاع؟"},{"h":["أدنى نقطة هي أقل ارتفاع، فطاقة الوضع فيها أقل ما يمكن.",null,"الطاقة الميكانيكية ثابتة في غياب الاحتكاك ولا تنعدم.","السرعة تنعدم عند طرفي الأرجحة، أما أدنى نقطة فيمر بها البندول مسرعا."],"g":"عند النزول تتحول طاقة الوضع إلى حركية، فأين يكتمل هذا التحول؟"},{"h":["يبدو أنك نسيت تسارع الجاذبية `g`.","يبدو أنك نسيت الكتلة أو أخذت نصف الارتفاع.",null,"يبدو أنك ضاعفت الناتج، والطاقة الحركية عند الأرض تساوي طاقة الوضع في البداية لا ضعفها."],"g":"بإهمال الهواء تتحول طاقة الوضع `m·g·h` كلها إلى طاقة حركية عند الأرض."},{"h":["الاحتكاك يعاكس الحركة ولا يضيف طاقة إلى الجسم.","الطاقة الميكانيكية تبقى ثابتة في النظام المعزول فقط، والاحتكاك قوة خارجية تجعله غير معزول.","الاحتكاك لا يرفع الجسم، فلا تتحول طاقته إلى طاقة وضع.",null],"g":"تذكر أن الطاقة لا تفنى، وأن الاحتكاك يسخن السطحين، فإلى أين تذهب الطاقة؟"}],"1-10":[{"h":["يبدو أنك جمعت القوة والمسافة، والشغل حاصل ضربهما لا مجموعهما.",null,"يبدو أنك قسمت القوة على المسافة، والقانون يضربهما.","يبدو أنك طرحت القوة من المسافة، والشغل حاصل ضرب لا فرق."],"g":"استخدم `W = F·x·cos θ`، والزاوية صفر لأن الإزاحة في اتجاه القوة."},{"h":["يبدو أنك ضربت الكتلة في السرعة دون تربيع السرعة.",null,"نسيت القسمة على 2 في قانون الطاقة الحركية.","يبدو أنك ضربت الكتلة في السرعة ثم قسمت على 2 دون تربيع السرعة."],"g":"عوض في `KE = mv²/2`، وربع السرعة قبل الضرب في الكتلة."},{"h":["ضربت الكتلة في الارتفاع فقط ونسيت تسارع الجاذبية `g`.",null,"يبدو أنك قسمت على 2، وقانون طاقة الوضع لا قسمة فيه على 2.","ضربت الكتلة في `g` فقط ونسيت الضرب في الارتفاع."],"g":"استخدم `PE = m·g·h` مع `g = 9.8 m/s²`."},{"h":["طرحت الطاقتين، والطاقة الميكانيكية مجموعهما.",null,"ضربت الطاقتين، والصحيح جمعهما.","قسمت إحدى الطاقتين على الأخرى، والصحيح جمعهما."],"g":"الطاقة الميكانيكية `ME = KE + PE`."},{"h":["قسمت الوزن على المسافة، والشغل حاصل ضربهما.",null,"جمعت الوزن والمسافة، والشغل حاصل ضربهما.","الجسم تحرك فعلا مسافة رأسية في اتجاه قوة الرفع، فلا يكون الشغل صفرا."],"g":"قوة الرفع تساوي الوزن وهي في اتجاه الإزاحة الرأسية، فاستخدم `W = F·x·cos θ` مع `θ = 0°`."},{"h":["طرحت الطاقتين، والصحيح جمعهما.",null,"ضربت الطاقتين، والطاقة الميكانيكية مجموعهما.","قسمت `60` على `40`، والصحيح جمع الطاقتين."],"g":"اجمع الطاقة الحركية وطاقة الوضع: `ME = KE + PE`."},{"h":["هذه طاقة الوضع وحدها، ونسيت إضافة الطاقة الحركية.","هذه الطاقة الحركية وحدها، ونسيت إضافة طاقة الوضع.",null,"يبدو أنك نسيت القسمة على 2 في الطاقة الحركية فحسبتها `12 J`."],"g":"احسب `PE = m·g·h` و `KE = mv²/2` كلا على حدة، ثم اجمعهما."},{"h":[null,"طاقة الوضع ترتبط بالارتفاع، والسؤال عن شغل القوة المحصلة الذي يغير سرعة الجسم.","حاصل ضرب الكتلة في السرعة ليس صورة من صور الطاقة، ولا يقاس بالجول.","القوة المحصلة تبذل شغلا كلما غيرت سرعة الجسم، فلا يكون شغلها صفرا دائما."],"g":"القوة المحصلة تغير سرعة الجسم، ففكر في صورة الطاقة التي تعتمد على السرعة."},{"h":["يبدو أنك ربعت فرق السرعتين `(6 − 2)²`، والصحيح طرح الطاقتين الحركيتين.",null,"نسيت القسمة على 2 في قانون الطاقة الحركية.","هذه الطاقة الحركية النهائية وحدها، ونسيت طرح الطاقة الابتدائية."],"g":"الشغل المحصل يساوي `KE` النهائية ناقص `KE` الابتدائية، واحسب كلا منهما من `KE = mv²/2`."},{"h":["استخدمت الارتفاع الابتدائي `2 m` وحده، والمطلوب الزيادة.","هذه طاقة الوضع كاملة عند الارتفاع النهائي، لا الزيادة فيها.","يبدو أنك جمعت الارتفاعين، والصحيح طرحهما.",null],"g":"الزيادة في طاقة الوضع تعتمد على فرق الارتفاع: `ΔPE = m·g·Δh`."}],"1-11":[{"h":["التسارع الموجب يحتاج إلى قوة محصلة في اتجاه الحركة، وهنا لا توجد قوة محصلة.","التسارع السالب يحتاج إلى قوة محصلة تعاكس الحركة، وهنا القوى متوازنة.",null,"`g` تسارع السقوط الحر تحت تأثير الوزن وحده، والقوى هنا متوازنة."],"g":"استخدم `F = m·a`: إذا انعدمت القوة المحصلة فماذا يبقى للتسارع؟"},{"h":[null,"المسافة طول المسار الفعلي، وليست الانتقال نفسه.","الإزاحة هي التغير في موضع الجسم، وليست الانتقال نفسه.","الطاقة هي القدرة على بذل شغل، ولا تعني الانتقال من مكان لآخر."],"g":"ابحث عن المصطلح الذي يصف عملية الانتقال نفسها، لا طول المسار ولا تغير الموضع."},{"h":[null,"يبدو أنك قسمت الكتلة على التسارع، والقانون يضربهما.","جمعت الكتلة والتسارع، والصحيح ضربهما.","يبدو أنك قسمت التسارع على الكتلة، والقانون يضربهما."],"g":"طبق قانون نيوتن الثاني `F = m·a`."},{"h":["النيوتن وحدة القوة، لا الطاقة.",null,"الواط وحدة القدرة، أي الشغل في الثانية، لا الطاقة نفسها.","الكيلوجرام وحدة الكتلة."],"g":"الطاقة تقاس بوحدة الشغل نفسها، أي `N·m`."},{"h":["الكمية القياسية لها مقدار فقط، والسرعة لها مقدار واتجاه.",null,"الكميات الأساسية مثل الطول والكتلة والزمن، والسرعة مشتقة من الإزاحة والزمن.","السرعة كمية فيزيائية تقاس بوحدة `m/s`."],"g":"اسأل نفسك: هل يكفي الرقم وحده لوصف السرعة، أم يلزم معه الاتجاه أيضا؟"},{"h":["`Vf` هي السرعة النهائية، والجسم المنطلق لا تكون سرعته النهائية منعدمة بالضرورة.",null,"الجسم ينطلق ويزيد سرعته، فتسارعه ليس منعدما.","الإزاحة تزداد مع الحركة، فلا تبقى منعدمة دائما."],"g":"عبارة «من السكون» تصف بداية الحركة، ففكر في أي سرعة تكون منعدمة."},{"h":["القوة دفع أو سحب يغير حالة الجسم الحركية، وليست القدرة على بذل الشغل.",null,"الإزاحة تغير في موضع الجسم، وليست قدرة على بذل شغل.","التسارع معدل تغير السرعة، ولا علاقة له بتعريف القدرة على بذل الشغل."],"g":"ابحث عن المفهوم الذي يقاس بالجول مثل الشغل نفسه."},{"h":[null,"يبدو أنك جمعت الكتلة والسرعة بدلا من ضرب الكتلة في مربع السرعة.","راجع الحساب: ربما أخطأت في نصف الكتلة، فاقسم `8` على 2 ثم اضرب في مربع السرعة.","نسيت القسمة على 2 في قانون الطاقة الحركية."],"g":"عوض في `KE = mv²/2`، وربع السرعة أولا."},{"h":["`N` وحدة القوة، لا الطاقة.",null,"`W` هنا رمز الواط، وهو وحدة القدرة لا الطاقة.","هذه وحدة حاصل ضرب الكتلة في السرعة، وليست وحدة طاقة لأن السرعة فيها غير مربعة."],"g":"الطاقة الحركية لها وحدة الشغل نفسها، أي `N·m`."},{"h":["الكتلة ليس لها اتجاه ولا تتغير بتغير المكان، وهذا الوصف أقرب إلى الوزن.",null,"الكتلة ثابتة فعلا، لكنها ليست متجهة لأنها لا اتجاه لها.","الكتلة لا تتغير بالجاذبية، فالذي يتغير بتغير `g` هو الوزن."],"g":"قارن الكتلة بالوزن: الوزن قوة لها اتجاه وتتغير بتغير `g`، والكتلة كمية المادة في الجسم."},{"h":["الإزاحة تغير في الموضع، لا تغير في السرعة.",null,"القوة سبب تغير السرعة، لكنها ليست معدل تغيرها.","الشغل حاصل ضرب القوة في الإزاحة، ولا يعبر عن معدل تغير السرعة."],"g":"ابحث عن الكمية التي وحدتها `m/s²`، أي سرعة مقسومة على زمن."},{"h":["يبدو أنك قسمت الكتلة على التسارع، والقانون يضربهما.","جمعت الكتلة والتسارع، والصحيح ضربهما.",null,"يبدو أنك قسمت التسارع على الكتلة، والقانون يضربهما."],"g":"السطح أملس فلا احتكاك، والقوة المحصلة `F = m·a`."},{"h":["هذه هي وحدة الجول نفسها، وهي الوحدة الأساسية للطاقة.","النيوتن في المتر وحدة الشغل، وهي تساوي الجول.","عند فك النيوتن إلى `kg·m/s²` وضربه في المتر نحصل على هذه الوحدة، فهي وحدة طاقة.",null],"g":"الطاقة تساوي قوة مضروبة في مسافة، فافحص كل وحدة: هل تمثل حاصل ضرب قوة في مسافة؟"},{"h":[null,"ضربت السرعة الابتدائية في الزمن كأن السرعة ثابتة، لكنها تتناقص حتى تتوقف السيارة.","قسمت السرعة على الزمن، وهذا مقدار التباطؤ بوحدة `m/s²` لا المسافة.","يبدو أنك أخذت التسارع موجبا، والسيارة تتباطأ فتسارعها سالب."],"g":"التسارع ثابت، فالمسافة تساوي متوسط السرعتين الابتدائية والنهائية مضروبا في الزمن، والسرعة النهائية عند التوقف منعدمة."}],"2-1":[{"h":["الكلفن وحدة لدرجة الحرارة في النظام الدولي، لا لكمية الحرارة.",null,"الدرجة المئوية وحدة لقياس درجة الحرارة، لا الطاقة المنتقلة.","الواط وحدة القدرة، أي الطاقة المنتقلة في كل ثانية."],"g":"الحرارة شكل من أشكال الطاقة، فابحث عن وحدة الطاقة في النظام الدولي المسماة باسم العالم جيمس."},{"h":["هذا عكس الاتجاه التلقائي، فالحرارة لا تنتقل وحدها نحو الجسم الأعلى حرارة.",null,"الحرارة تنتقل ما دام هناك فرق في درجة الحرارة بين الجسمين.","لو انتقلت بالتساوي في الاتجاهين لما تغيرت درجة حرارة أي جسم."],"g":"فكر في كوب شاي ساخن يترك في الغرفة: أي الجسمين يفقد الحرارة؟ الانتقال التلقائي يكون من الدرجة الأعلى إلى الأقل."},{"h":["لا توجد شمس في هذه العملية، فاليدان تدفآن حتى في الظلام.",null,"لا يحدث أي تفاعل نووي عند فرك اليدين.","لا يمر تيار كهربائي في اليدين عند فركهما."],"g":"الحرارة هنا ناتجة عن حركة سطحين متلامسين أحدهما على الآخر، فما اسم القوة التي تنشأ بينهما؟"},{"h":["السعر أكبر من الجول بعدة مرات، فلا يساوي جولا واحدا.",null,"الرقم 1000 يربط السعر بالسعر الغذائي (kcal)، لا السعر بالجول.","هذه قيمة الجول الواحد بالسعر تقريبا (`1 J ≈ 0.24 cal`)، أي أنك عكست التحويل."],"g":"تذكر المكافئ الميكانيكي للحرارة: السعر الواحد يساوي أكثر من أربعة جولات بقليل."},{"h":[null,"الصوت ليس من مصادر الطاقة الحرارية المذكورة في الحقيبة التدريبية.","المغناطيس لا ينتج حرارة بنفسه.","كلمة «فقط» تجعل الاختيار خاطئا، والضوء الأزرق ليس مصدرا مذكورا في القائمة."],"g":"راجع قائمة المصادر: باطن الأرض والاحتراق والاحتكاك والكهرباء، ومصدر طبيعي يضيء النهار."},{"h":["القوة دفع أو سحب وتقاس بالنيوتن، أما الحرارة فتقاس بالجول.",null,"الكتلة مقدار المادة وتقاس بالكيلوجرام، والحرارة لا تقاس بها.","الضغط قوة على وحدة المساحة ويقاس بالباسكال، لا بالجول."],"g":"انظر إلى وحدة الحرارة: الجول هو وحدة الشغل وما يماثله، فما الكمية التي تقاس بالجول؟"},{"h":["يبدو أنك ضربت في 4.186 بدل أن تقسم، والسعر أكبر من الجول فيكون عدد السعرات أصغر.",null,"راجع القسمة، فالناتج أكبر من هذا بعشر مرات، وربما أخطأت في موضع الفاصلة.","هذا هو العدد نفسه بالجول، ولم تجر أي تحويل."],"g":"السعر أكبر من الجول، فلتحويل الجول إلى سعرات اقسم على `4.186`."},{"h":["هذا مقدار السعر الواحد فقط، ونسيت الضرب في 1000.","يبدو أنك ضربت في 100 لا في 1000.",null,"هذا عدد السعرات في السعر الغذائي، لا عدد الجولات."],"g":"السعر الغذائي يساوي 1000 سعر، فاضرب قيمة السعر الواحد بالجول في 1000."},{"h":[null,"الكتلة لا تحدد انتقال الحرارة، فقد يتوقف الانتقال بين جسمين مختلفين في الكتلة.","قد يصل جسمان إلى الاتزان وطاقتاهما الداخلية مختلفتان، فالمهم هو درجة الحرارة.","لا يبرد الجسمان إلى الصفر، بل يتوقفان عند درجة مشتركة بينهما."],"g":"الحرارة تنتقل بسبب فرق درجة الحرارة، فمتى يختفي هذا الفرق؟ هذه الحالة هي الاتزان الحراري."},{"h":["لا يحدث انشطار أو اندماج للأنوية في محرك السيارة.","الاحتكاك يحدث بين أجزاء متحركة، أما الاحتراق فشيء مختلف.","المحرك لا يأخذ حرارته من باطن الأرض.",null],"g":"الاحتراق تفاعل بين الوقود والأكسجين ينتج مواد جديدة، فإلى أي نوع من المصادر ينتمي؟"},{"h":[null,"هذه القيمة لا تخرج من القانون، فراجع الضرب في 1.8 ثم جمع 32.","يبدو أنك جمعت 32 مباشرة دون أن تضرب في 1.8.","يبدو أنك ضربت في 1.8 ونسيت إضافة 32."],"g":"استخدم `F = 1.8·C + 32`: اضرب أولا ثم اجمع."},{"h":["يبدو أنك طرحت 20 من 273 بدل أن تجمع.",null,"هذه درجة تجمد الماء بالكلفن، ونسيت إضافة 20.","الرقم لم يتغير، والتحويل إلى الكلفن يحتاج إضافة 273."],"g":"القانون `K = C + 273`، فأضف القراءة المئوية إلى 273."},{"h":[null,"يبدو أنك قسمت على 1.5 لا على 1.8.","هذه القيمة أصغر من الصحيح، فراجع أنك طرحت 32 ثم قسمت على 1.8.","يبدو أنك طرحت 32 ونسيت القسمة على 1.8."],"g":"استخدم `C = (F − 32) / 1.8`: اطرح 32 أولا ثم اقسم."},{"h":[null,"غليان الماء على فهرنهايت عند `212°F` لا عند 32.","الصفر المطلق على فهرنهايت قيمة سالبة كبيرة، نحو `−459.4°F`.","حرارة جسم الإنسان نحو `98.6°F`، وهي أعلى بكثير."],"g":"حول `32°F` إلى المئوي بالقانون `C = (F − 32) / 1.8`، ثم تذكر ماذا يحدث للماء عند الناتج."},{"h":["عند `0°C` تكون القراءة على فهرنهايت `32°F`، فهما غير متساويين.","عند `100°C` تكون القراءة `212°F`، فهما غير متساويين.",null,"`32°F` تقابل `0°C`، فالقراءتان مختلفتان."],"g":"ضع `F = C = x` في `F = 1.8·C + 32` وحل المعادلة لإيجاد x."},{"h":[null,"يبدو أنك أضفت 273، وهذا تحويل إلى الكلفن لا إلى فهرنهايت.","يبدو أنك ضربت في 1.8 ونسيت إضافة 32.","لم تجر أي تحويل، والمقياسان لا يتساويان إلا عند قيمة سالبة."],"g":"اضرب القراءة المئوية في 1.8 ثم أضف 32."},{"h":["`0°C` درجة تجمد الماء، وهناك درجات أبرد منها كثيرا.",null,"الرقم 32 يخص مقياس فهرنهايت، ولا علاقة له بالصفر المطلق.","`100 K` أعلى من الصفر المطلق بمئة درجة، فالصفر المطلق هو `0 K`."],"g":"الصفر المطلق هو `0 K`، فحوله إلى المئوي بالقانون `C = K − 273`."},{"h":[null,"هذه قيمة الصفر المطلق بالمئوي، ولم تحولها إلى فهرنهايت.","يبدو أنك أضفت 32 دون أن تضرب في 1.8.","`32°F` درجة تجمد الماء، وهي أعلى بكثير من الصفر المطلق."],"g":"حول `0 K` إلى المئوي أولا، ثم استخدم `F = 1.8·C + 32`."},{"h":["هذه نقطة تساوي المئوي والفهرنهايت، لا الفهرنهايت والكلفن.","هذه درجة تجمد الماء بالكلفن، وعندها تكون القراءة `32°F`.",null,"يبدو أنك توقفت قبل القسمة على 0.8 في الخطوة الأخيرة."],"g":"عوض `C = K − 273` في `F = 1.8·C + 32`، ثم ضع `F = K = x` وحل المعادلة."},{"h":["100 قسم هو عدد أقسام المئوي والكلفن، لا فهرنهايت.","212 هي درجة غليان الماء على فهرنهايت، لا عدد الأقسام.","373 هي درجة غليان الماء بالكلفن، لا عدد أقسام فهرنهايت.",null],"g":"عدد الأقسام يساوي درجة الغليان مطروحا منها درجة التجمد على المقياس نفسه."},{"h":["هذا تحويل لقراءة درجة حرارة لا لفرق، فلا نضيف 273 ولا 32.",null,"جزء الكلفن صحيح، لكن إضافة 32 خطأ لأن المطلوب فرق لا قراءة.","جزء الفهرنهايت صحيح، لكن إضافة 273 خطأ لأن المطلوب فرق لا قراءة."],"g":"الفروق في درجة الحرارة تتأثر بحجم الدرجة فقط: درجة الكلفن بحجم الدرجة المئوية، والدرجة المئوية تساوي 1.8 درجة فهرنهايت."},{"h":["طاقة الحركة جزء منها فقط، فالجزيئات تمتلك طاقة وضع أيضا.",null,"درجة الحرارة مقياس لمتوسط طاقة الحركة، وليست هي الطاقة الداخلية.","الوزن قوة جذب الأرض للجسم، ولا علاقة له بطاقة الجزيئات."],"g":"تذكر أن الجزيئات تتحرك وتتجاذب، فالطاقة الداخلية تجمع نوعين من الطاقة."},{"h":["جسم صغير ساخن يعطي حرارة لجسم كبير بارد، فالكتلة لا تحدد الاتجاه.","الحجم لا يحدد الاتجاه، فقد تنتقل الحرارة من جسم صغير إلى جسم كبير.",null,"قد تكون الطاقة الداخلية لجسم بارد كبير أكبر، ومع ذلك تنتقل الحرارة إليه."],"g":"الحرارة تنتقل من الجسم الأسخن إلى الأبرد، فما الخاصية التي يقيسها الترمومتر؟"},{"h":["الارتفاع يحدث عند اكتساب حرارة لا عند فقدها.",null,"قد تثبت مؤقتا أثناء تغير الحالة فقط، لكن كلمة «أبدا» تجعل الاختيار خاطئا.","لا يوجد ما يجعلها تتضاعف، وفقد الحرارة يقلل الطاقة الداخلية."],"g":"فقد الحرارة يقلل الطاقة الداخلية للمادة، فماذا يحدث لدرجة حرارتها؟"}],"2-3":[{"h":[null,"يبدو أنك ضربت في 2 بدل 20، فالناتج أصغر بعشر مرات.","يبدو أنك استخدمت الكتلة `1 kg` بدل `0.1 kg`.","هذا ناتج `0.1 × 4180` فقط، ونسيت الضرب في التغير في درجة الحرارة."],"g":"عوض في `Q = m·c·ΔT` والكتلة بالكيلوجرام."},{"h":["هذه وحدة الحرارة النوعية c، لا السعة الحرارية C.",null,"هذه وحدة الحرارة الكامنة.","هذه الوحدة مقلوبة، فالسعة الحرارية جولات لكل درجة لا العكس."],"g":"السعة الحرارية `C = m·c`، فاضرب وحدة الكتلة في وحدة الحرارة النوعية واختصر kg."},{"h":[null,"هذه القيمة لا تخرج من القانون، فاقسم Q على حاصل ضرب m في ΔT.","يبدو أنك ضربت Q في m وفي ΔT بدل أن تقسم.","يبدو أنك قسمت على ΔT فقط ونسيت الكتلة."],"g":"أعد ترتيب `Q = m·c·ΔT` لتصبح `c = Q / (m·ΔT)` ثم عوض."},{"h":[null,"يبدو أنك قسمت c على C، والصحيح قسمة السعة الحرارية على الحرارة النوعية.","يبدو أنك ضربت القيمتين بدل أن تقسم.","راجع القسمة، فالناتج أكبر بعشر مرات من هذا."],"g":"من `C = m·c` نجد `m = C / c`."},{"h":["لو كانت صغيرة لبرد الماء بسرعة مثل المعادن.",null,"الكثافة لا تحدد سرعة التبريد هنا، والسبب يتعلق بخاصية حرارية.","اللون والشفافية لا علاقة لهما بسرعة فقد الحرارة."],"g":"الماء يحتاج حرارة كثيرة ليتغير درجة واحدة، فما الخاصية التي تقيس ذلك، وكيف قيمتها للماء مقارنة بالمعادن؟"},{"h":["هذا ناتج `2 × 460` فقط، ونسيت الضرب في 10.",null,"يبدو أنك استخدمت كتلة `1 kg` بدل `2 kg`.","راجع الضرب، فالناتج أكبر من هذا بمئة مرة."],"g":"عوض في `Q = m·c·ΔT` واضرب القيم الثلاث."},{"h":["الألمنيوم حرارته النوعية أكبر، فيحتاج حرارة أكثر لكل درجة، فيرتفع أقل.","الحرارتان النوعيتان مختلفتان، فلا يكون الارتفاع متساويا.",null,"يمكن المقارنة لأن الكتلة والحرارة متساويتان، والفرق في c فقط."],"g":"استخدم `ΔT = Q / (m·c)`: عند تساوي Q و m يكون الارتفاع أكبر للمادة ذات c الأصغر."},{"h":[null,"يبدو أنك قسمت على c فقط ونسيت الكتلة.","هذه القيمة ضعف الصحيح، فراجع القسمة على حاصل ضرب الكتلة في c.","يبدو أنك قلبت القسمة، فقسمت m·c على Q."],"g":"من `Q = m·c·ΔT` نجد `ΔT = Q / (m·c)`."},{"h":["يبدو أنك قسمت على 2 بدل أن تضرب.","هذه الحرارة النوعية لكل `1 kg`، ونسيت الضرب في الكتلة.","العدد صحيح لكن الوحدة خطأ، فوحدة kg اختصرت عند الضرب في الكتلة.",null],"g":"السعة الحرارية `C = m·c`، ووحدتها جول لكل درجة دون kg."},{"h":["يبدو أنك استخدمت `70°C` بدل الفرق بين الدرجتين.",null,"يبدو أنك استخدمت `20°C` بدل الفرق بين الدرجتين.","راجع الضرب، فالناتج أكبر من هذا بعشر مرات."],"g":"احسب `ΔT` أولا بطرح الدرجة الصغرى من الكبرى، ثم عوض في `Q = m·c·ΔT`."},{"h":[null,"يبدو أنك ضربت في 4 بدل أن تقسم.","يبدو أنك قسمت على 10 بدل 4.","راجع الأصفار، فالناتج أكبر من هذا بمئة مرة."],"g":"من `Q = m·H` نجد `H = Q / m`."},{"h":[null,"راجع الأصفار، فالناتج أكبر بعشر مرات.","يبدو أنك حولت 20 g إلى 0.2 kg، والصحيح القسمة على 1000.","هذا الناتج لا يطابق كتلة 20 g، فراجع تحويل الكتلة ثم الضرب في H."],"g":"حول الكتلة إلى kg ثم عوض في `Q = m·H` حيث `H = 336000 J/kg`."},{"h":["التبخر تحول السائل إلى غاز.",null,"التكثف تحول الغاز إلى سائل.","التجمد هو العكس: تحول السائل إلى صلب."],"g":"الثلج صلب والماء سائل، فما اسم تحول الصلب إلى سائل؟"},{"h":[null,"هذه وحدة السعة الحرارية.","هذه وحدة الحرارة النوعية، وفيها درجة الحرارة لأن c ترتبط بتغير الدرجة.","هذه وحدة درجة الحرارة، لا وحدة طاقة لكل كتلة."],"g":"من `H = Q / m` اقسم وحدة الطاقة على وحدة الكتلة، ولا تظهر درجة الحرارة لأنها ثابتة أثناء الانصهار."},{"h":["هذه حرارة رفع `1 kg` ماء درجة واحدة، لا حرارة صهر الجليد.",null,"273 رقم يخص التحويل إلى الكلفن، وليس طاقة.","هذه قيمة صغيرة جدا، وصهر الجليد يحتاج مئات الآلاف من الجولات."],"g":"الطاقة اللازمة لصهر 1 kg عند درجة الانصهار هي تعريف الحرارة الكامنة للانصهار، فتذكر قيمتها للجليد."},{"h":[null,"يبدو أنك ضربت في 2 بدل الضرب في 0.5.","هذا يشبه ناتج `0.5 × 4180`، والحرارة النوعية لا تستخدم في الانصهار.","راجع الأصفار، فالناتج أكبر بعشر مرات."],"g":"استخدم `Q = m·H` لأن درجة الحرارة ثابتة أثناء الانصهار."},{"h":["الامتصاص يحدث في الانصهار، أما التجمد فهو العملية العكسية.","4180 ترتبط بالحرارة النوعية للماء، لا بتغير الحالة.",null,"تغير الحالة يرافقه دائما تبادل حرارة كامنة."],"g":"التجمد عكس الانصهار: ما يمتص عند الانصهار يخرج بالمقدار نفسه عند التجمد."},{"h":["يبدو أنك قسمت H على Q بدل أن تقسم Q على H.","راجع الفاصلة العشرية، فالناتج أصغر من هذا بعشر مرات.","راجع الفاصلة العشرية، فالناتج أكبر من هذا بعشر مرات.",null],"g":"من `Q = m·H` نجد `m = Q / H`."}],"2-5":[{"h":["لو كانت أكبر لضاعت طاقة، والطاقة محفوظة في النظام المعزول.","لو كانت أقل لظهرت طاقة من لا شيء، وهذا يخالف حفظ الطاقة.",null,"الجسم الساخن يفقد حرارة فعلا حتى يبرد، فلا تكون كميتها صفرا."],"g":"تذكر أن الطاقة محفوظة: كل ما يفقده الجسم الساخن يذهب إلى الجسم البارد."},{"h":["الانصهار تحول المادة من صلب إلى سائل، ولا يحدث هنا تغير في الحالة.",null,"الحمل طريقة لانتقال الحرارة، وليس اسم الحالة النهائية للخليط.","الغليان تحول السائل إلى بخار، والخليط هنا يبقى سائلا."],"g":"ابحث عن اسم الحالة التي تتساوى فيها درجتا حرارة الجسمين بعد التلامس."},{"h":[null,"يبدو أنك طرحت الدرجتين `80 − 20`، والمطلوب متوسطهما لا فرقهما.","يبدو أنك جمعت الدرجتين ولم تقسم على 2.","الكتلتان متساويتان، فلا تقترب درجة الخليط من الماء البارد أكثر من الساخن."],"g":"عند خلط كتلتين متساويتين من المادة نفسها تكون درجة الخليط متوسط الدرجتين."},{"h":[null,"لو كانت صغيرة لتغيرت درجته بسرعة ولما خزن حرارة كثيرة.","الماء يتمدد عند تسخينه، والتمدد لا يتعلق بقدرته على تخزين الحرارة.","اللون لا علاقة له بكمية الحرارة التي يخزنها السائل."],"g":"فكر في الخاصية التي تحدد كمية الحرارة التي تخزنها المادة لكل درجة تغير في `Q = m·c·ΔT`."},{"h":["الكتلة لا تتغير بالتلامس، فكل جسم يحتفظ بكتلته.",null,"الطاقة الداخلية تعتمد على الكتلة ونوع المادة، فقد تختلف بين الجسمين بعد الاتزان.","الحرارة النوعية صفة ثابتة لكل مادة ولا تتساوى بالتلامس."],"g":"تذكر تعريف الاتزان الحراري: عند أي شيء يتوقف انتقال الحرارة بين الجسمين؟"},{"h":[null,"يبدو أنك جمعت `80 + 40` ولم تقسم على 2.","يبدو أنك طرحت `80 − 40`، والمطلوب المتوسط لا الفرق.","الكتلتان متساويتان، فلا يمكن أن تكون الدرجة أقرب إلى 40 منها إلى 80."],"g":"كتلتان متساويتان من الماء: درجة الخليط هي متوسط درجتي الحرارة."},{"h":["يبدو أنك أخذت المتوسط البسيط `(90 + 30) ÷ 2`، والكتلتان غير متساويتين.",null,"الخليط يقترب من الماء البارد لكثرته، لكن ليس بهذا القدر؛ أعد الحساب بالمتوسط الموزون.","الماء البارد كتلته أكبر، فيجب أن تقترب درجة الخليط منه لا من الساخن."],"g":"استعمل المتوسط الموزون بالكتل: `T = (m₁T₁ + m₂T₂) ÷ (m₁ + m₂)`."},{"h":["الماء البارد اكتسب حرارة فعلا، فقد ارتفعت درجته.","يبدو أنك قسمت الحرارة على 2، والحرارة لا تتوزع مناصفة بل تنتقل كلها إلى البارد.","يبدو أنك ضاعفت الحرارة، والطاقة لا تتضاعف في النظام المعزول.",null],"g":"في الوعاء المعزول الحرارة المفقودة من الساخن تساوي الحرارة المكتسبة للبارد."},{"h":[null,"الجسم الساخن يفقد حرارة ولا يكتسبها، فإشارته عكس إشارة البارد.","الجسم الساخن يفقد كمية حقيقية من الحرارة، فلا تكون كميته صفرا.","لو تشابهت الإشارتان لما أمكن أن يكون مجموعهما صفرا."],"g":"اتفقنا على أن الحرارة المكتسبة موجبة، فماذا تكون إشارة الحرارة المفقودة حتى يصبح المجموع صفرا؟"},{"h":["الترمومتر يقيس درجة الحرارة فقط ولا يعزل الخليط.","البارومتر جهاز لقياس الضغط الجوي.",null,"الأميتر جهاز لقياس شدة التيار الكهربائي."],"g":"ابحث عن الجهاز الذي يعزل الخليط عن الوسط المحيط حتى تتساوى الحرارة المفقودة والمكتسبة."},{"h":["التوصيل يحتاج تلامس جزيئات المادة، ولا يتم بالأشعة.","الحمل يحتاج حركة مائع ساخن، ولا يتم بالأشعة.",null,"الانصهار تغير في حالة المادة وليس طريقة لانتقال الحرارة."],"g":"الطاقة هنا تنتقل على شكل موجات كهرومغناطيسية، مثل حرارة الشمس."},{"h":["التوصيل ينقل الحرارة بين جزيئات متلامسة دون حركة المادة، والهواء في المنطاد يتحرك.",null,"المنطاد يرتفع بحركة الهواء الساخن نفسه، لا بموجات كهرومغناطيسية.","المنطاد مثال واضح على إحدى طرق انتقال الحرارة المذكورة."],"g":"الهواء الساخن داخل المنطاد تقل كثافته فيرتفع، فأي طريقة تعتمد على حركة المائع نفسه؟"},{"h":["التوصيل يحتاج مادة تتلامس جزيئاتها، والفراغ لا مادة فيه.","الحمل يحتاج مائعا يتحرك، والفراغ لا مادة فيه.",null,"طريقتان من الثلاث تحتاجان وسطا ماديا، فلا تعمل كلها في الفراغ."],"g":"فكر في كيفية وصول حرارة الشمس إلى الأرض عبر الفضاء الخالي."},{"h":[null,"الحمل يحدث في السوائل والغازات، والقضيب المعدني صلب لا تتحرك مادته.","الحرارة هنا تنتقل داخل المادة بالتلامس، لا بموجات عبر الفراغ.","التبخر تحول السائل إلى غاز وليس طريقة لانتقال الحرارة في قضيب."],"g":"في المادة الصلبة تنقل الجزيئات المهتزة الطاقة إلى جاراتها دون أن تنتقل المادة."},{"h":[null,"الهواء البارد أكبر كثافة فلا يرتفع، بل يحدث العكس.","الإشعاع ينتشر في كل الاتجاهات، والسبب هنا يتعلق بحركة الهواء.","الهواء ضعيف التوصيل، والسبب هنا هو تيارات الحمل."],"g":"قارن كثافة الهواء البارد بكثافة الهواء الساخن، وفكر في تيارات الحمل."},{"h":["لو كان موصلا جيدا لسخن المقبض وأحرق اليد.",null,"المطلوب منع وصول الحرارة إلى اليد بالتلامس، لا امتصاص الإشعاع.","خفة الوزن ميزة، لكنها ليست سبب اختيار الخشب للمقبض."],"g":"فكر في كيف تصل حرارة القدر إلى اليد عبر المقبض، وما الذي يمنعها."},{"h":["لو كانا عازلين لما وصلت حرارة اللهب إلى الطعام بسرعة.",null,"القاع يلامس اللهب، والمهم فيه نقل الحرارة بالتلامس لا عكس الإشعاع.","المعادن تتمدد بالحرارة، والتمدد ليس سبب اختيارهما."],"g":"قاع القدر يجب أن ينقل حرارة اللهب إلى الطعام بسرعة عن طريق التلامس."},{"h":["الهواء الساخن تقل كثافته فلا يهبط، بل يحدث العكس.","الإشعاع ينتشر في كل الاتجاهات، والسبب هنا يتعلق بحركة الهواء.",null,"الهواء ضعيف التوصيل، والتدفئة في الغرفة تتم أساسا بحركة الهواء."],"g":"قارن كثافة الهواء الساخن بالبارد، وفكر في الاتجاه الذي يتحرك فيه كل منهما."},{"h":[null,"ليست كل المواد الصلبة موصلة جيدة، والتوصيل لا علاقة له بغياب الحمل.","امتصاص الإشعاع لا علاقة له بشرط حدوث الحمل.","الكثافة الكبيرة ليست السبب، فالحمل يحتاج مادة تتحرك وتنساب."],"g":"تذكر أن الحمل يتطلب انتقال المادة الساخنة نفسها من مكان إلى آخر."},{"h":["الإشعاع يعبر الفراغ، لذلك تطلى الجدران بطبقة لامعة لتقليله.","التبخر تغير في حالة المادة وليس طريقة لانتقال الحرارة عبر الجدار.","الانصهار تغير في حالة المادة وليس طريقة لانتقال الحرارة.",null],"g":"الفراغ لا يحتوي مادة، فأي طرق انتقال الحرارة تحتاج وسطا ماديا؟"}],"2-7":[{"h":["يبدو أنك طرحت 200 من 273، والصحيح أن تضيف 273 إلى درجة سلسيوس.",null,"هذه قيمة `200°C` على مقياس فهرنهايت (`1.8 × 200 + 32`)، والمطلوب الكلفن.","لم تضف شيئا؛ الصفر المئوي يقابل `273 K` لا `0 K`."],"g":"حول من سلسيوس إلى كلفن بإضافة 273: `K = C + 273`."},{"h":[null,"يبدو أنك نسيت إضافة 32 بعد الضرب في 1.8.","يبدو أنك أضفت 32 إلى 150 ولم تضرب في 1.8.","يبدو أنك طرحت 32 من 150، وهذا من قانون التحويل العكسي."],"g":"استعمل `F = 1.8C + 32`: اضرب أولا ثم أضف 32."},{"h":[null,"يبدو أنك قسمت 80 على 1.8 دون أن تطرح 32 أولا.","هذا ناتج الطرح `80 − 32` فقط، وبقي أن تقسم على 1.8.","يبدو أنك أضفت 32 بدلا من أن تطرحها، ولم تقسم على 1.8."],"g":"اطرح 32 من درجة فهرنهايت أولا، ثم اقسم الناتج على 1.8."},{"h":["يبدو أنك قسمت 460 على 0.5 بدلا من أن تضرب.",null,"يبدو أنك جمعت الكتلة والحرارة النوعية، والصحيح ضربهما.","يبدو أنك قسمت الكتلة على الحرارة النوعية، والصحيح ضربهما."],"g":"السعة الحرارية `C = m·c`: اضرب الكتلة في الحرارة النوعية."},{"h":[null,"يبدو أنك قسمت 80 على 1.8 دون أن تطرح 32 أولا.","يبدو أنك أضفت 32 بدلا من أن تطرحها.","يبدو أنك استعملت قانون التحويل من سلسيوس إلى فهرنهايت، والمعطى هنا بالفهرنهايت."],"g":"التحويل إلى سلسيوس: `C = (F − 32) ÷ 1.8`."},{"h":[null,"يبدو أنك أخطأت في الفاصلة العشرية فصغر الناتج مئة مرة.","يبدو أنك نسيت الضرب في الكتلة `0.02 kg`.","الناتج أصغر من المطلوب، فتأكد أنك ضربت في التغير الكامل في درجة الحرارة `60°C`."],"g":"عوض في `Q = m·c·ΔT` والكتلة بالكيلوجرام."},{"h":["يبدو أنك استعملت حرارة الانصهار `336000 J/kg` بدل الحرارة النوعية للحديد.",null,"يبدو أنك نسيت الضرب في كتلة الحديد `3 kg`.","يبدو أنك أخطأت في عدد الأصفار عند الضرب."],"g":"الحديد برد من 560 إلى 0، فعوض في `Q = m·c·ΔT` بكتلة الحديد وحرارته النوعية."},{"h":["يبدو أنك قسمت H على Q، والصحيح `m = Q ÷ H`.","راجع الفاصلة العشرية؛ الناتج أكبر من الصحيح عشر مرات.","هذه كتلة لوح الجليد كله، والحرارة لا تكفي لصهره كله.",null],"g":"كمية الحرارة اللازمة للانصهار `Q = m·H`، فاقسم الحرارة على حرارة الانصهار."},{"h":[null,"هذا تعريف الحرارة النوعية، فهي تخص كيلوجراما واحدا من المادة.","التعريف لا يخص جراما واحدا، والحرارة النوعية نفسها تخص الكيلوجرام.","التعريف يخص رفع الدرجة بمقدار درجة واحدة لا حتى الغليان."],"g":"فرق بين السعة الحرارية التي تخص الجسم بأكمله والحرارة النوعية التي تخص وحدة الكتلة: `C = m·c`."},{"h":["هذا ناتج الضرب `1.8 × (−20)` فقط، وبقي أن تضيف 32.","انتبه للإشارة: ناتج `−36 + 32` سالب لا موجب.",null,"هذه الدرجة بالكلفن (`−20 + 273`)، والمطلوب فهرنهايت."],"g":"عوض في `F = 1.8C + 32` مع الانتباه لإشارة السالب."}],"2-8":[{"h":[null,"الحمل يحتاج حركة المادة نفسها، ولا يحدث في المادة الصلبة.","الإشعاع موجات لا تحتاج تلامسا، والسؤال عن انتقال بالتلامس.","التبخر تغير في حالة السائل وليس طريقة لانتقال الحرارة."],"g":"الكلمة المفتاحية «بالتلامس» في مادة صلبة: الجزيئات تنقل الطاقة لجاراتها دون أن تنتقل."},{"h":["كتلة الزئبق لا تتغير بالتسخين، فلا يمكن أن تقاس بها الحرارة.",null,"الزئبق سائل لا غاز، فالمبدأ يتعلق بالسائل الموجود في الأنبوب.","لون الزئبق ثابت ولا يتغير بالحرارة."],"g":"راقب ما يحدث لعمود الزئبق في الأنبوب عند التسخين: لماذا يرتفع؟"},{"h":[null,"هاتان النقطتان على مقياس فهرنهايت لا على المقياس المئوي.","هاتان النقطتان على مقياس كلفن لا على المقياس المئوي.","هاتان القيمتان لا تقابلان تجمد الماء وغليانه على المقياس المئوي."],"g":"النقطتان الثابتتان هما تجمد الماء النقي وغليانه عند الضغط الجوي المعتاد."},{"h":["هذا عكس الاتجاه الطبيعي، فالحرارة لا تنتقل تلقائيا نحو الأسخن.",null,"الكتلة لا تحدد الاتجاه، بل الفرق في درجة الحرارة.","الحرارة تنتقل تلقائيا دون أي جهاز ما دام هناك فرق في الدرجة."],"g":"اتجاه انتقال الحرارة تحدده درجة الحرارة: من الدرجة الأعلى إلى الأقل."},{"h":["الضوء يصل من المصباح دون تلامس مادي، فلا يكون توصيلا.","الضوء لا يحتاج حركة هواء ساخن ليصل إليك.",null,"الانصهار تغير في حالة المادة وليس طريقة لانتقال الطاقة."],"g":"الضوء موجات كهرومغناطيسية؛ فأي طريقة انتقال تعتمد على هذه الموجات؟"},{"h":[null,"راجع الضرب `1.8 × 42` ثم أضف 32 بدقة.","هذه قيمة `35°C` على فهرنهايت، لا قيمة `42°C`.","هذا ناتج الضرب في 1.8 فقط، ونسيت إضافة 32."],"g":"استعمل `F = 1.8C + 32` بالترتيب: اضرب ثم أضف."},{"h":[null,"هذه قيمة `30°C`، فيبدو أنك أخطأت في طرح 273 من 300.","يبدو أنك عوضت بـ 300 مباشرة كأنها سلسيوس، ونسيت طرح 273 أولا.","هذه الدرجة بالسلسيوس، وبقي تحويلها إلى فهرنهايت."],"g":"حول الكلفن إلى سلسيوس أولا بطرح 273، ثم إلى فهرنهايت بـ `F = 1.8C + 32`."},{"h":["انكماش الزجاج صغير جدا، والمقياس يعتمد على ما يحدث للسائل داخله.",null,"الكحول يبقى في أنبوب مغلق ولا يعتمد القياس على تبخره.","لون الكحول مجرد صبغة لتسهيل القراءة ولا يتغير بالحرارة."],"g":"الترمومتر الكحولي يعمل بالمبدأ نفسه الذي يعمل به الترمومتر الزئبقي."},{"h":["تجمد الماء على مقياس فهرنهايت عند `32°F`.",null,"حرارة الجسم نحو `37°C` أي قرابة `98.6°F`.","الصفر المطلق هو `0 K`، ويقابل قيمة سالبة كبيرة على فهرنهايت."],"g":"حول `212°F` إلى سلسيوس بـ `C = (F − 32) ÷ 1.8` ثم تذكر ما يحدث للماء عند هذه الدرجة."},{"h":["يبدو أنك قسمت القدرة على الزمن، والصحيح ضربهما.","يبدو أنك جمعت القدرة والزمن، والصحيح ضربهما.","راجع الأصفار في حاصل الضرب `500 × 60`.",null],"g":"الطاقة التي يعطيها السخان `E = P·t`."},{"h":["الناتج أصغر من اللازم؛ تأكد أنك ضربت في التغير كاملا `20°C` وقسمت على القدرة مرة واحدة.",null,"راجع القسمة على القدرة؛ يبدو أنك قسمت على 100 لا على 1000.","يبدو أنك نسيت الضرب في التغير في درجة الحرارة `20°C`."],"g":"ساو طاقة السخان بحرارة الماء: `P·t = m·c·ΔT` ثم اعزل `t`."},{"h":[null,"بعد التحويل `(120 − 32) ÷ 1.8 ≈ 48.9°C`، فليست الأعلى.","بطرح 273 تساوي `47°C`، فليست الأعلى.","حول الدرجات كلها إلى مقياس واحد وستجدها مختلفة."],"g":"حول كل الدرجات إلى سلسيوس ثم قارن بينها."},{"h":["الكتلة قلت لا زادت، والزمن يتناسب طرديا معها.","الكتلة الأقل تحتاج حرارة أقل، فلا بد أن يتغير الزمن.",null,"الزمن يتناسب مع الكتلة نفسها لا مع مربعها."],"g":"من `t = m·c·ΔT ÷ P` لاحظ العلاقة بين الزمن والكتلة عند ثبات بقية المقادير."}],"3-3":[{"h":["الخطوط تدخل في الشحنة السالبة ولا تخرج منها.",null,"للخطوط اتجاه محدد، فهي تخرج من نوع واحد من الشحنات وتدخل في النوع الآخر.","الخطوط تبدأ فعلا من شحنة وتنتهي عند شحنة أخرى، فهي تخرج من إحداهما."],"g":"تذكر أن اتجاه خطوط المجال هو اتجاه القوة على شحنة اختبار موجبة، فمن أي شحنة تبتعد؟"},{"h":["شدة الشحنات تظهر في تقارب الخطوط، وليس في تقاطعها.",null,"في المجال المنتظم تكون الخطوط متوازية، والخطوط المتوازية لا تلتقي.","الخطوط تدخل في الشحنة السالبة ولا تخرج منها."],"g":"فكر: لو التقى خطان في نقطة، فكم اتجاها سيكون للمجال عندها؟"},{"h":[null,"يبدو أنك ضربت القوة في الشحنة، والقانون قسمة القوة على الشحنة.","راجع قسمة قوى العشرة: `10⁻⁶ ÷ 10⁻⁹` تعني طرح الأسس، أي `−6 − (−9)`.","يبدو أنك قسمت الشحنة على القوة وأهملت قوى العشرة، والصحيح قسمة القوة على الشحنة."],"g":"استخدم `E = F / q` بعد تحويل nC إلى C بالضرب في `10⁻⁹`، ثم اطرح الأسس عند القسمة."},{"h":["يبدو أنك قسمت على 0.3 لا على مربعها، والمسافة في القانون مربعة.",null,"يبدو أنك قسمت على 0.03 بدلا من مربع 0.3 وهو `0.09 m²`.","هذا ناتج البسط فقط `9 × 10⁹ × 5 × 10⁻⁹`، ولم تقسم على مربع المسافة."],"g":"عوض في `E = k·q / r²` بعد تحويل nC إلى C، وتأكد من تربيع المسافة."},{"h":["كلمة منتظم تشمل الاتجاه أيضا، فلا يتغير اتجاهه من نقطة لأخرى.",null,"المجال المنتظم لا تتغير شدته من نقطة لأخرى.","المجال المنتظم موجود فعلا وله شدة، مثل المجال بين لوحي مكثف."],"g":"تذكر شكل خطوطه بين لوحي المكثف: مستقيمة متوازية متساوية التباعد، فماذا يعني ذلك للشدة والاتجاه؟"},{"h":["الحركة عكس الخطوط تخص الشحنة السالبة مثل الإلكترون.",null,"القوة على الشحنة تكون على امتداد خط المجال لا عمودية عليه.","المجال يؤثر بقوة على أي شحنة توضع فيه، فلا تبقى ساكنة."],"g":"تذكر أن اتجاه المجال يعرف بأنه اتجاه القوة على شحنة اختبار موجبة."},{"h":[null,"يبدو أنك قسمت على 0.3 لا على مربعها، والمسافة في القانون مربعة.","يبدو أنك قسمت على 0.9 بدلا من 0.09، فراجع تربيع 0.3.","الناتج كبير جدا، فراجع المقام: مربع `0.3 m` هو `0.09 m²` وليس `0.01 m²`."],"g":"عوض في `E = k·q / r²`: حول nC إلى C وربع المسافة قبل القسمة."},{"h":["الشغل لكل وحدة شحنة هو تعريف فرق الجهد لا المجال.",null,"الشحنة لكل وحدة جهد تصف السعة، لا المجال.","المجال ناتج قسمة لا ضرب، ووحدته `N/C` تدل على ذلك."],"g":"انظر إلى وحدة المجال `N/C`: نيوتن مقسوم على كولوم، فما الذي يقسم على ماذا؟"},{"h":["خطوط المجال الكهربائي تبدأ من شحنة وتنتهي عند أخرى، فلا تكون دوائر مغلقة.","خطوط المجال لا تتقاطع أبدا في أي مجال.",null,"الانحناء والتباعد من صفات مجال الشحنة النقطية غير المنتظم."],"g":"المجال بين لوحين متوازيين منتظم، ففكر كيف ترسم خطوطا تعبر عن شدة واتجاه ثابتين."},{"h":["الشدة تقل مع البعد ولا تزيد.","هذا يصح لو كانت الشدة تتناسب مع `1/r`، لكن المسافة في القانون مربعة.","الشدة تقل بالابتعاد عن الشحنة، فلا يمكن أن تزيد.",null],"g":"في `E = k·q / r²` عوض بـ `2r` بدل `r` وانظر ماذا يحدث للمقام."},{"h":[null,"هذا اتجاه القوة على الشحنة الموجبة، وشحنة الإلكترون سالبة.","القوة الكهربائية تكون على امتداد خط المجال لا عمودية عليه.","أي شحنة في مجال كهربائي تتأثر بقوة `F = q·E`، والإلكترون مشحون."],"g":"تذكر أن المجال يعرف باتجاه القوة على الشحنة الموجبة، ثم انظر إلى إشارة شحنة الإلكترون."}],"3-4":[{"h":[null,"يبدو أنك ضربت في 0.1 بدلا من 0.01، فراجع عدد الأصفار في المسافة.","يبدو أنك ضربت في 0.001، فراجع قيمة المسافة المعطاة.","يبدو أنك قسمت الشدة على المسافة بدلا من الضرب فيها."],"g":"في المجال المنتظم استخدم `ΔV = E·d` واضرب الشدة في المسافة بالمتر."},{"h":[null,"يبدو أنك ربعت المسافة، والمسافة في قانون الجهد غير مربعة.","هذا ناتج البسط فقط `9 × 10⁹ × 2 × 10⁻⁶`، ولم تقسم على المسافة.","يبدو أنك ضربت 9 في 2 وأهملت قوى العشرة والقسمة على المسافة."],"g":"استخدم `V = k·q / r` بعد تحويل µC إلى C، ولاحظ أن المسافة هنا غير مربعة."},{"h":[null,"هذا مقلوب الوحدة المطلوبة؛ الجهد طاقة مقسومة على شحنة لا العكس.","هذه وحدة شدة المجال الكهربائي.","الجهد ناتج قسمة لا ضرب."],"g":"من `V = PE / q₀`: وحدة الطاقة مقسومة على وحدة الشحنة."},{"h":["يبدو أنك ضربت الشغل في الشحنة، والقانون قسمة.",null,"يبدو أنك جمعت الشغل والشحنة، والقانون قسمة.","يبدو أنك طرحت الشحنة من الشغل، والقانون قسمة."],"g":"استخدم `ΔV = W / q₀`: اقسم الشغل بالجول على الشحنة بالكولوم."},{"h":[null,"هذا جهد كبير جدا يناسب كهرباء المنازل لا بطارية صغيرة.","هذا جهد عال جدا؛ حتى بطارية السيارة جهدها `12 V` فقط.","هذا جهد صغير جدا لا يكفي لتشغيل جهاز."],"g":"تذكر شريحة تطبيقات من الحياة: البطارية الصغيرة جهدها أقل بكثير من بطارية السيارة `12 V`."},{"h":["لو قسمت `N/C` على المتر لما حصلت على الفولت؛ تحقق من الوحدات.",null,"المسافة في هذه العلاقة غير مربعة، والتربيع يخص قانون المجال حول شحنة نقطية.","هذا مقلوب العلاقة؛ تحقق من أن الناتج يخرج بوحدة الفولت."],"g":"تذكر أن `N/C` تكافئ `V/m`، فما العملية بين الشدة والمسافة التي تعطي فولتا؟"},{"h":["القوة لكل وحدة شحنة هي شدة المجال الكهربائي.","هذه العبارة مقلوبة ولا تمثل الجهد؛ تذكر أن الفولت يساوي جول لكل كولوم.",null,"الجهد ناتج قسمة لا ضرب."],"g":"انظر إلى القانون `V = PE / q₀` واقرأه بالكلمات."},{"h":[null,"يبدو أنك ربعت المسافة، والمسافة في قانون الجهد غير مربعة.","هذا ناتج البسط فقط `9 × 10⁹ × 3 × 10⁻⁹`، ولم تقسم على المسافة.","يبدو أنك قسمت على 3 بدلا من 0.3."],"g":"عوض في `V = k·q / r` بعد تحويل nC إلى C، والمسافة غير مربعة."},{"h":["الوحدة مقسومة على المتر لا مضروبة فيه، لأن الشدة فرق جهد مقسوم على مسافة.","الجول لكل متر وحدة قوة (نيوتن)، لا وحدة مجال.","الكولوم لكل فولت وحدة السعة، لا وحدة المجال.",null],"g":"اكتب `E = ΔV / d` وعوض بوحدتي فرق الجهد والمسافة."},{"h":["الجهد يقل بالابتعاد عن الشحنة ولا يزيد.",null,"هذا يصح للمجال لأن فيه `r²`، أما الجهد ففيه `r` غير مربعة.","الجهد يعتمد على البعد `r`، فلا يبقى ثابتا."],"g":"في `V = k·q / r` عوض بـ `2r` بدل `r` ولاحظ أن المسافة غير مربعة."}],"3-5":[{"h":[null,"يبدو أنك ضربت الشحنة في الجهد، والسعة ناتج قسمة لا ضرب.","راجع الأسس: `150 = 1.5 × 10²`، فلا بد أن يتغير الأس عند القسمة.","يبدو أنك قسمت الجهد على الشحنة، والصحيح العكس."],"g":"استخدم تعريف السعة `C = q / V`، واكتب `150` بالصيغة العلمية ثم اطرح الأسس."},{"h":["الزيادة تحدث عند تكبير المساحة، أما المسافة فهي في مقام القانون.",null,"المسافة تدخل في قانون السعة، فتغييرها يغير السعة.","السعة تتغير تدريجيا مع المسافة ولا تنعدم بمجرد زيادتها."],"g":"انظر أين تقع `d` في القانون `C = ε₀·A / d`: في البسط أم في المقام؟"},{"h":[null,"يبدو أنك قسمت السعة على الجهد، والشحنة حاصل ضربهما.","يبدو أنك قسمت الجهد على السعة دون تحويل الوحدة، والمطلوب ضرب لا قسمة.","نسيت تحويل µF إلى F بالضرب في `10⁻⁶`، فخرج الناتج كبيرا جدا."],"g":"من `C = q / V` تكون `q = C·V`، وحول `27 µF` إلى فاراد أولا."},{"h":[null,"المكثف لا يصمم لتوليد الحرارة، وفوائده أوسع من ذلك.","قياس الكتلة لا علاقة له بالمكثف، فهو جهاز كهربائي يتعامل مع الشحنة.","المكثف لا يعمل كمقاوم، فهو يحفظ الشحنة بين لوحيه."],"g":"تذكر ما يحدث للشحنة بين لوحي المكثف: تبقى محفوظة حتى تستخدم لاحقا."},{"h":[null,"يبدو أنك ضربت الشحنة في الجهد بدل القسمة.","يبدو أنك قسمت الجهد على الشحنة، والسعة شحنة مقسومة على جهد.","نسيت الأس `10⁻⁴` في الشحنة، فخرج الناتج كبيرا جدا."],"g":"طبق `C = q / V`: اقسم الأعداد ثم انتبه للأس."},{"h":["المساحة في بسط القانون، فلا تنقص السعة بزيادتها.",null,"المساحة تدخل في قانون السعة، فتغييرها يغير السعة.","السعة لا تنعدم بتكبير المساحة، بل تتأثر بها طرديا."],"g":"انظر إلى موضع `A` في `C = ε₀·A / d`: في البسط أم في المقام؟"},{"h":["هذا مقلوب الوحدة المطلوبة، فالسعة شحنة على جهد لا جهد على شحنة.","حاصل ضرب الكولوم في الفولت وحدة طاقة لا سعة.",null,"الجول لكل كولوم هو الفولت نفسه، أي وحدة الجهد."],"g":"عبر عن تعريف السعة بالوحدات: الشحنة بالكولوم والجهد بالفولت."},{"h":["الوضع معكوس: اللوحان يجب أن يحملا الشحنة، والعازل لا يحملها.",null,"المكثف يحتاج لوحين متقابلين يحملان شحنتين متعاكستين.","الملف النحاسي ليس مكثفا، والمكثف يتكون من ألواح متقابلة."],"g":"فكر: أين تستقر الشحنات، وما الذي يمنع مرورها من لوح إلى آخر؟"},{"h":[null,"هذا ناتج قسمة لا ضرب، والشحنة حاصل ضرب السعة في الجهد.","يبدو أنك قسمت السعة على الجهد بدل الضرب.","نسيت تحويل µF إلى F بالضرب في `10⁻⁶`."],"g":"استخدم `q = C·V` بعد تحويل µF إلى F بالضرب في `10⁻⁶`."},{"h":["لون الطلاء لا يدخل في قانون السعة.","كتلة الأسلاك لا تغير أبعاد المكثف ولا العازل بين لوحيه.","التيار لا يدخل في قانون السعة، فالسعة صفة في المكثف نفسه.",null],"g":"ابحث عن عامل يظهر في قانون السعة `C = ε₀·εᵣ·A / d`."}],"3-6":[{"h":["الجهد يتوزع على المكثفات في التوالي، ولا يتساوى إلا إذا تساوت السعات.",null,"السعات يحددها صنع كل مكثف وقد تختلف من مكثف لآخر.","الطاقة تعتمد على جهد كل مكثف، والجهود مختلفة فتختلف الطاقات."],"g":"تخيل مسارا واحدا: ما يدفع إلى لوح المكثف الأول يحث مقدارا مساويا على لوح الثاني."},{"h":["هذا ناتج قانون التوالي، والمكثفان هنا على التوازي.","يبدو أنك طرحت السعتين، وفي التوازي لا نطرح.",null,"راجع العملية: يبدو أنك ضربت أحد العددين بدل تطبيق قانون التوازي."],"g":"في التوازي تكون `C_total = C₁ + C₂`."},{"h":["هذا ناتج قانون التوازي، والمكثفان على التوالي.",null,"حسبت البسط فقط، ونسيت القسمة على مجموع السعتين.","هذا متوسط السعتين، وقانون التوالي ليس متوسطا."],"g":"لمكثفين على التوالي `C = C₁·C₂ / (C₁ + C₂)`، والناتج أصغر من أصغرهما."},{"h":["هذه صفة التوصيل على التوازي.",null,"السعة المكافئة لا تحسب بالمتوسط.","مجموع السعات هو قانون التوازي لا التوالي."],"g":"في التوالي تجمع المقلوبات `1/C = 1/C₁ + 1/C₂`، ففكر: إذا كبر المقلوب فماذا يحدث للسعة نفسها؟"},{"h":["هذا ناتج قانون التوالي، والسؤال عن التوازي.",null,"يبدو أنك ضربت السعتين بدل جمعهما.","يبدو أنك طرحت السعتين، وفي التوازي لا نطرح."],"g":"في التوازي `C_total = C₁ + C₂`."},{"h":["الشحنات في التوازي تتوزع حسب سعة كل مكثف، فتختلف.",null,"السعات قد تختلف من مكثف لآخر حسب صنعه.","الطاقة تعتمد على السعة أيضا، فتختلف باختلاف السعات."],"g":"طرفا كل مكثف متصلان مباشرة بقطبي المصدر نفسه، ففكر في الكمية التي يفرضها المصدر على كل مكثف."},{"h":["هذا ناتج جمع السعات، وهو قانون التوازي.",null,"السعة المكافئة في التوالي أصغر من أصغر سعة، فلا تساوي سعة مكثف واحد.","يبدو أنك أخطأت في جمع المقلوبات، فمجموع ثلاثة مقلوبات متساوية ثلاثة أضعاف المقلوب الواحد."],"g":"اجمع المقلوبات `1/C = 1/9 + 1/9 + 1/9` ثم اقلب الناتج."},{"h":["لا سبب لأن تساوي الشحنة الكلية شحنة أصغر المكثفات.",null,"الشحنات في التوازي تختلف حسب السعات، فلا تساوي الكلية شحنة مكثف واحد.","المصدر يزود المكثفات بشحنة فعلية، فلا تكون الكلية صفرا."],"g":"فكر في الشحنة التي سحبها المصدر: إلى أين ذهبت وكيف توزعت على المكثفات؟"},{"h":["هذا ناتج جمع السعتين، وهو قانون التوازي لا التوالي.","يبدو أنك طرحت السعتين، وليس في قانون التوالي طرح.",null,"حسبت البسط فقط، ونسيت القسمة على مجموع السعتين."],"g":"لمكثفين على التوالي: حاصل ضرب السعتين مقسوما على مجموعهما."},{"h":[null,"التوالي يجعل السعة المكافئة أصغر من أصغر سعة.","فصل البطارية لا يغير السعة، والتوالي يقلل السعة الكلية.","المصدر لا يغير السعة، والتوالي يقلل السعة الكلية مهما كان جهد المصدر."],"g":"اختر التوصيل الذي تجمع فيه السعات مباشرة، ويكافئ زيادة مساحة الألواح."},{"h":["هذا جهد المكثف الأول وحده.","هذا جهد المكثف الثاني وحده.","يبدو أنك قسمت الجهدين، وفي التوالي يتوزع جهد المصدر على المكثفات.",null],"g":"في التوالي `V = V₁ + V₂`."},{"h":[null,"يبدو أنك ضربت السعة في الجهد فقط، ونسيت النصف وتربيع الجهد.","يبدو أنك نسيت تربيع الجهد.","نسيت تحويل µF إلى F بالضرب في `10⁻⁶`."],"g":"استخدم `PE = ½·C·V²`، وربع الجهد قبل الضرب."},{"h":["الطاقة لا تتناسب مع الجهد نفسه بل مع مربعه.",null,"زيادة الجهد تزيد الطاقة ولا تنقصها.","الطاقة تعتمد على الجهد، فتغيره يغيرها."],"g":"انظر إلى أس الجهد في `PE = ½·C·V²`، ثم عوض بضعف الجهد."},{"h":["نسيت ضرب الناتج في النصف.",null,"يبدو أنك قسمت الجهد على الشحنة، والطاقة حاصل ضرب.","يبدو أنك قسمت الشحنة على الجهد، والطاقة حاصل ضرب."],"g":"المعطى الشحنة والجهد، فاستخدم `PE = ½·q·V`."},{"h":["هذه صيغة صحيحة للطاقة بدلالة السعة والجهد.","هذه صيغة صحيحة للطاقة بدلالة الشحنة والجهد.","هذه صيغة صحيحة للطاقة بدلالة الشحنة والسعة.",null],"g":"تذكر أن `q = C·V`، ثم عوض في كل صيغة وانظر أيها لا يعطي وحدة طاقة."},{"h":["الفاراد وحدة السعة.",null,"الفولت وحدة الجهد.","الكولوم وحدة الشحنة."],"g":"الطاقة المختزنة طاقة كأي طاقة أخرى، فما وحدة الطاقة والشغل في النظام الدولي؟"},{"h":[null,"يبدو أنك ضربت السعة في الجهد فقط، ونسيت النصف والتربيع.","يبدو أنك نسيت تربيع الجهد.","نسيت الضرب في النصف."],"g":"طبق `PE = ½·C·V²` بعد تحويل µF إلى F."},{"h":[null,"يبدو أنك نسيت تربيع الجهد.","نسيت الضرب في النصف.","يبدو أنك ضربت السعة في الجهد فقط، ونسيت النصف والتربيع."],"g":"استخدم `PE = ½·C·V²` مع `10 µF = 10⁻⁵ F`، وربع الجهد أولا."},{"h":["حاصل ضرب الشحنة في السعة لا يعطي وحدة طاقة.",null,"هذه الصيغة لا تعطي وحدة طاقة، فقد وضعت السعة مكان الشحنة.","هذه الصيغة فيها الشحنة مرة واحدة، والتعويض الصحيح يجعلها تظهر مرتين."],"g":"ابدأ من `U = ½·q·V` وعوض فيها `V = q / C`."},{"h":["الطاقة تتناسب طرديا مع السعة عند ثبات الجهد، فلا تنقص.","الزيادة أربع مرات تحدث عند مضاعفة الجهد لا السعة، لأن الجهد مربع في الصيغة.","السعة موجودة في صيغة الطاقة، فتغيرها يغير الطاقة.",null],"g":"انظر إلى أس السعة في `U = ½·C·V²` مع بقاء الجهد ثابتا."},{"h":["الأسلاك تنقل الشحنة فقط ولا تختزن الطاقة.","الطاقة تبقى في المكثف حتى بعد فصل البطارية، فليست في البطارية.",null,"المكثف يعمل بالشحنات المفصولة على لوحيه، لا بالمغناطيسية."],"g":"فكر فيما يتكون بين لوحين يحملان شحنتين متعاكستين، فهناك تبقى الطاقة بعد فصل البطارية."}],"3-8":[{"h":[null,"المقدار صحيح، لكن الشحنتين مختلفتا الإشارة فلا تتنافران.","يبدو أنك قسمت على المسافة `2` لا على مربعها `4`.","يبدو أنك لم تقسم على مربع المسافة، كما أن الشحنتين المختلفتين لا تتنافران."],"g":"عوض في `F = k·|q₁|·|q₂| / r²` بعد تحويل nC إلى C، ثم حدد نوع القوة من إشارتي الشحنتين."},{"h":[null,"يبدو أنك قسمت `4` على `8` بدل `8` على `4`، فراجع ترتيب القسمة في `E = F ÷ q`.","هذا حاصل ضرب القوة في الشحنة، والمجال قسمة لا ضرب.","يبدو أنك حولت µC بالضرب في `10⁻³` بدل `10⁻⁶`."],"g":"استخدم `E = F ÷ q` بعد تحويل µC إلى C، وانتبه لطرح الأسس عند القسمة."},{"h":[null,"يبدو أنك ضربت الشحنة في الجهد، والسعة قسمة الشحنة على الجهد.","هذا ناتج قسمة الجهد على الشحنة، أي أن القسمة مقلوبة.","هذه قيمة الشحنة نفسها، ولم تقسمها على الجهد."],"g":"السعة هي الشحنة لكل فولت: `C = Q ÷ V`."},{"h":["هذا مجموع السعتين، وهو قانون التوازي لا التوالي.",null,"هذا حاصل ضرب السعتين فقط، ونسيت القسمة على مجموعهما.","هذا مجموع المقلوبات `1/2 + 1/4`، ونسيت أن تقلب الناتج."],"g":"في التوالي تجمع المقلوبات أو تستخدم `C = C₁·C₂ / (C₁ + C₂)`، والناتج أصغر من أصغر سعة."},{"h":["هذا ناتج قانون التوالي، والسؤال عن التوازي.",null,"هذا الفرق بين السعتين، والتوازي لا يطرح السعات.","هذا حاصل ضرب السعتين، والتوازي لا يضرب السعات."],"g":"في التوازي يتساوى الجهد على المكثفات، فتجمع السعات مباشرة: `C = C₁ + C₂`."},{"h":[null,"يبدو أنك قسمت على `0.25` لا على مربعها.","هذا ناتج `k·q` فقط، ونسيت القسمة على مربع المسافة.","يبدو أنك قسمت على مكعب المسافة، والقانون فيه مربعها فقط."],"g":"استخدم `E = k·q / r²`، وربع المسافة `0.25 m` قبل القسمة."},{"h":["يبدو أنك قسمت على `0.4` لا على مربعها.","الناتج أكبر بعشر مرات، فراجع الأسس وموضع الفاصلة العشرية.",null,"يبدو أنك حسبت مربع `0.4` على أنه `0.04`، والصحيح `0.16`."],"g":"عوض في `F = k·|q₁|·|q₂| / r²` بعد تحويل µC إلى C، ولا تنس تربيع المسافة."},{"h":[null,"هذا ناتج قسمة السعة على الجهد، والشحنة حاصل ضربهما.","يبدو أنك قسمت الجهد على السعة وأهملت البادئة µ.","الأس غير صحيح، فتأكد أن `µF` تعني الضرب في `10⁻⁶`."],"g":"من `C = q / V` نجد `q = C·V`، فحول µF إلى F ثم اضرب في الجهد."},{"h":["يبدو أنك قسمت المجال على `2` دون تحويل mm إلى m، والقانون ضرب لا قسمة.",null,"هذا ناتج قسمة المجال على المسافة، والصحيح ضربهما.","يبدو أنك قسمت بدل أن تضرب، وفرق الجهد هو `E` مضروبا في `d`."],"g":"في المجال المنتظم `ΔV = E·d`، وحول `2 mm` إلى `0.002 m` أولا."},{"h":["هذا ناتج قانون التوالي، والسؤال عن التوازي.","هذه أصغر سعة فقط، والتوازي يزيد السعة الكلية.","هذا متوسط السعات، والتوازي لا يأخذ المتوسط.",null],"g":"في التوازي تجمع السعات كلها مباشرة: `C = C₁ + C₂ + C₃`."}],"3-9":[{"h":["التنافر يحدث بين الشحنات المتشابهة، وهنا الشحنتان مختلفتان.",null,"كل شحنتين تؤثر إحداهما في الأخرى بقوة، فلا يمكن ألا تتأثرا.","نوع الشحنة لا يتغير بالتقريب، فالشحنة السالبة تبقى سالبة."],"g":"تذكر القاعدة: الشحنات المتشابهة تتنافر، والشحنات المختلفة تتجاذب."},{"h":["الكولوم وحدة الشحنة لا السعة.",null,"الفولت وحدة الجهد الكهربائي.","الأوم وحدة المقاومة الكهربائية."],"g":"السعة نسبة الشحنة إلى الجهد `C = q / V`، فوحدتها كولوم لكل فولت، ولها اسم خاص."},{"h":["الخطوط تخرج من الشحنة الموجبة، لا من السالبة.",null,"خطوط مجال الشحنة النقطية شعاعية مستقيمة، لا دائرية.","كل شحنة لها مجال، فلا بد من خطوط حولها."],"g":"اتجاه المجال هو اتجاه القوة على شحنة اختبار موجبة، فإلى أين تتحرك إذا وضعت قرب شحنة سالبة؟"},{"h":["الضعف يكون حيث تتباعد الخطوط لا حيث تتقارب.",null,"وجود الخطوط يعني وجود مجال، فلا ينعدم حيث تتقارب.","المجال المنتظم خطوطه متوازية متساوية التباعد، والتقارب وحده لا يعني ذلك."],"g":"كثافة خطوط المجال تعبر عن شدته: كلما تزاحمت الخطوط زادت الشدة."},{"h":["تساوي الجهد صفة التوصيل على التوازي لا التوالي.",null,"الجهود لا تضرب في بعضها، فالناتج لن يكون بوحدة الفولت.","جمع المقلوبات يخص سعات التوالي لا جهوده."],"g":"في التوالي تتساوى الشحنة على المكثفات، ويتقاسم المكثفات جهد المصدر."},{"h":[null,"لو كان التناسب عكسيا لقلت الشحنة بزيادة الجهد، وهذا لا يحدث.","الشحنة تتغير مع الجهد بنسبة ثابتة هي السعة، فهي تتناسب معه.","مربع الجهد يظهر في قانون الطاقة، لا في قانون الشحنة."],"g":"انظر إلى `q = C·V` مع ثبات السعة: ماذا يحدث للشحنة إذا تضاعف الجهد؟"},{"h":["المواد الموصلة تسمح بمرور الشحنات بسهولة لكثرة إلكتروناتها الحرة.",null,"أشباه الموصلات تسمح بمرور الشحنات بدرجة متوسطة.","المواد فائقة التوصيل تمرر الشحنات دون مقاومة تقريبا."],"g":"ابحث عن المواد التي إلكتروناتها مقيدة وغير حرة الحركة، مثل الزجاج والخشب والبلاستيك."},{"h":["كونها أصغر من أصغرها صفة التوالي لا التوازي.",null,"السعات لا تضرب في بعضها، فالوحدة الناتجة لن تكون وحدة سعة.","جمع المقلوبات ثم قلب الناتج قانون التوالي."],"g":"في التوازي يتساوى الجهد وتجمع الشحنات، فكيف تتغير السعة الكلية `q / V`؟"},{"h":[null,"هذه الوحدة مقلوبة، فالمجال قوة مقسومة على شحنة لا العكس.","`J/C` هي وحدة الجهد الكهربائي (الفولت).","الأمبير وحدة التيار، فهذه ليست وحدة المجال الكهربائي."],"g":"المجال هو القوة المؤثرة في وحدة الشحنات `E = F / q`، فاقسم وحدة القوة على وحدة الشحنة."},{"h":["يبدو أنك قلبت إشارة الأس فقط دون قسمة `1` على `1.6`.",null,"الأس يجب أن يكون موجبا، فالقسمة على عدد صغير جدا تعطي عددا كبيرا.","هذا تقريب خشن، والسؤال يطلب ناتج القسمة بدقة."],"g":"عدد الإلكترونات `n = q / e`، فاقسم `1 C` على شحنة الإلكترون."},{"h":[null,"المكثف المشحون بين لوحيه مجال يؤثر في الشحنات، فلا يكون صفرا.","الخطوط بين اللوحين مستقيمة متوازية، لا دائرية.","الشدة بين اللوحين ثابتة تقريبا في كل النقاط بعيدا عن الحواف."],"g":"تذكر شكل الخطوط بين لوحين متوازيين: متوازية ومتساوية التباعد، فماذا يعني ذلك عن الشدة والاتجاه؟"},{"h":["الخطوط تمتد من الموجبة إلى السالبة، وهنا الشحنتان موجبتان.","خطوط المجال لا تتقاطع أبدا.",null,"الخطوط تدخل في الشحنة السالبة، وتخرج من الموجبة."],"g":"الشحنتان متشابهتان فتتنافران، وخطوط المجال تخرج من كل شحنة موجبة ولا تتقاطع."},{"h":["هذا حاصل ضرب الشحنة في السعة، والجهد قسمة لا ضرب.","هذا ناتج قسمة السعة على الشحنة، أي أن القسمة مقلوبة.","الأس صحيح لكن يبدو أنك ضربت `4` في `2` بدل قسمتها.",null],"g":"من `C = q / V` نجد `V = q / C`، فحول µF إلى F ثم اقسم."}],"4-1":[{"h":["يبدو أنك ضربت الشحنة في الزمن، والتيار يحسب بالقسمة على الزمن.",null,"يبدو أنك قسمت 60 على 10، فعكست البسط والمقام.","يبدو أنك جمعت الشحنة والزمن، ولا يجمع مقداران مختلفا الوحدة."],"g":"التيار هو الشحنة مقسومة على الزمن: `I = q / t`، فضع الشحنة في البسط والزمن في المقام."},{"h":[null,"هذا مقدار ثابت كولوم `k` بوحدة `N·m²/C²`، وليس شحنة.","الأس هنا موجب، وشحنة الإلكترون صغيرة جدا فأسها سالب.","هذا مقدار سماحية الفراغ `ε₀` بوحدة `C²/N·m²`، وليس شحنة الإلكترون."],"g":"تذكر الرمز `e` في العلاقة `q = n·e`، وهو مقدار صغير جدا لأن الإلكترون جسيم دقيق."},{"h":["هذا هو الاتجاه الاصطلاحي للتيار، والسؤال عن حركة الإلكترونات الفعلية.",null,"الإلكترونات تنجرف في اتجاه محدد بتأثير المجال داخل الموصل.","الإلكترونات تتحرك على طول السلك لا عموديا عليه."],"g":"الإلكترونات سالبة الشحنة، فتنجذب نحو القطب ذي الشحنة المخالفة لها."},{"h":["هذه هي الشحنة بالكولوم، ولم تقسمها بعد على شحنة الإلكترون.",null,"يبدو أنك ضربت الشحنة في شحنة الإلكترون بدل أن تقسمها عليها.","يبدو أنك استعملت شحنة `5 C` بدل الشحنة الصحيحة، فراجع حساب `q = I·t`."],"g":"احسب الشحنة أولا من `q = I·t`، ثم اقسمها على شحنة الإلكترون `e` لتحصل على العدد."},{"h":["الأمبير معدل مرور الشحنة، فالزمن في المقام لا مضروب في الشحنة.",null,"هذه وحدة الجهد الكهربائي (الفولت).","هذه وحدة المقاومة (الأوم)."],"g":"انظر إلى تعريف شدة التيار `I = q / t` واكتب وحدة كل من البسط والمقام."},{"h":["يبدو أنك قسمت على 2 دقيقة دون تحويلها إلى ثوان.",null,"يبدو أنك ضربت الشحنة في عدد الدقائق بدل القسمة على الزمن.","يبدو أنك قسمت على 60 بدل الزمن الكلي بالثواني."],"g":"حول الدقيقتين إلى ثوان أولا، ثم اقسم الشحنة على الزمن."},{"h":[null,"التعريف يتحدث عن معدل مرور الشحنة مع الزمن، لا عن شحنة مخزنة.","هذا تعريف الجهد الكهربائي.","هذا تعريف فرق الجهد من خلال الشغل، لا تعريف التيار."],"g":"تذكر القانون `I = q / t`: الشحنة في البسط والزمن في المقام، فهو معدل."},{"h":["الإلكترونات تتحرك عكس الاتجاه الاصطلاحي، فهذا هو الاتجاه الحقيقي.","النيوترونات متعادلة الشحنة فلا تكون تيارا.",null,"الأيونات السالبة تتحرك كالإلكترونات عكس الاتجاه الاصطلاحي."],"g":"الاتجاه الاصطلاحي اتفاق قديم، وهو عكس اتجاه حركة الإلكترونات."},{"h":["يبدو أنك قسمت الزمن على التيار بدل الضرب.","يبدو أنك قسمت التيار على الزمن، والمطلوب هو الشحنة لا التيار.","يبدو أنك جمعت التيار والزمن بدل ضربهما.",null],"g":"أعد ترتيب `I = q / t` لتصبح `q = I·t`، ثم عوض."},{"h":["هذا العدد الذي يظهر في شحنة الإلكترون مع عكس إشارة الأس، وليس ناتج القسمة.",null,"هذه شحنة الإلكترون نفسها بالكولوم، لا عدد الإلكترونات.","العدد لا يمكن أن يكون أقل من واحد، فراجع إشارة الأس."],"g":"استعمل `n = q / e` واقسم `1` على `1.6 × 10⁻¹⁹`، وانتبه أن قسمة 1 على 1.6 ليست 1.6."},{"h":["الكثافة قسمة على المساحة لا ضرب فيها.",null,"المقام مساحة فوحدته متر مربع لا متر.","هذه وحدة كثافة الشحنة السطحية، والسؤال عن التيار."],"g":"كثافة التيار هي التيار مقسوما على مساحة المقطع، فاكتب وحدة كل منهما."},{"h":[null,"يبدو أنك ضربت المساحة في التيار أو قلبت القسمة، والتيار يقسم على المساحة.","يبدو أنك نسيت أن `10⁻⁶` في المقام تصبح `10⁶` في البسط.","هذه قيمة العدد في المساحة نفسها، لا ناتج القسمة."],"g":"عوض في `J = I / A` وانقل القوة العشرية من المقام إلى البسط بعكس إشارتها."},{"h":["`10⁻³` تحويل المليمتر الطولي، والمساحة تحتاج تربيع التحويل.",null,"`10⁻⁴` تحويل السنتيمتر المربع لا المليمتر المربع.","المليمتر المربع أصغر بكثير من المتر المربع، فلا يمكن أن يكبر الرقم."],"g":"بما أن `1 mm = 10⁻³ m` فربع هذا التحويل لتحصل على تحويل المليمتر المربع."},{"h":["الكمية القياسية لها مقدار فقط، وهذه الكمية لها اتجاه هو اتجاه التيار.",null,"لها وحدة هي الأمبير لكل متر مربع.","هي كمية مشتقة من التيار والمساحة، لا كمية أساسية."],"g":"اسأل نفسك: هل لكثافة التيار اتجاه؟ راجع الشريحة التي تربطها باتجاه التيار."},{"h":["الزيادة تحدث عند تصغير المساحة، لأن المساحة في المقام.",null,"المساحة داخلة في القانون، فتغيرها يغير الكثافة.","الكثافة لا تنعدم ما دام التيار يمر."],"g":"في `J = I / A` المساحة في المقام، فما أثر كبر المقام على الناتج؟"},{"h":[null,"يبدو أنك لم تحول `1 mm²` إلى `10⁻⁶ m²`.","يبدو أنك ضربت في `10⁻⁶` بدل القسمة عليها.","يبدو أنك قسمت المساحة على التيار ونسيت التحويل."],"g":"حول المساحة إلى `m²` أولا، ثم اقسم التيار عليها في `J = I / A`."},{"h":["هذا وصف لكثافة الشحنة الحجمية لا لكثافة التيار.","القسمة في كثافة التيار على المساحة لا على الطول.",null,"هذا يرمز له `n` في قانون سرعة الانجراف، وليس كثافة التيار."],"g":"تذكر `J = I / A` ووحدتها `A/m²`، فما الكمية في المقام؟"},{"h":[null,"النقص إلى النصف يحدث لو قلت المساحة في البسط، لكنها في المقام.","الكثافة تتغير لأن المساحة في المقام تغيرت.","التضاعف أربع مرات يحدث لو نقص نصف القطر إلى النصف، لا المساحة."],"g":"الكثافة تتناسب عكسيا مع المساحة في `J = I / A`."},{"h":["يبدو أنك قسمت 4 على 2 ونسيت تحويل `mm²` إلى `m²`.","يبدو أنك ضربت التيار في المساحة بدل القسمة.","يبدو أنك قسمت المساحة على التيار فقلبت القانون.",null],"g":"حول `2 mm²` إلى `m²` ثم اقسم التيار عليها."},{"h":["الأسلاك الأسمك تجعل الكثافة أصغر لا أكبر.",null,"سمك السلك لا يرفع جهد المصدر على الجهاز.","عدد الإلكترونات الحرة لوحدة الحجم صفة للمادة ولا يتغير بالسمك."],"g":"ارجع إلى `J = I / A`: زيادة سمك السلك تزيد المساحة، ففكر في أثر ذلك على الحرارة."},{"h":["هذه سرعة انتقال الإشارة (المجال) لا سرعة الإلكترونات نفسها.",null,"الإلكترونات تنجرف فعلا عند مرور التيار، فلا تكون سرعتها صفرا.","لا توجد سرعة لا نهائية، والتصادمات تبطئ الإلكترونات."],"g":"تذكر أثر التصادمات المتكررة مع ذرات الموصل على حركة الإلكترونات."},{"h":["كثافة التيار تقسم على `n·e` لا تضرب فيها.",null,"هذا مقلوب القانون، فوحدته لا تكون `m/s`.","حاصل ضرب التيار في المساحة لا يعطي سرعة."],"g":"تحقق من الوحدات: `(A/m²) ÷ (C/m³)` يعطي `m/s`."},{"h":["الموصلات فيها عدد هائل من الإلكترونات الحرة.",null,"قوة المصدر تؤثر في التيار، لكنها ليست سبب بطء الانجراف.","شحنة الإلكترون صغيرة جدا وثابتة."],"g":"فكر فيما يعترض الإلكترون وهو يتحرك داخل الشبكة البلورية للموصل."},{"h":[null,"السرعة تتناسب طرديا مع الكثافة لا عكسيا.","الكثافة في البسط، فتغيرها يغير السرعة.","السرعة لا تنعدم ما دام التيار يمر."],"g":"في `v_d = J / (n·e)` الكثافة في البسط، و `n` ثابت للموصل نفسه."},{"h":[null,"`n` في المقام، فالعلاقة معه عكسية.","شحنة الإلكترون في المقام وهي ثابتة أصلا.","طول السلك لا يظهر في القانون."],"g":"انظر إلى `v_d = J / (n·e)`: ما الكمية التي في البسط؟"},{"h":["المجال ينتقل بسرعة كبيرة جدا، أما الانجراف فبطيء.",null,"الضوء ليس هو ما يحمل التيار في الموصل.","الحركة العشوائية الحرارية لا تعطي محصلة في اتجاه معين."],"g":"ابحث عن تعريف يذكر المتوسط وأثر المجال الكهربائي على الإلكترونات الحرة."},{"h":["الاتجاه الاصطلاحي هو اتجاه الشحنات الموجبة، والإلكترونات سالبة.","الإلكترونات تنجرف على طول السلك لا عموديا عليه.",null,"الحركة العشوائية موجودة، لكن الانجراف له اتجاه محصل محدد."],"g":"الإلكترونات سالبة الشحنة فتتحرك عكس المجال الكهربائي داخل السلك."},{"h":[null,"`n` في المقام، فزيادته تقلل السرعة لا تزيدها.","اختلاف `n` يغير السرعة رغم تساوي الكثافة.","المقام تضاعف مرة واحدة لا مرتين، والعلاقة ليست تربيعية."],"g":"في `v_d = J / (n·e)` ثبت `J` و `e`، ثم انظر ماذا يحدث عند مضاعفة المقام."},{"h":["هذا يسري في اتجاه واحد ولا يغير اتجاهه.",null,"الشحنات الساكنة لا تكون تيارا أصلا.","كلمة المنتظم لا تصف تيارا يتغير اتجاهه دوريا."],"g":"الكلمة المفتاحية «يتغير اتجاهه دوريا»، وهذا وصف تيار المنازل AC."},{"h":[null,"البطارية لها قطبان ثابتان فلا يتغير اتجاه تيارها.","حركة الشحنات من البطارية في الدائرة تيار حقيقي.","اتجاه تيار البطارية ثابت من القطب نفسه."],"g":"تذكر أمثلة الشريحة: البطاريات والخلايا الشمسية تعطي تيارا في اتجاه واحد (DC)."},{"h":["هذا يرمز له AC (Alternating Current).",null,"فرق الجهد يقاس بالفولت ولا يرمز له DC.","المقاومة يرمز لها `R` ووحدتها الأوم."],"g":"DC اختصار Direct Current، أي التيار ذو الاتجاه الواحد."},{"h":["هذا يخص تيار المنازل AC الذي يغير اتجاهه دوريا.",null,"كل تيار يحمل طاقة، والبطارية تشغل الأجهزة.","المنازل يصلها AC، والتيار ذو الاتجاه الواحد يأتي من البطاريات."],"g":"تذكر تيار البطارية: قطباه ثابتان فاتجاه التيار لا يتغير."},{"h":["الشاحن يخفض الجهد ليناسب الجوال، لا يرفعه.",null,"الشاحن لا يغير التردد، بل يحول نوع التيار ويخفض الجهد.","لو لم يغيره لتلف الجوال، فبطاريته تحتاج جهدا صغيرا في اتجاه واحد."],"g":"بطارية الجوال تشحن بتيار في اتجاه واحد وبجهد صغير مثل `5 V`."},{"h":["جهد التيار المتردد يتغير دوريا مع الزمن.",null,"كل نقل للطاقة فيه فقد، لكن المتردد يقلله.","كل شبكات النقل تحتاج أسلاكا."],"g":"فكر في الجهاز الذي يغير الجهد ولا يعمل إلا مع التيار المتردد، وأثر ذلك على النقل لمسافات بعيدة."},{"h":["`12 V` جهد بطارية السيارة لا جهد المنازل.",null,"التيار ذو الاتجاه الواحد ليس له تردد، و `50 Hz` ليست تردد الشبكة في المملكة.","تردد `1 Hz` بطيء جدا، والشبكة تغير اتجاهها 120 مرة في الثانية."],"g":"راجع شريحة التيار المتردد: الجهد نحو `220 V` والتردد مذكور فيها."},{"h":[null,"العاكس يعمل بالعكس: يحول DC إلى AC.","المقاومة المتغيرة تتحكم في مقدار التيار لا في نوعه.","المصهر يحمي الدائرة بقطع التيار الزائد ولا يحول نوعه."],"g":"راجع جدول المقارنة في سطر «التحويل»: لكل اتجاه تحويل جهاز خاص."},{"h":["الألواح لا تغير اتجاه تيارها، ولذلك نحتاج العاكس للمنزل.","الألواح لا تنتج ترددا أصلا.",null,"اتجاه تيار الخلية الشمسية ثابت لا يتغير كل ثانية."],"g":"تذكر أن العاكس يوضع بعد الألواح ليحول تيارها إلى AC للمنزل."},{"h":["الخط الأفقي الثابت يمثل التيار المستمر DC.","الخط المتزايد يعني أن التيار يزداد دائما، وهذا لا يحدث في المنازل.","تيار المنازل يشغل الأجهزة فلا يكون صفرا.",null],"g":"تيار المنازل يغير مقداره واتجاهه دوريا، ففكر في شكل الموجة التي تصعد وتهبط."},{"h":["هذه وحدة الجهد الكهربائي.",null,"هذه وحدة المقاومة.","هذه وحدة القدرة الكهربائية."],"g":"راجع شريحة «وحدات مهمة»: وحدة التيار تساوي `C/s`."},{"h":[null,"هذه وحدة السعة الكهربائية.","هذه وحدة الشحنة الكهربائية.","هذه وحدة الطاقة والشغل."],"g":"رمز وحدة المقاومة الحرف اليوناني `Ω`، وهي تساوي `V/A`."},{"h":["هذا الجهاز يقيس فرق الجهد ويوصل على التوازي.",null,"هذا الجهاز يقيس درجة الحرارة.","هذا الجهاز يقيس الأطوال الصغيرة بدقة."],"g":"اسم الجهاز مشتق من اسم وحدة التيار، ويوصل على التوالي في الدائرة."}],"4-5":[{"h":["يبدو أنك ضربت الجهد في التيار بدل أن تقسم الجهد على التيار.",null,"هذا ناتج قسمة التيار على الجهد، والمقاومة هي الجهد مقسوما على التيار.","يبدو أنك جمعت الجهد والتيار، والقانون يحتاج قسمة لا جمعا."],"g":"استخدم قانون أوم `V = I·R` واستخرج منه `R` بقسمة الجهد على التيار."},{"h":["يبدو أنك ضربت الجهد في المقاومة، والتيار هو الجهد مقسوما على المقاومة.",null,"هذا ناتج قسمة المقاومة على الجهد، فقد عكست القسمة.","يبدو أنك طرحت المقاومة من الجهد، والقانون يحتاج قسمة."],"g":"من `V = I·R` يكون `I = V/R`، فاقسم الجهد على المقاومة."},{"h":[null,"التيار يتناسب طرديا مع الجهد، لا عكسيا.","الجهد هو سبب مرور التيار، فتغيره لا بد أن يغير التيار.","اتجاه التيار تحدده قطبية المصدر لا مقدار الجهد."],"g":"انظر إلى `I = V/R`: الجهد في البسط والمقاومة ثابتة."},{"h":["حاصل ضرب الجهد في التيار هو وحدة القدرة (الواط).",null,"هذه الوحدة مقلوبة، فقد قسمت التيار على الجهد.","جول لكل ثانية هي وحدة القدرة، أي الواط."],"g":"من قانون أوم `R = V/I`، فوحدة المقاومة هي وحدة الجهد مقسومة على وحدة التيار."},{"h":[null,"يبدو أنك قسمت المقاومة على التيار، والجهد حاصل ضربهما.","يبدو أنك جمعت التيار والمقاومة، والقانون يحتاج ضربا.","يبدو أنك قسمت التيار على المقاومة، والجهد حاصل ضربهما."],"g":"استخدم `V = I·R` واضرب التيار في المقاومة."},{"h":["التيار يتغير أثناء التجربة، فهو من الكميات المقيسة لا الشرط الثابت.","الجهد نغيره لنرى أثره على التيار، فهو ليس الشرط الثابت.",null,"الزمن لا يدخل في العلاقة بين الجهد والتيار."],"g":"ابحث عن الكمية التي إن تغيرت تغيرت مقاومة الموصل نفسه، فلم تعد النسبة `V/I` ثابتة."},{"h":[null,"العلاقة طردية لا عكسية، فزيادة الجهد تزيد التيار.","المقاومة ثابتة في قانون أوم، والذي يتغير مع الجهد هو التيار.","التيار يتغير بتغير الجهد، ولا يبقى ثابتا."],"g":"اكتب القانون على صورة `I = V/R` ولاحظ كيف يتغير التيار مع الجهد عند ثبات المقاومة."},{"h":["القدرة حاصل ضرب الجهد في التيار، والميل ناتج قسمة لا ضرب.","الموصلية خاصية للمادة تساوي مقلوب المقاومية، ولا تقرأ من ميل هذا المنحنى.",null,"الشحنة لا تظهر في هذا المنحنى، فالمحوران جهد وتيار."],"g":"الميل هو التغير الرأسي مقسوما على التغير الأفقي، أي `ΔV/ΔI`، فقارنه بقانون أوم."},{"h":["النحاس موصل أومي عند ثبات الحرارة، فالعلاقة بين الجهد والتيار فيه خطية.",null,"المقاومة الكربونية الثابتة عنصر أومي يعطي مقاومة ثابتة.","النيكروم سبيكة موصلة تخضع للقانون ما دامت حرارتها ثابتة."],"g":"ابحث عن العنصر المصنوع من مادة شبه موصلة، والذي لا تكون علاقته بين الجهد والتيار خطا مستقيما."},{"h":["هذا هو التيار القديم، والتيار يتغير عندما يتغير الجهد.","يبدو أنك حسبت المقاومة `3 Ω` وتوقفت، والمطلوب التيار الجديد.","يبدو أنك قسمت الجهد الجديد على التيار القديم، والصحيح القسمة على المقاومة.",null],"g":"احسب المقاومة أولا من القراءة الأولى، ثم استخدمها مع الجهد الجديد في `I = V/R`."},{"h":["المقاومة تتناسب طرديا مع الطول، فزيادته تزيدها.",null,"في الموصلات تزيد المقاومة بارتفاع الحرارة.","المقاومية في بسط القانون، فزيادتها تزيد المقاومة."],"g":"انظر إلى `R = ρ·L / A`: الكمية الموجودة في المقام هي التي تقل المقاومة بزيادتها."},{"h":["هذه وحدة المقاومة نفسها، والمقاومية تختلف عنها بضربها في وحدة طول.",null,"يبدو أنك قسمت على الطول فقط، لكن القانون `ρ = R·A / L` يضرب في المساحة أيضا.","هذه الوحدة مقلوبة ولا تخرج من أي ترتيب لقانون المقاومة."],"g":"اكتب `ρ = R·A / L` وعوض وحدة كل كمية: أوم في متر مربع مقسوما على متر."},{"h":[null,"يبدو أنك أضفت `0.156` إلى المقاومة مباشرة، والصحيح ضرب المقاومة في `1.156`.","يبدو أنك استخدمت `60` بدل فرق درجات الحرارة `40`.","يبدو أنك طرحت الزيادة بدل جمعها، والمقاومة تزيد بارتفاع الحرارة."],"g":"عوض في `R = R₀·(1 + α·(T − T₀))` مع `T − T₀ = 40 °C`."},{"h":[null,"نقصان المقاومة للنصف يحدث عند مضاعفة مساحة المقطع لا الطول.","أربعة أمثال تكون لو تناسبت المقاومة مع مربع الطول، وهي تتناسب مع الطول نفسه.","الطول في بسط القانون، فتغيره يغير المقاومة."],"g":"في `R = ρ·L / A` المقاومة تتناسب طرديا مع الطول، فما يحدث للطول يحدث لها بالنسبة نفسها."},{"h":[null,"السعة كمية تخص المكثفات، ولا علاقة لها بمقلوب المقاومية.","المعاوقة مصطلح يخص دوائر التيار المتردد، وليست مقلوب المقاومية.","المقاومة الكلية تخص مجموعة مقاومات في دائرة، لا خاصية المادة."],"g":"ابحث عن الكمية `σ = 1/ρ` التي تقيس سهولة توصيل المادة للتيار."},{"h":["المقاومية الكبيرة تزيد الفقد الحراري، ولهذا تستخدم في أسلاك السخانات لا أسلاك التوصيل.",null,"السعر ليس السبب العلمي الأساسي، فالمهم سهولة مرور التيار.","كل الموصلات تتأثر مقاومتها بالحرارة، ومنها النحاس."],"g":"فكر في المادة التي تجعل الفقد في الطاقة داخل الأسلاك أقل، وقارن مقاومية النحاس في الجدول."},{"h":["المساحة في المقام، فزيادتها لا تزيد المقاومة.",null,"الربع يكون لو تناسبت المقاومة عكسيا مع مربع المساحة، وهي تتناسب مع المساحة نفسها.","المساحة جزء من القانون، فتغيرها يغير المقاومة."],"g":"في `R = ρ·L / A` المقاومة تتناسب عكسيا مع مساحة المقطع."},{"h":["مقاومية الحديد `10 × 10⁻⁸ Ω·m`، وهي أكبر من مقاومية موصلات أخرى في الجدول.","النيكروم سبيكة مقاوميتها كبيرة، ولهذا تصنع منها أسلاك السخانات.",null,"الزجاج عازل، ومقاوميته من أكبر القيم في الجدول."],"g":"ارجع إلى جدول المقاومية وابحث عن أصغر قيمة لـ `ρ`."},{"h":[null,"مضاعفة المساحة تقلل المقاومة ولا تزيدها، فالمساحة في المقام.","تغير مساحة المقطع يغير المقاومة، فلا تبقى كما هي.","يبدو أنك قسمت على أربعة، والمقاومة تتناسب عكسيا مع المساحة لا مع مربعها."],"g":"من `R = ρ·L / A` إذا تضاعفت `A` تغيرت `R` بالنسبة العكسية نفسها."},{"h":["هذه وحدة المقاومية `ρ` لا المعامل الحراري.",null,"هذه وحدة مقاومة لكل متر طول، ولا علاقة لها بالحرارة.","هذه وحدة تيار لكل وحدة مساحة، ولا علاقة لها بالحرارة."],"g":"في `R = R₀·(1 + α·(T − T₀))` الحد `α·(T − T₀)` بلا وحدة، فوحدة `α` مقلوب وحدة درجة الحرارة."},{"h":["الطول يغير المقاومة `R` لا المقاومية `ρ`.","مساحة المقطع تغير المقاومة `R` لا المقاومية `ρ`.","الشكل الهندسي يؤثر في المقاومة لا في المقاومية.",null],"g":"المقاومية خاصية للمادة نفسها، ففكر فيما يغيرها دون تغيير أبعاد السلك."},{"h":["يبدو أنك ضربت الجهد في المقاومة، والصحيح `P = V²/R`.",null,"يبدو أنك قسمت المقاومة على الجهد ولم تربع الجهد.","هذا هو التيار المار في المصباح بالأمبير، لا قدرته."],"g":"استخدم `P = V²/R` ولا تنس تربيع الجهد."},{"h":["الجول وحدة الطاقة، والقدرة طاقة لكل ثانية.",null,"الأمبير وحدة التيار الكهربائي.","الفولت وحدة فرق الجهد."],"g":"القدرة طاقة مقسومة على زمن، فوحدتها `J/s` ولها اسم خاص."},{"h":["يبدو أنك ضربت التيار في المقاومة دون تربيع التيار.",null,"يبدو أنك قسمت المقاومة على التيار، والقانون ضرب لا قسمة.","يبدو أنك جمعت التيار والمقاومة، والقانون ضرب."],"g":"استخدم `P = I²·R` وربع التيار قبل الضرب في المقاومة."},{"h":[null,"النتيجة كبيرة جدا، والتيار يحسب بقسمة القدرة على الجهد لا بضربهما.","هذا ناتج قسمة الجهد على القدرة، فقد عكست القسمة.","يبدو أنك جمعت القدرة والجهد، والقانون يحتاج قسمة."],"g":"من `P = I·V` يكون `I = P/V`."},{"h":[null,"الشحنة المارة في وحدة الزمن هي تعريف التيار الكهربائي.","الشغل اللازم لنقل وحدة الشحنات هو تعريف فرق الجهد.","التيار لكل وحدة مساحة يسمى كثافة التيار، وليس القدرة."],"g":"تذكر الصيغة `P = E / t` واقرأ معنى كل رمز فيها."},{"h":["هذا يصح لو تناسبت القدرة مع التيار نفسه، لكنها تتناسب مع مربعه.","زيادة التيار تزيد القدرة ولا تنقصها.","التيار جزء من قانون القدرة، فتغيره يغيرها.",null],"g":"استخدم `P = I²·R` ولاحظ أن التيار مربع."}],"4-8":[{"h":[null,"هذا ناتج قانون التوازي `9 × 5 ÷ (9 + 5)`، والتوصيل هنا على التوالي.","يبدو أنك طرحت المقاومتين، والتوالي يجمعهما.","يبدو أنك ضربت المقاومتين، والتوالي يجمعهما جمعا مباشرا."],"g":"في التوالي `R_total = R₁ + R₂`."},{"h":["هذا قانون التوالي، والتوصيل هنا على التوازي.",null,"هذا حاصل الضرب فقط، ونسيت القسمة على المجموع.","يبدو أنك قسمت المجموع على اثنين، وليس هذا قانون التوازي."],"g":"لمقاومتين على التوازي `R = R₁·R₂ / (R₁ + R₂)`، والنتيجة أصغر من أصغر مقاومة."},{"h":["الجهد يتوزع على المقاومات في التوالي، فالمقاومة الأكبر تأخذ جهدا أكبر.",null,"القدرة تختلف من مقاومة لأخرى لأنها تعتمد على قيمة كل مقاومة.","المقاومات قد تختلف قيمها، فليست متساوية بالضرورة."],"g":"في التوالي يوجد مسار واحد فقط للشحنات، ففكر في الكمية التي تعبر كل المقاومات بالمقدار نفسه."},{"h":["هذه قيمة المقاومة الكلية بالأوم، ونسيت ضربها في `2 A`.",null,"يبدو أنك قسمت المقاومة الكلية على شدة السريان بدل الضرب.","هذا جهد المقاومة `9 Ω` وحدها، والمطلوب الجهد الكلي."],"g":"اجمع المقاومتين أولا، ثم استخدم `V = I·R_total`."},{"h":["الجمع المباشر قانون التوالي لا التوازي.",null,"حاصل الضرب يعطي وحدة `Ω²`، فلا يمكن أن يكون مقاومة.","المكافئة على التوازي أصغر من أصغر مقاومة، فلا تساوي أكبرها."],"g":"تذكر أن التوازي يتعامل مع مقلوب كل مقاومة، وأن الناتج أصغر من أصغر مقاومة."},{"h":["هذا جمع التوالي، والتوصيل هنا على التوازي.",null,"المكافئة على التوازي أصغر من أصغر مقاومة، فلا تساوي `10 Ω`.","هذا حاصل الضرب فقط، ونسيت القسمة على المجموع."],"g":"لـ `n` مقاومات متساوية على التوازي `R = R₁ / n`."},{"h":["تيار كل فرع جزء من التيار الكلي، ولا يساويه إلا لو كان فرعا واحدا.",null,"التيار الكلي يتوزع على الفروع، فهو أكبر من تيار أي فرع لا أصغر.","ما دامت الدائرة مغلقة والمصدر يعمل فالتيار لا يكون صفرا."],"g":"التيار الرئيسي يتفرع عند نقطة التفرع ولا تضيع منه شحنة، ففكر في العلاقة `I = I₁ + I₂ + I₃`."},{"h":[null,"التيار يتوزع على الفروع، والفرع الأصغر مقاومة يأخذ تيارا أكبر.","القدرة تختلف بين الفروع لأن تياراتها مختلفة.","المقاومات في الفروع قد تختلف قيمها."],"g":"كل فرع موصول مباشرة بين النقطتين نفسيهما، ففكر في الكمية التي تقاس بين نقطتين."},{"h":["إضافة فرع على التوازي تفتح مسارا جديدا للشحنات، فلا ترفع المكافئة.",null,"كل فرع جديد يغير المكافئة لأنه يضيف مسارا للشحنات.","المكافئة لا تصل إلى الصفر ما دامت كل مقاومة لها قيمة موجبة."],"g":"تذكر أن المكافئة على التوازي أصغر من أصغر مقاومة، وكل فرع جديد يضيف مسارا آخر للشحنات."},{"h":["هذا جمع التوالي `12 × 3`، والتوصيل هنا على التوازي.","المكافئة على التوازي أصغر من أصغر مقاومة، فلا تساوي `12 Ω`.",null,"يبدو أنك قسمت على أربعة، والمقاومات ثلاث فقط."],"g":"لـ `n` مقاومات متساوية على التوازي `R = R₁ / n`."},{"h":["التوازي لا يقلل الجهد، بل يحصل كل جهاز على جهد المصدر كاملا.","التيار نفسه يمر في الأجهزة عند التوصيل على التوالي لا التوازي.","التوازي يقلل المقاومة الكلية ولا يزيدها.",null],"g":"تذكر أن الجهد في التوازي واحد على كل الفروع، وكل فرع يعمل دون أن يتأثر بغيره."}],"4-9":[{"h":["هذا مجموع المقاومتين، وهو قانون التوالي لا التوازي.",null,"هذا حاصل الضرب فقط، ونسيت القسمة على مجموع المقاومتين.","يبدو أنك قسمت `9 ÷ 6`، والقانون حاصل الضرب على المجموع."],"g":"للمقاومتين على التوازي استخدم `R = R₁·R₂ / (R₁ + R₂)`، وتذكر أن الناتج أصغر من أصغر مقاومة."},{"h":[null,"يبدو أنك قسمت الجهد على `1 Ω` وحدها ونسيت المقاومة الثانية.","يبدو أنك ضربت الجهد في المقاومة الكلية، والتيار قسمة لا ضرب.","يبدو أنك قسمت المقاومة على الجهد، والصحيح العكس."],"g":"اجمع المقاومتين لأنهما على التوالي، ثم اقسم الجهد على المقاومة الكلية."},{"h":[null,"يبدو أنك قسمت الجهد على القدرة دون تربيع الجهد.","يبدو أنك ضربت الجهد في القدرة، والقانون مربع الجهد مقسوما على القدرة.","يبدو أنك قسمت القدرة على الجهد، وهذا يعطي التيار لا المقاومة."],"g":"استخدم `R = V²/P`: ربع الجهد أولا ثم اقسم على القدرة."},{"h":[null,"هذه قيمة المقاومة النوعية نفسها، ولم تضربها في الطول ولم تقسم على المساحة.","راجع الأسس: القسمة على `10⁻⁵` ترفع الأس بمقدار 5.","أهملت قوى العشرة وضربت `1.75 × 2` فقط."],"g":"عوض في `R = ρ·L / A`، وعند قسمة قوى العشرة اطرح أس المقام من أس البسط."},{"h":[null,"يبدو أنك قسمت الجهد على القدرة، والتيار هو القدرة مقسومة على الجهد.","يبدو أنك ضربت القدرة في الجهد، والمطلوب قسمة.","تأكد من موضع الفاصلة العشرية عند قسمة 60 على 127."],"g":"استخدم `P = I·V`، فالتيار يساوي القدرة مقسومة على الجهد."},{"h":["طرحت المقاومتين مباشرة، وفي التوازي نطرح المقلوبات.",null,"جمعت المقاومتين كأنهما على التوالي.","يبدو أنك طبقت حاصل الضرب على المجموع على `300` و `75`، لكن `75 Ω` هي المكافئة لا مقاومة فرع."],"g":"اطرح المقلوبات: `1/R₂ = 1/Rₜ − 1/R₁`، ثم اقلب الناتج."},{"h":["هذا جهد المقاومة `2 Ω`، والسؤال عن مقاومة أخرى.","هذا جهد المقاومة `3 Ω`، والسؤال عن مقاومة أخرى.",null,"هذا جهد المصدر كله، وهو يتوزع على المقاومات الثلاث."],"g":"اجمع المقاومات الثلاث لإيجاد التيار، ثم اضرب التيار في المقاومة المطلوبة."},{"h":[null,"هذا تيار الفرع `12 Ω`، والسؤال عن الفرع الآخر.","هذا التيار الرئيسي المار في المكافئة، لا تيار فرع واحد.","يبدو أنك جمعت المقاومتين كأنهما على التوالي، وفي التوازي يأخذ كل فرع جهد المصدر كاملا."],"g":"في التوازي جهد كل فرع يساوي جهد المصدر، فطبق `I = V/R` على الفرع المطلوب وحده."},{"h":["يبدو أنك قسمت الجهد على القدرة، والصحيح العكس.","هذا رقم الجهد نفسه وليس تيارا، فلم تستخدم القدرة.","هذه قيمة `V²/P` وهي مقاومة المكواة بالأوم، لا التيار.",null],"g":"التيار يساوي القدرة مقسومة على الجهد `I = P/V`."},{"h":["حسبت أثر مضاعفة الطول فقط، ونسيت أن تنصيف المساحة يضاعف المقاومة أيضا.",null,"المقاومة تتغير لأن الطول والمساحة كليهما تغيرا.","المقاومة لا تقل، فزيادة الطول ونقص المساحة كلاهما يزيدها."],"g":"في `R = ρL/A` الطول في البسط والمساحة في المقام، فاحسب أثر مضاعفة الطول وأثر تنصيف المساحة معا."}],"4-10":[{"h":["شحنة `1 C` في الدقيقة تعطي تيارا أصغر من الأمبير بستين مرة.",null,"الساعة زمن طويل جدا، فمرور `1 C` خلالها يعطي تيارا ضئيلا لا أمبيرا كاملا.","زمن أقصر بألف مرة من وحدة الزمن الأساسية يعطي تيارا أكبر بألف مرة من الأمبير."],"g":"تذكر أن `1 A = 1 C/s`، والرمز s يدل على وحدة الزمن الأساسية في النظام الدولي."},{"h":["هذا هو الاتجاه الاصطلاحي للتيار، لا اتجاه حركة الإلكترونات.",null,"الإلكترونات الحرة تتحرك فعلا عند وجود فرق جهد، وحركتها هي التيار.","الحركة العشوائية وحدها تكون في غياب فرق الجهد، وعند غلق الدائرة تضاف إليها حركة انجراف منتظمة."],"g":"الإلكترونات شحنات سالبة، فهي تنجذب نحو القطب الذي يحمل شحنة مخالفة لها."},{"h":["كثافة التيار قسمة تيار على مساحة لا ضرب.",null,"الكولوم وحدة شحنة والمتر وحدة طول، فهذه ليست وحدة تيار لكل مساحة.","هذه وحدة المجال الكهربائي."],"g":"تذكر تعريف كثافة التيار `J = I / A`، ثم اكتب وحدة كل من البسط والمقام."},{"h":["المقطع الأوسع يعطي الإلكترونات مسارات أكثر، فلا يمكن أن تكبر الإعاقة.",null,"مساحة المقطع موجودة في قانون المقاومة، فتغيرها يغير المقاومة.","المقاومة لا تنعدم بتوسيع المقطع، بل تبقى لها قيمة تعتمد على `ρ` والطول."],"g":"انظر إلى موقع `A` في `R = ρL/A`: هل هي في البسط أم في المقام؟"},{"h":["التوازي وحده نوع بسيط من التوصيل، وهذا خطأ شائع في تعريف المركب.","التوالي وحده نوع بسيط مستقل، والمركب أوسع منه.",null,"المصدر ضروري في أي دائرة، ولا علاقة له بتسمية نوع التوصيل."],"g":"كلمة «مركب» تعني أن الدائرة مكونة من أكثر من نوع واحد."},{"h":[null,"الحفاظ على الجهد هدف التوصيل على التوازي.","التوالي يزيد المقاومة الكلية، فالتيار لا يزيد بل ينقص.","المقاومة الكلية في التوالي تكبر ولا تصغر."],"g":"فكر: ماذا يحدث لجهد المصدر عندما يمر التيار نفسه في عدة مقاومات متتالية؟"},{"h":["الواط وحدة القدرة ويساوي `J/s`.",null,"الفاراد وحدة السعة الكهربائية.","الكولوم وحدة الشحنة الكهربائية."],"g":"من `R = V / I` تكون الوحدة فولت لكل أمبير، وقد سميت باسم العالم الذي وضع قانون العلاقة بين الجهد والتيار."},{"h":["هذا مجموع المقاومتين بالأوم، ولم تضربه في التيار.",null,"يبدو أنك حسبت المكافئة كأنهما على التوازي ونسيت الضرب في التيار.","يبدو أنك ضربت `4 × 6` ثم في التيار، والمقاومات على التوالي تجمع ولا تضرب."],"g":"اجمع المقاومتين لأنهما على التوالي، ثم طبق `V = I·R`."},{"h":["هذا اتجاه حركة الإلكترونات الحقيقي، لا الاتجاه الاصطلاحي.",null,"الحركة العشوائية لا تكون تيارا، والتيار له اتجاه محدد.","للتيار اتجاه اصطلاحي متفق عليه يرسم في الدوائر."],"g":"الاتجاه الاصطلاحي هو اتجاه حركة الشحنات الموجبة لو كانت هي المتحركة، أي عكس اتجاه الإلكترونات."},{"h":[null,"زيادة المقاومة بالحرارة سلوك عادي للفلزات، وليست ظاهرة خاصة.","فرط التوصيل عكس العزل تماما، فالمادة تصبح أسهل توصيلا لا أصعب.","الظاهرة تتعلق بقيمة المقاومة لا بنوع التيار."],"g":"كلمة «فائقة» تدل على توصيل كامل، فاسأل نفسك: ما قيمة المقاومة التي تجعل التوصيل كاملا، ومتى يحدث ذلك؟"},{"h":["النحاس فلز موصل جيد، لا شبه موصل.",null,"المطاط مادة عازلة.","الألومنيوم فلز موصل جيد، لا شبه موصل."],"g":"شبه الموصل موصليته بين الموصلات والعوازل، فاستبعد الفلزات والعوازل."},{"h":["جمعت المقاومات الثلاث كأنها كلها على التوالي.","هذه مكافئة المقاومات الثلاث لو كانت كلها على التوازي.",null,"يبدو أنك جمعت `6 + 6` دون أن تحسب مكافئة الفرعين المتوازيين."],"g":"احسب مكافئة الجزء المتوازي أولا، ثم اجمعها مع المقاومة الموصولة على التوالي."},{"h":["القدرة الأكبر عند الجهد نفسه تعني تيارا أكبر، أي مقاومة أصغر.","القدرتان مختلفتان عند الجهد نفسه، فلا يمكن أن تتساوى المقاومتان.","يكفي الجهد والقدرة لحساب المقاومة من `R = V²/P` دون معرفة التيار.",null],"g":"استخدم `R = V²/P`: عند ثبوت الجهد، ما العلاقة بين المقاومة والقدرة؟"}]};
window.FXB={"0-1":{"":["الفيزياء تصف العالم بأعداد لها وحدات، مثل قولك إن طولك `1.7 m`. وفي هذا الدرس نميز بين الكميات الأساسية والمشتقة ونعرف وحداتها في النظام الدولي SI.","سيارة تقطع `150 m` في `10 s`: سرعتها `v = 150 ÷ 10 = 15 m/s`. هنا الطول والزمن كميتان أساسيتان، والسرعة كمية مشتقة منهما.","لأن العلماء في كل الدول يحتاجون لغة قياس واحدة، فإذا اتفقوا على وحدات أساسية قليلة أمكن بناء كل الوحدات الأخرى منها دون تعارض."],"مقدمة الوحدة وأهدافها":["الكمية الفيزيائية شيء تستطيع أن تقيسه بمسطرة أو ساعة أو ميزان وتكتب له عددا ووحدة. أما الضوء نفسه فظاهرة، لكن شدته يمكن قياسها.","قولك «المسافة 5» ناقص، أما `5 km` فقياس كامل. ودرجة حرارة الغرفة `298 K` كمية فيزيائية، أما الحرارة كظاهرة فليست كذلك.","لأن العدد وحده لا يكفي للمقارنة؛ فالعدد 5 قد يعني `5 m` أو `5 km`، والفرق بينهما ألف مرة. لذلك يلزم العدد والوحدة معا."],"ماذا ستتعلم في هذه الوحدة":["هذه الوحدة خريطة طريق: نبدأ بمعرفة ما يقاس وبأي وحدة، ثم نتدرب على التحويل بين الوحدات، ثم ننتقل إلى الكميات التي لها اتجاه مثل القوة.","مما ستتدرب عليه: تحويل `2 km` إلى متر بالضرب في 1000 فيصبح `2000 m`، وجمع قوتين `3 N` و `4 N` متعامدتين لتكون المحصلة `5 N`.","لأن كل حساب لاحق في الفيزياء يعتمد على وحدات صحيحة واتجاهات صحيحة، فالخطأ في الوحدة أو الاتجاه يفسد الناتج مهما كان الحساب دقيقا."],"الكميات الفيزيائية":["الكميات الأساسية مثل حروف الهجاء، والكميات المشتقة مثل الكلمات المركبة منها. فالسرعة مثلا تتركب من الطول والزمن.","غرفة طولها `4 m` وعرضها `3 m`: مساحتها `A = 4 × 3 = 12 m²`. والمساحة مشتقة لأنها حاصل ضرب طول في طول.","لأن الكميات الأساسية اختيرت مستقلة لا يعبر عن إحداها بالأخرى، وكل كمية أخرى يمكن كتابتها بعلاقة تجمع بعض هذه الكميات."],"وحدات الكميات الأساسية في SI":["لكل كمية أساسية وحدة واحدة متفق عليها عالميا، مثل المتر للطول والثانية للزمن. فهي كالمقاس الموحد الذي يفهمه الجميع.","متدرب كتلته `70 kg` وطوله `1.75 m`، وقطع مسافة قصيرة في `12 s`؛ كل هذه القيم بوحدات أساسية في SI دون تحويل.","لأن توحيد الوحدات يمنع الالتباس بين الدول والمصانع والمعامل، فالقطعة المصنوعة في بلد تركب في جهاز صنع في بلد آخر."],"أمثلة على وحدات مشتقة":["الوحدة المشتقة تبنى من الوحدات الأساسية كما تبنى الجملة من الكلمات. فوحدة السرعة متر مقسوم على ثانية، والنيوتن اختصار لـ `kg·m/s²`.","قوة `10 N` تحرك جسما مسافة `3 m` في اتجاهها: الشغل `W = 10 × 3 = 30 J`، والجول هنا يساوي `N·m`.","لأن كل كمية مشتقة تعرف بقانون من كميات أساسية، فوحدتها تنتج من تعويض وحدات تلك الكميات في القانون نفسه."],"تحويلات أساسية":["التحويل يغير الوحدة فقط ولا يغير الشيء المقاس؛ فطول الطاولة هو نفسه سواء عبرت عنه بالمتر أو بالسنتيمتر.","رحلة مدتها `2 h` تساوي `2 × 3600 = 7200 s`، وكيس كتلته `3 kg` يساوي `3 × 1000 = 3000 g`.","لأن الوحدة الكبيرة تحتوي عددا ثابتا من الوحدات الصغيرة، فالضرب في هذا العدد أو القسمة عليه يحفظ المقدار نفسه."],"أمثلة الحقيبة التدريبية محلولة":["المتر أكبر من السنتيمتر، فإذا قسنا بالمتر احتجنا عددا أصغر. مثل النقود: المبلغ نفسه عدده بالهللات أكبر منه بالريالات.","حول `750 cm` إلى متر: `L = 750 ÷ 100 = 7.5 m`.","لأن المتر الواحد يضم `100 cm`، فعدد الأمتار هو عدد مجموعات المئة في الطول، وهذا ما تعطيه القسمة."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["بعد القسمة نتأكد بالعكس: نضرب الناتج في 100، فإن رجعنا إلى العدد الأصلي فالحل صحيح.","حول `320 cm` إلى متر: `320 ÷ 100 = 3.2 m`، والتحقق: `3.2 × 100 = 320 cm`.","لأن الضرب عكس القسمة، فإعادة الناتج إلى الوحدة الأصلية تكشف أي خطأ في اتجاه التحويل أو في العدد."],"رسم توضيحي":["الرسم يجمع الكميات الأساسية السبع في النظام الدولي مع وحدة كل منها، كبطاقة مرجعية ترجع إليها عند الحاجة.","مصباح يمر فيه تيار `0.5 A` لمدة `60 s` في غرفة درجة حرارتها `300 K`؛ هنا ثلاث كميات أساسية بوحداتها كما في الرسم.","لأن هذه الكميات السبع تكفي لبناء كل الوحدات الأخرى، فحفظها مع رموزها أساس لأي تحويل أو تحقق من قانون."],"الكميات الأساسية في النظام الدولي SI":["الجدول قائمة بسبع كميات ووحداتها، ولكل وحدة رمز قصير يكتب بعد العدد، مثل `kg` للكتلة و `mol` لكمية المادة.","سلك طوله `1.5 m` يمر فيه تيار `2 A` لمدة `30 s`، ودرجة حرارته `310 K`؛ كل قيمة هنا لكمية أساسية بوحدتها في SI.","لأن الزاوية بالراديان نسبة بين طولين، طول القوس على نصف القطر، فتلغي الوحدتان بعضهما وتصبح بلا أبعاد، لذلك ليست من الكميات الأساسية."],"أمثلة على الكميات المشتقة ووحداتها":["كل سطر في الجدول يقول: هذه الكمية تحسب بهذا القانون، فوحدتها تأتي من وحدات ما في القانون. فالكثافة كتلة على حجم فوحدتها `kg/m³`.","جسم كتلته `6 kg` وحجمه `0.002 m³`: كثافته `ρ = 6 ÷ 0.002 = 3000 kg/m³`.","لأن وحدتي طرفي أي قانون يجب أن تتساويا، فتعويض الوحدات الأساسية في القانون يعطي وحدة الكمية المشتقة مباشرة."],"تطبيقات من الحياة":["الوحدات حولنا في كل مكان: لتر البنزين وحدة حجم، وضغط الإطار يقاس بالبار أو psi، وجرعة الدواء بالمليجرام.","تعبئة `40 L` من الوقود تعني حجما `40 × 10⁻³ = 0.04 m³`، وقرص دواء `500 mg` كتلته `500 × 10⁻⁶ = 5 × 10⁻⁴ kg`.","لأن الأجهزة والحسابات العلمية تعمل بوحدات SI، فتحويل الوحدات اليومية إليها يمنع أخطاء قد تكون خطيرة، مثل خطأ جرعة الدواء."],"مثال محلول":["لنعرف وحدة القوة ننظر إلى قانونها: القوة كتلة في تسارع، إذن وحدتها هي وحدة الكتلة مضروبة في وحدة التسارع.","قوة تكسب كتلة `3 kg` تسارعا `2 m/s²`: `F = 3 × 2 = 6 N`، أي `6 kg·m/s²`.","لأن القانون مساواة بين طرفين، والمساواة لا تصح إلا بين أشياء من النوع نفسه، فوحدة الطرف الأيسر تساوي وحدة الطرف الأيمن."],"مثال محلول (تابع)":["نكتب وحدة الكتلة، ثم وحدة التسارع، ثم نضربهما، فينتج `kg·m/s²` ونسميه النيوتن اختصارا.","قوة `20 N` تؤثر في كتلة `4 kg`: التسارع `a = F ÷ m = 20 ÷ 4 = 5 m/s²`.","لأن التسارع تغير في السرعة كل ثانية، فنقسم `m/s` على `s` مرة أخرى، وعند ضربه في الكتلة نحصل على وحدة القوة."],"تمرين 1 · مثال ١ (صفحة 12)":["نحول من وحدة صغيرة إلى وحدة أكبر، فيقل العدد، لذلك نقسم على 100.","حول `45 cm` إلى متر: `L = 45 ÷ 100 = 0.45 m`.","لأن كل `100 cm` تكون مترا واحدا، فعدد الأمتار يساوي عدد السنتيمترات مقسوما على 100."]},"0-2":{"":["التحويل بين الوحدات يشبه تغيير العملة: المبلغ نفسه يكتب بأعداد مختلفة. والتحقق بالوحدات يشبه التأكد أن في كفتي الميزان النوع نفسه.","سرعة `72 km/h` تساوي `72 ÷ 3.6 = 20 m/s`. والقانون `x = v·t` صحيح الوحدات لأن `(m/s) × s = m`.","لأن القوانين الفيزيائية مكتوبة بوحدات SI، ولأن طرفي أي قانون صحيح يحملان الوحدة نفسها، فالتحويل والتحقق يمنعان أخطاء الحساب."],"قاعدة التحويل":["إذا انتقلت إلى وحدة أصغر احتجت عددا أكبر منها فتضرب، وإذا انتقلت إلى وحدة أكبر احتجت عددا أقل فتقسم. كأن تعد البيض بالحبة أو بالطبق.","`3.2 km` بالمتر: `3.2 × 1000 = 3200 m`، و `1.5 m` بالسنتيمتر: `1.5 × 100 = 150 cm`.","لأن الوحدة الكبيرة تحتوي عددا ثابتا من الوحدات الصغيرة يسمى معامل التحويل، فالضرب فيه أو القسمة عليه لا يغير المقدار الحقيقي."],"قاعدة التحويل (تابع)":["الكيلوجرام ألف جرام، والساعة ستون دقيقة في كل منها ستون ثانية، فمن الوحدة الكبيرة إلى الصغيرة نضرب في هذه الأعداد.","`0.25 kg` تساوي `0.25 × 1000 = 250 g`، و `1.5 h` تساوي `1.5 × 3600 = 5400 s`.","لأن الساعة تحولت مرتين: إلى دقائق ثم إلى ثوان، فيضرب المعاملان `60 × 60` ليعطيا معاملا واحدا هو 3600."],"تحويل السرعة":["السرعة فيها وحدتان: مسافة وزمن، فنحول كلا منهما. والنتيجة المختصرة: من km/h إلى m/s نقسم على 3.6، والعكس نضرب في 3.6.","سيارة سرعتها `54 km/h`: `v = 54 ÷ 3.6 = 15 m/s`. وعداء سرعته `8 m/s`: `8 × 3.6 = 28.8 km/h`.","لأن تحويل البسط يضرب في 1000 وتحويل المقام يقسم على 3600، و `3600 ÷ 1000 = 3.6`، فيجتمع التحويلان في عدد واحد."],"التحقق من صحة القانون بالوحدات":["القانون مثل الميزان: لا يتوازن إلا إذا كان في كفتيه النوع نفسه. فإذا كانت وحدة الطرفين واحدة فالقانون سليم الأبعاد.","تحقق من `P = F / A`: الطرف الأيمن `N ÷ m² = (kg·m/s²) ÷ m² = kg/(m·s²)`، وهي وحدة الباسكال `Pa`، فالقانون صحيح.","لأن المساواة لا تكون بين كميتين من نوعين مختلفين، فلا يصح مثلا أن يساوي طول زمنا، لذلك يكشف اختلاف الوحدات خطأ القانون."],"خطوات التحقق من صحة القانون بالوحدات":["نكتب وحدة كل رمز، ونعوض في كل طرف وحده، ونبسط إلى وحدات أساسية، ثم نقارن. وعند الجمع أو الطرح نتأكد أن الحدود متساوية الوحدة.","اختبر `x = v·t + a·t`: الحد الأول `(m/s) × s = m`، والحد الثاني `(m/s²) × s = m/s`، والحدان مختلفان، فالقانون خاطئ.","لأن الجمع لا يصح إلا بين أشياء من النوع نفسه، فلا تجمع مترا مع ثانية، ولأن طرفي المساواة يجب أن يكونا من النوع نفسه."],"أمثلة الحقيبة التدريبية محلولة":["كلمة «كيلو» تعني ألفا، فالكيلوجرام الواحد ألف جرام. ولأن الجرام أصغر نحتاج منه عددا أكبر، فنضرب.","حول `3.6 kg` إلى جرام: `m = 3.6 × 1000 = 3600 g`.","لأن البادئة k تساوي `10³`، فاستبدال الكيلوجرام بالجرام يعني ضرب العدد في `10³` حتى يبقى المقدار نفسه."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نعوض الكتلة في القانون ونضرب في 1000، فنحصل على الكتلة نفسها مكتوبة بالجرام.","حول `0.75 kg` إلى جرام: `m = 0.75 × 1000 = 750 g`.","لأن الكتلة لم تتغير، بل تغيرت الوحدة فقط، فكلما صغرت الوحدة كبر العدد بالنسبة نفسها."],"مثال ٣: تحويل السرعة من كيلومتر لكل ساعة إلى متر لكل ثانية (صفحة 13)":["نحول الكيلومتر في البسط إلى أمتار، والساعة في المقام إلى ثوان، كلا منهما على حدة، ثم نقسم.","حول `30 km/h`: `v = 30 × 1000 ÷ 3600 = 30000 ÷ 3600 ≈ 8.33 m/s`.","لأن السرعة نسبة مسافة إلى زمن، فتغيير وحدة المسافة يؤثر في البسط، وتغيير وحدة الزمن يؤثر في المقام، فيجب تحويل الاثنين."],"مثال ٣: تحويل السرعة من كيلومتر لكل ساعة إلى متر لكل ثانية (صفحة 13) (تابع)":["بعد الحساب نجد أن القسمة على 3600 بعد الضرب في 1000 هي نفسها القسمة على 3.6، وهذا أسرع.","حول `45 km/h`: `v = 45 ÷ 3.6 = 12.5 m/s`، وبالطريقة الطويلة `45000 ÷ 3600 = 12.5 m/s`.","لأن `1000 ÷ 3600 = 1 ÷ 3.6`، فالطريقتان متكافئتان رياضيا وتعطيان الناتج نفسه."],"مثال ١: تأكد من صحة القانون `F = m·a` (صفحة 14)":["نكتب وحدة القوة في جهة، ووحدة الكتلة مضروبة في وحدة التسارع في الجهة الأخرى، فإذا تطابقتا فالقانون سليم.","كتلة `5 kg` بتسارع `3 m/s²`: `F = 5 × 3 = 15 N`، ووحدة الناتج `kg × m/s² = kg·m/s² = N`.","لأن النيوتن عرف أصلا بأنه `kg·m/s²`، فوحدة الطرف الأيمن تطابق وحدة الطرف الأيسر تماما."],"مثال ٢: تأكد من صحة القانون `Vf = Vi + a·t` (صفحة 14)":["الطرف الأيمن فيه حدان مجموعان، فنتأكد أولا أن لهما الوحدة نفسها، ثم نقارن بالطرف الأيسر.","جسم سرعته الابتدائية `4 m/s` وتسارعه `2 m/s²` لمدة `3 s`: `Vf = 4 + 2 × 3 = 10 m/s`.","لأن الجمع لا يصح إلا بين حدين من نوع واحد، و `a·t` يعطي `m/s` مثل `Vi`، فالجمع مقبول."],"مثال ٢: تأكد من صحة القانون `Vf = Vi + a·t` (صفحة 14) (تابع)":["وحدة الطرف الأيسر `m/s` ووحدة الطرف الأيمن `m/s`، فالقانون سليم من جهة الوحدات.","جسم يبدأ من السكون `Vi = 0 m/s` بتسارع `5 m/s²` لمدة `4 s`: `Vf = 0 + 5 × 4 = 20 m/s`.","لأن تساوي وحدتي الطرفين شرط لصحة أي قانون، وقد تحقق هنا بعد تبسيط وحدات الطرف الأيمن."],"مثال ٣: تأكد من صحة القانون `W = F·x` (صفحة 14)":["الشغل قوة في مسافة، فوحدته نيوتن في متر، وهذا هو الجول. لكن الوحدات لا تكشف الأعداد الثابتة مثل 2 في مقام طاقة الحركة.","قوة `25 N` تحرك صندوقا `4 m` في اتجاهها: `W = 25 × 4 = 100 J`، و `N·m = kg·m²/s² = J`.","لأن العدد الثابت مثل 2 أو 0.5 ليس له وحدة، فوجوده أو غيابه لا يغير وحدة الطرف، لذلك قد تصح الوحدات ويبقى الثابت في القانون خاطئا."],"رسم توضيحي":["الرسم سلم: كل درجة أكبر من التي تحتها ألف مرة. فالنزول درجة يعني الضرب في 1000، والصعود درجة يعني القسمة على 1000.","`3 km` تنزل درجة إلى `3 × 1000 = 3000 m`، ثم درجة أخرى إلى `3000 × 1000 = 3 × 10⁶ mm`.","لأن البادئات الشائعة مثل كيلو `10³` وميجا `10⁶` وجيجا `10⁹` مبنية على قوى العدد 10، يفصل بين كل منها والتي تليها `10³`."],"البادئات الشائعة في النظام الدولي":["البادئة رمز يوضع قبل الوحدة ليختصر عددا كبيرا جدا أو صغيرا جدا، فبدلا من كتابة `0.001 m` نكتب `1 mm`.","`5 µm = 5 × 10⁻⁶ m`، و `2 GJ = 2 × 10⁹ J`، و `250 mg = 250 × 10⁻³ g = 0.25 g`.","لأن كتابة الأعداد الكبيرة والصغيرة جدا بالأصفار تسبب الخطأ، فالبادئات تختصرها بقوى العدد 10 وتسهل قراءتها."],"عوامل تحويل مفيدة":["الجدول يعطيك العملية الجاهزة لكل تحويل شائع. وتذكر أن المساحة يربع فيها معامل تحويل الطول، والحجم يكعب فيه.","`2 km²` تساوي `2 × 10⁶ m²`، و `1.2 g/cm³` تساوي `1.2 × 1000 = 1200 kg/m³`.","لأن الكيلومتر المربع مربع طوله `1000 m` وعرضه `1000 m`، فمساحته `1000 × 1000 = 10⁶ m²`، ولذلك يربع معامل الطول."],"تطبيقات من الحياة":["لوحة الطريق تكتب السرعة بالـ km/h لأنها أسهل للسائق، أما حسابات الفيزياء فتحتاج m/s، فنقسم على 3.6.","لوحة سرعة `120 km/h` تعني `120 ÷ 3.6 ≈ 33.3 m/s`، أي أن السيارة تقطع نحو `33 m` في كل ثانية.","لأن خلط وحدتين مختلفتين في حساب واحد يعطي أعدادا خاطئة قد تسبب حوادث أو أعطالا، فالتحقق من الوحدات يكشف ذلك قبل التنفيذ."],"تمرين 1 · مثال ٢ (صفحة 13)":["من الكيلوجرام إلى الجرام ننتقل إلى وحدة أصغر، فنضرب في 1000.","حول `4.5 kg` إلى جرام: `m = 4.5 × 1000 = 4500 g`.","لأن الكيلوجرام الواحد يحتوي ألف جرام، فكل كيلوجرام يتحول إلى 1000 جرام."],"تمرين 2 · مثال ٣ (صفحة 13)":["نضرب في 1000 لتحويل الكيلومترات إلى أمتار، ونقسم على 3600 لتحويل الساعات إلى ثوان.","حول `108 km/h`: `v = 108 × 1000 ÷ 3600 = 30 m/s`.","لأن السرعة بالـ m/s تخبرنا كم مترا يقطع الجسم في الثانية الواحدة، وهي الوحدة التي تعمل بها القوانين في SI."],"تمرين 3 · ورقة عمل (١) · سؤال ٢ (صفحة 15)":["المتر وحدة كبيرة والسنتيمتر وحدة صغيرة، فنضرب في 100 ليكبر العدد.","حول `2.4 m`: `L = 2.4 × 100 = 240 cm`.","لأن في المتر الواحد مئة سنتيمتر، فكل متر يتحول إلى 100 سنتيمتر."],"تمرين 4 · ورقة عمل (١) · سؤال ٣ (صفحة 16)":["الجرام أصغر من الكيلوجرام، فعند التحويل إلى الكيلوجرام يصغر العدد، لذلك نقسم على 1000.","حول `1250 g`: `m = 1250 ÷ 1000 = 1.25 kg`.","لأن كل ألف جرام تكون كيلوجراما واحدا، فعدد الكيلوجرامات هو عدد الجرامات مقسوما على 1000."],"تمرين 5 · ورقة عمل (١) · سؤال ٤ (صفحة 16)":["من m/s إلى km/h نضرب في 3.6، فيكبر العدد لأن الجسم يقطع في الساعة مسافة كبيرة.","حول `12 m/s`: `v = 12 × 3.6 = 43.2 km/h`.","لأن الجسم الذي يقطع `1 m` كل ثانية يقطع `3600 m` في الساعة، أي `3.6 km`، فالمعامل 3.6."],"تمرين 6 · تمارين الوحدة · اختر الإجابة ٢ (صفحة 28)":["نضرب السرعة في 3.6 للانتقال من متر لكل ثانية إلى كيلومتر لكل ساعة.","حول `25 m/s`: `v = 25 × 3.6 = 90 km/h`.","لأن الساعة `3600 s` والكيلومتر `1000 m`، و `3600 ÷ 1000 = 3.6` هو عدد الكيلومترات في الساعة المقابل لـ `1 m/s`."],"تمرين 7 · تمارين الوحدة · اختر الإجابة ١٠ (صفحة 29)":["النانومتر جزء صغير جدا من المتر، ففي المتر الواحد مليار نانومتر، لذلك نضرب في `10⁹`.","حول `0.5 m` إلى نانومتر: `L = 0.5 × 10⁹ = 5 × 10⁸ nm`.","لأن البادئة نانو تعني `10⁻⁹`، أي أن `1 nm = 10⁻⁹ m`، فالمتر يحتوي `10⁹` من النانومترات."],"تمرين 8 · تمارين الوحدة · اختر الإجابة ١١ (صفحة 29)":["الكيلومتر المربع مربع ضلعه ألف متر، فمساحته ألف في ألف متر مربع، أي نربع معامل التحويل.","حول `3 km²`: `S = 3 × 1000² = 3 × 10⁶ m²`.","لأن المساحة طول في طول، وكل طول يحول بالضرب في 1000، فيضرب الناتج في `1000 × 1000`."],"تمرين 9 · تمارين الوحدة · اختر الإجابة ١٣ (صفحة 30)":["الساعة ستون دقيقة، وكل دقيقة ستون ثانية، فنضرب عدد الساعات في 3600.","حول `2.5 h`: `t = 2.5 × 3600 = 9000 s`.","لأن التحويل يمر بخطوتين، من الساعة إلى الدقيقة ثم إلى الثانية، فيضرب المعاملان `60 × 60 = 3600`."]},"0-3":{"":["ورقة العمل تجمع ما تدربت عليه: وحدات SI، والتحويل بين الوحدات، والتحقق من القوانين بالوحدات، مع حل كل سؤال خطوة بخطوة.","من نوع أسئلة الورقة: حول `7 m` إلى سنتيمتر: `7 × 100 = 700 cm`، وحول `10 m/s` إلى km/h: `10 × 3.6 = 36 km/h`.","لأن حل التمارين بنفسك يثبت القواعد ويكشف مواضع الخطأ، مثل الخلط بين الضرب والقسمة في التحويل."],"ما تحتاجه لحل ورقة العمل":["قبل الحل جهز ثلاث أدوات: جدول الوحدات، ومعاملات التحويل، وطريقة مقارنة وحدتي طرفي القانون.","طاقة الوضع لجسم `2 kg` على ارتفاع `5 m` مع `g = 9.8 m/s²`: `P = 2 × 9.8 × 5 = 98 J`.","لأن كل سؤال في الورقة يعتمد على واحدة من هذه الأدوات، فإتقانها يجعل الحل خطوات واضحة لا تخمينا."],"حل ورقة العمل":["لكل كمية وحدة دولية واحدة: الطول بالمتر، والكتلة بالكيلوجرام، والسرعة بالمتر لكل ثانية، والقوة بالنيوتن.","سيارة كتلتها `1200 kg` تتسارع `2 m/s²`: القوة `F = 1200 × 2 = 2400 N`، وكل القيم بوحدات SI.","لأن النيوتن وحدة مشتقة عرفت من قانون `F = m·a`، فهو يساوي وحدة الكتلة مضروبة في وحدة التسارع."],"حل ورقة العمل (تابع)":["الشغل والطاقة لهما الوحدة نفسها، الجول. والمساحة بالمتر المربع، والحجم بالمتر المكعب، والأمبير لشدة التيار.","خزان أبعاده `2 m` و `1 m` و `0.5 m`: حجمه `V = 2 × 1 × 0.5 = 1 m³`، ومساحة قاعدته `2 × 1 = 2 m²`.","لأن الطاقة هي القدرة على بذل شغل، فتقاس بالوحدة نفسها التي يقاس بها الشغل، أي الجول."],"سؤال ٢: حوّل 3 m إلى cm (صفحة 15)":["المتر فيه مئة سنتيمتر، فكل متر نحوله إلى 100، ثم نضرب في عدد الأمتار.","حول `4.2 m`: `L = 4.2 × 100 = 420 cm`.","لأن السنتيمتر أصغر من المتر بمئة مرة، فيحتاج الطول نفسه عددا أكبر بمئة مرة."],"سؤال ٣: حوّل 500 g إلى kg (صفحة 16)":["الكيلوجرام ألف جرام، فنقسم عدد الجرامات على 1000 لنعرف كم كيلوجراما لدينا.","حول `750 g`: `m = 750 ÷ 1000 = 0.75 kg`.","لأن الانتقال إلى وحدة أكبر يجعل العدد أصغر، والوحدة الأكبر هنا تساوي ألف وحدة صغيرة."],"سؤال ٤: حوّل 4.4 m/s إلى km/h (صفحة 16)":["المتر جزء من ألف من الكيلومتر، والثانية جزء من 3600 من الساعة، فيجتمع ذلك في الضرب في 3.6.","حول `15 m/s`: `v = 15 × 3.6 = 54 km/h`.","لأن `1 m/s` يعني `3600 m` في الساعة، وهي `3.6 km`، فكل `1 m/s` يقابل `3.6 km/h`."],"سؤال ٥ (أولاً): تأكد من صحة القانون v = x·t بالوحدات (صفحة 16)":["السرعة مسافة مقسومة على زمن، أما ضرب المسافة في الزمن فيعطي وحدة `m·s` لا تشبه وحدة السرعة.","جسم يقطع `100 m` في `20 s`: `v = 100 ÷ 20 = 5 m/s`، أما `100 × 20 = 2000 m·s` فليست سرعة.","لأن طرفي القانون يجب أن يحملا الوحدة نفسها، و `m/s` لا تساوي `m·s`، فالقانون بالضرب خاطئ."],"سؤال ٥ (ثانياً): تأكد من صحة القانون P = m·g·h بالوحدات (صفحة 17)":["نضرب وحدة الكتلة في وحدة تسارع الجاذبية في وحدة الارتفاع، فينتج الجول، وهو وحدة الطاقة، فالقانون صحيح.","جسم `3 kg` على ارتفاع `4 m` مع `g = 9.8 m/s²`: `P = 3 × 9.8 × 4 = 117.6 J`.","لأن `m·g` هو الوزن، أي قوة بالنيوتن، وضرب القوة في الارتفاع يعطي شغلا بالجول، وهي وحدة الطاقة نفسها."],"سؤال ٥ (ثالثاً): تأكد من صحة القانون vf = vi + a·t بالوحدات (صفحة 17)":["نتأكد أولا أن الحدين المجموعين من النوع نفسه، ثم أن الناتج يطابق وحدة السرعة النهائية.","`vi = 6 m/s` و `a = 1.5 m/s²` و `t = 4 s`: `vf = 6 + 1.5 × 4 = 12 m/s`.","لأن التسارع مضروبا في الزمن يعطي تغيرا في السرعة بوحدة `m/s`، فيجمع مع السرعة الابتدائية ويعطي سرعة."],"رسم توضيحي":["سلم البادئات: كل درجة تساوي ألف مرة الدرجة التي تحتها، فالنزول يعني الضرب في 1000 والصعود يعني القسمة على 1000.","`2.5 kg` تنزل درجة إلى `2500 g`، ثم درجة أخرى إلى `2.5 × 10⁶ mg`.","لأن البادئات مثل كيلو وميجا وجيجا وميلي وميكرو ونانو يفصل بين كل منها والتي تليها `10³`، فيكفي معامل واحد للانتقال بين درجتين."],"تطبيقات من الحياة":["حول ما تراه يوميا: سرعة السيارة على العداد، وكتلة المشتريات على الميزان. هذا تدريب سريع يثبت القاعدة.","عداد السيارة يشير إلى `72 km/h`، أي `72 ÷ 3.6 = 20 m/s`. وكيس أرز `1500 g` يساوي `1500 ÷ 1000 = 1.5 kg`.","لأن تكرار التحويل في مواقف حقيقية يجعل القاعدة عادة، فلا تتردد بين الضرب والقسمة في الاختبار."],"تمرين 1 · سؤال ٢ (صفحة 15)":["من المتر إلى السنتيمتر نضرب في 100، لأن الوحدة الجديدة أصغر.","حول `0.85 m`: `L = 0.85 × 100 = 85 cm`.","لأن الطول الحقيقي لا يتغير، فإذا صغرت الوحدة مئة مرة كبر العدد مئة مرة."],"تمرين 2 · سؤال ٣ (صفحة 16)":["من الجرام إلى الكيلوجرام نقسم على 1000، لأن الوحدة الجديدة أكبر.","حول `3200 g`: `m = 3200 ÷ 1000 = 3.2 kg`.","لأن الكتلة ثابتة، فإذا كبرت الوحدة ألف مرة صغر العدد ألف مرة."],"تمرين 3 · سؤال ٤ (صفحة 16)":["نضرب السرعة بالمتر لكل ثانية في 3.6 لنحصل عليها بالكيلومتر لكل ساعة.","حول `20 m/s`: `v = 20 × 3.6 = 72 km/h`.","لأن `3.6` هو ناتج `3600 ÷ 1000`، أي عدد ثواني الساعة مقسوما على عدد أمتار الكيلومتر."]},"0-4":{"":["بعض الكميات يكفيها عدد ووحدة مثل الكتلة، وبعضها يحتاج اتجاها أيضا مثل القوة. وجمع النوع الثاني لا يكون بالجمع العادي بل بقانون جيب التمام.","قوتان `3 N` و `4 N` متعامدتان: المحصلة `C = √(3² + 4²) = √25 = 5 N`، وليست `7 N`.","لأن الاتجاه يغير أثر الكمية؛ فقوتان في الاتجاه نفسه تتعاونان، ومتعاكستان تضعف إحداهما الأخرى، فلا بد من حساب الزاوية بينهما."],"نوعان من الكميات":["إذا قلت «اشتريت `2 kg` من التمر» فالمعنى كامل بلا اتجاه، فهي قياسية. أما «قوة `10 N`» فتحتاج أن تقول نحو أي اتجاه، فهي متجهة.","مسافة `5 km` كمية قياسية. أما إزاحة `5 km` نحو الشمال فكمية متجهة، وتختلف عن إزاحة `5 km` نحو الجنوب.","لأن أثر الكميات المتجهة كالقوة والسرعة يعتمد على اتجاهها، فدفع صندوق إلى الأمام يختلف عن دفعه إلى الخلف وإن تساوت القوة."],"إيجاد المحصلة بقانون جيب التمام":["إذا خرج المتجهان من نقطة واحدة نستخدم الإشارة الموجبة مع الزاوية بينهما، وفي وضع رأس عند ذيل نستخدم الإشارة السالبة مع الزاوية الداخلية للمثلث.","متجهان `8` و `15` بينهما `90°` ذيلا على ذيل: `C² = 64 + 225 + 0 = 289`، فـ `C = 17`.","لأن المحصلة هي الضلع الثالث في المثلث المكون من المتجهين، وقانون جيب التمام يعطي طول ضلع إذا عرفنا الضلعين الآخرين والزاوية."],"ملحوظة: إشارة cos θ":["لا تغير إشارة القانون بنفسك؛ اكتب `+2AB·cos θ` دائما في حالة ذيل على ذيل، ودع قيمة `cos θ` تصير سالبة وحدها إذا كانت الزاوية أكبر من 90°.","`A = 5` و `B = 5` و `θ = 120°`: `C² = 25 + 25 + 2(5)(5)(−0.5) = 50 − 25 = 25`، فـ `C = 5`.","لأن جيب تمام الزاوية المنفرجة سالب، فالحد الثالث يطرح تلقائيا، وهذا منطقي لأن المتجهين يتعاكسان جزئيا فتقل المحصلة."],"أمثلة الحقيبة التدريبية محلولة":["المتجهان يبدآن من النقطة نفسها والزاوية بينهما صغيرة، فهما يتعاونان تقريبا، لذلك نستخدم الإشارة الموجبة.","`A = 3` و `B = 5` و `θ = 60°`: `C² = 9 + 25 + 2(3)(5)(0.5) = 34 + 15 = 49`، فـ `C = 7`.","لأن الزاوية أصغر من 90° فإن `cos θ` موجب، فيزيد الحد الثالث المحصلة، لأن المتجهين يشيران تقريبا إلى الجهة نفسها."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نعوض، ونحسب المربعات، ثم الحد الثالث، ثم نجمع ونأخذ الجذر. ونتأكد أن الناتج بين فرق المتجهين ومجموعهما.","`A = 2` و `B = 6` و `θ = 60°`: `C² = 4 + 36 + 2(2)(6)(0.5) = 40 + 12 = 52`، فـ `C = √52 ≈ 7.21`.","لأن أكبر محصلة تكون عندما يتجه المتجهان معا `A + B`، وأصغرها عند التعاكس `|A − B|`، فأي زاوية أخرى تعطي قيمة بينهما."],"مثال ٢: محصلة متجهين بينهما زاوية منفرجة (صفحة 19)":["الزاوية `120°` كبيرة، فالمتجهان يقتربان من التعاكس، لذلك تكون المحصلة أصغر مما لو كانت الزاوية حادة.","`A = 4` و `B = 4` و `θ = 120°`: `C² = 16 + 16 + 2(4)(4)(−0.5) = 32 − 16 = 16`، فـ `C = 4`.","لأن `cos 120°` سالب، فالحد الثالث يطرح من مجموع المربعات، وهذا يعبر عن أن جزءا من كل متجه يلغي جزءا من الآخر."],"مثال ٢: محصلة متجهين بينهما زاوية منفرجة (صفحة 19) (تابع)":["بعد التعويض نطرح الحد الثالث لأنه سالب، ثم نأخذ الجذر. والناتج أصغر من المتجه الأكبر لأن الزاوية منفرجة.","`A = 3` و `B = 8` و `θ = 120°`: `C² = 9 + 64 − 24 = 49`، فـ `C = 7`.","لأن المتجهين يعاكس كل منهما الآخر جزئيا، فتنقص المحصلة عن مجموعهما، وقد تصبح أصغر من أكبرهما."],"رسم توضيحي 1":["نرسم المتجهين من نقطة واحدة ونكمل الشكل متوازي أضلاع، فالقطر الخارج من نقطة البداية هو المحصلة.","متجهان `6` و `8` متعامدان: متوازي الأضلاع هنا مستطيل، وقطره `C = √(36 + 64) = 10`.","لأن نقل أحد المتجهين إلى رأس الآخر دون تغيير طوله أو اتجاهه يعطي الضلع المقابل في متوازي الأضلاع، فالقطر يجمع الأثرين معا."],"رسم توضيحي 2":["إذا كانت الزاوية بين ذيلي المتجهين فالحد موجب، وإذا كانت عند التقاء رأس A بذيل B فالحد سالب، لأن الزاوية هنا داخل المثلث.","`A = 4` و `B = 4` رأس عند ذيل والزاوية الداخلية `60°`: `C² = 16 + 16 − 16 = 16`، فـ `C = 4`، وهو ما تعطيه زاوية `120°` بين الذيلين بالإشارة الموجبة.","لأن الزاوية الداخلية في المثلث تكمل الزاوية بين الذيلين إلى `180°`، و `cos(180° − θ) = −cos θ`، فتنقلب الإشارة."],"رسم توضيحي 3":["إذا اتجه المتجهان معا جمعنا طوليهما فحصلنا على أكبر محصلة، وإذا تعاكسا طرحنا فحصلنا على أصغرها.","متجهان `5` و `2`: أكبر محصلة `5 + 2 = 7` عند `θ = 0°`، وأصغرها `5 − 2 = 3` عند `θ = 180°`.","لأن `cos 0° = 1` يجعل `C² = (A + B)²`، و `cos 180° = −1` يجعل `C² = (A − B)²`، وهما أكبر وأصغر قيمة ممكنة."],"الكمية القياسية والكمية المتجهة":["القياسية عدد ووحدة وتجمع جمعا عاديا، والمتجهة عدد ووحدة واتجاه، وتمثل بسهم وتجمع بقانون جيب التمام.","كتلتان `3 kg` و `4 kg` مجموعهما `7 kg` دائما، أما قوتان `3 N` و `4 N` فمحصلتهما بين `1 N` و `7 N` حسب الزاوية.","لأن الكمية القياسية ليس لها اتجاه فتجمع جمعا عاديا، أما المتجهة فاتجاهها يحدد هل تتعاون مع غيرها أم تعاكسه."],"تطبيقات من الحياة":["الطائرة يدفعها محركها وتدفعها الرياح معا، فسرعتها الحقيقية محصلة المتجهين، لا مجموع العددين.","طائرة سرعتها `200 m/s` شرقا ورياح `50 m/s` شمالا: `C = √(200² + 50²) = √42500 ≈ 206 m/s`.","لأن القوى والسرعات متجهة، فتجاهل اتجاهها في تصميم الجسور أو مسارات الطيران يعطي حسابات خاطئة قد تسبب انهيارا أو انحرافا."],"تمرين 1 · ورقة عمل (٢) · سؤال ٣ (صفحة 24)":["متجهان صغيران `2` و `3` بزاوية حادة، فالمحصلة قريبة من مجموعهما لكنها أقل منه.","`A = 3` و `B = 4` و `θ = 60°`: `C² = 9 + 16 + 2(3)(4)(0.5) = 25 + 12 = 37`، فـ `C = √37 ≈ 6.08`.","لأن `cos 60° = 0.5` موجب، فالحد الثالث يجعل المحصلة أكبر من حالة التعامد `√13 ≈ 3.61`، وتبقى أقل من المجموع `5`."]},"0-5":{"":["تحليل المتجه يعني تقسيمه إلى جزأين: جزء على المحور السيني وجزء على المحور الصادي. مثل ظل عصا مائلة على الأرض وظلها على الحائط.","متجه `A = 10 m` يصنع `30°` مع المحور السيني: `Ax = 10 × 0.866 ≈ 8.66 m` و `Ay = 10 × 0.5 = 5 m`.","لأن المحورين متعامدان، فكل مركبة مستقلة عن الأخرى. وهذا يسهل جمع المتجهات وحل المسائل بالعمل على كل محور وحده."],"تحليل متجه إلى مركبتين":["المتجه المائل هو وتر مثلث قائم، والمركبتان ضلعاه. جيب التمام يعطي الضلع على المحور السيني، والجيب يعطي الضلع على المحور الصادي.","مركبتا متجه `Ax = 3 m` و `Ay = 4 m`: المقدار `A = √(3² + 4²) = √25 = 5 m`، والاتجاه `tan θ = 4 ÷ 3 ≈ 1.33` فتكون `θ ≈ 53.1°`.","لأن المتجه ومركبتيه تشكل مثلثا قائما، فتنطبق عليه علاقات المثلث القائم: تعريف الجيب وجيب التمام ونظرية فيثاغورس."],"نصائح":["القانونان مبنيان على زاوية تقاس من المحور السيني. فإذا أعطيت الزاوية من المحور الصادي فاطرحها من `90°` أولا.","متجه `A = 10 m` يصنع `60°` مع المحور الصادي، إذن زاويته مع السيني `30°`: `Ax = 10 × 0.866 ≈ 8.66 m` و `Ay = 10 × 0.5 = 5 m`.","لأن جيب التمام يربط الوتر بالضلع المجاور للزاوية. فإذا تغير الضلع المجاور تبادل الجيب وجيب التمام دوريهما."],"أمثلة الحقيبة التدريبية محلولة":["نرسم المتجه وترا لمثلث قائم. الضلع الملاصق للزاوية هو المركبة السينية، والضلع المقابل لها هو المركبة الصادية.","قوة `F = 6 N` تصنع `60°` مع المحور السيني: `Fx = 6 × 0.5 = 3 N` و `Fy = 6 × 0.866 ≈ 5.20 N`.","لأن جيب التمام يساوي المجاور على الوتر، والجيب يساوي المقابل على الوتر. فضرب الوتر فيهما يعطي الضلعين."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["بعد حساب المركبتين نحدد إشارتيهما من الربع الذي يقع فيه المتجه، ثم نتحقق بأن جذر مجموع مربعيهما يعيد المقدار الأصلي.","متجه `A = 10 m` بزاوية `30°`: `Ax ≈ 8.66 m` و `Ay = 5 m`. التحقق: `√(8.66² + 5²) = √(75 + 25) = √100 = 10 m`.","لأن المركبتين ضلعا مثلث قائم وتره المتجه، ونظرية فيثاغورس تربط الوتر بالضلعين. فإن لم يتطابق الناتج فهناك خطأ في الحساب."],"تمرين: تمرين تحليل متجه بزاوية خمس وأربعين درجة (صفحة 21)":["الزاوية `45°` تقع في منتصف المسافة بين المحورين، لذلك يتقاسم المتجه طوله بالتساوي على المحورين.","متجه `A = 10 m` بزاوية `45°`: `Ax = 10 × 0.707 ≈ 7.07 m` و `Ay = 10 × 0.707 ≈ 7.07 m`.","لأن `cos 45°` و `sin 45°` متساويان، فالمثلث القائم هنا متساوي الساقين، فتتساوى المركبتان."],"تمرين: تمرين تحليل متجه بزاوية خمس وأربعين درجة (صفحة 21) (تابع)":["المركبتان موجبتان لأن المتجه في الربع الأول. والتحقق بفيثاغورس يؤكد أن الحساب صحيح.","متجه `A = 8 m` بزاوية `45°`: كل مركبة `8 × 0.707 ≈ 5.66 m`. التحقق: `√(32 + 32) = √64 = 8 m`.","لأن مربعي المركبتين متساويان، وكل منهما نصف مربع المقدار، فمجموعهما يعيد مربع المقدار كاملا."],"رسم توضيحي":["الرسم يبين المتجه `A` مائلا، ومنه خطان: واحد على المحور السيني هو `Ax`، وآخر على المحور الصادي هو `Ay`. كأنهما ظلا المتجه على المحورين.","متجه `A = 2 m` بزاوية `60°`: `Ax = 2 × 0.5 = 1 m` و `Ay = 2 × 0.866 ≈ 1.73 m`.","لأن الإسقاط العمودي على كل محور يصنع زاوية قائمة، فيتكون مثلث قائم تنطبق عليه قوانين الجيب وجيب التمام."],"تطبيقات من الحياة":["في الحياة نحلل الحركة أو القوة إلى جزأين لنفهم أثر كل جزء. ركلة الكرة جزء منها يدفعها للأمام وجزء يرفعها للأعلى.","كرة ركلت بسرعة `20 m/s` بزاوية `30°`: المركبة الأفقية `20 × 0.866 ≈ 17.3 m/s` والرأسية `20 × 0.5 = 10 m/s`.","لأن كل مركبة تؤثر في اتجاه محورها فقط، فنحسب أثر كل اتجاه وحده ثم نجمع الصورة كاملة."],"تمرين 1 · ورقة عمل (٢) · سؤال ٤ (صفحة 25)":["المطلوب المركبة السينية فقط، فنضرب المقدار في جيب تمام الزاوية لأنها مقاسة من المحور السيني.","قوة `F = 12 N` بزاوية `30°`: `Fx = 12 × cos 30° = 12 × 0.866 ≈ 10.39 N`.","لأن المركبة السينية هي الضلع المجاور للزاوية في المثلث القائم، وجيب التمام يربط المجاور بالوتر."],"تمرين 2 · ورقة عمل (٢) · سؤال ٤ (صفحة 25)":["المطلوب المركبة الصادية، فنضرب المقدار في جيب الزاوية لأن المركبة الصادية تقابل الزاوية.","قوة `F = 12 N` بزاوية `30°`: `Fy = 12 × sin 30° = 12 × 0.5 = 6 N`.","لأن المركبة الصادية هي الضلع المقابل للزاوية، والجيب يساوي المقابل على الوتر. وعند `30°` يكون الجيب نصفا، فالمركبة نصف المقدار."]},"0-6":{"":["متجهات الوحدة أسهم طولها 1 تدل على اتجاه المحاور. وهناك ضربان للمتجهات: القياسي يعطي عددا، والاتجاهي يعطي متجها جديدا.","`A = 3î + 4ĵ` و `B = 2î + ĵ`: الضرب القياسي `A·B = (3)(2) + (4)(1) = 10`، والضرب الاتجاهي `A × B = (3 × 1 − 4 × 2)k̂ = −5k̂`.","لأن بعض الكميات الفيزيائية عددية مثل الشغل، وبعضها متجه مثل عزم الدوران. فلكل منها نوع ضرب يناسبها."],"متجهات الوحدة":["متجه الوحدة مثل لافتة الاتجاه: تخبرك بالجهة فقط. والرقم أمامه يخبرك كم تمشي في تلك الجهة.","إزاحة `d = 3î + 4ĵ m` تعني `3 m` على المحور x و `4 m` على المحور y، ومقدارها `√(3² + 4²) = 5 m`.","لأن مقدار متجه الوحدة 1، فضربه في عدد لا يغير الاتجاه ويعطي المركبة بطولها الحقيقي."],"الضرب القياسي (النقطي) A·B ← الناتج كمية قياسية":["الضرب القياسي يجمع متجهين ويخرج عددا بلا اتجاه. ونحسبه بطريقتين حسب ما نعرفه عن المتجهين: المقدار والزاوية، أو المركبات.","قوة `F = 10 N` تؤثر في جسم يتحرك `d = 5 m` في اتجاهها نفسه: `W = F·d = 10 × 5 × cos 0° = 50 J`، وهو عدد بلا اتجاه.","لأن الضرب القياسي يأخذ من أحد المتجهين جزأه الموازي للآخر فقط ويضربه فيه، فالناتج يقيس التوافق بينهما لا اتجاها."],"أولا: الضرب القياسي لمتجهين ممثلين بالإحداثيات القطبية":["إذا عرفنا طولي المتجهين والزاوية بينهما، نضرب الطولين في جيب تمام الزاوية. وكلما اتجه المتجهان معا كبر الناتج.","`|A| = 5` و `|B| = 4` والزاوية `60°`: `A·B = 5 × 4 × cos 60° = 20 × 0.5 = 10`.","لأن `|B|·cos θ` هو الجزء من `B` الموازي لـ `A`، وضرب الموازي في الموازي هو معنى الضرب القياسي."],"أولا: الضرب القياسي لمتجهين ممثلين بالإحداثيات القطبية (تابع)":["يمكن عكس القانون: إذا عرفنا الضرب القياسي والمقدارين نقسم لنجد جيب تمام الزاوية، ثم نستخدم الآلة لإيجاد الزاوية.","`|A| = 2` و `|B| = 3` و `A·B = −3`: `cos θ = −3 ÷ (2 × 3) = −0.5`، إذن `θ = cos⁻¹(−0.5) = 120°`.","لأن الضرب القياسي يساوي حاصل ضرب المقدارين في `cos θ`، فالقسمة على المقدارين تترك `cos θ` وحده."],"ثانيا: الضرب القياسي لمتجهين ممثلين بالإحداثيات الديكارتية ومتجهات الوحدة":["إذا كان المتجهان مكتوبين بالمركبات، نضرب كل مركبة في نظيرتها على المحور نفسه ثم نجمع النواتج.","`A = î + 2ĵ + 3k̂` و `B = 4î − ĵ + 2k̂`: `A·B = (1)(4) + (2)(−1) + (3)(2) = 4 − 2 + 6 = 8`.","لأن `î·î = 1` بينما `î·ĵ = 0` لتعامد المحورين، فلا يبقى من الضرب إلا حاصل ضرب المركبات على المحور نفسه."],"ثانيا: الضرب القياسي لمتجهين ممثلين بالإحداثيات الديكارتية ومتجهات الوحدة (تابع)":["بعد كتابة القانون نعوض بالمركبات مع إشاراتها، ونضع السالب بين قوسين حتى لا تضيع الإشارة.","`A = 4î + ĵ` و `B = 2î − 3ĵ`: `A·B = (4)(2) + (1)(−3) = 8 − 3 = 5`.","لأن كل حد في القانون حاصل ضرب عددين بإشارتيهما، وخطأ إشارة واحدة يغير الناتج كله."],"الضرب الاتجاهي A×B ← الناتج كمية متجهة":["الضرب الاتجاهي يأخذ متجهين ويخرج متجها جديدا عموديا عليهما معا. مثل مفتاح الصامولة: تدفع بيدك في مستوى، والصامولة تتحرك عموديا عليه.","مفتاح طوله `r = 0.5 m` تؤثر عليه قوة عمودية `F = 20 N`: `|τ| = 0.5 × 20 × sin 90° = 10 N·m`.","لأن الناتج يحتاج اتجاها يميزه، والاتجاه الوحيد المرتبط بالمتجهين معا بالتساوي هو العمودي على مستواهما."],"أولا: الضرب الاتجاهي لمتجهين ممثلين بالإحداثيات القطبية":["مقدار الضرب الاتجاهي هو حاصل ضرب الطولين في جيب الزاوية، واتجاهه عمودي على المستوى الذي يحوي المتجهين.","`|A| = 4` و `|B| = 5` والزاوية `30°`: `|A × B| = 4 × 5 × sin 30° = 20 × 0.5 = 10`.","لأن `|B|·sin θ` هو الجزء من `B` العمودي على `A`، فالضرب الاتجاهي يقيس مقدار التعامد بين المتجهين."],"أولا: الضرب الاتجاهي لمتجهين ممثلين بالإحداثيات القطبية (تابع)":["اتجاه الناتج نحدده بقاعدة اليد اليمنى. وإذا عكسنا ترتيب الضرب انقلب الاتجاه، و `n̂` نكتبه فقط لنذكر أن الناتج متجه.","إذا كان `A × B = 12 n̂` إلى الأعلى، فإن `B × A = −12 n̂`، أي المقدار `12` نفسه لكن إلى الأسفل.","لأن عكس الترتيب يعكس اتجاه الدوران من المتجه الأول إلى الثاني، فيشير الإبهام في قاعدة اليد اليمنى إلى الجهة المعاكسة."],"ثانيا: الضرب الاتجاهي لمتجهين ممثلين بالإحداثيات الديكارتية ومتجهات الوحدة":["ضرب متجهي وحدة متعامدين يعطي متجه الوحدة الثالث، بشرط اتباع الترتيب الدوري x ثم y ثم z ثم العودة إلى x.","`(2î) × (3ĵ) = 6(î × ĵ) = 6k̂`، و `(4ĵ) × (2k̂) = 8(ĵ × k̂) = 8î`.","لأن الناتج يجب أن يكون عموديا على المتجهين، والمحور العمودي على x و y هو z، ومقدار الناتج `1 × 1 × sin 90° = 1`."],"ثانيا: الضرب الاتجاهي لمتجهين ممثلين بالإحداثيات الديكارتية ومتجهات الوحدة (تابع)":["ضرب متجه وحدة في نفسه اتجاهيا يعطي صفرا. وللمتجهين الكاملين نستخدم قانون المركبات مع الانتباه للإشارات.","`A = 2î + 3ĵ` و `B = î + 4ĵ`: مركبتا `î` و `ĵ` صفر لأن `Az = Bz = 0`، ويبقى `A × B = (2 × 4 − 3 × 1)k̂ = 5k̂`.","لأن الزاوية بين المتجه ونفسه صفر، و `sin 0° = 0`، فلا يوجد جزء عمودي ينتج عنه متجه."],"مثال ١ (صفحة 22)":["نبدأ بكتابة كل المركبات، ومنها المركبات الصفرية للمحور الغائب، حتى لا ننسى أي حد عند التعويض.","`A = 3î + 4ĵ` و `B = 4î − 3ĵ`: `|A| = 5` و `|B| = 5` و `A·B = (3)(4) + (4)(−3) = 0`، إذن `θ = 90°`.","لأن المحور غير المكتوب في المتجه مركبته صفر، وإهماله أو وضع رقم خاطئ مكانه يفسد القانون."],"مثال ١ (صفحة 22) (تابع)":["نحسب المقدارين من الجذر، والضرب القياسي من المركبات، ثم نقسم لنحصل على جيب تمام الزاوية ونستخدم الآلة.","`A = î + ĵ` و `B = î`: `|A| = √2 ≈ 1.41` و `|B| = 1` و `A·B = 1`، إذن `cos θ = 1 ÷ 1.41 ≈ 0.707` و `θ ≈ 45°`.","لأن الضرب القياسي يحسب بطريقتين فنساوي بينهما: المركبات تعطي قيمته، والمقداران يعطيان ما يضرب في `cos θ`. والناتج السالب يعني زاوية منفرجة."],"مثال ٢ (صفحة 23)":["نكتب المركبات الست، ثم نعوض في القانون حدا حدا، فكل حد يعطي مركبة واحدة من الناتج.","`A = î + 2ĵ` و `B = 3k̂`: `A×B = (2 × 3 − 0)î + (0 − 1 × 3)ĵ + (1 × 0 − 2 × 0)k̂ = 6î − 3ĵ`.","لأن قانون المركبات يجمع نتائج ضرب متجهات الوحدة بعضها في بعض، وكل زوج منها يعطي متجه وحدة محددا بالترتيب الدوري."],"مثال ٢ (صفحة 23) (تابع)":["بعد التعويض نحسب كل قوس وحده بإشاراته، ثم نكتب الناتج متجها بثلاث مركبات.","`A = 2î + ĵ` و `B = î + 3k̂`: `A×B = (1 × 3 − 0)î + (0 − 2 × 3)ĵ + (2 × 0 − 1 × 1)k̂ = 3î − 6ĵ − k̂`.","لأن الناتج عمودي على المتجهين، ويمكن التحقق: ضربه القياسي في `A` يعطي `6 − 6 + 0 = 0`، أي أنه عمودي عليه فعلا."],"مثال ٣ (صفحة 23)":["إذا عرفنا المقدارين والزاوية، نحسب الضربين من القانونين: جيب التمام للقياسي، والجيب للاتجاهي.","`|A| = 6` و `|B| = 4` والزاوية `30°`: `A·B = 24 × 0.866 ≈ 20.78` و `|A × B| = 24 × 0.5 = 12`.","لأن الضرب القياسي يقيس الجزء الموازي (جيب التمام) والضرب الاتجاهي يقيس الجزء العمودي (الجيب)."],"مثال ٣ (صفحة 23) (تابع)":["نعوض بالأرقام في القانونين ونحسب. والضرب القياسي عدد، أما ما حسبناه من الاتجاهي فهو مقدار متجه فقط.","`|A| = 10` و `|B| = 2` والزاوية `90°`: `A·B = 20 × cos 90° = 0` و `|A × B| = 20 × sin 90° = 20`.","لأن عند التعامد لا يوجد جزء مواز فينعدم الضرب القياسي، ويكون الجزء العمودي كاملا فيبلغ الاتجاهي أكبر قيمة."],"رسم توضيحي 1":["الرسم يبين ثلاثة أسهم قصيرة طول كل منها 1، كل سهم على محور: `î` على x و `ĵ` على y و `k̂` على z.","المتجه `5î` سهم طوله `5` على المحور x، والمتجه `−2k̂` سهم طوله `2` في الاتجاه السالب للمحور z.","لأن متجه الوحدة يحدد الاتجاه فقط، فنحتاج ثلاثة منها لنصف أي اتجاه في الفضاء ثلاثي الأبعاد."],"رسم توضيحي 2":["الرسم دائرة عليها `î` ثم `ĵ` ثم `k̂`. إذا ضربت باتجاه الدوران في الدائرة كان الناتج موجبا، وإذا عكست كان سالبا.","`(3k̂) × (2î) = 6ĵ` لأن الترتيب دوري، أما `(2î) × (3k̂) = −6ĵ` لأن الترتيب معكوس.","لأن الضرب الاتجاهي يتبع قاعدة اليد اليمنى، والترتيب الدوري يطابق اتجاه المحاور، وعكسه يعكس الاتجاه."],"الضرب القياسي والضرب الاتجاهي":["الضرب القياسي ناتجه عدد ويكون أكبر عند التوازي، والضرب الاتجاهي ناتجه متجه ويكون أكبر عند التعامد. والأول لا يتأثر بالترتيب والثاني يتأثر.","`|A| = 4` و `|B| = 3` والزاوية `0°`: `A·B = 12 × cos 0° = 12` و `|A × B| = 12 × sin 0° = 0`.","لأن الأول يعتمد على `cos θ` والثاني على `sin θ`، وأحدهما يكبر حين يصغر الآخر."],"تطبيقات من الحياة":["الشغل يحتاج قوة في اتجاه الحركة، فهو ضرب قياسي. وفتح الباب يحتاج قوة عمودية على الذراع، فهو ضرب اتجاهي.","قوة `10 N` تسحب صندوقا `3 m` بزاوية `60°`: `W = 10 × 3 × 0.5 = 15 J`. وقوة `40 N` عمودية على مفتاح طوله `0.25 m`: `τ = 0.25 × 40 = 10 N·m`.","لأن الشغل يهمه الجزء من القوة الموازي للحركة، والدوران يهمه الجزء من القوة العمودي على الذراع."],"تمرين 1 (صفحة 22)":["مقدار المتجه هو طوله، ونحسبه بتربيع كل مركبة ثم الجمع ثم أخذ الجذر. والإشارة السالبة تختفي بالتربيع.","`A = 6î − 8ĵ`: `|A| = √(6² + (−8)²) = √(36 + 64) = √100 = 10`.","لأن المركبتين ضلعا مثلث قائم والمتجه وتره، فنظرية فيثاغورس تعطي طول الوتر."],"تمرين 2 (صفحة 22)":["هنا المركبتان على المحورين x و z، والطريقة نفسها: تربيع ثم جمع ثم جذر.","`B = 5î − 12k̂`: `|B| = √(5² + (−12)²) = √(25 + 144) = √169 = 13`.","لأن المحورين x و z متعامدان كذلك، ففيثاغورس يصلح لأي مركبتين متعامدتين."],"تمرين 3 (صفحة 25)":["نربع المركبتين ونجمعهما ثم نأخذ الجذر بالآلة، والنتيجة غالبا عدد عشري.","`A = î + 2ĵ`: `|A| = √(1² + 2²) = √5 ≈ 2.24`.","لأن المقدار طول وتر المثلث القائم المكون من المركبتين، وهو أكبر من كل مركبة وأصغر من مجموعهما."],"تمرين 4 (صفحة 25)":["المركبة السالبة تعني اتجاها معاكسا للمحور، لكنها لا تنقص الطول، لأن التربيع يجعلها موجبة.","`B = −2î + 2ĵ`: `|B| = √((−2)² + 2²) = √8 ≈ 2.83`.","لأن الطول لا يعتمد على الجهة، ومربع العدد السالب موجب، فلا يكون المقدار سالبا أبدا."],"تمرين 5 (صفحة 25)":["نضرب السيني في السيني والصادي في الصادي ثم نجمع، مع الانتباه لإشارة السالب.","`A = î + 4ĵ` و `B = −2î + ĵ`: `A·B = (1)(−2) + (4)(1) = −2 + 4 = 2`.","لأن الضرب القياسي لمتجهي وحدة مختلفين يعطي صفرا، فلا يبقى إلا ضرب المركبات المتناظرة."],"تمرين 6 (صفحة 26)":["معنا المقداران والزاوية، فنستخدم القانون القطبي: ضرب المقدارين في جيب تمام الزاوية.","`|A| = 5` و `|B| = 4` والزاوية `30°`: `A·B = 5 × 4 × cos 30° = 20 × 0.866 ≈ 17.32`.","لأن جيب التمام يعطي نسبة الجزء الموازي، وعند `30°` يكون المتجهان قريبين من التوازي فالنسبة كبيرة."],"تمرين 7 (صفحة 26)":["معنا المقداران والزاوية، فنضرب المقدارين في جيب الزاوية لنحصل على مقدار الضرب الاتجاهي.","`|A| = 5` و `|B| = 4` والزاوية `30°`: `|A × B| = 5 × 4 × sin 30° = 20 × 0.5 = 10`.","لأن الجيب يعطي نسبة الجزء العمودي، وعند `30°` يكون هذا الجزء نصف المقدار فقط."]},"0-7":{"":["ورقة العمل تجمع كل ما سبق: الكميات القياسية والمتجهة، والمحصلة، وتحليل المتجه، والضرب القياسي والاتجاهي. حل كل سؤال بخطوات: معطيات، قانون، تعويض، نتيجة.","متجه `A = 10 m` بزاوية `60°`: `Ax = 10 × 0.5 = 5 m` و `Ay = 10 × 0.866 ≈ 8.66 m`.","لأن الترتيب في الخطوات يكشف الخطأ بسرعة، ويضمن اختيار القانون المناسب قبل التعويض بالأرقام."],"ما تحتاجه لحل ورقة العمل":["هذه قائمة القوانين التي ستحتاجها: قانون جيب التمام للمحصلة، وقانونا المركبتين، والمقدار، والضرب القياسي بطريقتيه.","متجهان `3 N` و `4 N` بينهما `90°` (ذيل على ذيل): `C² = 9 + 16 + 2 × 3 × 4 × cos 90° = 25`، إذن `C = 5 N`.","لأن كل سؤال في الورقة يعتمد على أحد هذه القوانين، فمعرفة متى يستخدم كل قانون هي نصف الحل."],"ما تحتاجه لحل ورقة العمل (تابع)":["الضرب الاتجاهي يحسب بطريقتين: بالمقدارين وجيب الزاوية، أو بالمركبات من القانون الطويل.","`A = î + 2ĵ` و `B = 3î + ĵ`: `A × B = (1 × 1 − 2 × 3)k̂ = −5k̂`.","لأن طريقة الحل تتبع طريقة تمثيل المتجهين في السؤال: مقدار وزاوية، أو مركبات ومتجهات وحدة."],"حل ورقة العمل":["الكمية القياسية يكفي فيها رقم ووحدة، مثل كتلتك. والكمية المتجهة تحتاج أيضا اتجاها، مثل قولك: امش `100 m` شمالا.","كتلة صندوق `5 kg` كمية قياسية، أما قوة `10 N` نحو الشرق فكمية متجهة لأن اتجاهها جزء من معناها.","لأن بعض الكميات يتغير أثرها بتغير الاتجاه، فالقوة نفسها نحو الشرق أو نحو الغرب تعطي نتيجتين مختلفتين."],"سؤال ٢: اذكر ثلاثة أمثلة على الكمية القياسية وثلاثة أمثلة على الكمية المتجهة (صفحة 24)":["اسأل نفسك: هل يكفي الرقم والوحدة؟ إن كفيا فالكمية قياسية، وإن احتجت إلى «إلى أين؟» فهي متجهة.","زمن رحلة `30 s` كمية قياسية، أما سرعة سيارة `20 m/s` نحو الشمال فكمية متجهة.","لأن الإزاحة والسرعة المتجهة والقوة تختلف نتائجها باختلاف الاتجاه، أما الكتلة والزمن والمسافة فلا اتجاه لها."],"سؤال ٣: باستخدام قانون جيب التمام أوجد محصلة المتجهين A = 2 و B = 3 والزاوية بينهما 60° (صفحة 24)":["نضع المتجهين من نقطة واحدة (ذيل على ذيل) ونستخدم قانون جيب التمام لإيجاد طول المحصلة.","`A = 3` و `B = 4` بينهما `60°`: `R = √(9 + 16 + 2 × 3 × 4 × 0.5) = √37 ≈ 6.08`.","لأن المحصلة قطر متوازي الأضلاع المرسوم على المتجهين، وقانون جيب التمام يعطي طول هذا القطر من الضلعين والزاوية."],"سؤال ٣: باستخدام قانون جيب التمام أوجد محصلة المتجهين A = 2 و B = 3 والزاوية بينهما 60° (صفحة 24) (تابع)":["بعد إيجاد طول المحصلة نحدد اتجاهها بزاوية تقاس من المتجه A، ونجدها من علاقة الجيب.","`A = 3` و `B = 4` و `θ = 60°` و `R ≈ 6.08`: `sin φ = 4 × 0.866 ÷ 6.08 ≈ 0.570`، إذن `φ ≈ 34.7°`.","لأن المحصلة متجه، فلا يكفي ذكر مقدارها، بل يجب تحديد اتجاهها أيضا."],"سؤال ٤: من الرسم أوجد المركبة السينية والمركبة الصادية للمتجه A = 8 بزاوية 30° (صفحة 25)":["نحلل المتجه إلى مركبتين: نضرب المقدار في جيب تمام الزاوية للسينية، وفي جيبها للصادية.","متجه `A = 6 m` بزاوية `30°`: `Ax = 6 × 0.866 ≈ 5.20 m` و `Ay = 6 × 0.5 = 3 m`.","لأن الزاوية مقاسة من المحور السيني، فالمركبة السينية مجاورة لها والصادية مقابلة لها."],"سؤال ٤: من الرسم أوجد المركبة السينية والمركبة الصادية للمتجه A = 8 بزاوية 30° (صفحة 25) (تابع)":["النتيجة النهائية مركبتان موجبتان لأن المتجه في الربع الأول، وقد تأكدنا منهما بفيثاغورس.","متجه `A = 6 m` بزاوية `30°`: المركبتان `5.20 m` و `3 m`، والتحقق: `√(27 + 9) = √36 = 6 m`.","لأن مجموع مربعي المركبتين يساوي مربع المقدار دائما، فهو اختبار سريع لصحة الحل."],"سؤال ٥: لديك المتجهان A = 2î + 3ĵ و B = −3î + 3ĵ، أوجد |A| و |B| و A · B والزاوية θ (صفحة 25)":["نحسب طول كل متجه بالجذر، ثم الضرب القياسي بضرب المركبات المتناظرة وجمعها.","`A = î + ĵ` و `B = −î + ĵ`: `|A| = |B| = √2 ≈ 1.41`، و `A·B = (1)(−1) + (1)(1) = 0`.","لأن الضرب القياسي يمكن حسابه من المركبات دون معرفة الزاوية، ثم نستفيد منه في إيجاد الزاوية."],"سؤال ٥: لديك المتجهان A = 2î + 3ĵ و B = −3î + 3ĵ، أوجد |A| و |B| و A · B والزاوية θ (صفحة 25) (تابع)":["نقسم الضرب القياسي على حاصل ضرب المقدارين، فنحصل على جيب تمام الزاوية، ثم نستخدم `cos⁻¹`.","`A = 3î + 4ĵ` و `B = 4î + 3ĵ`: `A·B = 12 + 12 = 24` و `|A||B| = 5 × 5 = 25`، إذن `cos θ = 0.96` و `θ ≈ 16.3°`.","لأن `A·B = |A||B|·cos θ`، فالقسمة على المقدارين تعزل `cos θ`. والناتج الموجب يعني زاوية حادة."],"سؤال ٦: لديك المتجهان A = 2î + 3ĵ و B = −3î + 3ĵ، أوجد حاصل الضرب الاتجاهي A × B (صفحة 26)":["عندما يكون المتجهان في المستوى xy فقط، تختفي مركبتا `î` و `ĵ` من الناتج، ويبقى حد `k̂` وحده.","`A = î + 2ĵ` و `B = 3î + 4ĵ`: `A × B = (1 × 4 − 2 × 3)k̂ = (4 − 6)k̂ = −2k̂`.","لأن الناتج عمودي على مستوى المتجهين، والعمودي على المستوى xy هو المحور z."],"سؤال ٦: لديك المتجهان A = 2î + 3ĵ و B = −3î + 3ĵ، أوجد حاصل الضرب الاتجاهي A × B (صفحة 26) (تابع)":["الناتج متجه على المحور z، ويمكن التأكد من مقداره بالقانون القطبي `|A||B|·sin θ`.","`A = 2î` و `B = 3ĵ`: بالمركبات `A × B = (2 × 3 − 0 × 0)k̂ = 6k̂`، وبالقطبي `2 × 3 × sin 90° = 6` ✓.","لأن الطريقتين تصفان الكمية نفسها، فيجب أن تعطيا المقدار نفسه، وهذا يكشف أي خطأ في الإشارات."],"سؤال ٧: إذا كان A = 8 و B = 6 والزاوية بينهما 30°، أوجد (١) حاصل الضرب القياسي (٢) مقدار حاصل الضرب الاتجاهي (صفحة 26)":["معنا المقداران والزاوية، فنستخدم جيب التمام للضرب القياسي، والجيب لمقدار الضرب الاتجاهي.","`|A| = 10` و `|B| = 4` والزاوية `60°`: `A·B = 40 × 0.5 = 20` و `|A × B| = 40 × 0.866 ≈ 34.6`.","لأن الضرب القياسي يأخذ الجزء الموازي والضرب الاتجاهي يأخذ الجزء العمودي، فيختلف الناتجان رغم تساوي المقدارين والزاوية."],"سؤال ٧: إذا كان A = 8 و B = 6 والزاوية بينهما 30°، أوجد (١) حاصل الضرب القياسي (٢) مقدار حاصل الضرب الاتجاهي (صفحة 26) (تابع)":["النتيجة الأولى عدد بلا اتجاه، والثانية مقدار متجه اتجاهه عمودي على المتجهين بقاعدة اليد اليمنى.","`|A| = 5` و `|B| = 2` والزاوية `30°`: `A·B = 10 × 0.866 ≈ 8.66` و `|A × B| = 10 × 0.5 = 5`.","لأن نوع الضرب يحدد نوع الناتج: القياسي يعطي كمية قياسية، والاتجاهي يعطي كمية متجهة."],"رسم توضيحي":["الرسم يبين المتجه A مائلا، وتحته مركبته السينية على المحور الأفقي، وبجانبه مركبته الصادية على المحور الرأسي.","متجه `A = 12 m` بزاوية `60°`: `Ax = 12 × 0.5 = 6 m` و `Ay = 12 × 0.866 ≈ 10.39 m`.","لأن المتجه ومركبتيه تشكل مثلثا قائما، فنستخدم الجيب وجيب التمام لإيجاد ضلعيه."],"تمرين 1 · سؤال ٣ (صفحة 24)":["المحصلة هي المتجه الذي يحل محل المتجهين معا، ونجد طولها بقانون جيب التمام عند وضعهما ذيلا على ذيل.","`A = 5` و `B = 5` بينهما `60°`: `C² = 25 + 25 + 2 × 5 × 5 × 0.5 = 75`، إذن `C ≈ 8.66`.","لأن الزاوية بين المتجهين تحدد مدى تعاونهما: كلما صغرت كبرت المحصلة، وكلما كبرت صغرت المحصلة."],"تمرين 2 · سؤال ٤ (صفحة 25)":["المركبة السينية تساوي المقدار مضروبا في جيب تمام الزاوية مع المحور السيني.","متجه `A = 20 m` بزاوية `30°`: `Ax = 20 × 0.866 ≈ 17.32 m`.","لأن المركبة السينية هي الضلع المجاور للزاوية، وجيب التمام نسبة المجاور إلى الوتر."],"تمرين 3 · سؤال ٤ (صفحة 25)":["المركبة الصادية تساوي المقدار مضروبا في جيب الزاوية مع المحور السيني.","متجه `A = 20 m` بزاوية `30°`: `Ay = 20 × 0.5 = 10 m`.","لأن المركبة الصادية هي الضلع المقابل للزاوية، والجيب نسبة المقابل إلى الوتر."],"تمرين 4 · سؤال ٥ (صفحة 25)":["طول المتجه من مركبتيه: نربع كل مركبة ونجمع ثم نأخذ الجذر.","`A = 4î + 3ĵ`: `|A| = √(16 + 9) = √25 = 5`.","لأن المركبتين متعامدتان، فهما ضلعا مثلث قائم وتره المتجه نفسه."],"تمرين 5 · سؤال ٥ (صفحة 25)":["المركبة السالبة تحدد الجهة فقط، أما الطول فيحسب بعد التربيع فلا تؤثر الإشارة.","`B = −5î + 5ĵ`: `|B| = √(25 + 25) = √50 ≈ 7.07`.","لأن مربع العدد السالب موجب، والطول كمية لا تكون سالبة."],"تمرين 6 · سؤال ٥ (صفحة 25)":["نضرب المركبتين السينيتين معا والصاديتين معا ثم نجمع، والسالب نضعه بين قوسين.","`A = 4î + ĵ` و `B = −î + 2ĵ`: `A·B = (4)(−1) + (1)(2) = −4 + 2 = −2`.","لأن الضرب القياسي لمتجهي وحدة مختلفين صفر، فتبقى المركبات المتناظرة فقط. والناتج السالب يعني أن الزاوية منفرجة."],"تمرين 7 · سؤال ٧ (صفحة 26)":["الضرب القياسي بالمقدارين والزاوية: نضرب المقدارين ثم نضرب في جيب تمام الزاوية.","`|A| = 10` و `|B| = 3` والزاوية `30°`: `A·B = 30 × 0.866 ≈ 25.98`.","لأن جيب التمام يعطي الجزء من أحد المتجهين الموازي للآخر، وهو ما يقيسه الضرب القياسي."],"تمرين 8 · سؤال ٧ (صفحة 26)":["مقدار الضرب الاتجاهي: نضرب المقدارين ثم نضرب في جيب الزاوية.","`|A| = 10` و `|B| = 3` والزاوية `30°`: `|A × B| = 30 × 0.5 = 15`.","لأن الجيب يعطي الجزء العمودي من أحد المتجهين على الآخر، وهو ما يقيسه الضرب الاتجاهي."]},"0-8":{"":["هذا الدرس مراجعة شاملة للوحدة الأولى: الكميات الأساسية والمشتقة، والبادئات وتحويل الوحدات، والمتجهات. فكر فيه كترتيب خزانتك قبل السفر لتجد كل شيء بسرعة وقت الحاجة.","حول `2 km` إلى متر: `2 × 10³ = 2000 m`. وحول `0.5 h` إلى ثوان: `0.5 × 3600 = 1800 s`.","لأن قوانين الفيزياء اللاحقة كلها تعتمد على وحدات صحيحة وتحويلات دقيقة. وخطأ صغير في وحدة واحدة يفسد ناتج المسألة كلها."],"مراجعة الوحدة الأولى":["الكميات الأساسية سبع تعرف بذاتها مثل الطول والكتلة والزمن، وكل ما عداها مشتق منها كالمساحة والقوة. والبادئات اختصارات لقوى العشرة، مثل كلمة «ألف» في «ألف ريال».","`3 km² = 3 × (10³ m)² = 3 × 10⁶ m²`، و `4 µs = 4 × 10⁻⁶ s`.","لأن الكميات الأساسية مستقلة لا تكتب إحداها بدلالة الأخرى، فيبنى عليها كل شيء. ونربع معامل التحويل في المساحة لأن المساحة حاصل ضرب طولين."],"تنبيهات شائعة":["الكتلة مقدار ما في الجسم من مادة وتقاس بالكيلوجرام، أما الوزن فهو قوة جذب الأرض له ويقاس بالنيوتن. فالكتلة هي حقيبتك نفسها، والوزن هو شدها ليدك.","جسم كتلته `5 kg` وزنه `W = m·g = 5 × 9.8 = 49 N`. وكتلة `750 g` تساوي `0.75 kg`.","لأن الوزن قوة، والقوة وحدتها `N = kg·m/s²`. والنظام الدولي اختار الكيلوجرام لا الجرام وحدة للكتلة."],"تمارين الوحدة محلولة":["المساحة ليست كمية مستقلة، بل نحصل عليها من ضرب طول في طول. مثل أرضية الغرفة: تعرف مساحتها من طولها وعرضها.","غرفة طولها `4 m` وعرضها `3 m`: `A = 4 × 3 = 12 m²`.","لأن الكمية الأساسية لا تعرف بدلالة غيرها، والمساحة تعرف بدلالة الطول، فهي مشتقة ووحدتها مشتقة من المتر."],"صح وخطأ ٢: وحدة التسارع (صفحة 27)":["التسارع يخبرك كم تزيد السرعة في كل ثانية، لذلك نقسم وحدة السرعة على الثانية مرة أخرى. فهو «سرعة لكل ثانية».","سرعة دراجة زادت من `2 m/s` إلى `8 m/s` في `3 s`: `a = (8 − 2) ÷ 3 = 2 m/s²`.","لأن التسارع معدل تغير السرعة مع الزمن، فوحدته وحدة السرعة `m/s` مقسومة على `s`، فتصبح `m/s²`."],"صح وخطأ ٣: وحدة الكثافة (صفحة 27)":["الكثافة تخبرك كم كيلوجراما في كل متر مكعب. الحديد أكثف من الخشب لأن الحجم نفسه منه يحمل كتلة أكبر.","قطعة كتلتها `54 kg` وحجمها `0.02 m³`: `ρ = 54 ÷ 0.02 = 2700 kg/m³`.","لأن الكثافة كتلة مقسومة على حجم، فوحدتها وحدة الكتلة `kg` مقسومة على وحدة الحجم `m³`."],"صح وخطأ ٤: وحدة الوزن (صفحة 27)":["الوزن هو قوة جذب الأرض للجسم، والقوة تقاس بالنيوتن. أما الجول فيقيس الشغل والطاقة، وهما شيء مختلف.","جسم كتلته `10 kg` وزنه `W = 10 × 9.8 = 98 N`.","لأن الوزن حاصل ضرب الكتلة في تسارع الجاذبية `W = m·g`، فوحدته `kg·m/s²` وهي النيوتن، بينما الجول يساوي `N·m`."],"صح وخطأ ٥: وحدة الكتلة (صفحة 27)":["الجرام صغير جدا، لذلك اعتمد النظام الدولي الكيلوجرام وحدة للكتلة. مثل كيس سكر كتلته كيلوجرام واحد.","`2500 g = 2500 ÷ 1000 = 2.5 kg`.","لأن النظام الدولي يعتمد وحدة واحدة لكل كمية أساسية، ووحدة الكتلة فيه `kg`، والجرام جزء من ألف منها."],"صح وخطأ ٦: السرعة من الكميات الأساسية (صفحة 27)":["السرعة تحسب بقسمة طول على زمن، فهي مبنية على كميتين أساسيتين. لذلك هي مشتقة لا أساسية.","عداء قطع `200 m` في `25 s`: `v = 200 ÷ 25 = 8 m/s`.","لأن كل كمية تعرف بقانون يربطها بكميات أخرى تكون مشتقة، والسرعة تعرف بالعلاقة `v = x ÷ t`."],"صح وخطأ ٧: التحويل من السنتيمتر إلى المتر (صفحة 27)":["في المتر مئة سنتيمتر، فالسنتيمتر جزء صغير من المتر. لذلك يصغر الرقم عند التحويل إلى المتر، فنضرب في `0.01`.","`350 cm × 0.01 = 3.5 m`.","لأن `1 cm = 0.01 m`، والضرب في `0.01` يساوي القسمة على `100`، فيعطي عدد الأمتار المكافئ."],"صح وخطأ ٨: وحدة القوة (صفحة 27)":["القوة دفع أو سحب وتقاس بالنيوتن، والجول يقيس الشغل الذي تبذله قوة عندما تحرك جسما مسافة ما. فهما كميتان مختلفتان.","قوة `20 N` تحرك صندوقا `3 m` في اتجاهها، فتبذل شغلا `W = 20 × 3 = 60 J`.","لأن القوة كتلة في تسارع فوحدتها `kg·m/s²`، أما الشغل فقوة في إزاحة فوحدته `N·m` أي الجول."],"صح وخطأ ٩: وحدة السرعة الابتدائية (صفحة 27)":["السرعة الابتدائية هي السرعة لحظة بدء الحساب، لكنها تبقى سرعة. لذلك وحدتها هي وحدة أي سرعة.","سيارة سرعتها الابتدائية `72 km/h`، وبالتحويل: `72 ÷ 3.6 = 20 m/s`.","لأن كلمة «الابتدائية» تحدد اللحظة لا نوع الكمية، والكمية نفسها طول مقسوم على زمن فوحدتها `m/s`."],"صح وخطأ ١٠: وحدة درجة الحرارة (صفحة 27)":["النظام الدولي يقيس درجة الحرارة بالكلفن، أما الدرجة السيليزية فتستخدم في الحياة اليومية. والتحويل بينهما بإضافة عدد ثابت.","`25 °C` تساوي `25 + 273 = 298 K`.","لأن درجة الحرارة من الكميات الأساسية السبع، وقد اعتمد لها النظام الدولي وحدة واحدة هي الكلفن `K`."],"اختر الإجابة ١: ما لا يعد كمية فيزيائية (صفحة 28)":["الكمية الفيزيائية شيء نعبر عنه برقم ووحدة. والزلزال حدث أو ظاهرة، أما ما نقيسه منه فهو شدته أو مدته.","مثال واقعي: سرعة الرياح `15 m/s` كمية فيزيائية، ومدة هزة أرضية `20 s` كمية فيزيائية، أما الهزة نفسها فظاهرة.","لأن تعريف الكمية الفيزيائية يتطلب إمكان قياسها بمقدار ووحدة، والظاهرة نفسها لا تعطى بمقدار ووحدة مباشرة."],"اختر الإجابة ٢: تحويل السرعة إلى كيلومتر لكل ساعة (صفحة 28)":["لتحويل `m/s` إلى `km/h` نضرب في `3.6`. فالساعة فيها ثوان كثيرة فيكبر الرقم، والكيلومتر كبير فيصغر قليلا.","`15 m/s × 3.6 = 54 km/h`.","لأن `1 m/s = 0.001 km ÷ (1/3600 h) = 3.6 km/h`، فالعامل `3.6` ناتج قسمة `3600` على `1000`."],"اختر الإجابة ٣: الكميات الأساسية في النظام الدولي (صفحة 28)":["الكميات الأساسية سبع: الطول والكتلة والزمن وشدة التيار ودرجة الحرارة وشدة الإضاءة وكمية المادة. اعتبرها حروف الأبجدية التي تكتب بها كلمات الفيزياء كلها.","مثال واقعي: طولك `1.7 m`، وكتلتك `65 kg`، وزمن ركضك `12 s`، كلها كميات أساسية بوحداتها في النظام الدولي.","لأن هذه الكميات السبع مستقلة لا تشتق إحداها من الأخرى، وتكفي لبناء وحدات الكميات الأخرى كلها."],"اختر الإجابة ٤: نوع الكتلة (صفحة 28)":["الكتلة لا تحتاج كمية أخرى لتعريفها، فهي أساسية. وليس لها اتجاه، فلا نقول كتلة نحو الشرق أو نحو الغرب.","كيس أرز كتلته `5 kg` تبقى كتلته `5 kg` مهما حركته في أي اتجاه.","لأن الكتلة من الكميات السبع المختارة أساسا للنظام الدولي، وتتحدد بالمقدار والوحدة فقط فهي قياسية."],"اختر الإجابة ٥: وحدة المساحة (صفحة 28)":["المساحة تقيس سطحا له طول وعرض، فنضرب مترا في متر فنحصل على المتر المربع.","ملعب طوله `100 m` وعرضه `60 m`: `A = 100 × 60 = 6000 m²`.","لأن المساحة حاصل ضرب طولين، فتضرب وحدتاهما `m × m = m²`."],"اختر الإجابة ٦: نوع درجة الحرارة (صفحة 29)":["درجة الحرارة لا تحسب من كميات أخرى، بل تقاس مباشرة بالمحرار، فهي أساسية.","الماء يتجمد عند `273 K` تقريبا ويغلي عند `373 K`، والفرق بينهما `100 K`.","لأنها إحدى الكميات السبع التي اختارها النظام الدولي أساسا، ولها وحدتها الخاصة الكلفن `K`."],"اختر الإجابة ٧: تعريف الكمية الفيزيائية (صفحة 29)":["الكمية الفيزيائية أي صفة في الطبيعة تستطيع قياسها، مثل الطول والحرارة. والكمية القياسية نوع منها يكفيه مقدار ووحدة.","مثال واقعي: حرارة الجو `308 K` كمية فيزيائية قياسية، وسرعة رياح `10 m/s` نحو الشمال كمية فيزيائية متجهة.","لأن التعريف عام يشمل كل ما يقاس، أما القياسية فتعريف أضيق يخص الكميات التي لا اتجاه لها."],"اختر الإجابة ٨: نوع المساحة (صفحة 29)":["المساحة تبنى من الطول، فهي مشتقة لا أساسية، مثل بيت مبني من الطوب.","قطعة أرض أبعادها `20 m` و `15 m`: `A = 20 × 15 = 300 m²`.","لأن الكمية المشتقة تعرف بدلالة كميات أساسية، والمساحة تعرف بضرب طولين `A = L × L`."],"اختر الإجابة ٩: وحدة الحجم (صفحة 29)":["الحجم له ثلاثة أبعاد: طول وعرض وارتفاع، فنضرب ثلاثة أمتار فنحصل على المتر المكعب.","خزان أبعاده `2 m` و `1.5 m` و `1 m`: `V = 2 × 1.5 × 1 = 3 m³`.","لأن الحجم حاصل ضرب ثلاثة أطوال، فتضرب الوحدات ثلاث مرات `m × m × m = m³`."],"اختر الإجابة ١٠: تحويل المتر إلى النانومتر (صفحة 29)":["النانومتر صغير جدا، فهو جزء من مليار من المتر. لذلك يحتوي المتر الواحد مليار نانومتر.","`3 m = 3 × 10⁹ nm`، و `0.002 m = 2 × 10⁻³ × 10⁹ = 2 × 10⁶ nm`.","لأن `1 nm = 10⁻⁹ m`، فعدد النانومترات في المتر هو `1 ÷ 10⁻⁹ = 10⁹`."],"اختر الإجابة ١١: تحويل الكيلومتر المربع إلى المتر المربع (صفحة 29)":["الكيلومتر المربع مربع ضلعه ألف متر، فمساحته ألف في ألف. لذلك نربع معامل التحويل.","`5 km² = 5 × (10³)² = 5 × 10⁶ m²`.","لأن المساحة طول في طول، فكل بعد يحول وحده بالضرب في `10³`، فيتضاعف الأس ليصبح `10⁶`."],"اختر الإجابة ١٢: تحويل الجيجاجرام إلى الجرام (صفحة 29)":["جيجا تعني مليارا، كما في سعة الذاكرة بالجيجابايت. فالجيجاجرام مليار جرام.","`4 Gg = 4 × 10⁹ g`، وبالكيلوجرام: `4 × 10⁶ kg`.","لأن كل بادئة تستبدل بقوة العشرة المقابلة لها، والجيجا `10⁹`، والجرام بلا بادئة."],"اختر الإجابة ١٣: تحويل الساعة إلى الثواني (صفحة 30)":["الساعة ستون دقيقة، وكل دقيقة ستون ثانية، فنضرب الستين في الستين.","`2.5 h = 2.5 × 3600 = 9000 s`.","لأن التحويل يتم على مرحلتين: من ساعات إلى دقائق بالضرب في `60`، ثم من دقائق إلى ثوان بالضرب في `60` مرة أخرى."],"رسم توضيحي 1":["تخيل سلما: كل درجة للأعلى تعني ألف مرة أكبر، وكل درجة للأسفل ألف مرة أصغر. فمن المتر إلى الكيلومتر درجة واحدة.","من الميلي إلى الميكرو درجة واحدة للأسفل: `1 mm = 10³ µm = 1000 µm`.","لأن البادئات في هذا السلم تتباعد بقوة `10³`، فكل انتقال درجة يعني الضرب أو القسمة على `1000`."],"رسم توضيحي 2":["إذا شد شخصان حبلا في الاتجاه نفسه تجمعت قوتاهما، وإذا شداه في اتجاهين متعاكسين طرحت إحداهما من الأخرى. وبين الحالتين قيم وسطى.","متجهان `A = 5` و `B = 2`: أكبر محصلة `5 + 2 = 7`، وأصغرها `5 − 2 = 3`، وعند التعامد `√(25 + 4) ≈ 5.4`.","لأن المحصلة تعتمد على الزاوية بين المتجهين؛ ففي الاتجاه نفسه تتراكم المركبات، وعند التعاكس يلغي جزء منها الآخر."],"رسم توضيحي 3":["رتب متجهات الوحدة في دائرة: `i` ثم `j` ثم `k`. إذا ضربت باتجاه الدوران كان الناتج موجبا، وإذا ضربت عكسه كان سالبا.","`i × j = k` و `j × k = i`، أما `j × i = −k`، و `i × i = 0` لأن الزاوية بينهما `0°`.","لأن الضرب الاتجاهي يعتمد على الترتيب، فعكس الترتيب يعكس اتجاه الناتج، ومقداره `AB sinθ` يساوي صفرا للمتجهين المتوازيين."],"مثال محلول":["لتحويل بادئة إلى أخرى اكتب كل بادئة كقوة للعشرة، ثم اقسم القديمة على الجديدة. الأمر يشبه تحويل العملة بسعر صرف ثابت.","حول `1 mm` إلى `µm`: `10⁻³ ÷ 10⁻⁶ = 10³`، أي `1 mm = 1000 µm`.","لأن كل بادئة تمثل قوة محددة للعشرة، والقسمة بين القوتين تعطي عدد الوحدات الجديدة في الوحدة القديمة."],"مثال محلول (تابع)":["قسمة قوى العشرة تعني طرح الأسس. ومن الميكرو إلى النانو درجة واحدة على السلم، فنضرب في ألف.","`5 µm = 5 × 10⁻⁶ ÷ 10⁻⁹ nm = 5 × 10³ nm = 5000 nm`.","لأن `10ᵃ ÷ 10ᵇ = 10ᵃ⁻ᵇ`، فطرح الأسس يعطي معامل التحويل مباشرة دون حفظ جداول."],"تمرين 1 · اختر الإجابة ٢ (صفحة 28)":["نضرب السرعة المقيسة بالمتر لكل ثانية في `3.6` لنحصل عليها بالكيلومتر لكل ساعة. ولعكس التحويل نقسم على `3.6`.","`25 m/s × 3.6 = 90 km/h`، وعكسيا `108 km/h ÷ 3.6 = 30 m/s`.","لأن في الساعة `3600 s` وفي الكيلومتر `1000 m`، فيكون المعامل `3600 ÷ 1000 = 3.6`."],"تمرين 2 · اختر الإجابة ١٠ (صفحة 29)":["في كل متر مليار نانومتر، فعند التحويل من المتر إلى النانومتر نضرب في `10⁹`.","`0.5 m × 10⁹ = 5 × 10⁸ nm`.","لأن النانو تعني `10⁻⁹`، والوحدة الأصغر تحتاج عددا أكبر منها لتغطي الطول نفسه."],"تمرين 3 · اختر الإجابة ١١ (صفحة 29)":["ضلع الكيلومتر ألف متر، والمساحة ضلع في ضلع، فنضرب في ألف مرتين.","`0.2 km² = 0.2 × 1000² = 2 × 10⁵ m²`.","لأن وحدة المساحة مربع وحدة الطول، فمعامل تحويل الطول يربع: `(1000)² = 10⁶`."],"تمرين 4 · اختر الإجابة ١٣ (صفحة 30)":["في كل ساعة `3600` ثانية، فنضرب عدد الساعات في `3600`.","`0.25 h × 3600 = 900 s`، أي إن ربع الساعة يساوي `15 min`.","لأن `1 h = 60 min` و `1 min = 60 s`، فمعامل التحويل `60 × 60 = 3600`."]},"1-1":{"":["هذا الدرس يصف الحركة: كم قطع الجسم (المسافة)، وأين انتهى بالنسبة لنقطة بدايته (الإزاحة)، وكم كان سريعا (السرعة)، وكيف تغيرت سرعته (التسارع).","مشيت `40 m` شرقا ثم `10 m` غربا في `25 s`: المسافة `50 m`، والإزاحة `30 m` شرقا، والسرعة المتوسطة `30 ÷ 25 = 1.2 m/s`.","لأن وصف الحركة بدقة يحتاج كميات تميز بين طول المسار والاتجاه، وهذه الكميات أساس قوانين نيوتن والشغل والطاقة في الوحدة."],"مقدمة الوحدة وأهدافها":["عدد الأبعاد هو عدد المحاور التي نحتاجها لتحديد موضع الجسم. قطار على سكة مستقيمة يحتاج محورا واحدا، وكرة مقذوفة تحتاج محورين.","مثال واقعي: سيارة على طريق مستقيم موضعها `x = 150 m`، أما كرة مقذوفة فموضعها `x = 12 m` أفقيا و `y = 3 m` رأسيا.","لأن متجه الموضع يحتاج مركبة لكل اتجاه يتغير فيه موضع الجسم، والحركة المستقيمة يتغير فيها الموضع في اتجاه واحد فقط."],"مقدمة الوحدة وأهدافها (تابع)":["في الحركة ثلاثية الأبعاد يتغير الموضع طولا وعرضا وارتفاعا معا، مثل طائرة تصعد وتنعطف في الوقت نفسه.","مثال واقعي: طائرة موضعها `x = 2000 m` و `y = 500 m` وارتفاعها `z = 3000 m` بالنسبة للمطار.","لأن الجسم هنا يتحرك بالنسبة لمحاور الإسناد الثلاثة، فيحتاج متجه موضعه ثلاث مركبات لوصفه كاملا."],"الهدف العام للوحدة":["الوحدة تربط أربعة مفاهيم: الحركة، والقوة التي تسببها أو تغيرها، والشغل الذي تبذله القوة، والطاقة التي تتغير نتيجة ذلك.","مثال واقعي: تدفع عربة التسوق بقوة فتتحرك، فتبذل عليها شغلا، وتكتسب العربة طاقة حركة.","لأن هذه المفاهيم مترابطة: القوة تغير الحركة، والقوة التي تحرك جسما تبذل شغلا، والشغل يغير طاقة الجسم."],"ما ستتعلمه في الوحدة":["تبدأ الحقيبة التدريبية بوصف الحركة على خط مستقيم، ثم تنتقل إلى القوة وقوانين نيوتن، وتنتهي بالشغل والطاقة وحفظها.","مثال واقعي: كرة تسقط من سطح بيت؛ نصف سرعتها بقوانين الحركة، ونفسر سقوطها بقوة الجاذبية، ونحسب طاقتها قبل وصولها للأرض.","لأن فهم الحركة يأتي أولا، ثم نسأل عن سببها وهو القوة، ثم عن أثر القوة في الطاقة، فكل خطوة تبنى على سابقتها."],"المسافة والإزاحة":["المسافة هي كل ما مشيته على الطريق، والإزاحة هي الخط المستقيم من نقطة البداية إلى نقطة الوصول مع اتجاهه. وإذا رجعت إلى البيت تكون إزاحتك صفرا.","تحركت `7 m` شمالا ثم `3 m` جنوبا: المسافة `7 + 3 = 10 m`، والإزاحة `7 − 3 = 4 m` شمالا.","لأن المسافة تجمع أطوال المسار كلها دون اتجاه، بينما الإزاحة تقارن الموضع النهائي بالموضع الابتدائي فقط، فتلغي الحركات المتعاكسة بعضها."],"السرعة المتوسطة":["السرعة المتوسطة تخبرك كم مترا يتحرك الجسم في كل ثانية في المتوسط، حتى لو أسرع أحيانا وأبطأ أحيانا.","دراجة إزاحتها `90 m` في `15 s`: `v = 90 ÷ 15 = 6 m/s`.","لأنها تقسم الإزاحة الكلية على الزمن الكلي، فتعطي معدلا واحدا يكافئ الحركة كلها دون تفاصيل الإسراع والإبطاء."],"التسارع":["التسارع يخبرك كم تزيد السرعة أو تنقص في كل ثانية. مثل الضغط على دواسة الوقود: كلما زاد الضغط زادت السرعة أسرع.","سيارة زادت سرعتها من `5 m/s` إلى `17 m/s` في `4 s`: `a = (17 − 5) ÷ 4 = 3 m/s²`.","لأن التسارع معدل تغير السرعة مع الزمن، فنقسم فرق السرعتين على الزمن، فتكون الوحدة `m/s²`."],"التسارع (تابع)":["إذا كانت السرعة تزيد فالتسارع موجب، وإذا كانت تقل فالتسارع سالب ونسميه تباطؤا، مثل سيارة تقترب من إشارة حمراء.","سيارة نقصت سرعتها من `20 m/s` إلى `8 m/s` في `4 s`: `a = (8 − 20) ÷ 4 = −3 m/s²`، أي تباطؤ.","لأن إشارة التسارع تأتي من الفرق `Vf − Vi`؛ فإذا كانت السرعة النهائية أصغر كان الفرق سالبا."],"أمثلة الحقيبة التدريبية محلولة":["عند حساب الإزاحة نختار اتجاها موجبا، والحركة في عكسه تكون سالبة. أما المسافة فنجمع الأطوال كلها دون إشارات.","سيارة تحركت `5 km` شرقا ثم `9 km` غربا: المسافة `14 km`، والإزاحة `5 − 9 = −4 km` باعتبار الشرق موجبا، أي `4 km` نحو الغرب.","لأن الإزاحة كمية متجهة فتراعي الاتجاه، والمسافة كمية قياسية لا يهمها إلا طول المسار."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["الرجوع شرقا يلغي جزءا من الذهاب غربا في حساب الإزاحة، لكنه يضاف إلى المسافة لأن السيارة قطعته فعلا.","سيارة تحركت `3 km` غربا ثم `3 km` شرقا: الإزاحة `(+3) + (−3) = 0`، والمسافة `3 + 3 = 6 km`.","لأن الإزاحة تعتمد على نقطتي البداية والنهاية فقط، بينما المسافة تحسب كل جزء من المسار المقطوع."],"مثال ١: سرعة سيارة (صفحة 36)":["إذا عرفت كم قطعت السيارة وكم استغرقت، فاقسم الأول على الثاني تعرف كم مترا تقطع في الثانية.","قطار قطع `450 m` في `30 s`: `v = 450 ÷ 30 = 15 m/s`.","لأن السيارة لم تغير اتجاهها، فتساوى مقدار الإزاحة والمسافة، فيمكن استخدام `v = x / t` مباشرة."],"مثال ١: سرعة سيارة (صفحة 36) (تابع)":["قسمة `120` على `10` تعني أن السيارة تقطع `12` مترا في كل ثانية.","إذا استمرت السيارة بالسرعة `12 m/s` لمدة `25 s` فإنها تقطع `x = 12 × 25 = 300 m`.","لأن السرعة المتوسطة معدل ثابت، فيمكن إعادة ترتيب القانون إلى `x = v·t` لحساب الإزاحة من السرعة والزمن."],"مثال ٢: تسارع سيارة زادت سرعتها (صفحة 36)":["نحتاج ثلاثة أشياء: السرعة في البداية، والسرعة في النهاية، والزمن بينهما. والفرق بين السرعتين هو ما يحدد التسارع.","حافلة زادت سرعتها من `10 m/s` إلى `22 m/s` في `6 s`: `a = (22 − 10) ÷ 6 = 2 m/s²`.","لأن التسارع لا يعتمد على قيمة السرعة نفسها، بل على مقدار تغيرها في كل ثانية."],"مثال ٢: تسارع سيارة زادت سرعتها (صفحة 36) (تابع)":["زادت السرعة `60 m/s` خلال `3 s`، أي `20 m/s` في كل ثانية، وهذا هو التسارع.","لو حدث التغير نفسه `60 m/s` خلال `6 s` لكان `a = 60 ÷ 6 = 10 m/s²`، أي نصف القيمة.","لأن التسارع يكون موجبا عندما تكون السرعة النهائية أكبر من الابتدائية، فيكون الفرق `Vf − Vi` موجبا."],"تطبيقات من الحياة":["عداد السيارة يجمع كل الأمتار التي قطعتها مهما انعطفت، أما GPS فيعرف موقعك وبعدك واتجاهك عن نقطة البداية.","`100 km/h` تساوي `100 ÷ 3.6 ≈ 27.8 m/s`، فإذا بلغتها السيارة من السكون في `6 s` كان `a ≈ 27.8 ÷ 6 ≈ 4.6 m/s²`.","لأن العداد يقيس طول المسار فقط فهو يقيس كمية قياسية، بينما تحديد الموقع يحتاج مقدارا واتجاها فهو كمية متجهة."],"تمرين 1 · ورقة عمل (١) · سؤال ٢ (صفحة 46)":["المعطى إزاحة وزمن، والمطلوب سرعة، فالقانون المناسب هو قسمة الإزاحة على الزمن.","عداء قطع `60 m` في `8 s`: `v = 60 ÷ 8 = 7.5 m/s`.","لأن السرعة المتوسطة تعرف بأنها الإزاحة لكل وحدة زمن، فوجود الإزاحة والزمن يكفي لحسابها."],"تمرين 1 · ورقة عمل (١) · سؤال ٢ (صفحة 46) (تابع)":["`100 ÷ 5` تعني أن السيارة تقطع عشرين مترا في كل ثانية.","بالكيلومتر لكل ساعة: `20 m/s × 3.6 = 72 km/h`.","لأن قسمة الأمتار على الثواني تعطي الوحدة `m/s`، فالوحدة نفسها تؤكد أن الناتج سرعة."],"تمرين 2 · ورقة عمل (١) · سؤال ٣ (صفحة 46)":["عندنا سرعة ابتدائية ونهائية وزمن، والمطلوب التسارع. اطرح السرعتين ثم اقسم على الزمن.","سيارة زادت سرعتها من `15 m/s` إلى `35 m/s` في `4 s`: `a = (35 − 15) ÷ 4 = 5 m/s²`.","لأن هذه المعطيات هي بالضبط ما يحتاجه تعريف التسارع `a = (Vf − Vi) / t`."],"تمرين 2 · ورقة عمل (١) · سؤال ٣ (صفحة 46) (تابع)":["زادت السرعة `60 m/s` في `5 s`، أي `12 m/s` في كل ثانية.","بعد ثانيتين فقط من البداية تكون السرعة `30 + 12 × 2 = 54 m/s`.","لأن التسارع ثابت، فالسرعة تزيد بالمقدار نفسه في كل ثانية."],"تمرين 3 · تمارين الوحدة · اختر الإجابة ٢٦ (صفحة 63)":["المطلوب السرعة المتوسطة، والمعطى إزاحة وزمن، فنقسم الإزاحة على الزمن.","طائرة على المدرج قطعت `840 m` في `12 s`: `v = 840 ÷ 12 = 70 m/s`.","لأن السرعة المتوسطة تصف الحركة كلها بمعدل واحد، فلا يهم إن كانت السيارة أسرعت أو أبطأت خلال الطريق."],"تمرين 3 · تمارين الوحدة · اختر الإجابة ٢٦ (صفحة 63) (تابع)":["`300 ÷ 10` تعني أن السيارة قطعت ثلاثين مترا في كل ثانية في المتوسط.","لو قطعت السيارة الإزاحة نفسها في `15 s` لكانت `v = 300 ÷ 15 = 20 m/s`، فالزمن الأطول يعني سرعة أقل.","لأن السرعة تتناسب عكسيا مع الزمن عند ثبات الإزاحة، فكلما زاد الزمن قلت السرعة."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ٢٣ (صفحة 63)":["عبارة «بدأ من السكون» تعني أن السرعة الابتدائية صفر، وهي معلومة مخفية في نص السؤال يجب الانتباه لها.","دراجة بدأت من السكون ووصلت سرعتها إلى `9 m/s` بعد `3 s`: `a = (9 − 0) ÷ 3 = 3 m/s²`.","لأن الجسم الساكن لا يتحرك، فسرعته لحظة البداية `Vi = 0`، وهذا يكمل معطيات قانون التسارع."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ٢٣ (صفحة 63) (تابع)":["زادت السرعة من صفر إلى `20 m/s` في `5 s`، أي بمقدار `4 m/s` كل ثانية.","بالتسارع نفسه تصبح سرعة الجسم بعد `8 s`: `Vf = 0 + 4 × 8 = 32 m/s`.","لأن التسارع الثابت يعني زيادة متساوية في السرعة كل ثانية، فيمكن توقع السرعة في أي لحظة."]},"1-2":{"":["هذا الدرس يعطيك أربع معادلات تصف حركة جسم تزيد سرعته أو تقل بانتظام. كل معادلة تربط أربع كميات، فإذا عرفت ثلاثا منها وجدت الرابعة.","سيارة بدأت من السكون بتسارع `2 m/s²` لمدة `6 s`: `Vf = 0 + 2 × 6 = 12 m/s`، و `x = ½ × 2 × 6² = 36 m`.","لأن التسارع الثابت يجعل السرعة تتغير بانتظام مع الزمن، فتصبح العلاقة بينهما خطية ويمكن اشتقاق معادلات بسيطة ودقيقة."],"علاقة السرعة والتسارع والزمن":["السرعة النهائية تساوي ما بدأ به الجسم مضافا إليه ما اكتسبه، وما يكتسبه هو التسارع مضروبا في الزمن. مثل حصالة تضيف إليها مبلغا ثابتا كل يوم.","دراجة سرعتها `4 m/s` وتسارعها `1.5 m/s²` لمدة `6 s`: `Vf = 4 + 1.5 × 6 = 13 m/s`.","لأن التسارع هو التغير في السرعة لكل ثانية، فبعد زمن `t` يكون التغير الكلي `a·t`، ونضيفه إلى السرعة الابتدائية."],"السرعة المتوسطة":["إذا زادت السرعة بانتظام، فمتوسطها يقع في منتصف الطريق بين سرعة البداية وسرعة النهاية، مثل متوسط درجتين. ثم نضرب هذا المتوسط في الزمن لنحصل على الإزاحة.","سيارة زادت سرعتها من `8 m/s` إلى `20 m/s` خلال `5 s`: `v̄ = (20 + 8) ÷ 2 = 14 m/s`، و `x = 14 × 5 = 70 m`.","لأن التسارع الثابت يجعل السرعة تتغير خطيا مع الزمن، فالزيادة في النصف الثاني من الزمن تعوض النقص في النصف الأول، فيمثل المتوسط الحركة كلها."],"علاقة الإزاحة والسرعة والتسارع والزمن":["الإزاحة جزءان: ما يقطعه الجسم لو بقي بسرعته الأولى `Vi·t`، وما يضيفه التسارع `½·a·t²`.","`Vi = 3 m/s` و `a = 2 m/s²` و `t = 4 s`: `x = 3 × 4 + ½ × 2 × 4² = 12 + 16 = 28 m`.","لأن المساحة تحت منحنى السرعة والزمن تساوي الإزاحة، وهي مستطيل مساحته `Vi·t` ومثلث مساحته `½·t·(a·t)`."],"علاقة السرعة والتسارع والإزاحة":["هذه المعادلة تربط السرعة بالإزاحة مباشرة دون الحاجة إلى الزمن، فهي مفيدة عندما لا يذكر الزمن في السؤال.","`Vi = 6 m/s` و `a = 2 m/s²` و `x = 16 m`: `Vf² = 36 + 2 × 2 × 16 = 100`، إذن `Vf = 10 m/s`.","لأنها تنتج من دمج `Vf = Vi + a·t` مع `x = v̄·t` وحذف الزمن بينهما، فتبقى علاقة بين السرعتين والتسارع والإزاحة فقط."],"كيف تختار المعادلة؟":["اكتب ما تعرفه وما تريده، ثم ابحث عن المعادلة التي تحتوي هذه الكميات فقط، مثل اختيار المفتاح المناسب للقفل.","`Vi = 0` و `a = 3 m/s²` و `x = 24 m` والمطلوب `Vf`: الزمن غائب، فنستخدم `Vf² = 0 + 2 × 3 × 24 = 144`، إذن `Vf = 12 m/s`.","لأن كل معادلة تربط أربع كميات فقط، فإذا عرفت ثلاثا منها في معادلة واحدة أمكن حساب الرابعة مباشرة دون خطوات إضافية."],"أمثلة الحقيبة التدريبية محلولة":["كلمة «توقفت» تعني أن السرعة النهائية صفر، فنحصل بذلك على معطى إضافي لم يذكر رقمه في السؤال.","دراجة سرعتها `6 m/s` توقفت بعد `9 m`: `v̄ = (0 + 6) ÷ 2 = 3 m/s`، فيكون `t = 9 ÷ 3 = 3 s`، و `a = (0 − 6) ÷ 3 = −2 m/s²`.","لأن الجسم المتوقف ليست له سرعة، فقراءة الكلمات بعناية تكشف قيم `Vi` أو `Vf` المخفية في نص المسألة."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["حسبنا أولا متوسط السرعة، ثم الزمن من الإزاحة، ثم التسارع من الزمن. كل خطوة تفتح الباب للخطوة التي بعدها.","تحقق من النتيجة: `x = 5 × 8 + ½ × (−0.625) × 8² = 40 − 20 = 20 m`، وهي الإزاحة المعطاة.","لأن التسارع يكون سالبا عندما تقل السرعة، فالإشارة السالبة تعني أن التسارع عكس اتجاه الحركة، أي تباطؤ."],"مثال ٢: المسافة باستخدام السرعة المتوسطة (صفحة 38)":["عندنا سرعتان وزمن، فأسهل طريق هو حساب متوسط السرعتين ثم ضربه في الزمن.","قطار زادت سرعته من `12 m/s` إلى `18 m/s` في `20 s`: `v̄ = 15 m/s`، و `x = 15 × 20 = 300 m`.","لأن التسارع منتظم، فمتوسط السرعتين يمثل السرعة الفعلية طوال الزمن، فلا نحتاج إلى حساب التسارع أولا."],"مثال ٢: المسافة باستخدام السرعة المتوسطة (صفحة 38) (تابع)":["متوسط `13` و `26` هو `19.5`، فكأن السيارة سارت بسرعة ثابتة `19.5 m/s` لمدة `10 s`.","تحقق بطريقة أخرى: `a = (26 − 13) ÷ 10 = 1.3 m/s²`، و `x = 13 × 10 + ½ × 1.3 × 10² = 130 + 65 = 195 m`.","لأن معادلات الحركة متسقة فيما بينها، فأي معادلتين صحيحتين تعطيان الناتج نفسه."],"مثال ٣: تسارع سيارة بدأت من السكون (صفحة 38)":["السيارة بدأت من السكون، فيختفي الجزء `Vi·t` ويبقى `½·a·t²` فقط.","جسم بدأ من السكون وقطع `50 m` في `5 s`: `50 = ½ × a × 25`، إذن `a = 50 ÷ 12.5 = 4 m/s²`.","لأن المعطيات إزاحة وزمن والسرعة النهائية غائبة، فالمعادلة المناسبة هي التي لا تحتوي `Vf`."],"مثال ٣: تسارع سيارة بدأت من السكون (صفحة 38) (تابع)":["عوضنا `Vi = 0` فصار القانون `x = ½·a·t²`، ثم قسمنا `110` على `12.5`.","بعد `5 s` تكون سرعة هذه السيارة `Vf = 0 + 8.8 × 5 = 44 m/s`.","لأن ضرب أي عدد في صفر يساوي صفرا، فالجزء `Vi·t` لا يساهم، ويبقى أثر التسارع وحده."],"مثال ٤: السرعة بعد قطع مسافة معينة (صفحة 38)":["المعطى تسارع وإزاحة والمطلوب سرعة، والزمن غير مذكور، فنختار المعادلة التي لا تحتوي الزمن.","جسم بدأ من السكون بتسارع `2 m/s²` وقطع `25 m`: `Vf² = 2 × 2 × 25 = 100`، إذن `Vf = 10 m/s`.","لأن `Vf² = Vi² + 2·a·x` هي المعادلة الوحيدة التي لا تحتوي الزمن، فتختصر الطريق ولا تحتاج حساب `t` أولا."],"مثال ٤: السرعة بعد قطع مسافة معينة (صفحة 38) (تابع)":["ناتج المعادلة هو مربع السرعة `160`، فنأخذ الجذر التربيعي لنصل إلى السرعة نفسها.","لو كانت الإزاحة `40 m` بالتسارع نفسه: `Vf² = 2 × 4 × 40 = 320`، إذن `Vf ≈ 17.9 m/s`.","لأن المعادلة تعطي `Vf²` لا `Vf`، والجذر التربيعي يعيد الكمية إلى وحدة السرعة `m/s`."],"معادلات الحركة بتسارع ثابت":["كل معادلة من الأربع تغيب عنها كمية واحدة. ابحث عن الكمية التي لا تعرفها ولا تطلبها، واختر المعادلة التي لا تحتويها.","`Vi = 5 m/s` و `a = 2 m/s²` و `t = 3 s` والمطلوب `x`: السرعة النهائية غائبة، فنستخدم `x = 5 × 3 + ½ × 2 × 3² = 15 + 9 = 24 m`.","لأن المعادلات الأربع مشتقة من تعريفي التسارع والسرعة المتوسطة، وكل منها تحذف كمية مختلفة لتناسب نوعا من المسائل."],"تطبيقات من الحياة":["إذا ضاعفت سرعة سيارتك فلا تتضاعف مسافة توقفها فقط، بل تصبح أربعة أضعاف. لذلك السرعة العالية خطيرة جدا.","بتباطؤ `5 m/s²`: من سرعة `10 m/s` تتوقف السيارة بعد `10² ÷ (2 × 5) = 10 m`، ومن `20 m/s` بعد `20² ÷ 10 = 40 m`.","لأن مسافة التوقف تتناسب مع مربع السرعة حسب `v² = 2ax`، فمضاعفة السرعة تضرب المسافة في `2² = 4`."],"تمرين 1 · ورقة عمل (١) · سؤال ٤ (صفحة 47)":["السيارة توقفت، فالسرعة النهائية صفر. والمعطى إزاحة والمطلوب زمن، فنستخدم متوسط السرعة.","سيارة سرعتها `16 m/s` توقفت بعد `40 m`: `v̄ = (0 + 16) ÷ 2 = 8 m/s`، و `t = 40 ÷ 8 = 5 s`.","لأن التسارع غير معطى ولا مطلوب، فنختار المعادلة التي لا تحتوي `a` وهي `x = ½·(Vi + Vf)·t`."],"تمرين 1 · ورقة عمل (١) · سؤال ٤ (صفحة 47) (تابع)":["متوسط السرعة `5 m/s`، فتحتاج السيارة `6` ثوان لتقطع `30` مترا.","تسارع هذه السيارة إذن `a = (0 − 10) ÷ 6 ≈ −1.67 m/s²`، والإشارة السالبة تعني تباطؤا.","لأن الإزاحة تساوي متوسط السرعة مضروبا في الزمن، فالزمن هو الإزاحة مقسومة على متوسط السرعة."],"تمرين 2 · ورقة عمل (١) · سؤال ٥ (صفحة 47)":["سرعتان وزمن والمطلوب المسافة: احسب متوسط السرعتين واضربه في الزمن.","سيارة زادت سرعتها من `6 m/s` إلى `14 m/s` في `8 s`: `x = (6 + 14) ÷ 2 × 8 = 80 m`.","لأن التسارع منتظم، فالسرعة المتوسطة تساوي متوسط السرعتين الابتدائية والنهائية بالضبط."],"تمرين 2 · ورقة عمل (١) · سؤال ٥ (صفحة 47) (تابع)":["متوسط `10` و `30` هو `20 m/s`، وفي `5 s` تقطع السيارة `100 m`.","تحقق: `a = (30 − 10) ÷ 5 = 4 m/s²`، و `x = 10 × 5 + ½ × 4 × 5² = 50 + 50 = 100 m`.","لأن المعادلات الأربع مترابطة، فالتحقق بمعادلة ثانية يكشف أي خطأ حسابي."],"تمرين 3 · ورقة عمل (١) · سؤال ٦ (صفحة 48)":["الجسم بدأ من السكون، وكل ثانية تضيف إلى سرعته مقدار التسارع.","جسم بدأ من السكون بتسارع `6 m/s²` لمدة `2.5 s`: `Vf = 0 + 6 × 2.5 = 15 m/s`.","لأن المعطيات سرعة ابتدائية وتسارع وزمن والإزاحة غائبة، فنستخدم `Vf = Vi + a·t`."],"تمرين 3 · ورقة عمل (١) · سؤال ٦ (صفحة 48) (تابع)":["زيادة `10 m/s` في كل ثانية لمدة `3` ثوان تعطي `30 m/s`.","وإزاحة الجسم في هذه المدة `x = ½ × 10 × 3² = 45 m`.","لأن السرعة الابتدائية صفر، فالسرعة النهائية كلها ناتجة عن التسارع `a·t`."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ٤ (صفحة 60)":["السيارة كانت تتحرك أصلا ثم زادت سرعتها، فنضيف الزيادة إلى السرعة الأولى.","سيارة سرعتها `15 m/s` بتسارع `3 m/s²` لمدة `4 s`: `Vf = 15 + 3 × 4 = 27 m/s`.","لأن الزيادة في السرعة تساوي `a·t`، وهي تضاف إلى السرعة عند البداية ولا تحل محلها."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ٤ (صفحة 60) (تابع)":["الزيادة `2 × 8 = 16 m/s` تضاف إلى `10 m/s`، فتصبح السرعة `26 m/s`.","إزاحة السيارة في الزمن نفسه: `x = (10 + 26) ÷ 2 × 8 = 144 m`.","لأن الضرب يسبق الجمع في ترتيب العمليات، فنحسب `a·t` أولا ثم نضيف `Vi`."],"تمرين 5 · تمارين الوحدة · اختر الإجابة ٥ (صفحة 60)":["الجسم ساكن، فالسرعة الابتدائية صفر. والمطلوب مسافة بمعلومية تسارع وزمن، فنستخدم `x = Vi·t + ½·a·t²`.","جسم ساكن انطلق بتسارع `4 m/s²` لمدة `3 s`: `x = ½ × 4 × 3² = 18 m`.","لأن السرعة النهائية غير معطاة ولا مطلوبة، فالمعادلة التي لا تحتويها هي الأنسب."],"تمرين 5 · تمارين الوحدة · اختر الإجابة ٥ (صفحة 60) (تابع)":["نربع الزمن أولا `5² = 25`، ثم نضربه في نصف التسارع `2.5`، فنحصل على `62.5 m`.","لو تضاعف الزمن إلى `10 s`: `x = ½ × 5 × 10² = 250 m`، أي أربعة أضعاف.","لأن الإزاحة من السكون تتناسب مع مربع الزمن، فمضاعفة الزمن تضرب الإزاحة في أربعة."]},"1-3":{"":["يدرس هذا الدرس سبب حركة الأجسام: القوة دفع أو سحب، وقوانين نيوتن الثلاثة تخبرنا متى يبقى الجسم على حاله، وكم يتسارع، وكيف تتبادل الأجسام القوى.","دراجة مع راكبها كتلتهما `80 kg` تؤثر عليهما قوة محصلة `160 N`: `a = 160 ÷ 80 = 2 m/s²`، ووزنهما `W = 80 × 9.8 = 784 N`.","لأن تغير حركة أي جسم يحتاج سببا، وهذا السبب هو القوة المحصلة. وبدونها يبقى الجسم على حالته، ومعها يتسارع بحسب كتلته."],"القوة":["القوة هي أن تدفع شيئا أو تسحبه، مثل دفع باب أو سحب درج. ولأن لها اتجاها نقول إنها كمية متجهة، ونقيسها بالنيوتن.","جسم كتلته `2 kg` يتسارع `5 m/s²`، فالقوة المؤثرة عليه `F = 2 × 5 = 10 N`، أي `10 kg·m/s²`.","القوة متجهة لأن أثرها يعتمد على اتجاهها: دفع الباب للداخل يختلف عن سحبه للخارج. ووحدتها `kg·m/s²` لأنها حاصل ضرب الكتلة في التسارع."],"قانون نيوتن الأول (القصور الذاتي)":["الجسم «كسول» بطبعه: إن كان ساكنا يبقى ساكنا، وإن كان متحركا يستمر بالسرعة نفسها في خط مستقيم، حتى تأتي قوة محصلة تغير حالته.","صندوق كتلته `30 kg` على الأرض وزنه `294 N` للأسفل، والقوة العمودية عليه `294 N` للأعلى، فالمحصلة `ΣF = 294 − 294 = 0` ويبقى ساكنا.","لأن تغير السرعة يحتاج قوة محصلة، فإذا كانت المحصلة صفرا فلا تسارع. وكلما زادت الكتلة زاد القصور الذاتي، فيصعب تحريك الجسم أو إيقافه."],"أمثلة على قانون نيوتن الأول":["الكتاب على الطاولة لا يتحرك وحده، لأن الطاولة تدفعه للأعلى بقدر ما تسحبه الأرض للأسفل، فتتعادل القوتان.","كتاب كتلته `0.5 kg` وزنه `W = 0.5 × 9.8 = 4.9 N`، والطاولة تدفعه بقوة عمودية `4.9 N` للأعلى، فالمحصلة صفر ويبقى ساكنا.","لأن القوتين المؤثرتين على الكتاب متساويتان ومتعاكستان، فمحصلتهما صفر، ولا يوجد ما يغير حالته الحركية."],"مثال: اندفاع راكب السيارة للأمام عند توقفها المفاجئ":["الفرامل توقف السيارة، لكنها لا توقف جسمك مباشرة، فيستمر جسمك في الحركة للأمام. وحزام الأمان هو القوة التي توقفك مع السيارة.","سيارة تسير بسرعة `20 m/s` وتتوقف فجأة، فيميل الراكب للاستمرار بسرعة `20 m/s`. ولو أوقفه الحزام بتباطؤ `10 m/s²` وكتلته `70 kg` فقوة الحزام `F = 70 × 10 = 700 N`.","لأن جسم الراكب له قصور ذاتي، فيحافظ على حالته الحركية ما لم تؤثر عليه قوة محصلة، والفرامل تؤثر على السيارة لا على الراكب."],"قانون نيوتن الثاني":["كلما دفعت الجسم بقوة أكبر تسارع أكثر، وكلما كان أثقل تسارع أقل. والقانون يجمع ذلك في `F = m·a`.","قوة `24 N` تؤثر على جسم كتلته `6 kg`، فتسارعه `a = 24 ÷ 6 = 4 m/s²`. ولو كانت الكتلة `12 kg` لصار التسارع `2 m/s²`.","لأن القوة هي ما يغير السرعة، فالقوة الأكبر تغيرها أسرع. أما الكتلة فتقاوم التغير بسبب القصور الذاتي، فيقل التسارع كلما زادت."],"أمثلة على قانون نيوتن الثاني":["دفع عربة تسوق فارغة سهل، أما الممتلئة فتتحرك ببطء مع أنك تدفعها بالقوة نفسها، لأن كتلتها أكبر.","بقوة `30 N`: عربة فارغة كتلتها `10 kg` تتسارع `30 ÷ 10 = 3 m/s²`، وممتلئة كتلتها `30 kg` تتسارع `30 ÷ 30 = 1 m/s²` فقط.","لأن التسارع يتناسب عكسيا مع الكتلة عند ثبات القوة `a = F / m`، فزيادة الكتلة تعني قصورا ذاتيا أكبر وتسارعا أقل."],"مثال: ركل الكرة بقوة خفيفة ثم بقوة كبيرة":["الكرة نفسها في المرتين، فكلما ركلتها أقوى انطلقت أسرع. القوة الأكبر تعطي تسارعا أكبر.","كرة كتلتها `0.4 kg`: ركلة بقوة `20 N` تعطيها `a = 20 ÷ 0.4 = 50 m/s²`، وركلة بقوة `40 N` تعطيها `100 m/s²`، أي الضعف.","لأن التسارع يتناسب طرديا مع القوة عند ثبات الكتلة، فمضاعفة القوة تضاعف التسارع."],"الوزن":["الوزن هو قوة سحب الأرض لك نحو الأسفل، أما الكتلة فهي كمية المادة فيك. كتلتك ثابتة أينما ذهبت، لكن وزنك يتغير بتغير الجاذبية.","حقيبة كتلتها `5 kg` وزنها على الأرض `W = 5 × 9.8 = 49 N` متجه رأسيا إلى الأسفل.","لأن الوزن قوة ناتجة عن الجاذبية، فهو يعتمد على الكتلة وعلى تسارع الجاذبية في المكان. أما الكتلة فخاصية للجسم نفسه لا تتغير."],"مثال: رائد الفضاء على سطح القمر":["رائد الفضاء هو نفسه على القمر، لكن القمر يجذبه أضعف من الأرض، فيشعر بخفة ويقفز عاليا.","رائد كتلته `80 kg`: وزنه على الأرض `80 × 9.8 = 784 N`، وعلى القمر حيث `g = 1.6 m/s²` وزنه `80 × 1.6 = 128 N`، وكتلته `80 kg` في الحالتين.","لأن الوزن `W = m·g` يعتمد على تسارع الجاذبية، وجاذبية القمر أضعف، بينما الكتلة مقدار المادة في الجسم فلا تتغير."],"قانون نيوتن الثالث":["إذا دفعت الحائط فإن الحائط يدفعك بالقدر نفسه في الاتجاه المعاكس. القوى تأتي دائما أزواجا بين جسمين.","إذا دفعت حائطا بقوة `120 N` نحو الشرق، فإن الحائط يدفعك بقوة `120 N` نحو الغرب: `F_AB = −F_BA`.","لأن القوة تأثير متبادل بين جسمين، فلا يؤثر جسم في آخر دون أن يتأثر به. والقوتان على جسمين مختلفين فلا تلغي إحداهما الأخرى."],"أمثلة على قانون نيوتن الثالث":["المجداف يدفع الماء للخلف، فيدفع الماء المجداف والقارب للأمام. كأنك تدفع الماء لتدفع نفسك.","إذا دفع المجداف الماء بقوة `150 N` للخلف، رد الماء بقوة `150 N` للأمام، فقارب كتلته `300 kg` يتسارع `150 ÷ 300 = 0.5 m/s²` بإهمال المقاومة.","لأن قوة المجداف على الماء وقوة الماء على المجداف زوج فعل ورد فعل متساويان ومتعاكسان، ورد الفعل يؤثر على القارب فيحركه."],"مثال: السباح (صفحة 43)":["السباح يدفع الماء بيديه وقدميه للخلف، فيرد الماء عليه بدفعة للأمام تحركه.","سباح كتلته `60 kg` يدفع الماء بقوة `120 N` للخلف، فيدفعه الماء `120 N` للأمام، وتسارعه بإهمال المقاومة `120 ÷ 60 = 2 m/s²`.","لأن الماء جسم آخر يتلقى قوة السباح، فيرد بقوة مساوية ومعاكسة تؤثر على السباح نفسه."],"مثال: السيارة والحائط (صفحة 43)":["عندما تصطدم السيارة بالحائط فإنها تدفعه، والحائط يدفعها بالقدر نفسه للخلف، ولهذا تتحطم مقدمة السيارة.","إذا أثرت السيارة على الحائط بقوة `20000 N` للأمام، أثر الحائط عليها بقوة `20000 N` للخلف، فسيارة كتلتها `1000 kg` تتباطأ بمقدار `20000 ÷ 1000 = 20 m/s²`.","لأن قوة الحائط على السيارة رد فعل لقوتها عليه، وتؤثر على جسم مختلف هو السيارة، فتوقفها وتشوه مقدمتها."],"مثال: الصاروخ (صفحة 44)":["الصاروخ يقذف الغازات الساخنة بقوة للأسفل، فتدفعه الغازات للأعلى، مثل بالون يندفع عند خروج الهواء منه.","صاروخ يدفع الغازات بقوة `5000 N` للأسفل، فتدفعه الغازات `5000 N` للأعلى. وإذا كان وزنه `3000 N` فالمحصلة `5000 − 3000 = 2000 N` للأعلى.","لأن الصاروخ والغازات جسمان يتبادلان قوتين متساويتين ومتعاكستين، فدفع الغازات للأسفل يعني دفع الصاروخ للأعلى."],"مثال: إطلاق الرصاصة من البندقية (صفحة 44)":["البندقية تدفع الرصاصة للأمام، والرصاصة تدفع البندقية للخلف بالقدر نفسه، فيشعر الرامي بالارتداد في كتفه.","قوة `2000 N` على رصاصة كتلتها `0.01 kg` تعطيها `a = 2000 ÷ 0.01 = 200000 m/s²`، والقوة نفسها على بندقية كتلتها `4 kg` تعطيها `500 m/s²` فقط.","لأن القوتين متساويتان، لكن كتلة البندقية أكبر بكثير، فتسارعها أصغر بكثير من تسارع الرصاصة حسب `a = F / m`."],"أمثلة الحقيبة التدريبية محلولة":["قبل الحل نرتب المسألة: نكتب المعطيات (الكتلة والتسارع) ونحدد المطلوب (القوة) ووحدته، فيسهل اختيار القانون.","جسم كتلته `6 kg` يتسارع `9 m/s²`: المعطيات `m = 6 kg` و `a = 9 m/s²`، والمطلوب القوة `F` بوحدة النيوتن.","لأن كتابة المعطيات بوحداتها تكشف القانون المناسب، فوجود الكتلة والتسارع وطلب القوة يقودنا مباشرة إلى `F = m·a`."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نضرب الكتلة في التسارع فنحصل على القوة بالنيوتن، واتجاهها هو اتجاه التسارع نفسه.","جسم كتلته `6 kg` يتسارع `9 m/s²`: `F = 6 × 9 = 54 N` في اتجاه التسارع.","لأن الكتلة كمية قياسية موجبة، فالقوة والتسارع في `F = m·a` لهما الاتجاه نفسه دائما."],"مثال ٢: تسارع سيارة بمعلومية القوة والكتلة (صفحة 40)":["هنا نعرف القوة والكتلة ونريد التسارع، أي كم تزداد سرعة السيارة في كل ثانية.","شاحنة كتلتها `4000 kg` تؤثر عليها قوة `12000 N`: المعطيات `F = 12000 N` و `m = 4000 kg`، والمطلوب `a` بوحدة `m/s²`.","لأن القانون نفسه `F = m·a` يربط الكميات الثلاث، فإذا عرفنا اثنتين منها أمكننا إيجاد الثالثة."],"مثال ٢: تسارع سيارة بمعلومية القوة والكتلة (صفحة 40) (تابع)":["نقسم القوة على الكتلة فنحصل على التسارع، واتجاهه هو اتجاه القوة.","شاحنة كتلتها `4000 kg` وقوة `12000 N`: `a = 12000 ÷ 4000 = 3 m/s²` في اتجاه القوة.","لأن `a = F / m`: القوة تزيد التسارع والكتلة تقلله، واتجاه التسارع يتبع اتجاه القوة المحصلة."],"مثال ٣: سرعة صندوق بعد زمن من تأثير قوة (صفحة 41)":["الصندوق ساكن، فسرعته الابتدائية صفر. القوة تعطيه تسارعا، ومع مرور الزمن تزداد سرعته.","قوة `40 N` على صندوق ساكن كتلته `8 kg` لمدة `5 s`: المعطيات `F = 40 N` و `m = 8 kg` و `t = 5 s` و `Vi = 0`، والمطلوب `Vf`.","لأننا نحتاج قانونين: قانون نيوتن الثاني ليعطينا التسارع، ثم معادلة الحركة لتعطينا السرعة بعد زمن معين."],"مثال ٣: سرعة صندوق بعد زمن من تأثير قوة (صفحة 41) (تابع)":["نجد التسارع أولا من القوة والكتلة، ثم نضربه في الزمن ونضيفه إلى السرعة الابتدائية.","قوة `40 N` وكتلة `8 kg` وزمن `5 s`: `a = 40 ÷ 8 = 5 m/s²`، ثم `Vf = 0 + 5 × 5 = 25 m/s`.","لأن التسارع الثابت يعني أن السرعة تزيد بالمقدار نفسه كل ثانية، فبعد زمن t تزيد بمقدار `a·t`."],"مثال ٤: صندوق يُسحب على سطح أملس (صفحة 41)":["السطح الأملس بلا احتكاك، فقوة السحب وحدها هي القوة المحصلة. ونريد ثلاثة أشياء: التسارع والسرعة النهائية والمسافة.","صندوق ساكن كتلته `10 kg` يسحب بقوة `30 N` لمدة `2 s` على سطح أملس: المعطيات `m = 10 kg` و `F = 30 N` و `t = 2 s` و `Vi = 0`.","لأن غياب الاحتكاك يجعل قوة السحب هي المحصلة، فنستطيع استخدامها مباشرة في `F = m·a`."],"مثال ٤: صندوق يُسحب على سطح أملس (صفحة 41) (تابع)":["نجد التسارع أولا، ثم نستخدمه في معادلتي الحركة لإيجاد السرعة النهائية والمسافة.","كتلة `10 kg` وقوة `30 N` وزمن `2 s`: `a = 30 ÷ 10 = 3 m/s²`، و `Vf = 0 + 3 × 2 = 6 m/s`، و `x = ½ × 3 × 2² = 6 m`.","لأن القوة الثابتة تعطي تسارعا ثابتا، وعندها تصلح معادلات الحركة بتسارع ثابت لربط السرعة والمسافة بالزمن."],"مثال ١: وزن جسم على سطح الأرض (صفحة 42)":["نريد معرفة قوة سحب الأرض للجسم، ونحتاج لذلك كتلته وتسارع الجاذبية.","جسم كتلته `50 kg`: المعطيات `m = 50 kg` و `g = 9.8 m/s²`، والمطلوب الوزن `W` بالنيوتن.","لأن الوزن قوة، فوحدته النيوتن مثل أي قوة، ويحسب من الكتلة وتسارع الجاذبية."],"مثال ١: وزن جسم على سطح الأرض (صفحة 42) (تابع)":["نضرب الكتلة في `9.8` فنحصل على الوزن، واتجاهه دائما نحو الأسفل.","جسم كتلته `50 kg`: `W = 50 × 9.8 = 490 N` رأسيا إلى الأسفل.","لأن الوزن حالة خاصة من `F = m·a` يكون فيها التسارع هو تسارع الجاذبية `g`، فنحصل على `W = m·g`."],"ملخص قوانين نيوتن":["الأول: بلا قوة محصلة لا تتغير الحركة. الثاني: القوة المحصلة تعطي تسارعا يقل بزيادة الكتلة. الثالث: القوى تأتي أزواجا متساوية ومتعاكسة بين جسمين.","كرة كتلتها `0.5 kg` ساكنة تبقى ساكنة (الأول)، وبقوة `10 N` تتسارع `10 ÷ 0.5 = 20 m/s²` (الثاني)، وتؤثر الكرة على القدم بقوة `10 N` معاكسة (الثالث).","لأن القوانين الثلاثة تصف القوة من زوايا مختلفة: متى لا تتغير الحركة، وكيف تتغير بالقوة، وكيف تتبادل الأجسام القوى."],"تطبيقات من الحياة":["قوانين نيوتن حولنا في كل مكان: الحزام يحمينا عند التوقف المفاجئ، والشاحنة المحملة تحتاج قوة أكبر، وأقدامنا تدفع الأرض لنمشي.","ميزان يقيس وزنا مقداره `588 N`، فيحوله إلى كتلة بالقسمة على `g`: `m = 588 ÷ 9.8 = 60 kg`.","لأن كل حركة أو توقف أو دفع في حياتنا يحتاج قوة، والقوانين الثلاثة هي التي تحكم أثر هذه القوى."],"تمرين 1 · ورقة عمل (١) · سؤال ٣ (صفحة 49)":["معنا كتلة وتسارع، والمطلوب القوة، فهي حالة مباشرة لقانون نيوتن الثاني.","جسم كتلته `7 kg` يتسارع `4 m/s²`: المعطيات `m = 7 kg` و `a = 4 m/s²`، والمطلوب القوة `F`.","لأن معرفة الكتلة والتسارع تكفي لإيجاد القوة المحصلة التي سببت هذا التسارع."],"تمرين 1 · ورقة عمل (١) · سؤال ٣ (صفحة 49) (تابع)":["نضرب الكتلة في التسارع مباشرة، والناتج بالنيوتن.","جسم كتلته `7 kg` يتسارع `4 m/s²`: `F = 7 × 4 = 28 N`.","لأن النيوتن الواحد هو القوة التي تكسب كتلة `1 kg` تسارعا مقداره `1 m/s²`، فتكبر القوة مع الكتلة ومع التسارع."],"تمرين 2 · ورقة عمل (١) · سؤال ٤ (صفحة 49)":["نعرف القوة والكتلة، والمطلوب التسارع، فنعيد ترتيب `F = m·a`.","سيارة كتلتها `1500 kg` تؤثر عليها قوة `4500 N`: المعطيات `m = 1500 kg` و `F = 4500 N`، والمطلوب `a`.","لأن التسارع هو المجهول الوحيد في `F = m·a`، فنحصل عليه بقسمة الطرفين على الكتلة."],"تمرين 2 · ورقة عمل (١) · سؤال ٤ (صفحة 49) (تابع)":["نقسم القوة على الكتلة فيظهر التسارع.","سيارة كتلتها `1500 kg` وقوة `4500 N`: `a = 4500 ÷ 1500 = 3 m/s²`.","لأن الكتلة الكبيرة تقاوم تغير الحركة، فكلما كبرت الكتلة صغر التسارع الناتج عن القوة نفسها."],"تمرين 3 · ورقة عمل (١) · سؤال ٥ (صفحة 50)":["نعرف القوة والتسارع، والمطلوب الكتلة، أي كم يقاوم الجسم تغير حركته.","قوة `36 N` تكسب جسما تسارعا `4 m/s²`: المعطيات `F = 36 N` و `a = 4 m/s²`، والمطلوب الكتلة `m`.","لأن الكتلة مقياس للقصور الذاتي، ويمكن معرفتها من مقدار التسارع الذي تحدثه قوة معلومة."],"تمرين 3 · ورقة عمل (١) · سؤال ٥ (صفحة 50) (تابع)":["نقسم القوة على التسارع فنحصل على الكتلة بالكيلوجرام.","قوة `36 N` وتسارع `4 m/s²`: `m = 36 ÷ 4 = 9 kg`.","لأن `m = F / a`: إذا أعطت القوة نفسها تسارعا صغيرا فالكتلة كبيرة، والعكس."],"تمرين 4 · ورقة عمل (١) · سؤال ٦ (صفحة 50)":["نعرف الكتلة، والمطلوب الوزن على الأرض، فنستخدم تسارع الجاذبية الأرضية.","جسم كتلته `75 kg`: المعطيات `m = 75 kg` و `g = 9.8 m/s²`، والمطلوب الوزن `W`.","لأن الوزن قوة جذب الأرض، فلا تكفي معرفة الكتلة وحدها، بل نحتاج تسارع الجاذبية أيضا."],"تمرين 4 · ورقة عمل (١) · سؤال ٦ (صفحة 50) (تابع)":["نضرب الكتلة في `9.8` فنحصل على الوزن بالنيوتن.","جسم كتلته `75 kg`: `W = 75 × 9.8 = 735 N`.","لأن الأرض تجذب كل كيلوجرام على سطحها بقوة `9.8 N`، فنضرب عدد الكيلوجرامات في هذا المقدار."],"تمرين 5 · تمارين الوحدة · اختر الإجابة ١٠ (صفحة 61)":["الجسم ساكن ونريد إكسابه تسارعا معينا، فنسأل: كم قوة نحتاج؟","جسم ساكن كتلته `9 kg` نريد إكسابه تسارعا `2 m/s²`: المعطيات `m = 9 kg` و `a = 2 m/s²`، والمطلوب `F`.","لأن الجسم الساكن لا يتحرك وحده حسب القانون الأول، ويحتاج قوة محصلة يحددها القانون الثاني."],"تمرين 5 · تمارين الوحدة · اختر الإجابة ١٠ (صفحة 61) (تابع)":["نضرب الكتلة في التسارع المطلوب فنعرف القوة اللازمة.","جسم كتلته `9 kg` وتسارع `2 m/s²`: `F = 9 × 2 = 18 N`.","لأن القوة اللازمة تتناسب طرديا مع التسارع المطلوب ومع الكتلة، فأي زيادة في أحدهما تحتاج قوة أكبر."],"تمرين 6 · تمارين الوحدة · اختر الإجابة ١١ (صفحة 61)":["السهم خفيف جدا، فالقوة المتوسطة تعطيه تسارعا كبيرا.","حجر كتلته `0.5 kg` يقذف بقوة `30 N`: المعطيات `m = 0.5 kg` و `F = 30 N`، والمطلوب التسارع `a`.","لأن التسارع يتناسب عكسيا مع الكتلة، فالكتلة الصغيرة جدا تعني تسارعا كبيرا بالقوة نفسها."],"تمرين 6 · تمارين الوحدة · اختر الإجابة ١١ (صفحة 61) (تابع)":["نقسم القوة على الكتلة، والقسمة على عدد أصغر من واحد تكبر الناتج.","حجر كتلته `0.5 kg` وقوة `30 N`: `a = 30 ÷ 0.5 = 60 m/s²`.","لأن القسمة على `0.5` تعني الضرب في 2، فالكتلة الصغيرة تضاعف أثر القوة على التسارع."],"تمرين 7 · تمارين الوحدة · اختر الإجابة ٣١ (صفحة 64)":["نعرف كتلة السيارة وتسارعها، والمطلوب القوة المحركة.","حافلة كتلتها `5000 kg` تتسارع `2 m/s²`: المعطيات `m = 5000 kg` و `a = 2 m/s²`، والمطلوب `F`.","لأن تسارع السيارة دليل على وجود قوة محصلة، ويمكن حسابها من الكتلة والتسارع."],"تمرين 7 · تمارين الوحدة · اختر الإجابة ٣١ (صفحة 64) (تابع)":["نضرب الكتلة في التسارع، فالسيارات الثقيلة تحتاج قوى بآلاف النيوتن.","حافلة كتلتها `5000 kg` وتسارع `2 m/s²`: `F = 5000 × 2 = 10000 N`.","لأن الكتلة الكبيرة للسيارة تعني قصورا ذاتيا كبيرا، فتحتاج قوة كبيرة لتكسبها حتى تسارعا صغيرا."]},"1-5":{"":["الاحتكاك قوة تظهر عندما يتلامس سطحان، فتعيق انزلاق أحدهما على الآخر. ونتدرب في هذا الدرس على حسابها، ومعرفة هل يتحرك الجسم أم لا.","صندوق وزنه `100 N` على أرض أفقية ومعامل الاحتكاك الحركي `0.3`: `fk = 0.3 × 100 = 30 N` عكس اتجاه الحركة.","لأن الاحتكاك يعتمد على طبيعة السطحين (المعامل) وعلى قوة ضغط أحدهما على الآخر (القوة العمودية)، لذلك نحسبه بالقانون `f = μ·N`."],"قوة الاحتكاك":["عندما تدفع خزانة على الأرض تشعر بشيء يقاومك، هذا هو الاحتكاك، ويعمل دائما ضد اتجاه الحركة.","جسم كتلته `5 kg` على سطح أفقي، فقوته العمودية تساوي وزنه `N = W = 5 × 9.8 = 49 N`.","لأن الاحتكاك يعيق الانزلاق، فلا بد أن يعاكس اتجاه الحركة أو الميل إليها. والقوة العمودية تساوي الوزن على السطح الأفقي لأن الجسم لا يتحرك رأسيا."],"أنواع قوى الاحتكاك":["الاحتكاك نوعان: ساكن يمنع الجسم من بدء الحركة، وحركي يعيقه وهو يتحرك. لهذا يكون تحريك الخزانة أصعب في البداية.","صندوق وزنه `50 N` على سطح أفقي، معاملاه `μs = 0.5` و `μk = 0.3`: أقصى احتكاك سكوني `0.5 × 50 = 25 N`، والاحتكاك الحركي `0.3 × 50 = 15 N`.","لأن معامل الاحتكاك السكوني عادة أكبر من الحركي، فبدء الحركة يحتاج قوة أكبر من الاستمرار فيها، وكل نوع يحسب بمعامله الخاص."],"قانون قوة الاحتكاك":["قوة الاحتكاك تعتمد على شيئين: نوع السطحين (المعامل)، وقوة ضغط الجسم على السطح (القوة العمودية).","القوة العمودية `60 N` ومعامل الاحتكاك الحركي `0.25`: `fk = 0.25 × 60 = 15 N`.","لأن الاحتكاك يزيد كلما زاد ضغط الجسم على السطح، أي بزيادة القوة العمودية. والمعامل بلا وحدة لأنه نسبة بين قوتين."],"هل يتحرك الجسم؟":["الأمر يشبه شد الحبل: إذا غلبت قوة دفعك أقصى ما يستطيعه الاحتكاك الساكن تحرك الجسم، وإلا بقي مكانه.","أقصى احتكاك سكوني `20 N`: الدفع بقوة `25 N` يحرك الجسم لأنها أكبر، والدفع بقوة `12 N` لا يحركه لأنها أقل.","لأن الاحتكاك الساكن يوازن قوة الدفع حتى يبلغ أقصى قيمة له `μs·N`، فإذا زادت قوة الدفع عليها أصبحت المحصلة غير منعدمة فيتحرك الجسم."],"أمثلة الحقيبة التدريبية محلولة":["الصندوق على سطح أفقي، فالقوة العمودية تساوي وزنه، ومعنا المعامل، فنستطيع حساب الاحتكاك.","صندوق وزنه `80 N` ينزلق على أرض أفقية بمعامل حركي `0.15`: المعطيات `N = 80 N` و `μk = 0.15`، والمطلوب `fk`.","لأن الصندوق ينزلق، فالاحتكاك المؤثر هو الاحتكاك الحركي، ويحسب بمعامل الاحتكاك الحركي."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نضرب المعامل في القوة العمودية، والناتج قوة بالنيوتن تعاكس الحركة.","صندوق وزنه `80 N` بمعامل `0.15`: `fk = 0.15 × 80 = 12 N` عكس اتجاه الحركة.","لأن الاحتكاك يعيق الانزلاق دائما، فاتجاهه عكس اتجاه الحركة مهما كان مقداره."],"مثال ٢: إيجاد معامل الاحتكاك الحركي (صفحة 45)":["هنا نعرف قوة الاحتكاك والقوة العمودية، ونريد المعامل الذي يصف طبيعة السطحين.","القوة العمودية `50 N` وقوة الاحتكاك الحركي `10 N`: المعطيات `N = 50 N` و `fk = 10 N`، والمطلوب `μk`.","لأن المعامل يربط القوتين في `fk = μk·N`، فمعرفة القوتين تكفي لإيجاده."],"مثال ٢: إيجاد معامل الاحتكاك الحركي (صفحة 45) (تابع)":["نقسم قوة الاحتكاك على القوة العمودية، فيخرج رقم بلا وحدة.","القوة العمودية `50 N` وقوة الاحتكاك `10 N`: `μk = 10 ÷ 50 = 0.2`، بلا وحدة.","لأنه ناتج قسمة نيوتن على نيوتن فتختصر الوحدتان، والمعامل يعبر عن طبيعة السطحين فقط."],"مثال ٣: هل يتحرك الصندوق؟ (صفحة 45)":["نريد مقارنة قوة الدفع بأقصى احتكاك سكوني، لكن نحتاج أولا القوة العمودية من الوزن.","صندوق كتلته `10 kg` يدفع بقوة `30 N` ومعامل الاحتكاك السكوني `0.5`: المعطيات `m = 10 kg` و `F = 30 N` و `μs = 0.5` و `g = 9.8 m/s²`.","لأن الصندوق ساكن، فالاحتكاك الذي يمنعه هو الاحتكاك السكوني، وأقصى قيمة له هي ما يجب أن تتجاوزه قوة الدفع."],"مثال ٣: هل يتحرك الصندوق؟ (صفحة 45) (تابع)":["نحسب الوزن ثم أقصى احتكاك سكوني، ثم نقارن: الدفع الأضعف من أقصى احتكاك لا يحرك الصندوق.","`W = 10 × 9.8 = 98 N`، و `fs(max) = 0.5 × 98 = 49 N`، وقوة الدفع `30 N` أقل منها فلا يتحرك الصندوق.","لأن الاحتكاك الساكن يعادل قوة الدفع ما دامت أقل من أقصى قيمة له، فتكون المحصلة صفرا ويبقى الصندوق ساكنا."],"تطبيقات من الحياة":["الاحتكاك أحيانا صديق وأحيانا عدو: نحتاجه في الإطارات والفرامل والأحذية، ونقلله بالزيت في المحركات.","سيارة وزنها `9800 N`: على طريق جاف بمعامل `0.7` أقصى احتكاك `0.7 × 9800 = 6860 N`، وعلى طريق مبلل بمعامل `0.4` يصبح `3920 N` فقط.","لأن قوة الاحتكاك تعتمد على المعامل، فالماء يقلله فتضعف قوة التوقف وتطول المسافة، والنعال الخشنة تزيده فتمنع الانزلاق."],"تمرين 1 · ورقة عمل (١) · سؤال ٧ (صفحة 50)":["الوزن معلوم والسطح أفقي، فالقوة العمودية تساوي الوزن، ثم نحسب الاحتكاك.","صندوق وزنه `60 N` على طاولة أفقية بمعامل حركي `0.2`: المعطيات `N = 60 N` و `μ = 0.2`، والمطلوب قوة الاحتكاك.","لأن الطاولة الأفقية تدفع الصندوق للأعلى بقدر وزنه حتى لا يتحرك رأسيا، فتكون القوة العمودية مساوية للوزن."],"تمرين 1 · ورقة عمل (١) · سؤال ٧ (صفحة 50) (تابع)":["نضرب المعامل في القوة العمودية فنحصل على قوة الاحتكاك.","صندوق وزنه `60 N` بمعامل `0.2`: `f = 0.2 × 60 = 12 N`.","لأن قوة الاحتكاك تتناسب طرديا مع القوة العمودية، والمعامل هو ثابت هذا التناسب للسطحين."],"تمرين 2 · ورقة عمل (١) · سؤال ٨ (صفحة 51)":["معنا القوتان، والمطلوب المعامل، فنعيد ترتيب القانون.","القوة العمودية `40 N` وقوة الاحتكاك `6 N`: المعطيات `N = 40 N` و `f = 6 N`، والمطلوب `μ`.","لأن المعامل هو المجهول الوحيد في `f = μ·N`، فنجده بقسمة الطرفين على N."],"تمرين 2 · ورقة عمل (١) · سؤال ٨ (صفحة 51) (تابع)":["نقسم قوة الاحتكاك على القوة العمودية فنحصل على المعامل.","القوة العمودية `40 N` وقوة الاحتكاك `6 N`: `μ = 6 ÷ 40 = 0.15`.","لأن قوة الاحتكاك عادة أصغر من القوة العمودية، فيكون المعامل غالبا أقل من 1 وبلا وحدة."],"تمرين 3 · ورقة عمل (١) · سؤال ٩ (صفحة 51)":["نعرف الكتلة لا الوزن، فنحسب القوة العمودية أولا، ثم أقصى احتكاك سكوني ونقارنه بالدفع.","صندوق كتلته `4 kg` بمعامل سكوني `0.3`: المعطيات `m = 4 kg` و `μs = 0.3` و `g = 9.8 m/s²`، والمطلوب أقصى احتكاك سكوني.","لأن القانون يحتاج القوة العمودية، وهي على السطح الأفقي تساوي الوزن `m·g` لا الكتلة."],"تمرين 3 · ورقة عمل (١) · سؤال ٩ (صفحة 51) (تابع)":["نحسب الوزن ثم نضربه في المعامل، ونقارن الناتج بقوة الدفع لنعرف هل يتحرك الصندوق.","صندوق كتلته `4 kg` بمعامل `0.3`: `N = 4 × 9.8 = 39.2 N`، و `f = 0.3 × 39.2 = 11.76 N`، فالدفع بقوة `10 N` لا يحركه.","لأن الجسم لا يتحرك إلا إذا زادت قوة الدفع على أقصى احتكاك سكوني."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ٣٣ (صفحة 64)":["المعامل والقوة العمودية معلومان مباشرة، فالحساب خطوة واحدة.","جسم يتحرك على سطح بمعامل حركي `0.4` وقوة عمودية `90 N`: المعطيات `μ = 0.4` و `N = 90 N`، والمطلوب `f`.","لأن معامل الاحتكاك يعتمد على نوع المادتين المتلامستين، فالصلب على النحاس له معامل خاص يختلف عن غيرهما."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ٣٣ (صفحة 64) (تابع)":["نضرب المعامل في القوة العمودية، فنحصل على قوة الاحتكاك بالنيوتن.","معامل `0.4` وقوة عمودية `90 N`: `f = 0.4 × 90 = 36 N`.","لأن قوة الاحتكاك تزيد بزيادة المعامل أو القوة العمودية، فهي حاصل ضربهما."]},"1-6":{"":["ورقة العمل تجمع قوانين الحركة وقوانين نيوتن في مسائل محلولة. في كل مسألة نكتب المعطيات والمطلوب، ثم نختار القانون، ثم نعوض ونكتب الناتج بوحدته.","جسم كتلته `5 kg` تؤثر عليه قوة `20 N`: `a = F ÷ m = 20 ÷ 5 = 4 m/s²`، وبعد `2 s` من السكون تصبح سرعته `Vf = 0 + 4 × 2 = 8 m/s`.","لأن ترتيب الحل في خطوات ثابتة يمنع نسيان معطى أو الخلط بين الرموز، ويجعل اختيار القانون مبنيا على ما هو معلوم وما هو مطلوب."],"ما تحتاجه لحل ورقة العمل":["هذه الشريحة مثل علبة أدوات: قوانين الحركة لحساب السرعة والتسارع والمسافة، وقانون نيوتن والوزن والاحتكاك لحساب القوى. تختار الأداة المناسبة حسب المعطيات.","جسم يبدأ بسرعة `4 m/s` ويتسارع بمعدل `2 m/s²` لمدة `3 s`: `x = Vi·t + ½·a·t² = 4 × 3 + ½ × 2 × 3² = 12 + 9 = 21 m`.","لأن كل قانون يربط بين كميات محددة، فإذا عرفت كل الكميات في القانون إلا واحدة أمكنك حسابها. لذلك نختار القانون الذي يحتوي المجهول والمعطيات فقط."],"حل ورقة العمل":["المسافة هي طول الطريق الذي مشيته فعلا، أما الإزاحة فهي الخط المستقيم من مكان البداية إلى مكان النهاية مع اتجاهه. لو درت حول الملعب ورجعت لمكانك فالإزاحة صفر.","متدرب مشى `5 m` شرقا ثم `2 m` غربا: المسافة `5 + 2 = 7 m`، والإزاحة `5 − 2 = 3 m` باتجاه الشرق.","لأن الإزاحة تهتم بالبداية والنهاية فقط فلها مقدار واتجاه، فهي متجهة. أما المسافة فتجمع طول المسار كله بلا اتجاه، فهي قياسية."],"حل ورقة العمل (تابع)":["السرعة تخبرك كم مترا تقطع في كل ثانية، والتسارع يخبرك كم تتغير سرعتك في كل ثانية. عداد السيارة يعرض السرعة، والضغط على دواسة الوقود يصنع التسارع.","دراجة قطعت `60 m` في `12 s`: `v = 60 ÷ 12 = 5 m/s`. وإذا زادت سرعتها من `5 m/s` إلى `9 m/s` في `2 s` فإن `a = (9 − 5) ÷ 2 = 2 m/s²`.","لأن السرعة معدل تغير الموضع مع الزمن فوحدتها `m/s`، والتسارع معدل تغير السرعة مع الزمن فنقسم `m/s` على `s` مرة أخرى فتصبح الوحدة `m/s²`."],"سؤال ٢: سرعة سيارة (صفحة 46)":["المطلوب هنا معرفة كم مترا تقطعها السيارة في الثانية الواحدة. نحدد المعطيات أولا وهي الإزاحة والزمن، ثم نعرف أن المطلوب سرعة بوحدة `m/s`.","عداء قطع `200 m` في `25 s`: `v = x / t = 200 ÷ 25 = 8 m/s`.","لأن كتابة المعطيات بوحداتها قبل الحل تكشف القانون المناسب مباشرة: لدينا إزاحة وزمن والمطلوب سرعة، والقانون الذي يربطها هو `v = x / t`."],"سؤال ٢: سرعة سيارة (صفحة 46) (تابع)":["نقسم المسافة على الزمن، أي نوزع الأمتار على الثواني بالتساوي، فنعرف نصيب كل ثانية من الأمتار.","سيارة قطعت `150 m` في `6 s`: `v = 150 ÷ 6 = 25 m/s`.","لأن السرعة المتوسطة هي الإزاحة الكلية مقسومة على الزمن الكلي، فهي القيمة الثابتة التي لو سارت بها السيارة لقطعت المسافة نفسها في الزمن نفسه."],"سؤال ٣: تسارع سيارة (صفحة 46)":["السيارة زادت سرعتها، والسؤال: بكم تزداد سرعتها في كل ثانية؟ نكتب السرعة الابتدائية والنهائية والزمن ثم نبحث عن التسارع.","قطار تغيرت سرعته من `10 m/s` إلى `40 m/s` في `10 s`: `a = (40 − 10) ÷ 10 = 3 m/s²`.","لأن التسارع يقيس سرعة تغير السرعة، فنحتاج مقدار التغير في السرعة والزمن الذي حدث فيه هذا التغير."],"سؤال ٣: تسارع سيارة (صفحة 46) (تابع)":["نطرح السرعة الابتدائية من النهائية لنعرف مقدار الزيادة، ثم نقسمها على عدد الثواني لنعرف الزيادة في كل ثانية.","دراجة نارية زادت سرعتها من `8 m/s` إلى `20 m/s` في `4 s`: `a = (20 − 8) ÷ 4 = 3 m/s²`.","لأن الطرح يعطي التغير في السرعة، والقسمة على الزمن تحول هذا التغير إلى معدل لكل ثانية، ولذلك تكون الوحدة `m/s²`."],"سؤال ٤: زمن توقف سيارة وتسارعها (صفحة 47)":["السيارة كانت تسير ثم ضغط السائق على الفرامل حتى وقفت. كلمة توقفت تعطينا معلومة مخفية: السرعة النهائية صفر.","دراجة سرعتها `6 m/s` توقفت بانتظام بعد `9 m`: السرعة المتوسطة `(0 + 6) ÷ 2 = 3 m/s`، والزمن `t = 9 ÷ 3 = 3 s`.","لأن السيارة التي تقف لم تعد تتحرك، فسرعتها في نهاية الحركة صفر، وهذه المعلومة تكمل المعطيات اللازمة لحل المسألة."],"سؤال ٤: زمن توقف سيارة وتسارعها (صفحة 47) (تابع)":["عندما تتغير السرعة بانتظام نأخذ متوسط السرعتين، ثم نقسم المسافة عليه لنعرف الزمن، ثم نحسب التسارع. والإشارة السالبة تعني أن السيارة تبطئ.","سيارة سرعتها `20 m/s` توقفت بانتظام بعد `50 m`: `v̄ = (0 + 20) ÷ 2 = 10 m/s`، و `t = 50 ÷ 10 = 5 s`، و `a = (0 − 20) ÷ 5 = −4 m/s²`.","لأن التسارع المنتظم يجعل السرعة تتغير بالمقدار نفسه كل ثانية، فتكون السرعة المتوسطة نصف مجموع السرعتين. والإشارة سالبة لأن السرعة النهائية أصغر من الابتدائية."],"سؤال ٥: المسافة التي قطعتها سيارة (صفحة 47)":["السيارة زادت سرعتها بانتظام خلال زمن معلوم، والمطلوب كم مترا قطعت. لدينا السرعتان والزمن، ولا نحتاج إلى التسارع.","عداء زادت سرعته بانتظام من `2 m/s` إلى `6 m/s` في `4 s`: `v̄ = (2 + 6) ÷ 2 = 4 m/s`، و `x = 4 × 4 = 16 m`.","لأن معرفة السرعتين الابتدائية والنهائية تكفي لحساب السرعة المتوسطة، والمسافة هي السرعة المتوسطة مضروبة في الزمن، فلا حاجة لحساب التسارع أولا."],"سؤال ٥: المسافة التي قطعتها سيارة (صفحة 47) (تابع)":["نحسب السرعة المتوسطة بجمع السرعتين وقسمتهما على 2، ثم نضربها في الزمن فنحصل على المسافة.","سيارة تسارعت بانتظام من `12 m/s` إلى `28 m/s` في `6 s`: `v̄ = (12 + 28) ÷ 2 = 20 m/s`، و `x = 20 × 6 = 120 m`.","لأن السرعة تزيد بانتظام، فما تنقصه السرعة في النصف الأول من الزمن عن المتوسط تعوضه في النصف الثاني، فتكون المسافة كأن السيارة سارت بالسرعة المتوسطة طوال الزمن."],"سؤال ٦: سرعة جسم بدأ من السكون (صفحة 48)":["عبارة بدأ من السكون تعني أن الجسم كان واقفا، أي أن سرعته الابتدائية صفر. ثم يزيد التسارع سرعته كل ثانية بمقدار ثابت.","كرة بدأت من السكون بتسارع `4 m/s²`، وبعد `5 s` تصبح سرعتها `Vf = 0 + 4 × 5 = 20 m/s`.","لأن التسارع الثابت يعني زيادة متساوية في السرعة كل ثانية، فالسرعة النهائية تساوي السرعة الابتدائية مضافا إليها التسارع مضروبا في الزمن."],"سؤال ٦: سرعة جسم بدأ من السكون (صفحة 48) (تابع)":["كل ثانية تزيد السرعة بمقدار التسارع، فنضرب التسارع في عدد الثواني ونضيفه إلى السرعة الابتدائية التي هي صفر هنا.","سيارة بدأت من السكون بتسارع `2.5 m/s²` لمدة `8 s`: `Vf = 0 + 2.5 × 8 = 20 m/s`.","لأن `Vf = Vi + a·t` مأخوذ مباشرة من تعريف التسارع `a = (Vf − Vi) / t` بعد ضرب الطرفين في الزمن ونقل `Vi`."],"سؤال ١: عرّف كلًّا من: القوة، الوزن، قوة الاحتكاك (صفحة 49)":["القوة دفع أو سحب، مثل دفع عربة التسوق. والوزن هو سحب الأرض للجسم نحو الأسفل. والاحتكاك هو ما يجعل الصندوق صعب الجر على الأرض لأنه يعاكس الحركة.","حقيبة كتلتها `5 kg` وزنها `W = 5 × 9.8 = 49 N`، وإذا جررتها على أرض أفقية معامل احتكاكها الحركي `0.3` فإن `fk = 0.3 × 49 = 14.7 N`.","لأن كلا منها يغير حركة الجسم أو يعيقها، ولها مقدار واتجاه فهي متجهة ووحدتها النيوتن. والاحتكاك يعاكس الحركة لأن السطحين المتلامسين يعيق أحدهما انزلاق الآخر."],"سؤال ٢: ما الفرق بين الكتلة والوزن؟ (صفحة 49)":["الكتلة هي كمية المادة في الجسم وتبقى ثابتة أينما ذهب. أما الوزن فهو قوة سحب الجاذبية له، فلو ذهب إلى القمر بقيت كتلته كما هي لكن وزنه يقل.","رائد كتلته `70 kg`: وزنه على الأرض `70 × 9.8 = 686 N`، وعلى القمر حيث `g = 1.6 m/s²` وزنه `70 × 1.6 = 112 N`، وكتلته تبقى `70 kg`.","لأن الوزن يحسب من `W = m·g`، والكتلة ثابتة لكن `g` تتغير من مكان لآخر فيتغير الوزن. والوزن قوة لها اتجاه نحو مركز الأرض فهو متجه، أما الكتلة فمقدار فقط."],"سؤال ٣: القوة المؤثرة على جسم (صفحة 49)":["نريد معرفة القوة التي تجعل جسما معينا يتسارع بمعدل معين. المعطيات كتلة وتسارع، والمطلوب قوة بالنيوتن.","صندوق كتلته `6 kg` يتسارع بمعدل `4 m/s²`: `F = m·a = 6 × 4 = 24 N`.","لأن قانون نيوتن الثاني يربط القوة بالكتلة والتسارع، فوجود الكتلة والتسارع في المعطيات يدل على استخدامه مباشرة."],"سؤال ٣: القوة المؤثرة على جسم (صفحة 49) (تابع)":["نضرب الكتلة في التسارع فتخرج القوة. كلما كان الجسم أثقل أو أردنا تسارعا أكبر احتجنا قوة أكبر.","عربة كتلتها `15 kg` تتسارع بمعدل `3 m/s²`: `F = 15 × 3 = 45 N`.","لأن القوة المحصلة هي سبب التسارع، والتسارع يتناسب طرديا مع القوة وعكسيا مع الكتلة، ووحدة النيوتن تساوي `kg·m/s²`."],"سؤال ٤: تسارع سيارة (صفحة 49)":["لدينا قوة كبيرة تدفع سيارة ثقيلة، والسؤال: كم تتسارع؟ المعطيات قوة وكتلة، والمطلوب تسارع.","شاحنة كتلتها `5000 kg` تؤثر عليها قوة `20000 N`: `a = 20000 ÷ 5000 = 4 m/s²`.","لأن القانون `F = m·a` يحتوي القوة والكتلة والتسارع معا، فإذا عرفنا اثنتين منها وجدنا الثالثة."],"سؤال ٤: تسارع سيارة (صفحة 49) (تابع)":["نعوض في القانون ثم نقسم القوة على الكتلة لنعزل التسارع.","سيارة كتلتها `1500 kg` تؤثر عليها قوة `4500 N`: `a = 4500 ÷ 1500 = 3 m/s²`.","لأن التسارع مضروب في الكتلة، ولعزله نقسم الطرفين على الكتلة فنحصل على `a = F ÷ m`."],"سؤال ٥: كتلة جسم (صفحة 50)":["هنا نعرف القوة والتسارع ونريد الكتلة. الجسم الذي يحتاج قوة كبيرة ليتسارع قليلا تكون كتلته كبيرة.","قوة `84 N` أكسبت جسما تسارعا `3 m/s²`: `m = 84 ÷ 3 = 28 kg`.","لأن الكتلة مقياس لممانعة الجسم لتغيير حركته، فنحسبها بقسمة القوة على التسارع الذي أحدثته."],"سؤال ٥: كتلة جسم (صفحة 50) (تابع)":["نعوض القوة والتسارع في `F = m·a`، ثم نقسم القوة على التسارع لنجد الكتلة.","قوة `120 N` أكسبت جسما تسارعا `4 m/s²`: `m = 120 ÷ 4 = 30 kg`.","لأن الكتلة مضروبة في التسارع، فلعزلها نقسم الطرفين على التسارع، وتخرج الوحدة `N ÷ m/s² = kg`."],"سؤال ٦: وزن جسم (صفحة 50)":["الوزن هو قوة سحب الأرض للجسم. نعرف الكتلة، ونعرف أن تسارع الجاذبية على الأرض `9.8 m/s²`.","حقيبة كتلتها `15 kg` وزنها `W = 15 × 9.8 = 147 N`.","لأن الوزن حالة خاصة من قانون نيوتن الثاني، فالقوة هي جاذبية الأرض والتسارع هو تسارع الجاذبية `g`."],"سؤال ٦: وزن جسم (صفحة 50) (تابع)":["نضرب الكتلة في `9.8` فنحصل على الوزن بالنيوتن.","شخص كتلته `60 kg`: `W = 60 × 9.8 = 588 N`.","لأن كل كيلوجرام على سطح الأرض تسحبه الجاذبية بقوة مقدارها `9.8 N` تقريبا، فنضرب عدد الكيلوجرامات في هذا المقدار."],"سؤال ٧: قوة الاحتكاك (صفحة 50)":["صندوق ينزلق على طاولة، والطاولة تعيق انزلاقه بقوة احتكاك. وعلى السطح الأفقي تساوي القوة العمودية وزن الصندوق.","صندوق وزنه `50 N` ينزلق على أرض أفقية معامل احتكاكها الحركي `0.2`: `N = 50 N` و `fk = 0.2 × 50 = 10 N`.","لأن السطح الأفقي يدفع الصندوق للأعلى بقوة تساوي وزنه حتى لا يتحرك رأسيا، فتكون القوة العمودية مساوية للوزن."],"سؤال ٧: قوة الاحتكاك (صفحة 50) (تابع)":["نضرب معامل الاحتكاك في القوة العمودية. والمعامل الصغير يعني سطحا أملس وقوة احتكاك صغيرة.","صندوق قوته العمودية `80 N` ومعامل احتكاكه الحركي `0.25`: `fk = 0.25 × 80 = 20 N`.","لأن قوة الاحتكاك تزداد كلما ضغط الجسم على السطح أكثر، فتتناسب طرديا مع القوة العمودية، ومعامل الاحتكاك يصف خشونة السطحين."],"سؤال ٨: معامل الاحتكاك الحركي (صفحة 51)":["هنا نعرف قوة الاحتكاك والقوة العمودية، ونريد معامل الاحتكاك الذي يصف مدى خشونة السطحين.","قوة عمودية `40 N` وقوة احتكاك حركي `12 N`: `μk = 12 ÷ 40 = 0.3`.","لأن معامل الاحتكاك نسبة بين قوة الاحتكاك والقوة العمودية، فهو يصف السطحين ولا يعتمد على وزن الجسم."],"سؤال ٨: معامل الاحتكاك الحركي (صفحة 51) (تابع)":["نقسم قوة الاحتكاك على القوة العمودية، فيخرج عدد بلا وحدة.","قوة احتكاك `6 N` وقوة عمودية `30 N`: `μk = 6 ÷ 30 = 0.2`.","لأن معامل الاحتكاك ناتج قسمة قوة على قوة، فتختصر وحدة النيوتن من البسط والمقام ويبقى عددا بلا وحدة."],"سؤال ٩: هل يتحرك الصندوق؟ (صفحة 51)":["الصندوق الساكن يقاوم الدفع بالاحتكاك السكوني، لكن لهذه المقاومة حدا أقصى. إذا تجاوز الدفع هذا الحد بدأ الصندوق بالحركة.","صندوق كتلته `5 kg` ومعامل احتكاكه السكوني `0.4` دفع بقوة `15 N`: `fs(max) = 0.4 × 5 × 9.8 = 19.6 N`، والدفع أقل منها فلا يتحرك.","لأن الاحتكاك السكوني يزيد ليساوي قوة الدفع حتى يصل إلى قيمته القصوى، فالمقارنة بين الدفع وهذه القيمة تحدد هل يتحرك الجسم أم لا."],"سؤال ٩: هل يتحرك الصندوق؟ (صفحة 51) (تابع)":["نحسب أولا القوة العمودية من الوزن، ثم أقصى احتكاك سكوني، ثم نقارنه بقوة الدفع. فإذا كان الدفع أكبر انزلق الصندوق.","صندوق كتلته `3 kg` ومعامل احتكاكه السكوني `0.5` دفع بقوة `20 N`: `N = 3 × 9.8 = 29.4 N` و `fs(max) = 0.5 × 29.4 = 14.7 N`، والدفع أكبر فيتحرك.","لأن الجسم يبقى ساكنا ما دام الاحتكاك قادرا على موازنة الدفع، فإذا زاد الدفع على أقصى احتكاك سكوني صارت المحصلة غير صفرية فيتسارع الجسم."]},"1-7":{"":["الشغل يعني أن قوة حركت جسما. إذا دفعت عربة فتحركت فقد بذلت شغلا، أما إذا دفعت جدارا ولم يتحرك فلا شغل مهما تعبت.","دفعت عربة بقوة أفقية `25 N` فتحركت `4 m` في اتجاه الدفع: `W = 25 × 4 × cos 0° = 100 J`.","لأن الشغل في الفيزياء يقيس أثر القوة في نقل الجسم، فهو يعتمد على القوة والإزاحة معا، وعلى جزء القوة الذي يعمل في اتجاه الحركة."],"تعريف الشغل":["الشغل هو القوة مضروبة في المسافة التي تحركها الجسم في اتجاهها، كأنك تحسب كم دفعت وإلى أي مدى أوصلت الجسم.","صندوق دفع بقوة `40 N` في اتجاه حركته مسافة `6 m`: `W = F·x = 40 × 6 = 240 J`.","لأن القوة لا تنقل الجسم إلا بالجزء منها الذي في اتجاه الإزاحة، فإذا كانت القوة كلها في اتجاه الحركة كان الشغل حاصل ضرب القوة في الإزاحة مباشرة."],"تعريف الشغل (تابع)":["إذا سحبت شيئا بحبل مائل فجزء من سحبك فقط يحركه للأمام، والجزء الآخر يرفعه للأعلى. لذلك نضرب في `cos θ` لنأخذ الجزء المفيد فقط.","قوة `60 N` بزاوية `60°` مع الإزاحة، والإزاحة `5 m`: `W = 60 × 5 × cos 60° = 60 × 5 × 0.5 = 150 J`.","لأن `F·cos θ` هي مركبة القوة في اتجاه الإزاحة، وهي وحدها التي تبذل شغلا. والشغل ناتج ضرب مقادير فهو قياسي بلا اتجاه، ووحدته `N·m` وتسمى الجول."],"حالات مهمة":["إذا لم يتحرك الجسم فلا شغل، وإذا كانت القوة عمودية على الحركة فلا شغل أيضا. وإذا كانت القوة تعاكس الحركة مثل الاحتكاك فالشغل سالب لأنها تعيق الحركة.","صندوق ينزلق `4 m` وقوة الاحتكاك عليه `5 N`: `W = 5 × 4 × cos 180° = 5 × 4 × (−1) = −20 J`.","لأن `cos 90° = 0` فينعدم شغل القوة العمودية، و `cos 180° = −1` فيصبح شغل القوة المعاكسة سالبا، وإذا كانت `x = 0` كان حاصل الضرب صفرا."],"أمثلة الحقيبة التدريبية محلولة":["القوة تدفع الجسم في اتجاه حركته نفسه، لذلك الزاوية صفر. نكتب القوة والإزاحة والزاوية، والمطلوب الشغل بالجول.","قوة `20 N` أزاحت جسما `150 m` في اتجاهها: `W = 20 × 150 × cos 0° = 3000 J`.","لأن القوة في اتجاه الحركة تماما، فالزاوية بينهما `0°`، وهذا يعني أن القوة كلها تبذل شغلا."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نضرب القوة في الإزاحة، و `cos 0°` يساوي واحدا فلا يغير الناتج.","قوة `80 N` أزاحت جسما `25 m` في اتجاهها: `W = 80 × 25 × 1 = 2000 J`.","لأن `cos 0° = 1`، فعندما تكون القوة في اتجاه الإزاحة يصبح القانون العام `W = F·x·cos θ` هو نفسه `W = F·x`."],"مثال ٢: شغل قوة مائلة بزاوية (صفحة 53)":["الحبل يسحب الصندوق مائلا للأعلى، لكن الصندوق يتحرك أفقيا فقط. والزاوية بين القوة واتجاه الحركة هي زاوية الحبل مع الأفقي.","صندوق سحب بقوة `80 N` بزاوية `60°` مع الأفقي وتحرك `10 m`: `W = 80 × 10 × cos 60° = 80 × 10 × 0.5 = 400 J`.","لأن الزاوية في القانون هي بين القوة والإزاحة، والإزاحة هنا أفقية، فتكون الزاوية مع الأفقي هي نفسها الزاوية المطلوبة."],"مثال ٢: شغل قوة مائلة بزاوية (صفحة 53) (تابع)":["نعوض القوة والإزاحة، ونضرب في `cos 60°` الذي يساوي نصفا، أي أن نصف القوة فقط يعمل في اتجاه الحركة.","قوة `120 N` بزاوية `60°` وإزاحة `5 m`: `W = 120 × 5 × 0.5 = 300 J`.","لأن مركبة القوة في اتجاه الحركة هي `F·cos 60°` أي نصف القوة، والمركبة الرأسية لا تبذل شغلا لأن الصندوق لا يتحرك رأسيا."],"مثال ٣: الشغل بمعلومية الكتلة والتسارع (صفحة 53)":["هنا لا نعرف القوة مباشرة، لكننا نعرف الكتلة والتسارع، ومن قانون نيوتن الثاني نستطيع إيجاد القوة أولا.","جسم كتلته `0.5 kg` يتسارع بمعدل `4 m/s²` ويتحرك `2 m`: `F = 0.5 × 4 = 2 N`، و `W = 2 × 2 × cos 0° = 4 J`.","لأن القانون `W = F·x·cos θ` يحتاج القوة، والقوة غير معطاة، لكن الكتلة والتسارع يحددانها من `F = m·a`."],"مثال ٣: الشغل بمعلومية الكتلة والتسارع (صفحة 53) (تابع)":["نحل على مرحلتين: نحسب القوة من الكتلة والتسارع، ثم نضرب القوة في الإزاحة لنجد الشغل.","جسم كتلته `3 kg` يتسارع بمعدل `2 m/s²` ويتحرك `5 m` في اتجاه القوة: `F = 3 × 2 = 6 N`، و `W = 6 × 5 = 30 J`.","لأن القوة المحصلة هي التي تسبب التسارع، فهي القوة نفسها التي تبذل الشغل على الجسم أثناء إزاحته."],"تطبيقات من الحياة":["عندما تجر حقيبة السفر بمقبض مائل فالجزء الأفقي من سحبك هو ما يحركها. وعندما تحمل صندوقا وتمشي فيداك ترفعانه للأعلى لكنه يتحرك أفقيا، فلا شغل لقوة الحمل.","رافعة في ميناء ترفع حاوية وزنها `20000 N` إلى ارتفاع `15 m`: `W = 20000 × 15 = 300000 J`.","لأن الشغل يحسب بمركبة القوة في اتجاه الحركة: في الحمل الأفقي الزاوية `90°` و `cos 90° = 0`، وفي الرافعة القوة الرأسية في اتجاه الارتفاع نفسه."],"تمرين 1 · ورقة عمل (٢) · سؤال ٢ (صفحة 58)":["القوة في اتجاه الإزاحة نفسه، فالمسألة مباشرة: لدينا قوة وإزاحة والمطلوب الشغل.","قوة `45 N` أزاحت جسما `20 m` في اتجاهها: `W = 45 × 20 = 900 J`.","لأن عبارة في اتجاهها تعني أن الزاوية `0°`، فلا نحتاج إلى `cos θ` ونستخدم `W = F·x` مباشرة."],"تمرين 1 · ورقة عمل (٢) · سؤال ٢ (صفحة 58) (تابع)":["نضرب القوة في الإزاحة فنحصل على الشغل بالجول.","قوة `12 N` أزاحت جسما `250 m` في اتجاهها: `W = 12 × 250 = 3000 J`.","لأن الجول هو `N·m`، فضرب قوة بالنيوتن في إزاحة بالمتر يعطي الشغل بالجول مباشرة."],"تمرين 2 · ورقة عمل (٢) · سؤال ٣ (صفحة 58)":["الرجل تعب ودفع بقوة كبيرة، لكن الجسم بقي في مكانه. وفي الفيزياء التعب وحده لا يعني شغلا.","متدرب دفع خزانة بقوة `350 N` دقيقة كاملة دون أن تتحرك: `x = 0`، إذن `W = 350 × 0 = 0 J`.","لأن الشغل هو القوة مضروبة في الإزاحة، فإذا كانت الإزاحة صفرا صار الشغل صفرا مهما كبرت القوة."],"تمرين 2 · ورقة عمل (٢) · سؤال ٣ (صفحة 58) (تابع)":["أي عدد مضروب في صفر يساوي صفرا. لا توجد إزاحة، إذن لا يوجد شغل.","سيارة معطلة دفعها شخص بقوة `500 N` ولم تتحرك: `W = 500 × 0 × cos 0° = 0 J`.","لأن الشغل يقيس نقل القوة للجسم من مكان إلى آخر، وما دام موضع الجسم لم يتغير فلم تنقله القوة."],"تمرين 3 · تمارين الوحدة · اختر الإجابة ١٣ (صفحة 61)":["قوة أفقية تدفع عربة على أرض أفقية، فالقوة والحركة في الاتجاه نفسه.","قوة أفقية `15 N` أزاحت عربة `4 m`: `W = 15 × 4 × cos 0° = 60 J`.","لأن القوة أفقية والعربة تتحرك أفقيا في اتجاهها، فالزاوية بينهما `0°` وتبذل القوة كلها شغلا."],"تمرين 3 · تمارين الوحدة · اختر الإجابة ١٣ (صفحة 61) (تابع)":["نضرب القوة في الإزاحة في `cos 0°` الذي يساوي واحدا.","قوة `8 N` أزاحت عربة `7 m` في اتجاهها: `W = 8 × 7 × 1 = 56 J`.","لأن `cos 0° = 1`، فلا ينقص من القوة شيء عند حساب الشغل، ويكون الشغل أكبر ما يمكن لهذه القوة والإزاحة."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ١٤ (صفحة 62)":["القوة مائلة بزاوية مع الأفقي، والجسم يتحرك أفقيا، إذن جزء من القوة فقط يبذل شغلا.","قوة `30 N` تصنع `60°` مع الأفقي وأزاحت جسما `4 m`: `W = 30 × 4 × cos 60° = 30 × 4 × 0.5 = 60 J`.","لأن الزاوية بين القوة والإزاحة ليست صفرا، فنحتاج `cos θ` لنأخذ المركبة الأفقية للقوة فقط."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ١٤ (صفحة 62) (تابع)":["نضرب القوة في الإزاحة ثم في نصف، لأن `cos 60° = 0.5`.","قوة `90 N` بزاوية `60°` وإزاحة `2 m`: `W = 90 × 2 × 0.5 = 90 J`.","لأن مركبة القوة في اتجاه الحركة `F·cos 60°` تساوي نصف القوة، فيكون الشغل نصف ما لو كانت القوة أفقية تماما."]},"1-8":{"":["الطاقة هي قدرة الجسم على إنجاز شغل. الكرة المتحركة لها طاقة حركية بسبب سرعتها، والحجر المرفوع له طاقة وضع بسبب ارتفاعه.","كرة كتلتها `2 kg` على ارتفاع `4 m` وتتحرك بسرعة `3 m/s`: `PE = 2 × 9.8 × 4 = 78.4 J`، و `KE = 2 × 3²/2 = 9 J`.","لأن الجسم المتحرك يستطيع دفع جسم آخر وتحريكه، والجسم المرتفع يستطيع السقوط وبذل شغل، فكلاهما يملك قدرة على إنجاز شغل، وهذا معنى الطاقة."],"الطاقة":["الطاقة مثل رصيد يمكنك أن تصرفه في إنجاز شغل. ولها صور كثيرة: ميكانيكية بنوعيها الحركية والكامنة، وكهربائية، وحرارية.","مروحة كهربائية تحول الطاقة الكهربائية إلى طاقة حركية في شفراتها، ويتحول جزء منها إلى طاقة حرارية في المحرك.","لأن الطاقة تعرف بقدرتها على إنجاز شغل، والشغل يمكن أن ينتج من الحركة أو الارتفاع أو الكهرباء أو الحرارة، فتتعدد صورها والمعنى واحد."],"الطاقة (تابع)":["من صور الطاقة أيضا: الكيميائية المخزنة في الوقود والطعام، والنووية في أنوية الذرات، والشمسية القادمة من الشمس. وكلها تقاس بالجول.","عند تشغيل الهاتف تتحول الطاقة الكيميائية في بطاريته إلى طاقة كهربائية، ثم إلى ضوء وصوت وحرارة، وكل ذلك يقاس بالجول `J`.","لأن الطاقة قدرة على إنجاز شغل، فهي تقاس بوحدة الشغل نفسها وهي الجول `J = N·m`."],"أولا: الطاقة الحركية":["كل جسم يتحرك يملك طاقة حركية، وكلما كان أثقل أو أسرع كانت طاقته أكبر. والسرعة أكثر تأثيرا لأنها مربعة في القانون.","كرة كتلتها `0.5 kg` تتحرك بسرعة `4 m/s`: `KE = 0.5 × 4²/2 = 4 J`. وإذا تضاعفت سرعتها إلى `8 m/s` تصبح `KE = 0.5 × 8²/2 = 16 J`.","لأن السرعة في القانون مربعة، فمضاعفة السرعة تضرب الطاقة في `2² = 4`، بينما مضاعفة الكتلة تضاعف الطاقة مرتين فقط."],"ثانيا: الطاقة الكامنة (الوضع)":["الجسم المرفوع يخزن طاقة بسبب ارتفاعه، مثل كتاب على رف عال. وكلما زاد الارتفاع أو الكتلة زادت هذه الطاقة المخزنة.","كتاب كتلته `1.5 kg` على رف ارتفاعه `2 m`: `PE = 1.5 × 9.8 × 2 = 29.4 J`.","لأن رفع الجسم ضد الجاذبية يحتاج شغلا يساوي وزنه مضروبا في الارتفاع `m·g·h`، وهذا الشغل يخزن في الجسم طاقة وضع يمكن أن يعيدها عند سقوطه."],"أمثلة الحقيبة التدريبية محلولة":["جسم يتحرك ونعرف كتلته وسرعته، والمطلوب طاقته الحركية بالجول.","جسم كتلته `30 kg` يتحرك بسرعة `6 m/s`: `KE = 30 × 6²/2 = 30 × 36/2 = 540 J`.","لأن الطاقة الحركية تعتمد على الكتلة والسرعة فقط، فإذا عرفناهما حسبناها مباشرة من `KE = mv²/2`."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نربع السرعة أولا، ثم نضربها في الكتلة، ثم نقسم الناتج على 2.","جسم كتلته `40 kg` يتحرك بسرعة `11 m/s`: `KE = 40 × 11²/2 = 40 × 121/2 = 2420 J`.","لأن التربيع يخص السرعة وحدها، فلو ضربنا الكتلة في السرعة أولا ثم ربعنا الناتج لربعنا الكتلة أيضا وأخطأنا."],"مثال ٢: كتلة كرة بمعلومية طاقتها الحركية (صفحة 55)":["هذه المرة نعرف الطاقة الحركية والسرعة ونريد الكتلة، فنستخدم القانون نفسه لكن نبحث عن مجهول مختلف.","كرة سرعتها `2 m/s` وطاقتها الحركية `10 J`: `10 = m × 2²/2`، أي `20 = 4 × m`، إذن `m = 5 kg`.","لأن القانون `KE = mv²/2` يربط ثلاث كميات، فإذا عرفنا اثنتين منها وجدنا الثالثة بإعادة ترتيبه."],"مثال ٢: كتلة كرة بمعلومية طاقتها الحركية (صفحة 55) (تابع)":["نضرب الطاقة في 2 للتخلص من القسمة، ثم نقسم على مربع السرعة لنجد الكتلة.","كرة سرعتها `4 m/s` وطاقتها الحركية `24 J`: `48 = 16 × m`، إذن `m = 48 ÷ 16 = 3 kg`.","لأن إعادة ترتيب القانون تعطي `m = 2·KE / v²`، فنعزل الكتلة بخطوات جبرية دون تغيير معنى القانون."],"مثال ٣: طاقة الوضع لجسم على ارتفاع (صفحة 56)":["جسم موضوع على حافة مرتفعة، فهو يخزن طاقة بسبب ارتفاعه. ونعرف الكتلة والارتفاع و `g`.","صندوق كتلته `4 kg` على رف ارتفاعه `2.5 m`: `PE = 4 × 9.8 × 2.5 = 98 J`.","لأن طاقة الوضع تقاس من مستوى الإسناد، والارتفاع المعطى هو بعد الجسم عن هذا المستوى، فنعوض به مباشرة."],"مثال ٣: طاقة الوضع لجسم على ارتفاع (صفحة 56) (تابع)":["نضرب الكتلة في `9.8` ثم في الارتفاع فنحصل على طاقة الوضع بالجول.","جسم كتلته `10 kg` على ارتفاع `6 m`: `PE = 10 × 9.8 × 6 = 588 J`.","لأن `m·g` هو وزن الجسم بالنيوتن، وضربه في الارتفاع بالمتر يعطي `N·m` أي جول."],"الطاقة الحركية وطاقة الوضع":["الطاقة الحركية سببها الحركة وتنعدم عندما يقف الجسم، وطاقة الوضع سببها الارتفاع وتنعدم عند المستوى المرجعي. ومجموعهما هو الطاقة الميكانيكية.","طائر كتلته `0.4 kg` يطير على ارتفاع `10 m` بسرعة `5 m/s`: `PE = 0.4 × 9.8 × 10 = 39.2 J`، و `KE = 0.4 × 5²/2 = 5 J`، و `ME = 44.2 J`.","لأن الطاقة الحركية تتناسب مع مربع السرعة فتصبح 4 أمثالها بمضاعفة السرعة، أما طاقة الوضع فتتناسب طرديا مع الارتفاع فتتضاعف مرتين فقط بمضاعفته."],"تطبيقات من الحياة":["الماء المحجوز خلف السد مرتفع فيخزن طاقة وضع، وعند نزوله يدير التوربينات فتنتج الكهرباء. والسيارة المسرعة تحمل طاقة حركية كبيرة تظهر في شدة الاصطدام.","سيارة كتلتها `1200 kg`: عند `10 m/s` تكون `KE = 1200 × 10²/2 = 60000 J`، وعند `20 m/s` تصبح `KE = 240000 J`، أي 4 أمثالها.","لأن طاقة الوضع للماء تتحول عند نزوله إلى طاقة حركية تدير التوربينات، ولأن الطاقة الحركية تتناسب مع مربع السرعة فإن زيادة قليلة في السرعة تزيد طاقة الاصطدام كثيرا."],"تمرين 1 · ورقة عمل (٢) · سؤال ٤ (صفحة 59)":["جسم يتحرك بكتلة وسرعة معلومتين، والمطلوب طاقته الحركية.","جسم كتلته `12 kg` يتحرك بسرعة `5 m/s`: `KE = 12 × 5²/2 = 150 J`.","لأن الجسم متحرك، فطاقته المطلوبة هي الطاقة الحركية، وهي تعتمد على كتلته وسرعته فقط."],"تمرين 1 · ورقة عمل (٢) · سؤال ٤ (صفحة 59) (تابع)":["نربع السرعة، ثم نضربها في الكتلة، ثم نقسم على 2.","جسم كتلته `6 kg` سرعته `8 m/s`: `KE = 6 × 8²/2 = 6 × 64/2 = 192 J`.","لأن القانون يحتوي `v²` لا `v`، فإهمال التربيع يعطي ناتجا خاطئا، والقسمة على 2 جزء أصيل من القانون."],"تمرين 2 · ورقة عمل (٢) · سؤال ٥ (صفحة 59)":["جسم ساكن على ارتفاع معين، والمطلوب الطاقة المخزنة فيه بسبب ارتفاعه.","جسم كتلته `3 kg` على ارتفاع `4 m`: `PE = 3 × 9.8 × 4 = 117.6 J`.","لأن الجسم مرتفع عن مستوى الإسناد، فطاقته المطلوبة هي طاقة الوضع، وتعتمد على الكتلة والارتفاع و `g`."],"تمرين 2 · ورقة عمل (٢) · سؤال ٥ (صفحة 59) (تابع)":["نضرب الكتلة في `g` ثم في الارتفاع.","جسم كتلته `7 kg` على ارتفاع `2 m`: `PE = 7 × 9.8 × 2 = 137.2 J`.","لأن طاقة الوضع تساوي الشغل المبذول لرفع الجسم بسرعة ثابتة، وهو الوزن `m·g` مضروبا في الارتفاع `h`."],"تمرين 3 · تمارين الوحدة · اختر الإجابة ١٩ (صفحة 62)":["جسم متحرك نعرف كتلته وسرعته، ونريد طاقته الحركية.","جسم كتلته `4 kg` يتحرك بسرعة `6 m/s`: `KE = 4 × 6²/2 = 72 J`.","لأن الطاقة الحركية مرتبطة بحركة الجسم، فالكتلة والسرعة هما كل ما نحتاجه لحسابها."],"تمرين 3 · تمارين الوحدة · اختر الإجابة ١٩ (صفحة 62) (تابع)":["نربع السرعة أولا، ثم نضرب في الكتلة ونقسم على 2.","جسم كتلته `10 kg` سرعته `3 m/s`: `KE = 10 × 3²/2 = 10 × 9/2 = 45 J`.","لأن السرعة مربعة في القانون، والخطأ الشائع أن نضرب في السرعة دون تربيع فنحصل على ناتج خاطئ."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ٢٠ (صفحة 62)":["جسم موضوع على ارتفاع، نعرف كتلته وارتفاعه و `g = 9.8 m/s²`، والمطلوب طاقة وضعه.","جسم كتلته `20 kg` على ارتفاع `1.5 m`: `PE = 20 × 9.8 × 1.5 = 294 J`.","لأن طاقة الوضع تزداد بزيادة الكتلة والارتفاع، وتسارع الجاذبية ثابت قرب سطح الأرض."],"تمرين 4 · تمارين الوحدة · اختر الإجابة ٢٠ (صفحة 62) (تابع)":["نضرب الكتلة في `9.8` ثم في الارتفاع.","جسم كتلته `12 kg` على ارتفاع `5 m`: `PE = 12 × 9.8 × 5 = 588 J`.","لأن القانون `PE = m·g·h` حاصل ضرب ثلاث كميات، فإذا تضاعفت أي منها تضاعفت طاقة الوضع."]},"1-9":{"":["الطاقة لا تضيع ولا تخلق من لا شيء، بل تتحول من صورة إلى أخرى. فالكرة الساقطة تفقد طاقة وضع وتكسب طاقة حركية بالمقدار نفسه.","حجر كتلته `0.5 kg` سقط من ارتفاع `5 m` بإهمال الهواء: `PEi = 0.5 × 9.8 × 5 = 24.5 J`، فتكون طاقته الحركية عند الأرض `24.5 J` أيضا.","لأن النظام المعزول لا تؤثر عليه قوى خارجية مثل الاحتكاك ومقاومة الهواء، فلا تدخله طاقة ولا تخرج منه، فيبقى مجموع الطاقة الحركية وطاقة الوضع ثابتا."],"مبدأ قانون حفظ الطاقة":["تخيل مبلغا تنقله من جيب إلى جيب دون أن تصرف منه شيئا، فالمجموع لا يتغير. وكذلك الطاقة في النظام المعزول تنتقل بين صورها ومجموعها ثابت.","كرة طاقتها الميكانيكية في البداية `50 J`، وبعد حركتها في نظام معزول تبقى `50 J`، أي أن `ΔE = 50 − 50 = 0`.","لأن الطاقة لا تفنى ولا تستحدث من العدم، والنظام المعزول لا تدخله طاقة ولا تخرج منه، فلا يمكن أن يتغير مجموع طاقته."],"مبدأ قانون حفظ الطاقة (تابع)":["إذا زادت الطاقة الحركية في نظام معزول فلا بد أن تنقص طاقة الوضع بالمقدار نفسه، فيكون مجموع التغيرين صفرا، كالميزان: ما تضيفه إلى كفة تأخذه من الأخرى.","جسم يسقط فتنقص طاقة وضعه `30 J` أي `ΔPE = −30 J`، فتزيد طاقته الحركية `ΔKE = +30 J`، والمجموع `ΔKE + ΔPE = 30 − 30 = 0`.","لأن التغير الكلي في طاقة النظام المعزول صفر، وطاقته الميكانيكية مكونة من حركية ووضع فقط، فأي زيادة في إحداهما يقابلها نقص مساو في الأخرى."],"الطاقة الميكانيكية لنظام محفوظ":["الطاقة الميكانيكية هي حاصل جمع الطاقة الحركية وطاقة الوضع. وفي النظام المعزول يبقى هذا المجموع نفسه في البداية والنهاية، حتى لو تغيرت كل طاقة وحدها.","كرة في البداية `KEi = 10 J` و `PEi = 40 J`، وفي النهاية `PEf = 15 J`: `KEf = 10 + 40 − 15 = 35 J`.","لأن الطاقة في النظام المعزول لا تفنى ولا تستحدث، فالطاقة الميكانيكية في النهاية تساوي الطاقة الميكانيكية في البداية `MEf = MEi`."],"الطاقة الميكانيكية لنظام محفوظ (تابع)":["الحرف `i` يعني لحظة البداية، والحرف `f` يعني لحظة النهاية. فنكتب طاقة كل لحظة وحدها ثم نساوي بين المجموعين.","جسم عند القمة `KEi = 0` و `PEi = 60 J`، وعند منتصف النزول `PEf = 30 J`، إذن `KEf = 60 − 30 = 30 J`، و `MEi = MEf = 60 J`.","لأن تحديد اللحظتين بوضوح يمنع الخلط بين قيم البداية والنهاية، والمقارنة بين اللحظتين هي أساس استخدام حفظ الطاقة."],"أمثلة الحقيبة التدريبية محلولة":["الجسم الساقط له طاقة حركية لأنه يتحرك، وطاقة وضع لأنه ما زال مرتفعا، والمطلوب مجموعهما.","جسم ساقط طاقته الحركية `25 J` وطاقة وضعه `40 J`: `ME = 25 + 40 = 65 J`.","لأن الجسم الساقط يتحرك وهو مرتفع في الوقت نفسه، فيملك النوعين معا، والطاقة الميكانيكية تجمعهما."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نجمع الطاقة الحركية وطاقة الوضع فنحصل على الطاقة الميكانيكية بالجول.","جسم طاقته الحركية `18 J` وطاقة وضعه `22 J`: `ME = 18 + 22 = 40 J`.","لأن الطاقتين تقاسان بالوحدة نفسها وهي الجول، فيمكن جمعهما مباشرة لإيجاد الطاقة الميكانيكية."],"مثال ٢: أعلى حائط يقفز عليه قط (صفحة 57)":["القط يركض فيملك طاقة حركية، وعندما يقفز تتحول هذه الطاقة إلى طاقة وضع. وعند أعلى نقطة يتوقف لحظيا فتكون كل طاقته طاقة وضع.","قط سرعته `4 m/s`: `4²/2 = 9.8 × h`، أي `8 = 9.8 × h`، إذن `h = 8 ÷ 9.8 ≈ 0.82 m`.","لأن الطاقة الحركية على الأرض تتحول كلها إلى طاقة وضع عند أعلى ارتفاع بإهمال الاحتكاك، فنساوي بينهما لنجد الارتفاع."],"مثال ٢: أعلى حائط يقفز عليه قط (صفحة 57) (تابع)":["نساوي الطاقة الحركية في البداية بطاقة الوضع في النهاية، ثم نقسم لنجد الارتفاع. والكتلة تظهر في الطرفين فتختصر.","قط كتلته `2 kg` سرعته `5 m/s`: `2 × 5²/2 = 2 × 9.8 × h`، أي `25 = 19.6 × h`، إذن `h ≈ 1.28 m`.","لأن الكتلة موجودة في `KE` و `PE` معا فتختصر من الطرفين، ولذلك لا يعتمد أقصى ارتفاع على الكتلة بل على السرعة و `g` فقط."],"تطبيقات من الحياة":["قطار الملاهي يصعد إلى القمة فيخزن طاقة وضع، ثم ينزل فتتحول إلى طاقة حركية ويسرع. والأرجوحة تبادل بين الطاقتين ذهابا وإيابا.","عربة أفعوانية كتلتها `500 kg` تبدأ من السكون على قمة ارتفاعها `20 m`: عند الأسفل بإهمال الاحتكاك `KE = 500 × 9.8 × 20 = 98000 J`.","لأن مجموع الطاقتين ثابت في غياب الاحتكاك، فكلما نقص الارتفاع زادت السرعة. وفي فرامل السيارات الكهربائية لا تفنى الطاقة الحركية بل تتحول إلى كهرباء تخزن في البطارية."],"تمرين 1 · ورقة عمل (٢) · سؤال ٦ (صفحة 59)":["الجسم الساقط يملك طاقتين في اللحظة نفسها: حركية ووضع، والمطلوب مجموعهما.","جسم ساقط طاقته الحركية `15 J` وطاقة وضعه `45 J`: `ME = 15 + 45 = 60 J`.","لأن الطاقة الميكانيكية هي مجموع الطاقة الحركية وطاقة الوضع، فتكفي معرفتهما لحسابها."],"تمرين 1 · ورقة عمل (٢) · سؤال ٦ (صفحة 59) (تابع)":["نجمع العددين فقط، لأن الطاقة الميكانيكية مجموع الطاقتين.","جسم طاقته الحركية `8 J` وطاقة وضعه `52 J`: `ME = 8 + 52 = 60 J`.","لأنه أثناء السقوط تنقص طاقة الوضع وتزيد الطاقة الحركية بالمقدار نفسه، فيبقى مجموعهما ثابتا في أي لحظة بإهمال مقاومة الهواء."]},"1-10":{"":["هذه الورقة تجمع أربعة قوانين: الشغل والطاقة الحركية وطاقة الوضع والطاقة الميكانيكية. في كل سؤال حدد المعطيات، واختر القانون، ثم عوض واحسب.","جسم كتلته `4 kg` يتحرك بسرعة `3 m/s` على ارتفاع `2 m`: `KE = 4 × 3²/2 = 18 J` و `PE = 4 × 9.8 × 2 = 78.4 J`، إذن `ME = 18 + 78.4 = 96.4 J`.","لأن الشغل طريقة لنقل الطاقة إلى الجسم، فكل هذه الكميات تقاس بالجول نفسه. ومعرفة صور الطاقة تسمح بحساب ما يكسبه الجسم بسبب حركته أو ارتفاعه."],"ما تحتاجه لحل ورقة العمل":["تحتاج أربع أدوات فقط: قانون الشغل، وقانون الطاقة الحركية للجسم المتحرك، وقانون طاقة الوضع للجسم المرتفع، ثم جمع الطاقتين. مثل صندوق عدة صغير تختار منه الأداة المناسبة لكل سؤال.","قوة `20 N` تسحب صندوقا مسافة `4 m` في اتجاهها: `W = 20 × 4 × cos 0° = 80 J`. ولو لم يتحرك الصندوق لكان `W = 0`.","لأن الشغل يحتاج إلى قوة وإزاحة معا، فإذا كانت الإزاحة صفرا كان الناتج صفرا مهما كبرت القوة. والطاقة الميكانيكية مجموع الطاقتين لأنهما صورتان لطاقة الجسم نفسه."],"حل ورقة العمل":["الشغل يحدث عندما تدفع شيئا فيتحرك في اتجاه دفعك، مثل دفع عربة التسوق. والطاقة هي المخزون الذي يمكنك من بذل هذا الشغل، وكلاهما يقاس بالجول.","عامل يدفع عربة بقوة `40 N` فتتحرك `5 m` في اتجاه القوة: `W = 40 × 5 × cos 0° = 200 J`، أي نقل إليها `200 J` من الطاقة.","يدخل `cos θ` في القانون لأن مركبة القوة في اتجاه الإزاحة فقط هي التي تبذل شغلا. والشغل والطاقة لهما الوحدة نفسها لأن الشغل نقل للطاقة."],"حل ورقة العمل (تابع)":["الطاقة الحركية طاقة يملكها الجسم لأنه يتحرك، مثل كرة مقذوفة. وطاقة الوضع طاقة مخزنة لأن الجسم مرتفع، مثل كتاب على رف عال يمكن أن يسقط.","كرة كتلتها `0.5 kg` سرعتها `4 m/s`: `KE = 0.5 × 4²/2 = 4 J`. وإذا وضعت على ارتفاع `2 m`: `PE = 0.5 × 9.8 × 2 = 9.8 J`.","الطاقة الحركية تتناسب مع مربع السرعة، فمضاعفة السرعة تضاعفها أربع مرات. وطاقة الوضع تتناسب مع الارتفاع لأن الجاذبية تبذل شغلا على الجسم عند سقوطه من هذا الارتفاع."],"سؤال ٢: شغل قوة (صفحة 58)":["عندنا قوة تدفع جسما مسافة في اتجاهها نفسه، والمطلوب الشغل. ولأن القوة والحركة في اتجاه واحد فالزاوية بينهما صفر.","قوة `25 N` تزيح جسما `80 m` في اتجاهها: `θ = 0°`، إذن `W = 25 × 80 × 1 = 2000 J`.","نكتب المعطيات أولا لأن كل رمز في القانون يجب أن يعرف بقيمته ووحدته. والزاوية هنا صفر لأنها الزاوية بين اتجاه القوة واتجاه الإزاحة، وهما متطابقان."],"سؤال ٢: شغل قوة (صفحة 58) (تابع)":["نضرب القوة في المسافة، ثم في `cos 0°` التي تساوي واحدا فلا تغير الناتج. فالشغل هنا مجرد حاصل ضرب القوة في المسافة.","قوة `15 N` تزيح جسما `40 m` في اتجاهها: `W = 15 × 40 × cos 0° = 15 × 40 × 1 = 600 J`.","لأن `cos 0° = 1`، فكل القوة تعمل في اتجاه الحركة ولا يضيع منها شيء. لذلك يكون الشغل أكبر ما يمكن عندما تكون القوة في اتجاه الإزاحة."],"سؤال ٣: رجل لم يستطع تحريك جسم (صفحة 58)":["رجل يدفع جسما ثقيلا بكل قوته لكنه لا يتحرك. هنا القوة موجودة، لكن الإزاحة صفر.","شخص يدفع جدارا بقوة `300 N` مدة دقيقة كاملة ولا يتحرك الجدار: `x = 0`، إذن `W = 300 × 0 × cos θ = 0 J`.","الشغل في الفيزياء يشترط حدوث إزاحة، فالقوة وحدها لا تكفي. والتعب الذي يشعر به الرجل لا يعني أنه بذل شغلا على الجسم."],"سؤال ٣: رجل لم يستطع تحريك جسم (صفحة 58) (تابع)":["أي عدد يضرب في صفر يساوي صفرا. فلأن الإزاحة صفر يصبح الشغل صفرا مهما كانت القوة.","رافع أثقال يمسك ثقلا ثابتا فوق رأسه بقوة `800 N` دون أن يتحرك الثقل: `W = 800 × 0 × cos θ = 0 J`.","لأن القانون `W = F·x·cos θ` حاصل ضرب، فإذا انعدم أحد العوامل انعدم الناتج. وانعدام الإزاحة يعني أن القوة لم تنقل طاقة إلى الجسم."],"سؤال ٤: الطاقة الحركية لجسم (صفحة 59)":["جسم يتحرك، فله طاقة حركية تعتمد على كتلته وسرعته. نجمع الكتلة والسرعة من نص السؤال أولا، ثم نحسب.","دراجة مع راكبها كتلتهما `60 kg` تسير بسرعة `4 m/s`: `KE = 60 × 4²/2 = 60 × 16/2 = 480 J`.","نحتاج الكتلة والسرعة فقط لأن الطاقة الحركية تعتمد عليهما وحدهما. ويجب أن تكون الكتلة بالكيلوجرام والسرعة بالمتر لكل ثانية ليخرج الناتج بالجول."],"سؤال ٤: الطاقة الحركية لجسم (صفحة 59) (تابع)":["نربع السرعة أولا، ثم نضربها في الكتلة، ثم نقسم على اثنين. ترتيب الخطوات مهم مثل خطوات وصفة طبخ.","جسم كتلته `20 kg` سرعته `6 m/s`: `KE = 20 × 6²/2 = 20 × 36/2 = 360 J`.","تربع السرعة لأن الطاقة الحركية تزداد بسرعة كبيرة مع زيادة السرعة، فمضاعفة السرعة تضاعف الطاقة أربع مرات. لذلك نسيان التربيع خطأ شائع يغير الناتج كثيرا."],"سؤال ٥: طاقة الوضع لجسم (صفحة 59)":["جسم موضوع على حافة مرتفعة يخزن طاقة بسبب ارتفاعه، مثل ماء خلف سد. نحتاج الكتلة والارتفاع وتسارع الجاذبية.","حقيبة كتلتها `3 kg` على رف ارتفاعه `2 m`: `PE = 3 × 9.8 × 2 = 58.8 J`.","يدخل تسارع الجاذبية `g` في القانون لأن الجاذبية هي التي تسحب الجسم إلى أسفل وتمنحه هذه الطاقة. ويقاس الارتفاع من مستوى الإسناد الذي نختاره."],"سؤال ٥: طاقة الوضع لجسم (صفحة 59) (تابع)":["نضرب الكتلة في `9.8` ثم في الارتفاع. كلما ارتفع الجسم أو زادت كتلته زادت طاقة وضعه.","جسم كتلته `4 kg` على ارتفاع `5 m`: `PE = 4 × 9.8 × 5 = 196 J`.","لأن طاقة الوضع تساوي الشغل اللازم لرفع الجسم ضد وزنه `m·g` مسافة `h`. لذلك تتناسب طرديا مع الكتلة والارتفاع."],"سؤال ٦: الطاقة الميكانيكية (صفحة 59)":["الجسم الساقط يملك طاقتين معا: حركية لأنه يتحرك، ووضع لأنه ما زال مرتفعا. والمطلوب مجموعهما.","كرة ساقطة طاقتها الحركية `25 J` وطاقة وضعها `35 J` في لحظة ما: `ME = 25 + 35 = 60 J`.","الطاقة الميكانيكية تجمع صورتي الطاقة المرتبطتين بحركة الجسم وموضعه. ونجمعهما مباشرة لأنهما من النوع نفسه وبالوحدة نفسها وهي الجول."],"سؤال ٦: الطاقة الميكانيكية (صفحة 59) (تابع)":["نجمع الطاقتين مثل جمع مبلغين في محفظتين. لا ضرب ولا تربيع، فقط جمع.","جسم طاقته الحركية `12 J` وطاقة وضعه `18 J`: `ME = 12 + 18 = 30 J`.","لأن الطاقة كمية قياسية ليس لها اتجاه، فتجمع جمعا عاديا. وأثناء السقوط تتحول طاقة الوضع إلى حركية بينما يبقى مجموعهما ثابتا إذا أهملنا مقاومة الهواء."]},"1-11":{"":["هذا الدرس مراجعة للوحدة الثانية كلها: الحركة وقوانين نيوتن والاحتكاك والشغل والطاقة. وفيه حل تمارين الكتاب سؤالا بسؤال لتثبيت طريقة الحل.","سيارة كتلتها `1000 kg` تبدأ من السكون بتسارع `2 m/s²` لمدة `5 s`: `Vf = 0 + 2 × 5 = 10 m/s`، والقوة `F = 1000 × 2 = 2000 N`، وطاقتها الحركية `KE = 1000 × 10²/2 = 50000 J`.","لأن موضوعات الوحدة مترابطة: القوة تسبب التسارع، والتسارع يغير السرعة، والسرعة تحدد الطاقة الحركية. فمراجعتها معا تبني صورة واحدة متكاملة."],"مراجعة الوحدة الثانية":["الوحدة لها أربعة أجزاء: وصف الحركة بالسرعة والتسارع، وأسبابها بقوانين نيوتن، والقوى مثل الوزن والاحتكاك، ثم الشغل والطاقة. كأنها قصة: ماذا يحدث، ولماذا، وكم يلزم من طاقة.","جسم كتلته `5 kg` على سطح أفقي خشن معامل احتكاكه الحركي `0.2`: الوزن `W = 5 × 9.8 = 49 N`، فتكون القوة العمودية `49 N`، والاحتكاك `fk = 0.2 × 49 = 9.8 N`.","لأن قوانين الحركة بتسارع ثابت مشتقة من تعريفي السرعة والتسارع. وقوانين نيوتن تفسر سبب التسارع، والشغل يربط القوة بتغير الطاقة."],"أخطاء شائعة":["ثلاثة أخطاء تتكرر: الخلط بين الكتلة والوزن، ونسيان أن القوة العمودية على الحركة لا تبذل شغلا، والخلط بين التسارع والسرعة. انتبه لها كما تنتبه لإشارات المرور.","شخص كتلته `70 kg`: وزنه `W = 70 × 9.8 = 686 N` وليس `70 N`. وإذا حمل حقيبة ومشى أفقيا `10 m` فشغل قوة حمله `W = F × 10 × cos 90° = 0`.","الكتلة كمية المادة ولا تتغير، أما الوزن فقوة تعتمد على الجاذبية. والقوة العمودية على الحركة لا تبذل شغلا لأن `cos 90° = 0`، فلا مركبة لها في اتجاه الإزاحة."],"تمارين الوحدة محلولة":["الحركة أن ينتقل الجسم من مكان إلى آخر خلال زمن، مثل سيارة تنتقل من بيتك إلى عملك. أما المسافة فطول الطريق، والإزاحة الفرق بين نقطة البداية ونقطة النهاية.","عداء يجري حول مضمار دائري طوله `400 m` ويعود إلى نقطة البداية: المسافة `400 m`، والإزاحة `0 m`، مع أنه تحرك فعلا.","نفرق بين المصطلحات لأن كل واحد يصف شيئا مختلفا: الحركة تصف الانتقال نفسه، والإزاحة كمية متجهة تهتم بالبداية والنهاية فقط، والمسافة كمية قياسية تقيس طول المسار كله."],"اختر الإجابة ٣: معادلة من معادلات الحركة (صفحة 60)":["معادلات الحركة تصف كيف تتغير سرعة الجسم وموضعه مع الزمن، ولا تذكر القوة أو الكتلة. لذلك نبحث عن المعادلة التي فيها سرعة وتسارع وزمن.","عداء يبدأ بسرعة `2 m/s` ويتسارع `1 m/s²` لمدة `4 s`: `Vf = 2 + 1 × 4 = 6 m/s`.","لأن `Vf = Vi + a·t` تأتي من تعريف التسارع: التغير في السرعة مقسوما على الزمن. أما المعادلتان الأخريان ففيهما الكتلة والقوة، فتنتميان إلى قوانين القوى."],"اختر الإجابة ٤: سرعة سيارة بعد زمن (صفحة 60)":["السيارة تبدأ بسرعة ما، ثم تزداد سرعتها بمقدار ثابت كل ثانية. نكتب ما نعرفه: السرعة الابتدائية والتسارع والزمن، والمطلوب السرعة النهائية.","دراجة سرعتها `4 m/s` تتسارع `1.5 m/s²` لمدة `6 s`: `Vf = 4 + 1.5 × 6 = 13 m/s`.","التسارع `2 m/s²` يعني أن السرعة تزيد `2 m/s` كل ثانية. لذلك نحتاج الزمن لنعرف كم مرة تتكرر هذه الزيادة."],"اختر الإجابة ٤: سرعة سيارة بعد زمن (صفحة 60) (تابع)":["نضرب التسارع في الزمن لنعرف مقدار الزيادة في السرعة، ثم نضيفها إلى السرعة الابتدائية. مثل حصالة فيها مبلغ تضيف إليه مبلغا ثابتا كل يوم.","سيارة سرعتها `12 m/s` تتسارع `3 m/s²` لمدة `5 s`: `Vf = 12 + 3 × 5 = 27 m/s`.","لأن التسارع ثابت، فالسرعة تزداد بالمقدار نفسه في كل ثانية. فالزيادة الكلية `a·t` تضاف إلى السرعة الابتدائية."],"اختر الإجابة ٥: مسافة جسم بدأ من السكون (صفحة 60)":["الجسم كان واقفا ثم بدأ يتحرك ويزيد سرعته. عبارة «من السكون» تعطينا معلومة مخفية: السرعة الابتدائية صفر.","قطار يبدأ من السكون بتسارع `2 m/s²` لمدة `10 s`: `Vi = 0`، و `x = ½ × 2 × 10² = 100 m`.","نختار قانونا يحتوي على `x` و `a` و `t` معا لأنها المعطيات والمطلوب. وكلمة السكون تعني أن الجسم لا يتحرك في البداية، فسرعته الابتدائية صفر."],"اختر الإجابة ٥: مسافة جسم بدأ من السكون (صفحة 60) (تابع)":["بما أن السرعة الابتدائية صفر يختفي الحد الأول، ويبقى نصف التسارع في مربع الزمن. ربع الزمن أولا ثم أكمل الضرب.","جسم يبدأ من السكون بتسارع `4 m/s²` لمدة `3 s`: `x = 0 + ½ × 4 × 3² = ½ × 4 × 9 = 18 m`.","الزمن مربع لأن السرعة تزداد مع الزمن، فالجسم يقطع في كل ثانية مسافة أكبر من التي قبلها. لذلك تنمو المسافة أسرع من نمو الزمن."],"اختر الإجابة ٦: المؤثر الذي يغير السرعة (صفحة 60)":["الشيء الذي يغير سرعة الجسم أو اتجاهه هو القوة، مثل ركلة تغير اتجاه كرة. فبدون قوة لا يتغير شيء في حركة الجسم.","ركلة تؤثر بقوة `60 N` على كرة كتلتها `0.4 kg` تكسبها تسارعا `a = 60 ÷ 0.4 = 150 m/s²`، فتتغير سرعتها.","حسب قانون نيوتن الثاني فإن القوة المحصلة تسبب تسارعا، والتسارع تغير في السرعة مقدارا أو اتجاها. أما الحركة والإزاحة فهما نتيجة لا مؤثر."],"اختر الإجابة ٧: بقاء الجسم على حالته (صفحة 60)":["الجسم لا يغير حالته وحده: إذا كان واقفا يبقى واقفا، وإذا كان يتحرك يستمر بالسرعة نفسها، حتى تجبره قوة على التغيير. مثل اندفاعك للأمام عند توقف الحافلة فجأة.","ركاب حافلة سرعتها `15 m/s` تتوقف فجأة: تميل أجسامهم إلى الاستمرار بسرعة `15 m/s` إلى الأمام، فيندفعون حتى يوقفهم حزام الأمان.","لأن تغيير السرعة يحتاج إلى تسارع، والتسارع يحتاج إلى قوة محصلة. فإذا انعدمت القوة المحصلة بقيت السرعة ثابتة، وهذه خاصية القصور الذاتي."],"اختر الإجابة ٨: تناسب القوة مع التسارع (صفحة 61)":["كلما دفعت العربة بقوة أكبر زادت سرعتها بشكل أسرع. هذا التناسب الطردي بين القوة والتسارع هو قانون نيوتن الثاني.","عربة كتلتها `10 kg`: قوة `20 N` تعطيها `a = 2 m/s²`، وقوة `40 N` تعطيها `a = 4 m/s²`. مضاعفة القوة ضاعفت التسارع.","في `F = m·a` إذا ثبتت الكتلة فالقوة تساوي عددا ثابتا مضروبا في التسارع. وهذا هو معنى التناسب الطردي."],"اختر الإجابة ٩: الفعل ورد الفعل (صفحة 61)":["عندما تدفع الحائط يدفعك الحائط بالقوة نفسها في الاتجاه المعاكس. القوى تأتي دائما في أزواج.","سباح يدفع الماء إلى الخلف بقوة `150 N`، فيدفعه الماء إلى الأمام بقوة `150 N`، ولذلك يتقدم.","لأن القوة تفاعل بين جسمين، فلا يمكن أن يؤثر جسم في آخر دون أن يتأثر به. لذلك `F_AB = −F_BA`، والإشارة السالبة تعني الاتجاه المعاكس."],"اختر الإجابة ١٠: القوة اللازمة لإكساب جسم تسارعًا (صفحة 61)":["نريد أن نعرف كم يجب أن ندفع جسما ساكنا ليتسارع بمقدار معين. نحتاج الكتلة والتسارع فقط.","صندوق كتلته `5 kg` نريد إكسابه تسارعا `2 m/s²`: نحتاج قوة `F = 5 × 2 = 10 N`.","كون الجسم ساكنا لا يغير القوة اللازمة، لأن قانون نيوتن الثاني يربط القوة بالتسارع لا بالسرعة. فالمهم كتلة الجسم والتسارع المطلوب."],"اختر الإجابة ١٠: القوة اللازمة لإكساب جسم تسارعًا (صفحة 61) (تابع)":["نضرب الكتلة في التسارع مباشرة فنحصل على القوة بالنيوتن. عملية ضرب واحدة فقط.","جسم كتلته `7 kg` وتسارعه `3 m/s²`: `F = 7 × 3 = 21 N`.","لأن النيوتن معرف بأنه القوة التي تكسب كتلة `1 kg` تسارعا `1 m/s²`. لذلك ضرب الكيلوجرام في `m/s²` يعطي النيوتن."],"اختر الإجابة ١١: تسارع سهم (صفحة 61)":["سهم خفيف تدفعه قوة كبيرة، والمطلوب تسارعه. القانون نفسه `F = m·a`، لكن المجهول هذه المرة هو التسارع.","كرة كتلتها `0.5 kg` تدفع بقوة `20 N`: `a = 20 ÷ 0.5 = 40 m/s²`.","الكتلة الصغيرة جدا للسهم تجعل تسارعه كبيرا، لأن التسارع يتناسب عكسيا مع الكتلة عند ثبات القوة."],"اختر الإجابة ١١: تسارع سهم (صفحة 61) (تابع)":["عوضنا بالقوة والكتلة، ثم قسمنا القوة على الكتلة لنعزل التسارع. القسمة على `0.25` تعني الضرب في 4.","سهم كتلته `0.2 kg` يطلق بقوة `30 N`: `a = 30 ÷ 0.2 = 150 m/s²`.","نقسم الطرفين على الكتلة لعزل `a`، وهذا ترتيب للقانون نفسه لا قانون جديد. والقسمة على عدد أصغر من واحد تكبر الناتج، فيظهر تسارع كبير."],"اختر الإجابة ١٢: صيغة قانون الشغل (صفحة 61)":["الشغل يعتمد على ثلاثة أشياء: قوة الدفع، والمسافة التي يتحركها الجسم، والزاوية بين اتجاه القوة واتجاه الحركة. كمن يسحب حقيبة بمقبض مائل.","حقيبة تسحب بقوة `40 N` بمقبض يميل `60°` مسافة `10 m`: `W = 40 × 10 × cos 60° = 40 × 10 × 0.5 = 200 J`.","لأن جزء القوة الذي في اتجاه الحركة فقط هو الذي ينقل الطاقة، وهذا الجزء يساوي `F·cos θ`. أما الجزء العمودي على الحركة فلا يبذل شغلا."],"اختر الإجابة ١٣: الشغل على عربة صغيرة (صفحة 61)":["قوة أفقية تدفع عربة على أرض أفقية، فالقوة والحركة في اتجاه واحد. لذلك الزاوية صفر.","طفل يدفع عربة لعبة بقوة `8 N` مسافة `4 m` أفقيا: `W = 8 × 4 × cos 0° = 32 J`.","كلمة «أفقية» هي المفتاح: العربة تتحرك أفقيا والقوة أفقية، فالزاوية بينهما صفر. وهذا يجعل `cos θ = 1`."],"اختر الإجابة ١٣: الشغل على عربة صغيرة (صفحة 61) (تابع)":["نضرب القوة في الإزاحة، و `cos 0°` يساوي واحدا فلا يغير شيئا. والناتج بالجول.","قوة أفقية `12 N` تحرك عربة `5 m`: `W = 12 × 5 × 1 = 60 J`.","عندما تكون الزاوية صفرا تعمل القوة كلها في اتجاه الحركة. لذلك يصبح الشغل حاصل ضرب القوة في الإزاحة مباشرة."],"اختر الإجابة ١٤: شغل قوة مائلة (صفحة 62)":["القوة هنا مائلة وليست أفقية، فجزء منها فقط يسحب الجسم إلى الأمام. لذلك لا نهمل الزاوية هذه المرة.","قوة `20 N` تصنع زاوية `60°` مع الأفقي وتحرك جسما `5 m`: `W = 20 × 5 × cos 60° = 20 × 5 × 0.5 = 50 J`.","الزاوية تؤخذ بين اتجاه القوة واتجاه الإزاحة، والجسم يتحرك أفقيا. فالزاوية مع الأفقي هي نفسها الزاوية المطلوبة في القانون."],"اختر الإجابة ١٤: شغل قوة مائلة (صفحة 62) (تابع)":["`cos 60°` يساوي نصفا، أي أن نصف القوة فقط يعمل في اتجاه الحركة. فالشغل نصف ما كان سيكون لو كانت القوة أفقية.","قوة `100 N` بزاوية `60°` تزيح جسما `2 m`: `W = 100 × 2 × 0.5 = 100 J`.","كلما زادت الزاوية قلت مركبة القوة في اتجاه الحركة، لأن `cos θ` يتناقص من 1 عند `0°` إلى صفر عند `90°`. لذلك الشغل هنا أقل من شغل القوة الأفقية."],"اختر الإجابة ١٥: القدرة على بذل شغل (صفحة 62)":["الطاقة مثل الوقود الذي يمكنك من العمل: من يملك طاقة يستطيع أن يبذل شغلا. لذلك تعرف الطاقة بأنها القدرة على بذل شغل.","جسم كتلته `2 kg` على ارتفاع `10 m` يملك طاقة وضع `PE = 2 × 9.8 × 10 = 196 J`، فيستطيع عند سقوطه أن يبذل شغلا يصل إلى `196 J`.","لأن بذل الشغل يعني نقل الطاقة من جسم إلى آخر. فالجسم الذي لا يملك طاقة لا يستطيع أن يبذل شغلا، ولذلك لهما الوحدة نفسها."],"اختر الإجابة ١٦: طاقة الحركة (صفحة 62)":["كل جسم يتحرك يملك طاقة بسبب حركته، مثل الكرة المتدحرجة التي تستطيع إسقاط القوارير. هذه هي الطاقة الحركية.","كرة بولينج كتلتها `6 kg` سرعتها `3 m/s`: `KE = 6 × 3²/2 = 27 J`.","لأن تحريك جسم من السكون يحتاج إلى شغل، وهذا الشغل يخزن في الجسم على صورة طاقة حركية. وإذا توقف الجسم تصبح طاقته الحركية صفرا."],"اختر الإجابة ١٧: صيغة الطاقة الحركية (صفحة 62)":["الطاقة الحركية نصف الكتلة مضروبا في مربع السرعة. فأثر السرعة أكبر من أثر الكتلة لأنها مربعة.","سيارة كتلتها `1000 kg`: عند `10 m/s` طاقتها `KE = 1000 × 10²/2 = 50000 J`، وعند `20 m/s` تصبح `200000 J`، أي أربعة أضعاف.","تأتي الصيغة من حساب الشغل اللازم لتسريع الجسم من السكون إلى السرعة `v`. ولأن المسافة اللازمة تزداد مع السرعة، يظهر مربع السرعة في الناتج."],"اختر الإجابة ١٨: صيغة طاقة الوضع (صفحة 62)":["طاقة الوضع هي الكتلة في تسارع الجاذبية في الارتفاع. كلما كان الجسم أثقل أو أعلى زادت طاقته المخزنة.","دلو ماء كتلته `10 kg` على ارتفاع `3 m`: `PE = 10 × 9.8 × 3 = 294 J`.","لرفع الجسم نحتاج قوة تساوي وزنه `m·g` نبذلها عبر الارتفاع `h`، فيكون الشغل `m·g·h`. وهذا الشغل يخزن في الجسم على صورة طاقة وضع."],"اختر الإجابة ١٩: طاقة حركية لجسم (صفحة 62)":["جسم كتلته معروفة وسرعته معروفة، والمطلوب طاقته الحركية. نحتاج فقط قانون `KE = mv²/2`.","جسم كتلته `10 kg` سرعته `4 m/s`: `KE = 10 × 4²/2 = 80 J`.","نكتب المعطيات بوحداتها لنتأكد أنها بوحدات SI، فالكتلة بالكيلوجرام والسرعة بالمتر لكل ثانية. عندها يخرج الناتج بالجول مباشرة."],"اختر الإجابة ١٩: طاقة حركية لجسم (صفحة 62) (تابع)":["نربع السرعة، ونقسم الكتلة على اثنين، ثم نضرب. يمكنك القسمة على 2 قبل الضرب أو بعده، والنتيجة واحدة.","جسم كتلته `6 kg` سرعته `5 m/s`: `KE = 6 × 5²/2 = 3 × 25 = 75 J`.","ترتيب الضرب والقسمة لا يغير الناتج، لذلك نقسم الكتلة على 2 أولا لتسهيل الحساب. لكن التربيع خاص بالسرعة وحدها، فلا نربع الكتلة."],"اختر الإجابة ٢٠: طاقة وضع لجسم مرتفع (صفحة 62)":["جسم مرفوع عن الأرض يخزن طاقة بسبب ارتفاعه. نحتاج كتلته وارتفاعه وقيمة `g`.","صندوق كتلته `12 kg` على ارتفاع `2 m`: `PE = 12 × 9.8 × 2 = 235.2 J`.","السؤال يعطي `g = 9.8 m/s²` لأنها قيمة تسارع الجاذبية قرب سطح الأرض. وطاقة الوضع تقاس نسبة إلى مستوى الإسناد وهو هنا سطح الأرض."],"اختر الإجابة ٢٠: طاقة وضع لجسم مرتفع (صفحة 62) (تابع)":["نضرب الأعداد الثلاثة: الكتلة ثم `9.8` ثم الارتفاع. ويمكن ضرب `15 × 3 = 45` أولا ثم الضرب في `9.8`.","جسم كتلته `10 kg` على ارتفاع `4 m`: `PE = 10 × 9.8 × 4 = 392 J`.","لأن طاقة الوضع تتناسب طرديا مع الكتلة والارتفاع، فمضاعفة أي منهما تضاعفها. وترتيب الضرب لا يغير الناتج."],"اختر الإجابة ٢١: تحول الطاقة (صفحة 63)":["الطاقة لا تختفي ولا تظهر من لا شيء، بل تنتقل من شكل إلى آخر. مثل المال الذي تحوله من عملة إلى أخرى دون أن يضيع.","كرة كتلتها `1 kg` تسقط من `5 m`: طاقة وضعها في الأعلى `PE = 1 × 9.8 × 5 = 49 J`، وقبيل الأرض تصبح طاقتها الحركية `49 J` إذا أهملنا مقاومة الهواء.","لأن الطاقة الكلية في نظام معزول ثابتة، فما ينقص من صورة يزيد في صورة أخرى. وهذا ما نلاحظه عندما تتحول طاقة الوضع إلى حركية أثناء السقوط."],"اختر الإجابة ٢٢: معنى تباطؤ الجسم (صفحة 63)":["التباطؤ يعني أن السرعة تقل، مثل سيارة يضغط سائقها على الفرامل. وفي المعادلات يظهر ذلك بتسارع سالب.","سيارة سرعتها `20 m/s` تقل إلى `8 m/s` خلال `4 s`: `a = (8 − 20) / 4 = −3 m/s²`.","التسارع هو `(Vf − Vi) / t`، فإذا كانت السرعة النهائية أقل من الابتدائية كان البسط سالبا. لذلك يكون التسارع في عكس اتجاه السرعة."],"اختر الإجابة ٢٣: تسارع جسم بدأ من السكون (صفحة 63)":["جسم كان واقفا ثم وصلت سرعته إلى قيمة معينة بعد زمن. المطلوب: كم زادت سرعته في كل ثانية.","دراجة تبدأ من السكون وتصل إلى `12 m/s` خلال `4 s`: `Vi = 0`، فيكون `a = (12 − 0) / 4 = 3 m/s²`.","عبارة «من حالة السكون» تعطينا `Vi = 0` دون أن تكتب صراحة. والتسارع يحتاج إلى السرعتين والزمن، فهي كل ما يلزم."],"اختر الإجابة ٢٣: تسارع جسم بدأ من السكون (صفحة 63) (تابع)":["نطرح السرعة الابتدائية من النهائية لنعرف التغير، ثم نقسم على الزمن. فنعرف كم تزيد السرعة كل ثانية.","سيارة تبدأ من السكون وتصل إلى `30 m/s` خلال `6 s`: `a = (30 − 0) / 6 = 5 m/s²`.","لأن التسارع معرف بأنه معدل تغير السرعة بالنسبة للزمن. ووحدته `m/s²` لأننا نقسم `m/s` على `s`."],"اختر الإجابة ٢٤: تعريف السرعة المتوسطة (صفحة 63)":["السرعة المتوسطة تخبرك بما قطعته في الثانية الواحدة في المتوسط خلال الرحلة كلها. فتقسم المسافة الكلية على الزمن الكلي.","قطار قطع `1500 m` في `60 s`: `v = 1500 / 60 = 25 m/s`.","لأن السرعة قد تتغير أثناء الرحلة، فنستبدلها بقيمة واحدة ثابتة تعطي المسافة نفسها في الزمن نفسه. وهذا يتحقق بقسمة المسافة الكلية على الزمن الكلي."],"اختر الإجابة ٢٥: وحدة التسارع (صفحة 63)":["التسارع يخبرك كم تتغير السرعة في كل ثانية. فوحدته وحدة السرعة مقسومة على الثانية.","سيارة تزيد سرعتها من `5 m/s` إلى `17 m/s` خلال `4 s`: `a = 12 ÷ 4 = 3 m/s²`، أي تزيد `3 m/s` كل ثانية.","لأن التسارع تغير في السرعة `m/s` مقسوم على زمن `s`، فتجتمع الثانيتان في المقام لتصبح `s²`."],"اختر الإجابة ٢٦: سرعة سيارة (صفحة 63)":["سيارة قطعت مسافة معروفة في زمن معروف، والمطلوب سرعتها المتوسطة. نحتاج قسمة واحدة فقط.","عداء قطع `100 m` في `20 s`: `v = 100 / 20 = 5 m/s`.","نحتاج المسافة والزمن فقط لأن السرعة المتوسطة تعرف بهما. ويجب أن تكون المسافة بالمتر والزمن بالثانية لتخرج السرعة بوحدة `m/s`."],"اختر الإجابة ٢٦: سرعة سيارة (صفحة 63) (تابع)":["نقسم المسافة على الزمن فنعرف كم مترا تقطع السيارة في كل ثانية في المتوسط.","حافلة قطعت `360 m` في `15 s`: `v = 360 / 15 = 24 m/s`.","القسمة تعطي نصيب الثانية الواحدة من المسافة الكلية. لذلك تقاس السرعة بالمتر لكل ثانية."],"اختر الإجابة ٢٩: مجموع القوى يساوي صفرًا (صفحة 64)":["إذا ألغت القوى المؤثرة على الجسم بعضها بعضا، كفريقين يشدان حبلا بالقوة نفسها، فلا يتغير شيء في حركته. وهذا ما يعبر عنه قانون نيوتن الأول.","كتاب وزنه `20 N` على طاولة تدفعه إلى أعلى بقوة `20 N`: `ΣF = 20 − 20 = 0`، فيبقى ساكنا.","لأن `ΣF = 0` تعني حسب `F = m·a` أن التسارع صفر. وبدون تسارع لا تتغير السرعة، فيبقى الجسم ساكنا أو متحركا بسرعة ثابتة."],"اختر الإجابة ٣٠: ممانعة الجسم لتغيير حالته (صفحة 64)":["كل جسم يقاوم تغيير حالته الحركية، فالكرة الساكنة لا تتحرك وحدها والمتحركة لا تتوقف وحدها. هذه الممانعة اسمها القصور الذاتي.","قوة `10 N` تعطي صندوقا فارغا كتلته `2 kg` تسارعا `5 m/s²`، وتعطي صندوقا ممتلئا كتلته `40 kg` تسارعا `0.25 m/s²` فقط، لأن قصوره الذاتي أكبر.","لأن تغيير السرعة يحتاج إلى قوة، والجسم لا يغير حالته من تلقاء نفسه. والكتلة مقياس هذا القصور، فكلما كبرت احتاج الجسم قوة أكبر لتغيير حالته."],"اختر الإجابة ٣١: القوة المحركة لسيارة (صفحة 64)":["سيارة ثقيلة تتسارع، والمطلوب القوة التي تحركها. نطبق قانون نيوتن الثاني مباشرة.","سيارة كتلتها `1500 kg` تتسارع `2 m/s²`: `F = 1500 × 2 = 3000 N`.","الكتلة كبيرة لذلك ستكون القوة كبيرة، فالقوة تتناسب طرديا مع الكتلة عند ثبات التسارع."],"اختر الإجابة ٣١: القوة المحركة لسيارة (صفحة 64) (تابع)":["نضرب الكتلة في التسارع فنحصل على القوة بالنيوتن. كلما كانت السيارة أثقل احتاجت قوة أكبر للتسارع نفسه.","سيارة كتلتها `1200 kg` تتسارع `2.5 m/s²`: `F = 1200 × 2.5 = 3000 N`.","لأن `F = m·a`، فكل كيلوجرام يحتاج إلى `3 N` ليتسارع `3 m/s²`. فالقوة الكلية `3 N` مضروبة في عدد الكيلوجرامات."],"اختر الإجابة ٣٢: اتجاه قوة الاحتكاك (صفحة 64)":["الاحتكاك يعمل دائما ضد الحركة، مثل أرض خشنة تبطئ صندوقا تسحبه. إذا سحبت الصندوق يمينا شده الاحتكاك يسارا.","صندوق يسحب يمينا بقوة `50 N` والاحتكاك `20 N` نحو اليسار: القوة المحصلة `ΣF = 50 − 20 = 30 N` نحو اليمين.","لأن الاحتكاك ينشأ من تلامس السطحين وخشونتهما، فيقاوم انزلاق أحدهما على الآخر. لذلك يكون دائما عكس اتجاه الحركة النسبية."],"اختر الإجابة ٣٣: قوة الاحتكاك بين الصلب والنحاس (صفحة 64)":["جسم ينزلق على سطح، وقوة الاحتكاك تعتمد على نوع السطحين وعلى مدى ضغط الجسم على السطح. نوع السطحين يمثله المعامل، والضغط تمثله القوة العمودية.","جسم خشبي على أرض معامل احتكاكها الحركي `0.4` والقوة العمودية `50 N`: `fk = 0.4 × 50 = 20 N`.","معامل الاحتكاك ليس له وحدة لأنه نسبة بين قوتين. وكلما زادت القوة العمودية زاد ضغط السطحين أحدهما على الآخر فزاد الاحتكاك."],"اختر الإجابة ٣٣: قوة الاحتكاك بين الصلب والنحاس (صفحة 64) (تابع)":["نضرب معامل الاحتكاك في القوة العمودية مباشرة. المعامل `0.3` يعني أن الاحتكاك يساوي `30%` من القوة العمودية.","معامل احتكاك `0.25` وقوة عمودية `80 N`: `fk = 0.25 × 80 = 20 N`.","لأن المعامل نسبة بلا وحدة، فوحدة الناتج هي وحدة القوة العمودية وهي النيوتن. وقوة الاحتكاك تتناسب طرديا مع القوة العمودية."],"صح وخطأ ١: تسارع جسم محصلة القوى عليه صفر (صفحة 65)":["إذا ألغت القوى بعضها بعضا فلا يوجد ما يغير سرعة الجسم، فالتسارع صفر لا موجب. لذلك العبارة خطأ.","جسم كتلته `4 kg` تؤثر عليه قوتان `10 N` يمينا و `10 N` يسارا: `ΣF = 0`، فيكون `a = 0 ÷ 4 = 0 m/s²`.","حسب قانون نيوتن الثاني `a = ΣF / m`، والتسارع ينتج فقط عن قوة محصلة. فإذا كانت المحصلة صفرا كان التسارع صفرا."],"صح وخطأ ٢: نص قانون نيوتن الثالث (صفحة 65)":["كل قوة تؤثر بها على جسم يرد عليك الجسم بقوة مساوية في المقدار ومعاكسة في الاتجاه. لذلك العبارة صحيحة.","تضغط قدماك على الأرض بقوة `600 N` إلى أسفل، فتدفع الأرض قدميك بقوة `600 N` إلى أعلى.","لأن القوة تفاعل بين جسمين، فالجسمان يتبادلان التأثير في اللحظة نفسها. ويؤثر الفعل ورد الفعل في جسمين مختلفين، لذلك لا يلغي أحدهما الآخر."],"صح وخطأ ٣: طاقة الوضع أثناء السقوط (صفحة 65)":["عند السقوط يقل الارتفاع، فتقل طاقة الوضع ولا تزيد. والطاقة المفقودة منها تظهر في زيادة سرعة الجسم.","كرة كتلتها `2 kg` تسقط من `10 m` إلى `4 m`: طاقة وضعها تقل من `196 J` إلى `78.4 J`، أي تتحول `117.6 J` إلى طاقة حركية.","لأن `PE = m·g·h` تتناسب طرديا مع الارتفاع، والكتلة و `g` ثابتتان. فنقص `h` يعني نقص طاقة الوضع."],"صح وخطأ ٤: وحدة الطاقة والشغل (صفحة 65)":["الطاقة والشغل وجهان لشيء واحد، فالشغل نقل للطاقة. لذلك يقاسان بالوحدة نفسها، وهي الجول.","رفع جسم وزنه `10 N` مسافة `2 m` إلى أعلى يحتاج شغلا `W = 10 × 2 = 20 J`، فتزيد طاقة وضعه `20 J`.","لأن الشغل المبذول على الجسم يتحول إلى طاقة فيه، فلا بد أن يقاس الاثنان بالوحدة نفسها. والجول يساوي `N·m`."],"صح وخطأ ٥: نوع كمية السرعة (صفحة 65)":["السرعة لا يكفي فيها الرقم وحده، بل يجب معرفة الاتجاه أيضا. مثل أن تقول: `20 m/s` نحو الشمال.","سيارتان سرعة كل منهما `20 m/s`، الأولى شمالا والثانية جنوبا: لهما المقدار نفسه، لكن سرعتيهما مختلفتان لاختلاف الاتجاه.","لأن السرعة هي الإزاحة مقسومة على الزمن، والإزاحة كمية متجهة. والقسمة على الزمن، وهو كمية قياسية، لا تزيل الاتجاه."],"صح وخطأ ٦: السرعة الابتدائية عند الانطلاق من السكون (صفحة 65)":["الجسم الساكن لا يتحرك، فسرعته في البداية صفر. فعبارة «انطلق من السكون» تعني `Vi = 0`.","سيارة تنطلق من السكون بتسارع `3 m/s²` لمدة `4 s`: `Vf = 0 + 3 × 4 = 12 m/s`.","لأن السكون يعني انعدام الحركة، أي أن الجسم لا يغير موضعه. وهذه معلومة مخفية في نص السؤال يجب استخراجها."],"صح وخطأ ٧: تعريف التسارع (صفحة 65)":["الإزاحة على الزمن تعطي السرعة، لا التسارع. أما التسارع فيخبرنا كم تتغير السرعة في كل ثانية.","جسم قطع `40 m` في `8 s`: سرعته المتوسطة `v = 40 / 8 = 5 m/s`. وإذا تغيرت سرعته من `2 m/s` إلى `10 m/s` خلال `4 s` فتسارعه `a = (10 − 2) / 4 = 2 m/s²`.","التسارع يصف تغير الحركة لا الحركة نفسها، فجسم يسير بسرعة ثابتة كبيرة تسارعه صفر. لذلك يعتمد تعريفه على تغير السرعة لا على الإزاحة."],"صح وخطأ ٨: تعريف الوزن (صفحة 65)":["ما يحتويه الجسم من مادة هو الكتلة، وتقاس بالكيلوجرام. أما الوزن فهو قوة سحب الأرض للجسم، ويقاس بالنيوتن.","جسم كتلته `10 kg`: وزنه على الأرض `W = 10 × 9.8 = 98 N`، وكتلته `10 kg` لا تتغير أينما ذهب.","لأن الوزن يعتمد على تسارع الجاذبية `g` في المكان، أما الكتلة فخاصية ثابتة للجسم. لذلك الوزن قوة تقاس بالنيوتن والكتلة تقاس بالكيلوجرام."],"صح وخطأ ٩: اتجاه الاحتكاك (صفحة 65)":["الاحتكاك دائما يعاكس انزلاق السطحين أحدهما على الآخر. فإذا تحرك الجسم إلى الأمام شده الاحتكاك إلى الخلف.","صندوق ينزلق نحو الشرق على أرض معامل احتكاكها الحركي `0.2` والقوة العمودية `100 N`: `fk = 0.2 × 100 = 20 N` نحو الغرب.","لأن نتوءات السطحين الخشنة تتشابك وتقاوم الانزلاق النسبي بينهما. لذلك تتجه قوة الاحتكاك دائما عكس الحركة النسبية."],"صح وخطأ ١٠: انعدام الشغل (صفحة 65)":["إذا لم يتحرك الجسم فلا شغل، حتى لو دفعته بقوة كبيرة. لذلك العبارة صحيحة.","دفع سيارة متوقفة بقوة `500 N` دون أن تتحرك: `W = 500 × 0 × cos 0° = 0 J`.","لأن الإزاحة أحد عوامل الضرب في `W = F·x·cos θ`، فانعدامها يجعل الناتج صفرا. فالشغل يتطلب قوة وإزاحة معا."],"تمرين 1 · اختر الإجابة ٤ (صفحة 60)":["هذا التمرين يعيد سؤال السيارة: سرعة ابتدائية وتسارع وزمن، والمطلوب السرعة النهائية. حدد المعطيات قبل أي حساب.","سيارة سرعتها `5 m/s` تتسارع `2 m/s²` لمدة `10 s`: المعطيات `Vi = 5 m/s` و `a = 2 m/s²` و `t = 10 s`، فتكون `Vf = 5 + 2 × 10 = 25 m/s`.","كتابة المعطيات بالرموز تساعد على اختيار القانون: لدينا `Vi` و `a` و `t` ونريد `Vf`. والمعادلة التي تجمع هذه الرموز الأربعة هي `Vf = Vi + a·t`."],"تمرين 1 · اختر الإجابة ٤ (صفحة 60) (تابع)":["التسارع في الزمن يعطي مقدار الزيادة في السرعة، ثم نضيفها إلى السرعة الابتدائية.","سيارة سرعتها `8 m/s` تتسارع `2 m/s²` لمدة `6 s`: `Vf = 8 + 2 × 6 = 20 m/s`.","نضرب قبل أن نجمع حسب ترتيب العمليات الحسابية، لأن `a·t` حد واحد يمثل الزيادة. ولو جمعنا أولا لحصلنا على ناتج خاطئ."],"تمرين 2 · اختر الإجابة ٥ (صفحة 60)":["جسم يبدأ من السكون ويتسارع مدة معينة، والمطلوب المسافة. السكون يعني أن السرعة الابتدائية صفر.","جسم ساكن يتسارع `6 m/s²` لمدة `2 s`: `x = ½ × 6 × 2² = 12 m`.","لدينا `Vi` و `a` و `t` ونريد `x`، فنختار المعادلة التي تحتوي هذه الرموز. وهي `x = Vi·t + ½·a·t²`."],"تمرين 2 · اختر الإجابة ٥ (صفحة 60) (تابع)":["الحد الأول صفر لأن الجسم بدأ من السكون. ويبقى نصف التسارع في مربع الزمن.","جسم يبدأ من السكون بتسارع `3 m/s²` لمدة `4 s`: `x = 0 × 4 + 0.5 × 3 × 4² = 24 m`.","`Vi·t` تمثل المسافة لو تحرك الجسم بسرعته الابتدائية فقط، و `½·a·t²` تمثل المسافة الإضافية بسبب التسارع. ولأن `Vi = 0` فكل المسافة هنا ناتجة عن التسارع."],"تمرين 3 · اختر الإجابة ١٠ (صفحة 61)":["نريد القوة التي تجعل جسما كتلته معروفة يتسارع بمقدار معروف. هذه مسألة مباشرة على قانون نيوتن الثاني.","جسم كتلته `9 kg` نريد تسارعه `2 m/s²`: `F = 9 × 2 = 18 N`.","القوة سبب التسارع، فكلما أردنا تسارعا أكبر أو كانت الكتلة أكبر احتجنا قوة أكبر."],"تمرين 3 · اختر الإجابة ١٠ (صفحة 61) (تابع)":["نضرب الكتلة في التسارع فنحصل على القوة، ووحدتها النيوتن.","جسم كتلته `8 kg` وتسارعه `2.5 m/s²`: `F = 8 × 2.5 = 20 N`.","لأن `1 N = 1 kg·m/s²`، فضرب الكتلة بالكيلوجرام في التسارع بوحدة `m/s²` يعطي النيوتن مباشرة."],"تمرين 4 · اختر الإجابة ١١ (صفحة 61)":["معنا القوة والكتلة، والمجهول التسارع. سنعيد ترتيب قانون نيوتن الثاني لنجد التسارع.","سهم كتلته `0.1 kg` يطلق بقوة `25 N`: `a = 25 ÷ 0.1 = 250 m/s²`.","لأن التسارع يتناسب طرديا مع القوة وعكسيا مع الكتلة. لذلك الكتلة الصغيرة جدا تعطي تسارعا كبيرا."],"تمرين 4 · اختر الإجابة ١١ (صفحة 61) (تابع)":["نقسم القوة على الكتلة مباشرة. والقسمة على ربع تساوي الضرب في أربعة.","جسم كتلته `0.5 kg` تؤثر عليه قوة `47 N`: `a = 47 ÷ 0.5 = 94 m/s²`.","الصيغة `a = F / m` هي `F = m·a` نفسها بعد قسمة الطرفين على `m`. فهي ليست قانونا جديدا بل ترتيب له."],"تمرين 5 · اختر الإجابة ١٣ (صفحة 61)":["قوة أفقية تحرك عربة مسافة، والمطلوب الشغل. القوة في اتجاه الحركة فالزاوية صفر.","قوة أفقية `15 N` تحرك عربة `6 m`: `θ = 0°`، و `W = 15 × 6 × 1 = 90 J`.","تحديد الزاوية خطوة أساسية لأن `cos θ` يغير الناتج. وعندما تكون القوة أفقية والحركة أفقية تكون الزاوية صفرا."],"تمرين 5 · اختر الإجابة ١٣ (صفحة 61) (تابع)":["القوة في الإزاحة في واحد، فالشغل هنا حاصل ضرب القوة في الإزاحة.","قوة `25 N` في اتجاه الحركة تزيح جسما `4 m`: `W = 25 × 4 × cos 0° = 100 J`.","لأن `cos 0° = 1`، فالقوة كلها تعمل في اتجاه الإزاحة. ووحدة الناتج `N·m` وهي الجول."],"تمرين 6 · اختر الإجابة ١٤ (صفحة 62)":["القوة مائلة بزاوية مع الأفقي، والجسم يتحرك أفقيا. لذلك يجب إدخال الزاوية في الحساب.","قوة `30 N` بزاوية `60°` تزيح جسما `4 m`: `W = 30 × 4 × cos 60° = 30 × 4 × 0.5 = 60 J`.","الزاوية هنا بين القوة والإزاحة الأفقية، ولذلك نستخدمها مباشرة في `cos θ`."],"تمرين 6 · اختر الإجابة ١٤ (صفحة 62) (تابع)":["نضرب القوة في الإزاحة ثم في `0.5`، لأن نصف القوة فقط يعمل في اتجاه الحركة.","قوة `80 N` بزاوية `60°` تزيح جسما `5 m`: `W = 80 × 5 × 0.5 = 200 J`.","لأن مركبة القوة الأفقية `F·cos 60°` تساوي نصف القوة. والمركبة الرأسية لا تبذل شغلا لأنها عمودية على الحركة."],"تمرين 7 · اختر الإجابة ١٩ (صفحة 62)":["جسم متحرك كتلته وسرعته معلومتان، والمطلوب طاقته الحركية.","جسم كتلته `4 kg` سرعته `6 m/s`: `KE = 4 × 6²/2 = 72 J`.","نكتب `m` و `v` لأنهما المتغيران الوحيدان في قانون الطاقة الحركية، فلا نحتاج إلى الارتفاع أو الزمن."],"تمرين 7 · اختر الإجابة ١٩ (صفحة 62) (تابع)":["نربع السرعة، ونضرب في الكتلة، ونقسم على اثنين.","جسم كتلته `12 kg` سرعته `5 m/s`: `KE = 12 × 5²/2 = 150 J`.","لأن الطاقة الحركية تتناسب مع مربع السرعة، فأثر السرعة أكبر من أثر الكتلة. مضاعفة الكتلة تضاعف الطاقة، أما مضاعفة السرعة فتجعلها أربعة أضعاف."],"تمرين 8 · اختر الإجابة ٢٠ (صفحة 62)":["جسم على ارتفاع، والمطلوب طاقة وضعه. نحتاج الكتلة والارتفاع و `g`.","جسم كتلته `5 kg` على ارتفاع `6 m`: `PE = 5 × 9.8 × 6 = 294 J`.","نأخذ `g = 9.8 m/s²` لأنها قيمة تسارع الجاذبية الأرضية المعتمدة في المقرر."],"تمرين 8 · اختر الإجابة ٢٠ (صفحة 62) (تابع)":["نضرب الكتلة في `9.8` ثم في الارتفاع، والناتج بالجول.","جسم كتلته `20 kg` على ارتفاع `2 m`: `PE = 20 × 9.8 × 2 = 392 J`.","لأن `kg × m/s² × m` تساوي `N·m`، وهي الجول. فالوحدات تؤكد أن الناتج طاقة."],"تمرين 9 · اختر الإجابة ٢٣ (صفحة 63)":["جسم يبدأ من السكون وتصل سرعته إلى قيمة معينة بعد زمن، والمطلوب تسارعه.","جسم يبدأ من السكون ويصل إلى `18 m/s` خلال `6 s`: `a = (18 − 0) / 6 = 3 m/s²`.","التسارع يحتاج إلى التغير في السرعة والزمن فقط، ولذلك تكفي هذه المعطيات."],"تمرين 9 · اختر الإجابة ٢٣ (صفحة 63) (تابع)":["نطرح السرعتين لنعرف التغير، ثم نقسم على الزمن.","سيارة سرعتها `4 m/s` تصل إلى `19 m/s` خلال `3 s`: `a = (19 − 4) ÷ 3 = 5 m/s²`.","لأن التسارع معدل تغير السرعة، أي مقدار تغيرها في كل ثانية. والتسارع الموجب يعني أن السرعة تزداد."],"تمرين 10 · اختر الإجابة ٢٦ (صفحة 63)":["سيارة قطعت مسافة في زمن، والمطلوب سرعتها المتوسطة.","دراجة قطعت `200 m` في `25 s`: `v = 200 / 25 = 8 m/s`.","السرعة المتوسطة تحتاج المسافة الكلية والزمن الكلي فقط، لذلك لا نحتاج إلى التسارع."],"تمرين 10 · اختر الإجابة ٢٦ (صفحة 63) (تابع)":["نقسم المسافة على الزمن فنعرف ما تقطعه السيارة في الثانية الواحدة.","قطار قطع `900 m` في `45 s`: `v = 900 ÷ 45 = 20 m/s`.","لأن السرعة معدل قطع المسافة بالنسبة للزمن، ووحدتها `m/s`."],"تمرين 11 · اختر الإجابة ٣١ (صفحة 64)":["سيارة كتلتها وتسارعها معلومان، والمطلوب القوة المحركة.","سيارة كتلتها `1600 kg` تتسارع `2 m/s²`: `F = 1600 × 2 = 3200 N`.","لأن قانون نيوتن الثاني يربط القوة بالكتلة والتسارع مباشرة."],"تمرين 11 · اختر الإجابة ٣١ (صفحة 64) (تابع)":["نضرب الكتلة في التسارع فنحصل على القوة.","سيارة كتلتها `800 kg` تتسارع `3 m/s²`: `F = 800 × 3 = 2400 N`.","لأن القوة المحصلة على الجسم تساوي حاصل ضرب كتلته في تسارعه."],"تمرين 12 · اختر الإجابة ٣٣ (صفحة 64)":["جسم ينزلق على سطح، والمطلوب قوة الاحتكاك من معامل الاحتكاك والقوة العمودية.","جسم على سطح معامل احتكاكه `0.5` والقوة العمودية `40 N`: `f = 0.5 × 40 = 20 N`.","لأن قوة الاحتكاك تعتمد على نوع السطحين المتلامسين وعلى القوة العمودية فقط."],"تمرين 12 · اختر الإجابة ٣٣ (صفحة 64) (تابع)":["نضرب المعامل في القوة العمودية.","معامل احتكاك `0.2` وقوة عمودية `90 N`: `f = 0.2 × 90 = 18 N`.","لأن المعامل نسبة بلا وحدة، فيخرج الاحتكاك بوحدة القوة العمودية وهي النيوتن."]},"2-1":{"":["هذا الدرس يفرق بين الحرارة، وهي طاقة تنتقل من الجسم الأسخن إلى الأبرد، ودرجة الحرارة، وهي مقياس لسخونة الجسم. ثم يعرض ثلاثة مقاييس لدرجة الحرارة وطرق التحويل بينها، كما تحول المال بين عملات مختلفة.","`15°C` تساوي بالكلفن `K = 15 + 273 = 288 K`، وبالفهرنهايت `F = 1.8 × 15 + 32 = 59°F`.","نميز بين الحرارة ودرجة الحرارة لأن الأولى طاقة تعتمد على الكتلة والثانية لا تعتمد عليها. ونحتاج قوانين التحويل لأن المقاييس تختلف في نقطة البداية وفي حجم الدرجة الواحدة."],"مقدمة الوحدة وأهدافها":["تخيل جزيئات المادة كأطفال في ساحة يركضون ويهتزون ويمسك بعضهم بعضا. طاقة الركض هي طاقة الحركة، وطاقة التماسك هي طاقة الوضع، ومجموعهما هو الطاقة الداخلية.","إذا كانت طاقة حركة جزيئات قطعة معدن `500 J` وطاقة وضعها `300 J`، فطاقتها الداخلية `500 J + 300 J = 800 J`.","الجزيئات في حركة دائمة فتمتلك طاقة حركة، وبينها قوى تجاذب فتمتلك طاقة وضع. لذلك تجمع الطاقة الداخلية النوعين معا."],"درجة الحرارة وكمية الحرارة":["درجة الحرارة تخبرك أي الجسمين أسخن، فتحدد إلى أين تذهب الحرارة. أما كمية الحرارة فهي مقدار الطاقة الذي انتقل فعلا، مثل الفرق بين ارتفاع الماء في خزانين ومقدار الماء الذي يجري بينهما.","كوب شاي عند `80°C` في غرفة عند `25°C`: تنتقل الحرارة من الشاي إلى الهواء، فإذا فقد الشاي `4186 J` نقصت طاقته الداخلية بالمقدار نفسه وانخفضت درجة حرارته.","عند اكتساب الحرارة تزيد طاقة حركة الجزيئات فترتفع درجة الحرارة. وتنتقل الحرارة من الجسم الأعلى درجة لأن جزيئاته الأسرع تعطي جزءا من طاقتها للجزيئات الأبطأ عند التلامس."],"ما ستتعلمه":["هذه خريطة الطريق للوحدة: كيف نقيس السخونة ونحول بين مقاييسها، وكم حرارة تحتاج المادة لتسخن أو تذوب، وكيف تنتقل الحرارة من مكان إلى آخر.","مثال واقعي لما سنصل إليه: تحويل نشرة جوية تقول `77°F` إلى `25°C`، وحساب الحرارة اللازمة لتسخين ماء الشاي قبل غليه.","الحرارة تدخل في كل شيء حولنا من الطبخ إلى المحركات والمناخ. وفهم مقاييسها وقوانينها يمكن المتدرب من تفسير هذه الظواهر وحسابها بدقة."],"الحرارة (كمية الحرارة)":["الحرارة طاقة تنتقل وحدها من الجسم الساخن إلى البارد، مثل الماء الذي ينساب من المكان العالي إلى المنخفض. ويتوقف الانتقال عندما تتساوى درجتا الحرارة.","`500 cal` تساوي بالجول `500 × 4.186 = 2093 J`.","جزيئات الجسم الساخن أسرع في المتوسط، فتعطي جزءا من طاقتها للجزيئات الأبطأ عند التصادم. ويستمر ذلك حتى يتساوى متوسط طاقة الحركة، وهذا هو الاتزان الحراري."],"مصادر الطاقة الحرارية":["كل ما ينتج دفئا يعد مصدرا للطاقة الحرارية: الشمس في النهار، والنار في الموقد، وفرك اليدين في البرد، والمدفأة الكهربائية.","مدفأة كهربائية قدرتها `1000 W` تحول في دقيقة واحدة `1000 × 60 = 60000 J` من الطاقة الكهربائية إلى حرارة.","الطاقة لا تفنى ولا تستحدث بل تتحول من شكل إلى آخر. فالطاقة الكيميائية في الوقود، والحركية في الاحتكاك، والكهربائية في السخان، تتحول كلها إلى طاقة حرارية."],"درجة الحرارة":["درجة الحرارة تعبر عن سرعة حركة الجزيئات في المتوسط: كلما أسرعت الجزيئات كان الجسم أسخن. والترمومتر هو الأداة التي نقرأ بها هذه السخونة.","ماء عند `60°C` جزيئاته أسرع في المتوسط من ماء عند `20°C`، ولذلك يقرأ الترمومتر فيه قيمة أعلى بمقدار `40°C`.","السخونة التي نحسها ناتجة عن اصطدام الجزيئات بأجسامنا، وكلما زادت طاقة حركتها زاد هذا الأثر. لذلك تعرف درجة الحرارة بمتوسط طاقة الحركة لا بمجموعها."],"المقاييس الثلاثة (تجمد الماء ← غليانه)":["المقاييس الثلاثة مثل مساطر مختلفة لقياس الشيء نفسه. المئوي والكلفن درجتهما بالحجم نفسه لكنهما يبدآن من نقطتين مختلفتين، أما الفهرنهايت فدرجته أصغر لأن المسافة نفسها مقسمة إلى 180 قسما.","منتصف المسافة بين التجمد والغليان: `50°C` تقابل `50 + 273 = 323 K`، و `1.8 × 50 + 32 = 122°F`.","اختيرت نقطتا تجمد الماء وغليانه لأنهما ثابتتان ويسهل تكرارهما في أي مختبر. واختلاف عدد الأقسام بين النقطتين هو سبب اختلاف حجم الدرجة بين المقاييس."],"قوانين التحويل":["للتحويل من المئوي إلى الكلفن أضف 273 فقط. وللتحويل إلى الفهرنهايت اضرب في 1.8 ثم أضف 32، وللعودة اطرح 32 ثم اقسم على 1.8.","`25°C` تساوي `25 + 273 = 298 K`، وتساوي `1.8 × 25 + 32 = 77°F`.","نضرب في 1.8 لأن 100 قسم مئوي تقابل 180 قسما فهرنهايت، ونضيف 32 لأن تجمد الماء على الفهرنهايت عند 32. أما الكلفن فدرجته بحجم الدرجة المئوية، لذلك تكفي إزاحة 273."],"أمثلة الحقيبة التدريبية محلولة":["التحويل من المئوي إلى الكلفن مثل عداد يبدأ من رقم مختلف: لا ضرب ولا قسمة، فقط نضيف 273 إلى القراءة المئوية.","جسم عند `150°C`: `K = 150 + 273 = 423 K`.","الدرجة المئوية ودرجة الكلفن متساويتان في الحجم، والفرق بينهما في نقطة الصفر فقط. فصفر المئوي يقابل 273 على الكلفن."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["بعد التعويض نجمع الرقمين فنحصل على القراءة بالكلفن، وتكون دائما أكبر من القراءة المئوية بمقدار 273.","هواء بارد جدا عند `−73°C`: `K = −73 + 273 = 200 K`.","قراءة الكلفن أكبر دائما لأن الكلفن يبدأ من الصفر المطلق، وهو أبرد من صفر المئوي بمقدار 273 درجة. لذلك لا تظهر في الكلفن قيم سالبة."],"مثال ٢: تحويل درجة حرارة الغرفة من الفهرنهايت إلى المئوي (صفحة 73)":["قراءة الفهرنهايت تبدأ تجمد الماء عند 32، فنطرح 32 أولا لنعرف كم درجة فوق التجمد، ثم نقسم على 1.8 لأن درجة الفهرنهايت أصغر.","`50°F`: `50 − 32 = 18` ثم `C = 18 ÷ 1.8 = 10°C`.","نطرح قبل القسمة لأن إضافة 32 هي آخر خطوة في التحويل إلى فهرنهايت، فتزال أولا عند العكس. ثم نقسم على 1.8 لأن كل درجة مئوية تعادل 1.8 درجة فهرنهايت."],"مثال ٢: تحويل درجة حرارة الغرفة من الفهرنهايت إلى المئوي (صفحة 73) (تابع)":["بعد الطرح نقسم الناتج على 1.8 فنحصل على القراءة المئوية، وهي في الأجواء العادية أصغر من قراءة الفهرنهايت.","`104°F`: `104 − 32 = 72` ثم `C = 72 ÷ 1.8 = 40°C`.","القراءة المئوية أصغر لأن الدرجة المئوية أكبر حجما من درجة الفهرنهايت، فنحتاج عددا أقل منها لوصف السخونة نفسها. كما أن الفهرنهايت يبدأ من 32 عند التجمد."],"مثال ٣: تحويل درجة جسم ساخن من المئوي إلى الفهرنهايت (صفحة 73)":["للتحويل من المئوي إلى الفهرنهايت نعكس الخطوات: نضرب أولا في 1.8 ثم نضيف 32، كمن يحول عملة ثم يضيف رسوما ثابتة.","`100°C`: `1.8 × 100 = 180` ثم `F = 180 + 32 = 212°F`، وهي درجة غليان الماء.","نضرب في 1.8 لأن كل درجة مئوية تعادل 1.8 درجة فهرنهايت، ثم نضيف 32 لأن الفهرنهايت يبدأ تجمد الماء عنده من 32 لا من الصفر."],"مثال ٣: تحويل درجة جسم ساخن من المئوي إلى الفهرنهايت (صفحة 73) (تابع)":["يمكن الوصول إلى الناتج بطريقتين: التعويض المباشر في قانون الفهرنهايت، أو التعويض في قانون المئوي ثم حل المعادلة. والطريقتان تعطيان النتيجة نفسها.","`250°C`: `1.8 × 250 = 450` ثم `F = 450 + 32 = 482°F`.","تتفق الطريقتان لأن القانونين صورتان لعلاقة واحدة، فأحدهما ينتج من الآخر بنقل الحدود وحل المعادلة."],"سؤال ١: متى تتساوى قراءة الفهرنهايت والسلسيوس (صفحة 74)":["نبحث عن درجة يقرأ فيها المقياسان العدد نفسه، فنضع الرمز x مكان القراءتين في القانون ونحل معادلة بسيطة.","متى تكون قراءة الفهرنهايت ضعف المئوية؟ `2x = 1.8x + 32` ← `0.2x = 32` ← `x = 160°C`، وعندها `F = 320°F`.","نضع المجهول نفسه للقراءتين لأن المطلوب حالة واحدة تتساوى فيها القيمتان. وبما أن الفهرنهايت يبدأ من 32 ويتغير أسرع، فلا يلتقي المقياسان إلا عند قيمة سالبة."],"سؤال ١: متى تتساوى قراءة الفهرنهايت والسلسيوس (صفحة 74) (تابع)":["بعد قسمة الطرفين على العدد السالب نحصل على القيمة، ثم نعوضها في القانون للتأكد أن القراءتين متساويتان فعلا.","تحقق بالقانون العكسي: `C = (−40 − 32) ÷ 1.8 = −72 ÷ 1.8 = −40°C`.","التحقق يكشف أي خطأ في الإشارات أو القسمة. والناتج سالب لأن الفهرنهايت يبدأ متقدما بمقدار 32، فلا يلتقي بالمئوي إلا تحت الصفر حيث يهبط الفهرنهايت أسرع."],"سؤال ٢: متى تتساوى قراءة الفهرنهايت والكلفن (صفحة 74)":["لا يوجد قانون مباشر بين الفهرنهايت والكلفن، فنمر بالمئوي كجسر: نحول الكلفن إلى مئوي ثم المئوي إلى فهرنهايت.","`373 K`: `C = 373 − 273 = 100°C` ثم `F = 1.8 × 100 + 32 = 212°F`.","المئوي مرتبط بالمقياسين بقانونين معروفين، فالتعويض بأحدهما في الآخر ينتج علاقة واحدة بين F و K."],"سؤال ٢: متى تتساوى قراءة الفهرنهايت والكلفن (صفحة 74) (تابع)":["بعد فك القوس وتجميع الحدود نحصل على معادلة بسيطة في x، ونقسم على معاملها لنجد الدرجة التي يتساوى عندها المقياسان.","جرب `500 K`: `C = 500 − 273 = 227°C` ثم `F = 1.8 × 227 + 32 = 440.6°F`، فالقراءتان غير متساويتين ونحتاج قيمة أعلى.","يلتقي المقياسان عند قيمة موجبة كبيرة لأن الكلفن يبدأ متقدما على الفهرنهايت، لكن الفهرنهايت يزيد 1.8 درجة مقابل كل درجة كلفن فيلحق به."],"رسم توضيحي 1":["في الرسم جزيئات تتحرك بسرعات مختلفة، ودرجة الحرارة تعبر عن متوسط طاقة حركتها. فكلما زادت سرعة الجزيئات في المتوسط ارتفعت درجة الحرارة.","في إناءين ماء عند `20°C` وعند `80°C`، جزيئات الإناء الثاني أسرع في المتوسط، ويقرأ الترمومتر فيه `60°C` زيادة.","نستخدم المتوسط لا المجموع لأن الجزيئات لا تتحرك كلها بالسرعة نفسها. والمتوسط لا يتغير بزيادة كمية المادة، لذلك لا تعتمد درجة الحرارة على الكتلة."],"رسم توضيحي 2":["الرسم يضع الترمومترات الثلاثة جنبا إلى جنب: كلها تشير إلى الحالة نفسها عند تجمد الماء وعند غليانه، لكن بأرقام مختلفة.","ماء دافئ عند `40°C` يقابل `40 + 273 = 313 K` و `1.8 × 40 + 32 = 104°F`.","تختلف الأرقام لأن كل مقياس اختار نقطة بداية وعدد أقسام مختلفين بين التجمد والغليان، مع أن سخونة الماء واحدة."],"رسم توضيحي 3":["كل خط رأسي في الرسم حالة سخونة واحدة، تقرؤها على المقاييس الثلاثة بأرقام مختلفة، مثل طول واحد تقيسه بالمتر وبالقدم.","هواء شتوي عند `−10°C` يقابل `−10 + 273 = 263 K` و `1.8 × (−10) + 32 = 14°F`.","درجة الحرارة خاصية للجسم لا تتغير بتغير المقياس، والذي يتغير هو الرقم فقط. لذلك تربط قوانين التحويل بين القراءات الثلاث على الخط نفسه."],"الحرارة ودرجة الحرارة":["كمية الحرارة طاقة تنتقل ورمزها Q ووحدتها الجول، أما درجة الحرارة فمقياس للسخونة ورمزها T ونقيسها بالترمومتر. وكمية الحرارة تعتمد على الكتلة، أما درجة الحرارة فلا.","إبريق فيه `2 kg` ماء وكوب فيه `0.2 kg` ماء، كلاهما عند `90°C`: درجة الحرارة واحدة، لكن الإبريق يعطي حرارة أكثر بعشر مرات عند تبريده إلى درجة الغرفة.","كمية الحرارة تعتمد على عدد الجزيئات التي تحمل الطاقة، فتزيد بزيادة الكتلة. أما درجة الحرارة فتعبر عن متوسط طاقة الجزيء الواحد، فلا تتغير بتغير الكمية."],"مقاييس درجة الحرارة":["الجدول يلخص لكل مقياس أين يتجمد الماء وأين يغلي وكم قسما بينهما وأين الصفر المطلق. الكلفن وحده يبدأ من الصفر المطلق، فلا قيم سالبة فيه.","`−200°C` تقابل `−200 + 273 = 73 K` و `1.8 × (−200) + 32 = −328°F`.","الصفر المطلق أدنى درجة ممكنة لأن طاقة حركة الجزيئات تصل عنده إلى أقل قيمة لها. لذلك جعل مقياس الكلفن يبدأ منه، فسمي المقياس المطلق."],"تطبيقات من الحياة":["الحرارة حولنا في كل مكان: الطعام يعطينا طاقة تقاس بالسعرات، وفرامل السيارة تسخن بالاحتكاك، وميزان الحرارة يكشف الحمى إذا ارتفعت حرارة الجسم عن `37°C`.","وجبة خفيفة فيها 250 سعرا غذائيا تعطي `250 × 4186 = 1046500 J`، أي نحو `1.05 × 10⁶ J`.","الطاقة تتحول من شكل إلى آخر: طاقة الطعام الكيميائية تتحول في الجسم إلى حرارة وحركة، وطاقة حركة السيارة تتحول بالاحتكاك إلى حرارة في الفرامل."],"تمرين 1 · مثال ١ (صفحة 72)":["للتحويل من المئوي إلى الكلفن أضف 273 إلى القراءة، ولا شيء غير ذلك.","فرن عند `400°C`: `K = 400 + 273 = 673 K`.","درجة الكلفن بحجم الدرجة المئوية نفسها، والفرق الوحيد أن صفر الكلفن أبرد من صفر المئوي بمقدار 273 درجة."],"تمرين 2 · مثال ٢ (صفحة 73)":["من الفهرنهايت إلى المئوي: اطرح 32 أولا ثم اقسم الناتج على 1.8.","غرفة عند `68°F`: `C = (68 − 32) ÷ 1.8 = 36 ÷ 1.8 = 20°C`.","نطرح 32 لأن الفهرنهايت يبدأ تجمد الماء عنده من 32، ثم نقسم على 1.8 لأن 180 قسما فهرنهايت تقابل 100 قسم مئوي."],"تمرين 3 · ورقة العمل · سؤال ٢ (صفحة 79)":["نعوض القراءة المئوية في `K = C + 273` ونجمع، فنحصل على القراءة بالكلفن.","زيت ساخن عند `127°C`: `K = 127 + 273 = 400 K`.","المقياسان يتفقان في حجم الدرجة، فإزاحة القراءة بمقدار 273 تكفي دون ضرب أو قسمة."],"تمرين 4 · ورقة العمل · سؤال ٣ (صفحة 79)":["من المئوي إلى الفهرنهايت: اضرب في 1.8 ثم أضف 32.","ماء ساخن عند `60°C`: `F = 1.8 × 60 + 32 = 108 + 32 = 140°F`.","نضرب أولا لأن الدرجة المئوية أكبر من درجة الفهرنهايت بمقدار 1.8 مرة، ثم نضيف 32 لأن تجمد الماء على الفهرنهايت عند 32 لا عند الصفر."],"تمرين 5 · ورقة العمل · سؤال ٤ (صفحة 80)":["اطرح 32 من قراءة الفهرنهايت، ثم اقسم ما بقي على 1.8 لتحصل على المئوي.","يوم حار عند `86°F`: `C = (86 − 32) ÷ 1.8 = 54 ÷ 1.8 = 30°C`.","الطرح يزيل الإزاحة بين نقطتي البداية، والقسمة تحول عدد الأقسام الصغيرة إلى أقسام مئوية أكبر. لذلك الترتيب مهم ولا يصح أن نقسم أولا."],"تمرين 6 · تمارين الوحدة · اختر الإجابة ٤ (صفحة 84)":["حول درجة حرارة الجو من المئوي إلى الفهرنهايت بالضرب في 1.8 ثم إضافة 32.","جو عند `35°C`: `F = 1.8 × 35 + 32 = 63 + 32 = 95°F`.","100 قسم مئوي بين التجمد والغليان تقابل 180 قسما فهرنهايت، فكل درجة مئوية تساوي 1.8 درجة فهرنهايت، ثم نضيف نقطة البداية 32."],"تمرين 7 · تمارين الوحدة · اختر الإجابة ٥ (صفحة 84)":["لا يوجد قانون مباشر من الكلفن إلى الفهرنهايت، فنحول إلى المئوي أولا ثم إلى الفهرنهايت، كمن يسافر عبر محطة وسطى.","`310 K`: `C = 310 − 273 = 37°C` ثم `F = 1.8 × 37 + 32 = 98.6°F`، وهي حرارة جسم الإنسان.","المئوي يرتبط بالكلفن وبالفهرنهايت بقانونين معروفين، فيصلح وسيطا بينهما. ونطرح 273 أولا لأننا نعكس قانون الكلفن."],"تمرين 8 · تمارين الوحدة · اختر الإجابة ٦ (صفحة 84)":["أضف 273 إلى القراءة المئوية، حتى لو كانت سالبة.","ثلاجة تجميد عند `−20°C`: `K = −20 + 273 = 253 K`.","نجمع 273 لأن صفر المئوي يقع عند 273 على الكلفن. والقراءة بالكلفن تبقى موجبة لأن الكلفن يبدأ من الصفر المطلق."],"تمرين 9 · تمارين الوحدة · اختر الإجابة ٧ (صفحة 85)":["اطرح 32 من قراءة الفهرنهايت ثم اقسم على 1.8.","`113°F`: `C = (113 − 32) ÷ 1.8 = 81 ÷ 1.8 = 45°C`.","هذا القانون عكس قانون الفهرنهايت: هناك نضرب ثم نضيف، وهنا نطرح ثم نقسم بالترتيب المعاكس."],"تمرين 10 · تمارين الوحدة · اختر الإجابة ٨ (صفحة 85)":["اضرب درجة الجو المئوية في 1.8 ثم أضف 32 لتحصل على قراءة الفهرنهايت.","`45°C`: `F = 1.8 × 45 + 32 = 81 + 32 = 113°F`.","درجة الفهرنهايت أصغر من الدرجة المئوية، فنحتاج عددا أكبر منها للسخونة نفسها، ثم نزيح القراءة بمقدار 32 لاختلاف نقطة التجمد."]},"2-3":{"":["هذا الدرس يجيب عن سؤالين: كم حرارة تحتاج المادة لترتفع درجة حرارتها، وكم حرارة تحتاج لتتحول من صلب إلى سائل. الأول تجيب عنه الحرارة النوعية، والثاني تجيب عنه الحرارة الكامنة.","تسخين `0.2 kg` ماء بمقدار `25°C`: `Q = 0.2 × 4180 × 25 = 20900 J`، وصهر `0.1 kg` جليد عند `0°C`: `Q = 0.1 × 336000 = 33600 J`.","المواد تختلف في مقدار الحرارة التي تحتاجها لكل درجة، لذلك نحتاج الحرارة النوعية. وأثناء تغير الحالة تذهب الحرارة إلى تفكيك الروابط لا إلى رفع الدرجة، لذلك نحتاج الحرارة الكامنة."],"الحرارة النوعية c":["الحرارة النوعية تقيس عناد المادة أمام التسخين: المادة ذات c الكبيرة مثل الماء تحتاج حرارة كثيرة لترتفع درجة واحدة، فتسخن ببطء وتبرد ببطء.","رفع درجة `1 kg` ألمنيوم (`c = 900 J/(kg·°C)`) بمقدار `5°C`: `Q = 1 × 900 × 5 = 4500 J`.","تختلف المواد في تركيب جزيئاتها وقوى الترابط بينها، فتحتاج كميات مختلفة من الطاقة لزيادة طاقة حركة جزيئاتها بالمقدار نفسه. وهذا الاختلاف تعبر عنه الحرارة النوعية."],"السعة الحرارية C":["الحرارة النوعية تخص المادة لكل كيلوجرام، أما السعة الحرارية فتخص الجسم كله بكتلته الفعلية. فقدر كبيرة وملعقة من المعدن نفسه لهما c واحدة لكن سعتهما الحرارية مختلفة.","قطعة حديد `2 kg` و `c = 460 J/(kg·°C)`: `C = 2 × 460 = 920 J/°C`.","كلما زادت الكتلة زاد عدد الجزيئات التي يجب تسخينها، فيحتاج الجسم حرارة أكبر لكل درجة. لذلك تساوي السعة الحرارية الكتلة مضروبة في الحرارة النوعية."],"تنبيه":["الحرارة النوعية مكتوبة لكل كيلوجرام، فإذا أعطيت الكتلة بالجرام فاقسمها على 1000 قبل التعويض.","`250 g` ماء تصبح `0.25 kg`، وتسخينها `10°C` يحتاج `Q = 0.25 × 4180 × 10 = 10450 J`.","وحدة c هي `J/(kg·°C)`، فيجب أن تكون الكتلة بالكيلوجرام حتى تختصر الوحدات ويخرج الناتج بالجول. ولو عوضت بالجرام لخرج الناتج أكبر بألف مرة."],"الحرارة الكامنة للانصهار":["عند صهر الجليد لا ترتفع درجة حرارته، بل تذهب الحرارة كلها إلى تحويله من صلب إلى ماء. والحرارة الكامنة تخبرك كم جولا يلزم لصهر كل كيلوجرام.","صهر `2 kg` جليد عند `0°C`: `Q = 2 × 336000 = 672000 J`.","جزيئات الصلب مرتبطة بقوى تجاذب قوية، والحرارة المكتسبة عند نقطة الانصهار تستهلك في التغلب على هذه الروابط. فتزيد طاقة الوضع ولا تزيد طاقة الحركة، لذلك تبقى درجة الحرارة ثابتة."],"أمثلة الحقيبة التدريبية محلولة":["إذا بقي الماء سائلا فكل الحرارة التي يأخذها ترفع درجته، وكمية الحرارة تزيد بزيادة الكتلة وبزيادة الحرارة النوعية وبزيادة التغير في درجة الحرارة.","تسخين `200 g` ماء من `20°C` إلى `50°C`: `m = 0.2 kg` و `ΔT = 30°C`، فتكون `Q = 0.2 × 4180 × 30 = 25080 J`.","نختار `Q = m·c·ΔT` لأنه لا يحدث تغير في الحالة. ولو وصل الماء إلى الغليان وتحول إلى بخار لاحتجنا الحرارة الكامنة أيضا."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نحسب أولا التغير في درجة الحرارة بطرح الابتدائية من النهائية، ثم نضرب الكتلة في الحرارة النوعية في هذا التغير.","`0.5 kg` ماء من `25°C` إلى `35°C`: `ΔT = 10°C` و `Q = 0.5 × 4180 × 10 = 20900 J`.","تكون Q موجبة عندما تكون الدرجة النهائية أكبر من الابتدائية، أي أن الجسم اكتسب حرارة. وإذا برد الجسم صارت ΔT سالبة فتكون Q سالبة، أي أنه فقد حرارة."],"مثال: السعة الحرارية وكمية الحرارة لقطعة نحاس (صفحة 75)":["السعة الحرارية جواب سؤال: كم جولا تحتاج هذه القطعة بعينها لترتفع درجة واحدة؟ نحسبها بضرب كتلتها في الحرارة النوعية لمادتها.","قطعة نحاس `50 g = 0.05 kg` و `c = 400 J/(kg·°C)`: `C = 0.05 × 400 = 20 J/°C`.","الحرارة النوعية تخص `1 kg` فقط، والقطعة لها كتلة محددة، فنضرب في الكتلة لنحصل على ما يلزم الجسم كله لكل درجة."],"مثال: السعة الحرارية وكمية الحرارة لقطعة نحاس (صفحة 75) (تابع)":["بعد معرفة السعة الحرارية يصبح الحساب أسهل: اضربها في التغير في درجة الحرارة لتحصل على كمية الحرارة مباشرة.","القطعة السابقة `C = 20 J/°C` سخنت من `20°C` إلى `50°C`: `Q = C·ΔT = 20 × 30 = 600 J`.","بما أن `C = m·c`، فإن `Q = m·c·ΔT` تصبح `Q = C·ΔT`. فالقانونان واحد، والثاني اختصار للأول."],"مثال: حساب الحرارة الكامنة لانصهار الجليد (صفحة 76)":["إذا عرفنا الحرارة التي صهرت كتلة من الجليد، نقسمها على الكتلة لنعرف نصيب الكيلوجرام الواحد، وهذا هو الحرارة الكامنة.","`1008000 J` صهرت `3 kg` جليد: `H = 1008000 ÷ 3 = 336000 J/kg`.","لا نستخدم `Q = m·c·ΔT` لأن درجة الحرارة ثابتة أثناء الانصهار، فلا يوجد تغير في الدرجة. والحرارة كلها تستهلك في تحويل الصلب إلى سائل."],"مثال: حساب الحرارة الكامنة لانصهار الجليد (صفحة 76) (تابع)":["الناتج قيمة كبيرة: صهر كيلوجرام واحد من الجليد يحتاج طاقة تكفي لتسخين الكتلة نفسها من الماء نحو 80 درجة.","صهر `1.5 kg` جليد يحتاج `Q = 1.5 × 336000 = 504000 J`، أي `5.04 × 10⁵ J`.","الحرارة الكامنة كبيرة لأن تفكيك الروابط بين جزيئات الجليد يحتاج طاقة كثيرة. وهذه الطاقة تختزن في الماء الناتج طاقة وضع، وتنطلق من جديد عند التجمد."],"الحرارة النوعية لمواد شائعة":["الجدول يرتب المواد حسب حاجتها للحرارة: الماء في الأعلى يحتاج حرارة كثيرة ليسخن، والرصاص في الأسفل يسخن بحرارة قليلة.","الحرارة نفسها `4180 J` ترفع `1 kg` ماء بمقدار `1°C`، لكنها ترفع `1 kg` رصاص بمقدار `4180 ÷ 130 ≈ 32°C`.","تختلف الحرارة النوعية باختلاف تركيب المادة وطريقة ترابط جزيئاتها. وقيمة الماء كبيرة جدا، لذلك يستخدم في التبريد وفي تلطيف المناخ."],"الحرارة الكامنة للماء":["عند الانصهار والتبخر تمتص المادة حرارة، وعند التجمد والتكثف تطلق المقدار نفسه. وفي كل هذه التحولات تبقى درجة الحرارة ثابتة.","تبخير `0.1 kg` ماء عند `100°C`: `Q = 0.1 × 2260000 = 226000 J`.","التحول العكسي يعيد الطاقة نفسها لأن الروابط التي تفككت عند الانصهار أو التبخر تتكون من جديد عند التجمد أو التكثف. وحرارة التبخر أكبر لأن الجزيئات تبتعد تماما بعضها عن بعض."],"تطبيقات من الحياة":["الماء بطيء التسخين والتبريد، لذلك تبقى المدن الساحلية معتدلة ويستخدم الماء في تبريد السيارات. والثلج يبرد العصير لأنه يسحب حرارة كثيرة وهو يذوب.","مكعب ثلج كتلته `30 g = 0.03 kg` يمتص عند ذوبانه `Q = 0.03 × 336000 = 10080 J` من العصير.","الحرارة النوعية الكبيرة للماء تجعله يمتص حرارة كثيرة دون أن ترتفع درجته كثيرا. والحرارة الكامنة الكبيرة للجليد تجعل ذوبانه يسحب حرارة كبيرة من الوسط المحيط."],"تمرين 1 · مثال (صفحة 75)":["السعة الحرارية تساوي الكتلة بالكيلوجرام مضروبة في الحرارة النوعية.","نحاس `30 g = 0.03 kg` و `c = 400 J/(kg·°C)`: `C = 0.03 × 400 = 12 J/°C`.","الحرارة النوعية تخص كل كيلوجرام، والجسم كتلته جزء من الكيلوجرام، فنضرب لنحصل على ما يحتاجه الجسم كله لكل درجة."],"تمرين 2 · ورقة العمل · سؤال ٥ (صفحة 80)":["حول الكتلة إلى kg، واحسب التغير في درجة الحرارة، ثم اضرب الكتلة في الحرارة النوعية في هذا التغير.","`50 g` ماء من `20°C` إلى `80°C`: `Q = 0.05 × 4180 × 60 = 12540 J`.","الماء يبقى سائلا بين هاتين الدرجتين، فكل الحرارة ترفع درجته، ولذلك يكفي القانون `Q = m·c·ΔT`."],"تمرين 3 · ورقة العمل · سؤال ٦ (صفحة 81)":["اضرب كتلة قطعة الحديد في حرارته النوعية لتحصل على سعتها الحرارية.","حديد `1.5 kg` و `c = 460 J/(kg·°C)`: `C = 1.5 × 460 = 690 J/°C`.","القطعة الأكبر تحتوي جزيئات أكثر، فتحتاج حرارة أكثر لترتفع درجة واحدة، لذلك تتناسب السعة الحرارية طرديا مع الكتلة."],"تمرين 4 · ورقة العمل · سؤال ٩ (صفحة 83)":["إذا كانت الحرارة النوعية مجهولة فاقسم كمية الحرارة على حاصل ضرب الكتلة في التغير في درجة الحرارة.","معدن `0.1 kg` امتص `1800 J` فارتفعت درجته `20°C`: `c = 1800 ÷ (0.1 × 20) = 900 J/(kg·°C)`، وهي قيمة الألمنيوم في الجدول.","القانون `Q = m·c·ΔT` معادلة فيها مجهول واحد، فنعزله بالقسمة. وبمقارنة الناتج بالجدول يمكن التعرف على نوع المادة."],"تمرين 5 · ورقة العمل · سؤال ١٠ (صفحة 83)":["من `C = m·c` نجد الكتلة بقسمة السعة الحرارية على الحرارة النوعية.","وعاء سعته الحرارية `1800 J/°C` وحرارته النوعية `900 J/(kg·°C)`: `m = 1800 ÷ 900 = 2 kg`.","السعة الحرارية تساوي ما يحتاجه كل كيلوجرام مضروبا في عدد الكيلوجرامات، فالقسمة على c تعطينا عدد الكيلوجرامات أي الكتلة."],"تمرين 6 · تمارين الوحدة · اختر الإجابة ١١ (صفحة 85)":["السخان يعطي كل ثانية عددا ثابتا من الجولات هو قدرته، فنحسب الحرارة التي يحتاجها الماء ثم نقسمها على القدرة لنعرف الزمن.","سخان `500 W` و `0.2 kg` ماء من `25°C` إلى `100°C`: `Q = 0.2 × 4180 × 75 = 62700 J` و `t = 62700 ÷ 500 = 125.4 s`.","الطاقة الكهربائية التي يعطيها السخان `P·t` تتحول كلها إلى حرارة في الماء بفرض عدم ضياع شيء منها. لذلك نساوي `P·t` بالمقدار `m·c·ΔT`."],"تمرين 7 · ورقة العمل · سؤال ٧ (صفحة 81)":["حول كتلة الجليد إلى kg ثم اضربها في الحرارة الكامنة للانصهار.","صهر `50 g = 0.05 kg` جليد: `Q = 0.05 × 336000 = 16800 J`.","الجليد عند `0°C` في نقطة انصهاره، فلا يوجد تغير في الدرجة ولا يصلح `Q = m·c·ΔT`، وتذهب الحرارة كلها إلى تغيير الحالة."],"تمرين 8 · ورقة العمل · سؤال ٨ (صفحة 82)":["الحرارة التي يفقدها الحديد الساخن وهو يبرد حتى `0°C` لا تضيع، بل يأخذها الجليد فيذوب جزء منه. فنساوي حرارة تبريد الحديد بحرارة صهر الجليد.","حديد `1 kg` عند `336°C` و `c = 460 J/(kg·°C)`: `Q = 1 × 460 × 336 = 154560 J`، فكتلة الجليد المنصهر `154560 ÷ 336000 = 0.46 kg`.","هذا تطبيق لحفظ الطاقة: ما يفقده الجسم الساخن يكسبه الجسم البارد. والحديد تتغير درجته فنستخدم له `m·c·ΔT`، والجليد تتغير حالته فنستخدم له `m·H`."],"تمرين 9 · ورقة العمل · سؤال ٨ (صفحة 82)":["نطرح الجزء الذائب من كتلة اللوح لنعرف ما بقي، ثم نضرب الباقي في الحرارة الكامنة.","لوح `2 kg` ذاب منه `0.46 kg`: الباقي `1.54 kg` ويحتاج `Q = 1.54 × 336000 = 517440 J`.","الجليد المتبقي ما زال عند `0°C`، فيحتاج الحرارة الكامنة فقط ليذوب، وكل كيلوجرام منه يحتاج المقدار نفسه من الطاقة."]},"2-5":{"":["عندما يتلامس جسمان مختلفان في الحرارة تنتقل الحرارة من الساخن إلى البارد حتى تتساوى درجتاهما، مثل كوب شاي يبرد في الغرفة. وتنتقل الحرارة بثلاث طرق: التوصيل والحمل والإشعاع.","مزج `2 kg` ماء عند `70°C` مع `2 kg` ماء عند `30°C`: الكتلتان متساويتان فتكون درجة الخليط `(70 + 30) ÷ 2 = 50°C`.","لأن الطاقة محفوظة، فما يفقده الجسم الساخن يكتسبه البارد. ويتوقف الانتقال عند تساوي الدرجتين لأن الحرارة تنتقل بسبب فرق درجة الحرارة فقط."],"الاتزان الحراري":["إذا وضعت يدك الباردة على كوب دافئ، تدفأ يدك ويبرد الكوب حتى يصلا إلى درجة واحدة. هذا هو الاتزان الحراري، وما يخرج من الساخن يدخل كله في البارد.","`1 kg` ماء عند `60°C` مع `3 kg` ماء عند `20°C`: `1 × (60 − T_f) = 3 × (T_f − 20)` ومنه `T_f = 120 ÷ 4 = 30°C`.","لأن الحرارة طاقة تنتقل بسبب فرق درجة الحرارة، فإذا تساوت الدرجتان توقف الانتقال. وبما أن الطاقة لا تفنى ولا تستحدث فمجموع الحرارة المفقودة والمكتسبة صفر."],"خطوات الحل":["ابدأ بالجسم الذي تعرف كل معطياته فاحسب حرارته، ثم اجعل حرارة الجسم الآخر مساوية لها، وبعدها أوجد المجهول. الأمر مثل ميزان: كفة الساخن تساوي كفة البارد.","ماء `0.2 kg` سخن من `20°C` إلى `30°C`: `Q = 0.2 × 4186 × 10 = 8372 J`، فالجسم الساخن فقد `8372 J` أيضا، ومنها نحل للمجهول.","لأن قانون حفظ الطاقة يربط الجسمين بمعادلة واحدة، فإذا عرفنا حرارة أحدهما عرفنا حرارة الآخر. لذلك يكفي أن يبقى مجهول واحد لنحل المعادلة."],"طرق انتقال الحرارة":["التوصيل مثل تمرير كرة يدا بيد في صف ثابت، والحمل مثل أن يحمل الشخص الكرة ويمشي بها، والإشعاع مثل رمي الكرة عبر الهواء دون حاجة لأحد في الطريق.","ملعقة معدنية في شاي ساخن يسخن مقبضها بالتوصيل، والماء في القدر يدور بالحمل، وحرارة الشمس تقطع نحو `1.5 × 10¹¹ m` من الفراغ إلى الأرض بالإشعاع.","في التوصيل تهتز الجزيئات وتنقل طاقتها لجاراتها، وفي الحمل يتمدد المائع الساخن فتقل كثافته فيرتفع. أما الإشعاع فموجات كهرومغناطيسية لا تحتاج وسطا ماديا."],"أمثلة الحقيبة التدريبية محلولة":["قطعة ألمنيوم ساخنة وضعت في ماء بارد، فبردت هي وسخن الماء حتى تساوت الدرجتان. نريد معرفة حرارة القطعة في البداية، وبما أن الماء سخن فالقطعة هي الأسخن.","نحاس `0.1 kg` (`c = 385 J/(kg·°C)`) في `0.2 kg` ماء عند `20°C` فاستقر الخليط عند `25°C`: حرارة الماء `0.2 × 4186 × 5 = 4186 J`، و `T₁ − 25 = 4186 ÷ 38.5 ≈ 108.7°C`، إذن `T₁ ≈ 133.7°C`.","لأن درجة الماء ارتفعت فهو الذي اكتسب الحرارة، والألمنيوم هو الذي فقدها. وبإهمال الوعاء تكون الطاقة محفوظة بين الجسمين فقط."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["نحسب أولا ما اكتسبه الماء من حرارة، ثم نقسمه على حاصل ضرب كتلة الألمنيوم في حرارته النوعية لنعرف كم انخفضت درجته، ثم نضيف درجة الاتزان.","لو كانت كتلة الألمنيوم `0.1 kg`: `m₁·c₁ = 0.1 × 899 = 89.9 J/°C`، و `T₁ − 25 = 2511.6 ÷ 89.9 ≈ 27.9°C`، إذن `T₁ ≈ 52.9°C`.","لأن الحرارة المفقودة من الألمنيوم تساوي الحرارة المكتسبة للماء، وكلتاهما تحسب بـ `Q = m·c·ΔT`. ونطرح الدرجة الأقل من الأعلى في كل جسم حتى تكون الكميتان موجبتين."],"رسم توضيحي 1":["عند خلط كمية من الماء الساخن مع كمية مساوية من الماء البارد، يعطي الساخن البارد حرارة حتى يلتقيا في المنتصف تماما.","`0.5 kg` ماء عند `90°C` مع `0.5 kg` ماء عند `10°C`: درجة الخليط `(90 + 10) ÷ 2 = 50°C`.","لأن الكتلتين والحرارة النوعية متساوية، فكل درجة يفقدها الساخن تقابلها درجة يكتسبها البارد. لذلك يتساوى مقدار التغير في الجهتين."],"رسم توضيحي 2":["المسعر يشبه الترمس: يحبس الحرارة داخله فلا تهرب إلى الخارج، فيتبادل الساخن والبارد الحرارة فيما بينهما فقط.","في مسعر فقد ماء ساخن `3000 J`، فيكتسب الماء البارد `3000 J` كاملة لأن المسعر يمنع تسرب الحرارة إلى الوسط.","لأن عزل الخليط عن الوسط يمنع ضياع الحرارة إلى الهواء المحيط. فتصبح الحرارة المفقودة مساوية للمكتسبة تماما وتصح معادلة الاتزان."],"رسم توضيحي 3":["حول نار المخيم ترى الطرق الثلاث: عصا معدنية يسخن طرفها بالتوصيل، والهواء الساخن يصعد فوق النار بالحمل، ووجهك يدفأ من بعيد بالإشعاع.","في قدر على موقد: قاع القدر يسخن بالتوصيل، والماء يدور فيه بالحمل حتى يصل إلى `100°C`، وتشعر بالدفء بجانب الموقد بالإشعاع.","الطرق تختلف في الآلية: اهتزاز الجزيئات في التوصيل، وحركة المائع في الحمل، وموجات كهرومغناطيسية في الإشعاع. لذلك يحتاج الأولان وسطا ماديا ولا يحتاجه الثالث."],"رسم توضيحي 4":["تخيل صفا من الناس يهز كل واحد جاره دون أن يتحرك أحد من مكانه، فتصل الهزة إلى آخر الصف. هكذا تنتقل الحرارة بالتوصيل.","ضع ملعقة معدنية طولها `0.15 m` في شاي عند `80°C`، فبعد قليل يسخن طرفها الذي في يدك مع أن المعدن نفسه لم يتحرك.","لأن الجزيئات الساخنة تهتز بقوة أكبر فتصطدم بجاراتها وتعطيها جزءا من طاقتها. والجزيئات في الصلب ثابتة في أماكنها، فتنتقل الطاقة وحدها دون المادة."],"رسم توضيحي 5":["الهواء البارد ثقيل فيهبط، والهواء الساخن خفيف فيصعد. لذلك نضع المكيف في الأعلى ليهبط برده، والمدفأة في الأسفل ليصعد دفؤها، فيدور الهواء في الغرفة كلها.","غرفة ارتفاعها `3 m`: مكيف قرب السقف يرسل هواء عند `18°C` فيهبط، ويرتفع الهواء الدافئ عند `30°C` إليه ليبرد، فتتكون دورة حمل كاملة.","لأن المائع الساخن يتمدد فتقل كثافته فيرتفع، والبارد كثافته أكبر فيهبط. وهذه الحركة المستمرة تكون تيارات الحمل التي تنقل الحرارة."],"مقارنة طرق انتقال الحرارة":["التوصيل يحدث غالبا في الصلب دون حركة المادة، والحمل في السوائل والغازات مع حركة المادة، والإشعاع لا يحتاج مادة أصلا ويعمل في الفراغ.","في الترمس: الفراغ بين الجدارين يمنع التوصيل والحمل، والطبقة اللامعة تقلل الإشعاع، فيبقى الشاي قريبا من `70°C` لساعات.","الفرق كله في حاجة كل طريقة إلى المادة: التوصيل يحتاج جزيئات متلامسة، والحمل يحتاج مائعا يتحرك. أما الإشعاع فطاقة موجات كهرومغناطيسية تسير في الفراغ."],"تطبيقات من الحياة":["نستعمل طرق انتقال الحرارة كل يوم: نختار الخشب أو البلاستيك للمقابض حتى لا نحترق، ونضع المكيف في الأعلى، ونلبس الملابس الفاتحة صيفا لتعكس أشعة الشمس.","خلط `4 kg` ماء ساخن عند `50°C` مع `4 kg` ماء بارد عند `20°C` للاستحمام يعطي درجة `(50 + 20) ÷ 2 = 35°C`.","لأن كل تطبيق يقلل طريقة انتقال غير مرغوبة أو يستفيد منها: العوازل تقلل التوصيل، وموضع المكيف يستفيد من الحمل، والأسطح اللامعة والفاتحة تعكس الإشعاع."],"تمرين 1 · مثال (صفحة 77)":["الماء سخن بمقدار 4 درجات، فنضرب كتلته في حرارته النوعية في مقدار التغير لنعرف كم جولا اكتسب.","`0.3 kg` ماء سخن من `20°C` إلى `25°C`: `Q = 0.3 × 4186 × 5 = 6279 J`.","لأن كمية الحرارة تزيد بزيادة الكتلة وبزيادة التغير في درجة الحرارة، وتعتمد على نوع المادة من خلال حرارتها النوعية. لذلك `Q = m·c·ΔT`."],"تمرين 2 · مثال (صفحة 77)":["نعرف كم جولا فقد الألمنيوم، فنقسمها على حاصل ضرب كتلته في حرارته النوعية لنعرف مقدار انخفاض درجته، ثم نضيف هذا الانخفاض إلى درجته النهائية.","نحاس `0.1 kg` (`c = 385 J/(kg·°C)`) فقد `3850 J` حتى برد إلى `30°C`: `ΔT = 3850 ÷ 38.5 = 100°C` و `Ti = 30 + 100 = 130°C`.","لأن الجسم الذي يفقد حرارة تنخفض درجته، فدرجته الابتدائية أعلى من النهائية. لذلك نضيف `ΔT` إلى الدرجة النهائية ولا نطرحه."]},"2-7":{"":["ورقة العمل تجمع أهم قوانين الوحدة: تحويل درجات الحرارة بين المقاييس، وحساب كمية الحرارة والسعة الحرارية والانصهار. كل سؤال يحتاج قانونا واحدا تعوض فيه بالوحدات الصحيحة.","تسخين `0.5 kg` ماء من `20°C` إلى `40°C` (`c = 4180 J/(kg·°C)`): `Q = 0.5 × 4180 × 20 = 41800 J`.","لأن كمية الحرارة تعتمد على الكتلة ونوع المادة والتغير في درجة الحرارة، والمقاييس المختلفة تصف الدرجة نفسها بأرقام مختلفة. لذلك نحتاج القوانين والتحويلات معا."],"ما تحتاجه لحل ورقة العمل":["هذه قائمة الأدوات قبل الحل: قوانين التحويل بين سلسيوس وكلفن وفهرنهايت، وقوانين الحرارة والسعة الحرارية والانصهار، وأهم تنبيه أن الكتلة تكون بالكيلوجرام.","`50 g` جليد عند `0°C`: نحول الكتلة إلى `0.05 kg` ثم `Q = 0.05 × 336000 = 16800 J`.","لأن الحرارة النوعية وحرارة الانصهار معطاة لكل كيلوجرام، فلو عوضنا بالجرام لكبر الناتج ألف مرة. ولكل نوع من التغير قانونه: تغير الدرجة أو تغير الحالة."],"حل ورقة العمل":["الطاقة الداخلية هي كل ما في الجسم من طاقة جزيئات، ودرجة الحرارة متوسط طاقة حركتها، وكمية الحرارة هي الطاقة المنتقلة. والحرارة النوعية تخص `1 kg`، والسعة الحرارية تخص الجسم كله.","حديد `2 kg` حرارته النوعية `460 J/(kg·°C)`: السعة الحرارية `C = 2 × 460 = 920 J/°C`، أي يحتاج `920 J` لكل درجة.","لأن الحرارة طاقة تنتقل بسبب فرق درجة الحرارة، فتنتقل من الأسخن إلى الأبرد. والسعة الحرارية تكبر مع الكتلة لأن الجسم الأكبر فيه جزيئات أكثر تحتاج طاقة."],"سؤال ٢: درجة حرارة جسم ساخن 200 °C، ما درجة حرارته بالكلفن؟ (صفحة 79)":["مقياس كلفن يبدأ من الصفر المطلق، وصفر سلسيوس يقابل `273 K`. لذلك نضيف 273 إلى أي درجة سلسيوس.","`100°C` بالكلفن: `K = 100 + 273 = 373 K`.","لأن تدريج الكلفن بحجم تدريج سلسيوس نفسه، لكن صفره أقل بـ 273 درجة. فالفرق بين المقياسين إزاحة ثابتة فقط."],"سؤال ٣: درجة حرارة جسم 150 °C، ما درجة حرارته على مقياس فهرنهايت؟ (صفحة 79)":["درجة فهرنهايت أصغر من درجة سلسيوس، فكل درجة سلسيوس تساوي 1.8 درجة فهرنهايت، ثم نضيف 32 لأن الماء يتجمد عند `32°F`.","`50°C` بالفهرنهايت: `F = 1.8 × 50 + 32 = 122°F`.","لأن بين تجمد الماء وغليانه 100 درجة على سلسيوس و 180 درجة على فهرنهايت، والنسبة `180 ÷ 100 = 1.8`. ونقطة البداية على فهرنهايت هي 32 لا صفر."],"سؤال ٤: درجة حرارة جسم 80 °F، ما درجة حرارته على مقياس سلسيوس؟ (صفحة 80)":["نعكس الخطوات: نطرح 32 أولا لنرجع إلى نقطة التجمد، ثم نقسم على 1.8 لأن درجة فهرنهايت أصغر.","`104°F` بالمئوي: `C = (104 − 32) ÷ 1.8 = 72 ÷ 1.8 = 40°C`.","لأن هذا القانون عكس قانون `F = 1.8C + 32`، فنلغي الإضافة بالطرح ثم نلغي الضرب بالقسمة."],"سؤال ٤: درجة حرارة جسم 80 °F، ما درجة حرارته على مقياس سلسيوس؟ (صفحة 80) (تابع)":["النتيجة قرابة 27 درجة سلسيوس، وهي درجة جو دافئ معتدل، وهذا منطقي لأن `80°F` تعني يوما دافئا.","`68°F`: `C = (68 − 32) ÷ 1.8 = 36 ÷ 1.8 = 20°C`.","نقرب الناتج لأن القسمة على 1.8 لا تعطي عددا صحيحا هنا. ونتحقق بعكس التحويل: `1.8 × 26.67 + 32 ≈ 80°F`."],"سؤال ٥: ما الحرارة اللازمة لتسخين 20 g من الماء من 30 °C إلى 90 °C؟ (صفحة 80)":["نريد معرفة الطاقة اللازمة لرفع حرارة قليل من الماء 60 درجة. نحول الجرامات إلى كيلوجرام، ثم نضرب الكتلة في الحرارة النوعية في التغير.","`50 g` ماء من `20°C` إلى `60°C`: `Q = 0.05 × 4180 × 40 = 8360 J`.","لأن الحرارة النوعية للماء معطاة لكل كيلوجرام، فالكتلة يجب أن تكون بالكيلوجرام. والتغير `ΔT` هو الفرق بين الدرجة النهائية والابتدائية."],"سؤال ٥: ما الحرارة اللازمة لتسخين 20 g من الماء من 30 °C إلى 90 °C؟ (صفحة 80) (تابع)":["بعد الضرب نحصل على عدد الجولات اللازمة، وهي طاقة صغيرة نسبيا لأن كمية الماء قليلة.","لو كانت الكتلة `40 g` بدل `20 g` لتضاعفت الحرارة: `Q = 0.04 × 4180 × 60 = 10032 J`.","لأن `Q` تتناسب طرديا مع الكتلة، فمضاعفة الكتلة تضاعف الحرارة اللازمة للتغير نفسه في الدرجة."],"سؤال ٦: احسب السعة الحرارية لقطعة من الحديد كتلتها 0.5 kg وحرارتها النوعية 460 J/(kg·°C) (صفحة 81)":["السعة الحرارية تخبرنا كم جولا يحتاج الجسم كله ليسخن درجة واحدة. نضرب كتلة القطعة في حرارتها النوعية.","قطعة نحاس `0.4 kg` و `c = 385 J/(kg·°C)`: `C = 0.4 × 385 = 154 J/°C`.","لأن الحرارة النوعية تخص كل كيلوجرام، والجسم قد يكون أكبر أو أصغر من كيلوجرام. فنضرب في الكتلة لنحصل على ما يحتاجه الجسم كله."],"سؤال ٧: احسب كمية الحرارة اللازمة لصهر 20 g من الجليد عند 0 °C (صفحة 81)":["الجليد عند الصفر يحتاج طاقة ليتحول إلى ماء دون أن تتغير درجته. نضرب الكتلة بالكيلوجرام في حرارة الانصهار.","`100 g` جليد عند `0°C`: `Q = 0.1 × 336000 = 33600 J`.","لأن الطاقة المكتسبة أثناء الانصهار تستعمل في فك الروابط بين جزيئات الجليد لا في رفع درجته. لذلك لا يظهر `ΔT` في القانون."],"سؤال ٧: احسب كمية الحرارة اللازمة لصهر 20 g من الجليد عند 0 °C (صفحة 81) (تابع)":["النتيجة هي الطاقة اللازمة لصهر هذه الكمية كلها، وبعدها يصبح لدينا ماء عند `0°C`.","`0.25 kg` جليد: `Q = 0.25 × 336000 = 84000 J`.","لأن درجة الحرارة تبقى ثابتة أثناء الانصهار حتى يذوب الجليد كله، فكل الطاقة تذهب لتغيير الحالة."],"سؤال ٨: قطعة حديد كتلتها 3 kg عند 560 °C أُلقيت على لوح جليد كتلته 3 kg عند 0 °C فانصهر جزء منه (صفحة 82)":["الحديد الساخن جدا يبرد حتى الصفر، وكل الحرارة التي يفقدها تذهب لصهر الجليد. فنحسب حرارة الحديد ثم نقسمها على حرارة الانصهار.","حديد `1 kg` عند `336°C` (`c = 460 J/(kg·°C)`): `Q = 1 × 460 × 336 = 154560 J`، فيصهر `154560 ÷ 336000 = 0.46 kg` من الجليد.","لأن الطاقة محفوظة: الحرارة المفقودة من الحديد تساوي الحرارة المكتسبة للجليد. والجليد عند `0°C` يستعمل هذه الحرارة للانصهار فقط دون أن تتغير درجته."],"سؤال ٨: قطعة حديد كتلتها 3 kg عند 560 °C أُلقيت على لوح جليد كتلته 3 kg عند 0 °C فانصهر جزء منه (صفحة 82) (تابع)":["انصهر جزء من الجليد فقط، فنطرحه من الكتلة الكلية لنعرف الباقي، ثم نحسب ما يحتاجه الباقي ليذوب.","لو كان اللوح `3 kg` وانصهر منه `1.8 kg`: الباقي `1.2 kg` ويحتاج `Q = 1.2 × 336000 = 403200 J`.","لأن الحديد وصل إلى `0°C` فتوقف انتقال الحرارة، فلم يعد قادرا على صهر المزيد. والباقي يحتاج حرارة جديدة من مصدر آخر."],"سؤال ٩: قطعة نحاس كتلتها 20 g اكتسبت 600 J فتغيرت درجة حرارتها 80 °C، أوجد الحرارة النوعية للنحاس (صفحة 83)":["نعرف الحرارة والكتلة والتغير، ونبحث عن الحرارة النوعية. نعوض في القانون ثم نقسم الحرارة على حاصل ضرب الكتلة في التغير.","ألمنيوم `0.05 kg` اكتسب `1800 J` فارتفعت درجته `40°C`: `c = 1800 ÷ (0.05 × 40) = 1800 ÷ 2 = 900 J/(kg·°C)`.","لأن `c = Q ÷ (m·ΔT)` مأخوذ من قانون الحرارة نفسه بعد عزل المجهول. والحرارة النوعية صفة للمادة، فقياسها يساعد على معرفة نوعها."],"سؤال ٩: قطعة نحاس كتلتها 20 g اكتسبت 600 J فتغيرت درجة حرارتها 80 °C، أوجد الحرارة النوعية للنحاس (صفحة 83) (تابع)":["بعد القسمة نحصل على الحرارة النوعية للنحاس، وهي أقل كثيرا من حرارة الماء النوعية، أي أن النحاس يسخن بسرعة.","نحاس `0.1 kg` اكتسب `3000 J` فارتفعت درجته `80°C`: `c = 3000 ÷ (0.1 × 80) = 3000 ÷ 8 = 375 J/(kg·°C)`.","لأن حرارة النحاس النوعية صغيرة، فالكمية نفسها من الحرارة ترفع درجته كثيرا. لذلك تسخن الأواني النحاسية بسرعة."],"سؤال ١٠: السعة الحرارية لوعاء ألمنيوم 270 J/°C والحرارة النوعية للألمنيوم 900 J/(kg·°C)، أوجد كتلة الوعاء (صفحة 83)":["نعرف كم يحتاج الوعاء كله لكل درجة، وكم يحتاج كل كيلوجرام. فنقسم الأولى على الثانية لنعرف عدد الكيلوجرامات.","وعاء حديد سعته الحرارية `920 J/°C` و `c = 460 J/(kg·°C)`: `m = 920 ÷ 460 = 2 kg`.","لأن `C = m·c`، فالسعة الحرارية تساوي ما يحتاجه الكيلوجرام الواحد مضروبا في عدد الكيلوجرامات. وبالقسمة نعزل الكتلة."],"سؤال ١٠: السعة الحرارية لوعاء ألمنيوم 270 J/°C والحرارة النوعية للألمنيوم 900 J/(kg·°C)، أوجد كتلة الوعاء (صفحة 83) (تابع)":["الناتج بالكيلوجرام، ويمكن تحويله إلى جرام بالضرب في 1000 ليسهل تخيله.","وعاء ألمنيوم سعته الحرارية `450 J/°C`: `m = 450 ÷ 900 = 0.5 kg = 500 g`.","لأن وحدة الناتج `(J/°C) ÷ (J/(kg·°C))` تساوي `kg`، فتحقق الوحدات يؤكد صحة القانون."],"رسم توضيحي 1":["عند خلط كمية من الماء الساخن مع كمية مساوية من الماء البارد، يلتقيان في منتصف المسافة بين الدرجتين تماما.","`2 kg` ماء عند `80°C` مع `2 kg` ماء عند `40°C`: درجة الخليط `(80 + 40) ÷ 2 = 60°C`.","لأن الكتلتين والحرارة النوعية متساوية، فكل درجة يفقدها الساخن تقابلها درجة يكتسبها البارد."],"رسم توضيحي 2":["المسعر وعاء معزول يشبه الترمس، يمنع الحرارة من الهروب إلى الخارج، فيتبادل الساخن والبارد الحرارة فيما بينهما فقط.","ماء ساخن في مسعر فقد `4200 J`، فيكتسب الماء البارد `4200 J` كاملة لأن الحرارة لا تتسرب إلى الخارج.","لأن العزل يمنع ضياع الحرارة إلى الوسط المحيط، فتصبح الحرارة المفقودة مساوية للمكتسبة تماما وتصح معادلة الاتزان."],"تمرين 1 · سؤال ٢ (صفحة 79)":["لتحويل سلسيوس إلى كلفن نضيف 273 فقط، لأن المقياسين متشابهان في حجم الدرجة ويختلفان في نقطة الصفر.","`27°C`: `K = 27 + 273 = 300 K`.","لأن صفر كلفن هو الصفر المطلق، ويقع تحت صفر سلسيوس بـ 273 درجة. فنضيف هذه الإزاحة لكل قراءة."],"تمرين 2 · سؤال ٣ (صفحة 79)":["نضرب درجة سلسيوس في 1.8 ثم نضيف 32، فنحصل على قراءة فهرنهايت.","`20°C`: `F = 1.8 × 20 + 32 = 68°F`.","لأن كل درجة سلسيوس تعادل 1.8 درجة فهرنهايت، وتجمد الماء على فهرنهايت يقع عند 32 لا عند الصفر."],"تمرين 3 · سؤال ٤ (صفحة 80)":["نطرح 32 من قراءة فهرنهايت، ثم نقسم الناتج على 1.8 لنحصل على سلسيوس.","`212°F`: `C = (212 − 32) ÷ 1.8 = 180 ÷ 1.8 = 100°C`.","لأن هذا عكس قانون التحويل إلى فهرنهايت، فنلغي إضافة 32 أولا ثم نلغي الضرب في 1.8 بالقسمة."],"تمرين 4 · سؤال ٥ (صفحة 80)":["نحول الجرامات إلى كيلوجرام، ونحسب التغير في الدرجة، ثم نضرب الكتلة في الحرارة النوعية في التغير.","`30 g` ماء من `25°C` إلى `75°C`: `Q = 0.03 × 4180 × 50 = 6270 J`.","لأن الحرارة اللازمة تزيد بزيادة الكتلة والتغير في الدرجة، وتعتمد على نوع المادة. والحرارة النوعية معطاة لكل كيلوجرام فلا بد من تحويل الكتلة."],"تمرين 5 · سؤال ٦ (صفحة 81)":["السعة الحرارية هي ما يحتاجه الجسم كله ليسخن درجة واحدة، فنضرب كتلته في حرارته النوعية.","حديد `1.5 kg` و `c = 460 J/(kg·°C)`: `C = 1.5 × 460 = 690 J/°C`.","لأن الحرارة النوعية تخص كيلوجراما واحدا، فالجسم الأكبر كتلة يحتاج حرارة أكثر لكل درجة."],"تمرين 6 · سؤال ٧ (صفحة 81)":["الجليد عند الصفر يحتاج حرارة ليذوب دون أن تتغير درجته، فنضرب كتلته بالكيلوجرام في حرارة الانصهار.","`40 g` جليد عند `0°C`: `Q = 0.04 × 336000 = 13440 J`.","لأن حرارة الانصهار هي الطاقة اللازمة لتحويل كيلوجرام واحد من الصلب إلى السائل دون تغير في الدرجة، فنضربها في الكتلة."],"تمرين 7 · سؤال ٨ (صفحة 82)":["نحسب الحرارة التي يفقدها الحديد حتى يبرد إلى الصفر، ثم نقسمها على حرارة الانصهار لنعرف كم كيلوجراما من الجليد تذيب.","حديد `2 kg` عند `420°C`: `Q = 2 × 460 × 420 = 386400 J`، فيصهر `386400 ÷ 336000 = 1.15 kg` من الجليد.","لأن الطاقة محفوظة: كل جول يفقده الحديد يكتسبه الجليد. والجليد عند الصفر يستعمل الحرارة للانصهار لا لرفع درجته."],"تمرين 8 · سؤال ٨ (صفحة 82)":["نطرح الكتلة التي ذابت من الكتلة الكلية لنعرف الباقي، ثم نضرب الباقي في حرارة الانصهار.","لوح `2 kg` انصهر منه `1.15 kg`: الباقي `0.85 kg` ويحتاج `Q = 0.85 × 336000 = 285600 J`.","لأن الحديد توقف عن إعطاء الحرارة بعد وصوله إلى `0°C`، فالجليد الباقي يحتاج حرارته الخاصة ليذوب."],"تمرين 9 · سؤال ٩ (صفحة 83)":["نعوض بالحرارة والكتلة والتغير في قانون الحرارة، ثم نقسم لنعزل الحرارة النوعية.","معدن `0.04 kg` امتص `1200 J` فارتفعت درجته `60°C`: `c = 1200 ÷ (0.04 × 60) = 1200 ÷ 2.4 = 500 J/(kg·°C)`.","لأن `Q = m·c·ΔT` فيه مجهول واحد هنا هو `c`، فنقسم الطرفين على `m·ΔT` لنحصل عليه."],"تمرين 10 · سؤال ١٠ (صفحة 83)":["نقسم السعة الحرارية للوعاء على الحرارة النوعية لمادته، فنعرف كتلته.","وعاء نحاس سعته الحرارية `77 J/°C` و `c = 385 J/(kg·°C)`: `m = 77 ÷ 385 = 0.2 kg`.","لأن السعة الحرارية `C = m·c`، فهي ما يحتاجه كل كيلوجرام مضروبا في عدد الكيلوجرامات، وبالقسمة نجد الكتلة."]},"2-8":{"":["هذا الدرس يراجع الوحدة كلها: قياس درجة الحرارة وتحويلها بين المقاييس، وحساب كمية الحرارة، وطرق انتقالها، ثم حل تمارين الوحدة خطوة خطوة.","`25°C` تساوي `K = 25 + 273 = 298 K`، وتساوي `F = 1.8 × 25 + 32 = 77°F`.","لأن مسائل الوحدة كلها تقوم على فكرتين: الحرارة طاقة تنتقل بسبب فرق درجة الحرارة، والطاقة محفوظة. ومنهما تخرج القوانين كلها."],"مراجعة الوحدة الثالثة":["درجة الحرارة تخبرك كم الجسم ساخن، والحرارة هي الطاقة التي تنتقل. والطاقة تنتقل بالتوصيل في الصلب، وبالحمل في السوائل والغازات، وبالإشعاع حتى في الفراغ.","رفع `2 kg` ماء بمقدار `10°C` يحتاج `Q = 2 × 4180 × 10 = 83600 J`، وسعته الحرارية `C = 2 × 4180 = 8360 J/°C`.","لأن درجة الحرارة مرتبطة بمتوسط طاقة حركة الجزيئات، فإضافة الحرارة تزيد حركتها فترتفع الدرجة. وعند تغير الحالة تذهب الحرارة لتغيير الحالة فتبقى الدرجة ثابتة."],"مسألة سخان كهربائي":["السخان يعطي كل ثانية عددا ثابتا من الجولات هو قدرته. فإذا عرفنا كم جولا يحتاجه الماء، قسمناه على القدرة فعرفنا عدد الثواني.","سخان `500 W` يسخن `0.5 kg` ماء بمقدار `40°C`: `Q = 0.5 × 4180 × 40 = 83600 J` و `t = 83600 ÷ 500 = 167.2 s`.","لأن القدرة هي الطاقة في وحدة الزمن، فالطاقة الكلية `E = P·t`. وبإهمال الفقد تتحول هذه الطاقة كلها إلى حرارة يكتسبها الماء."],"تمارين الوحدة محلولة":["في التوصيل تبقى جزيئات المادة في أماكنها، لكنها تهتز وتمرر الطاقة لجاراتها، مثل صف من الناس يمرر دلوا يدا بيد.","ملعقة معدنية طولها `0.2 m` في شاي عند `80°C` يدفأ مقبضها بعد قليل، مع أن المعدن نفسه لم يتحرك.","لأن الجزيئات الأسخن تهتز بطاقة أكبر فتصطدم بجاراتها وتنقل لها جزءا من طاقتها. وفي الصلب لا تتحرك الجزيئات من أماكنها، فتنتقل الطاقة وحدها."],"اختر الإجابة ٢: انتقال الحرارة بحركة المادة المسخنة (صفحة 84)":["في الحمل يحمل الماء أو الهواء الساخن الحرارة معه وهو يتحرك، مثل شخص يحمل كوبا ساخنا ويمشي به إلى مكان آخر.","في قدر ماء على النار يسخن الماء في القاع فيصعد، وينزل الماء الأبرد مكانه، فيسخن الماء كله حتى يقترب من `100°C`.","لأن المائع الساخن يتمدد فتقل كثافته فيرتفع، والبارد كثافته أكبر فيهبط. وهذه الحركة تنقل المادة الساخنة نفسها ومعها الحرارة."],"اختر الإجابة ٣: انتقال الحرارة بواسطة الأشعة (صفحة 84)":["الإشعاع مثل ضوء الشمس: يصل إلينا عبر الفضاء الخالي دون أن يحتاج هواء أو ماء ينقله.","ضوء الشمس يقطع نحو `1.5 × 10¹¹ m` في قرابة `500 s` ليصل إلى الأرض عبر الفراغ.","لأن الإشعاع موجات كهرومغناطيسية، وهذه الموجات تنتشر بنفسها ولا تحتاج جزيئات تنقلها. لذلك هو الطريقة الوحيدة التي تعمل في الفراغ."],"اختر الإجابة ٤: درجة حرارة الرياض بالفهرنهايت (صفحة 84)":["لتحويل درجة سلسيوس إلى فهرنهايت نضربها في 1.8 لأن درجة فهرنهايت أصغر، ثم نضيف 32 لأن الماء يتجمد عند 32 على فهرنهايت.","`35°C`: `F = 1.8 × 35 + 32 = 63 + 32 = 95°F`.","لأن المسافة بين التجمد والغليان 100 درجة سلسيوس و 180 درجة فهرنهايت، فالنسبة 1.8. وصفر سلسيوس يقابل 32 فهرنهايت فنضيفها."],"اختر الإجابة ٥: تحويل درجة من الكلفن إلى الفهرنهايت (صفحة 84)":["لا يوجد طريق مباشر من الكلفن إلى فهرنهايت، فنمر بمحطة وسطى هي سلسيوس: نطرح 273 أولا ثم نحول إلى فهرنهايت.","`310 K`: `C = 310 − 273 = 37°C` ثم `F = 1.8 × 37 + 32 = 98.6°F`.","لأن قوانين التحويل المعطاة تربط كل مقياس بسلسيوس، فسلسيوس هو المرجع المشترك. والتحويل على مرحلتين يقلل الخطأ."],"اختر الإجابة ٥: تحويل درجة من الكلفن إلى الفهرنهايت (صفحة 84) (تابع)":["بعد معرفة الدرجة بالسلسيوس وضربها في 1.8، يبقى أن نضيف 32 لنصل إلى قراءة فهرنهايت.","`273 K` تساوي `0°C`، و `F = 1.8 × 0 + 32 = 32°F`، وهي درجة تجمد الماء.","لأن صفر سلسيوس يقابل 32 على فهرنهايت، فلا بد من إضافة 32 بعد الضرب حتى تبدأ القراءة من النقطة الصحيحة."],"اختر الإجابة ٦: تحويل درجة من المئوي إلى الكلفن (صفحة 84)":["الكلفن يبدأ من الصفر المطلق، فنضيف 273 إلى درجة سلسيوس، ونكتب الوحدة `K` دون رمز الدرجة.","`−10°C`: `K = −10 + 273 = 263 K`.","لأن حجم الدرجة في المقياسين متساو، والفرق بينهما في نقطة الصفر فقط. وصفر سلسيوس يقابل `273 K`."],"اختر الإجابة ٧: تحويل درجة من الفهرنهايت إلى المئوي (صفحة 85)":["نرجع من فهرنهايت إلى سلسيوس بعكس الخطوات: نطرح 32 أولا، ثم نقسم على 1.8.","`59°F`: `C = (59 − 32) ÷ 1.8 = 27 ÷ 1.8 = 15°C`.","لأن هذا القانون عكس قانون التحويل إلى فهرنهايت، وفي العكس نبدأ بإلغاء آخر عملية وهي إضافة 32."],"اختر الإجابة ٨: درجة حرارة الصيف في الرياض بالفهرنهايت (صفحة 85)":["يوم صيفي حار في الرياض يصبح رقما أكبر بالفهرنهايت، لأن درجة فهرنهايت أصغر والمقياس يبدأ من 32.","`45°C`: `F = 1.8 × 45 + 32 = 81 + 32 = 113°F`.","لأن كل درجة سلسيوس تساوي 1.8 درجة فهرنهايت، وصفر سلسيوس يقابل 32 فهرنهايت. لذلك تكون القراءة بالفهرنهايت أكبر للدرجات الموجبة."],"اختر الإجابة ٩: مبدأ عمل الترمومتر الزئبقي (صفحة 85)":["عندما يسخن الزئبق يتمدد فيرتفع في الأنبوب الرفيع، وعندما يبرد ينكمش فينخفض، فنقرأ الدرجة من طول العمود.","ترمومتر طبي يرتفع زئبقه إلى نحو `37°C` في جسم سليم، وإلى نحو `39°C` عند الحمى.","لأن الزئبق يتمدد بانتظام مع ارتفاع درجة الحرارة، وكتلته لا تتغير. والأنبوب الشعري الرفيع يجعل التمدد الصغير ظاهرا بوضوح."],"اختر الإجابة ١٠: معنى القراءة الفهرنهايتية لتجمد الماء (صفحة 85)":["`32°F` هي النقطة التي يتجمد عندها الماء على مقياس فهرنهايت، وتقابل الصفر على سلسيوس.","`212°F`: `C = (212 − 32) ÷ 1.8 = 100°C`، وهي درجة غليان الماء.","لأن مقياس فهرنهايت جعل تجمد الماء عند 32 لا عند الصفر. والتحويل `(32 − 32) ÷ 1.8` يعطي صفرا على سلسيوس."],"اختر الإجابة ١١: زمن تسخين الماء بسخان كهربائي (صفحة 85)":["السخان يعطي كل ثانية `200 J`. نحسب الطاقة التي يحتاجها الماء ليصل إلى الغليان، ثم نقسمها على 200 لنعرف عدد الثواني.","سخان `400 W` و `0.2 kg` ماء من `20°C` إلى `100°C`: `Q = 0.2 × 4187 × 80 = 66992 J` و `t = 66992 ÷ 400 ≈ 167.5 s`.","لأن القدرة هي الطاقة المعطاة في الثانية، فالطاقة الكلية `P·t`. وبافتراض أن الماء يمتصها كلها، نساويها بـ `m·c·ΔT`."],"اختر الإجابة ١١: زمن تسخين الماء بسخان كهربائي (صفحة 85) (تابع)":["بعد حساب الحرارة اللازمة نقسمها على القدرة، فيخرج الزمن بالثانية، وهو أقل من ثلاث دقائق.","لو كانت قدرة السخان `400 W` للماء نفسه: `t = 32239.9 ÷ 400 ≈ 80.6 s`، أي نصف الزمن.","لأن الزمن يتناسب عكسيا مع القدرة: السخان الأقوى يعطي جولات أكثر كل ثانية، فيصل الماء إلى الغليان أسرع."],"صح وخطأ ١: اتجاه انتقال الحرارة تلقائيًا (صفحة 86)":["الحرارة تنتقل وحدها من الأسخن إلى الأبرد، مثل الماء الذي ينساب من الأعلى إلى الأسفل لا العكس.","كوب شاي عند `80°C` في غرفة عند `25°C` يبرد حتى يقترب من `25°C`، ولا يسخن من تلقاء نفسه.","لأن الحرارة تنتقل بسبب فرق درجة الحرارة، فالجزيئات الأسرع حركة تعطي طاقة للأبطأ. لذلك لا تنتقل الحرارة تلقائيا في الاتجاه المعاكس."],"صح وخطأ ٢: الفرق بين كمية الحرارة ودرجة الحرارة (صفحة 86)":["درجة الحرارة تخبرك كم الجسم ساخن، وكمية الحرارة تخبرك كم طاقة انتقلت. فكوب ماء مغلي وقدر ماء مغلي لهما الدرجة نفسها، لكن القدر يحتاج حرارة أكثر بكثير.","رفع `1 kg` ماء بمقدار `10°C` يحتاج `41800 J`، ورفع `2 kg` بالمقدار نفسه يحتاج `83600 J`، مع أن التغير في الدرجة واحد.","لأن درجة الحرارة تقيس متوسط طاقة حركة الجزيئات، أما كمية الحرارة فطاقة منتقلة تعتمد أيضا على الكتلة ونوع المادة."],"صح وخطأ ٣: المنطاد الهوائي وتيارات الحمل (صفحة 86)":["نار المنطاد تسخن الهواء داخله فيصبح أخف من الهواء الخارجي، فيرتفع ويرفع المنطاد معه.","هواء المنطاد يسخن إلى نحو `100°C` بينما الهواء الخارجي عند `20°C`، فيكون الهواء الداخلي أقل كثافة فيرتفع.","لأن الغاز الساخن يتمدد فتقل كثافته، فيدفعه الهواء الأبرد الأكبر كثافة إلى أعلى. وهذا هو مبدأ تيارات الحمل."],"صح وخطأ ٤: الضوء الأصفر والحمل الحراري (صفحة 86)":["ضوء المصباح يصل إلى عينك دون أن يتحرك الهواء ليحمله، فهو إشعاع لا حمل.","ضوء مصباح على بعد `2 m` يصل إليك في نحو `7 × 10⁻⁹ s`، ولا يمكن لتيار هواء أن ينقله بهذه السرعة.","لأن الضوء موجات كهرومغناطيسية تنتشر بنفسها حتى في الفراغ. أما الحمل فيحتاج مائعا ساخنا يتحرك وينقل الحرارة معه."],"صح وخطأ ٥: النقطتان الثابتتان على المقياس المئوي (صفحة 86)":["على المقياس المئوي اختير تجمد الماء ليكون صفرا وغليانه ليكون 100، ثم قسمت المسافة بينهما إلى 100 جزء متساو.","ماء يتجمد عند `0°C` ويغلي عند `100°C`، والمسافة بينهما `100` درجة تقابل `180` درجة على فهرنهايت.","لأن تجمد الماء النقي وغليانه عند الضغط الجوي المعتاد يحدثان دائما عند الدرجة نفسها، فهما نقطتان ثابتتان يسهل تكرارهما."],"صح وخطأ ٦: الحالة التي يصل إليها خليط من الماء الساخن والبارد (صفحة 86)":["عند خلط ماء ساخن ببارد يعطي الساخن البارد حرارة حتى يصبح الخليط كله بدرجة واحدة، وهذه الحالة هي الاتزان الحراري.","`1 kg` ماء عند `70°C` مع `1 kg` ماء عند `10°C`: درجة الخليط `(70 + 10) ÷ 2 = 40°C`.","لأن انتقال الحرارة سببه فرق درجة الحرارة، فإذا تساوت الدرجتان توقف الانتقال. والحرارة المفقودة تساوي المكتسبة لحفظ الطاقة."],"صح وخطأ ٧: تحول الثلج إلى ماء (صفحة 86)":["الثلج يأخذ حرارة فيتحول من صلب إلى سائل، وتبقى درجته صفرا حتى يذوب كله، وهذا هو الانصهار.","صهر `0.5 kg` ثلج عند `0°C`: `Q = 0.5 × 336000 = 168000 J`.","لأن الحرارة المكتسبة أثناء الانصهار تستعمل في فك الروابط بين الجزيئات لا في زيادة سرعتها، لذلك تبقى الدرجة ثابتة."],"صح وخطأ ٨: الماء سائل مثالي للتبريد والتسخين (صفحة 86)":["الماء يشبه إسفنجة كبيرة للحرارة: يمتص كثيرا منها ولا ترتفع درجته إلا قليلا، لذلك يبرد محرك السيارة جيدا.","`1 kg` ماء يمتص `41800 J` فترتفع درجته `10°C` فقط، أما `1 kg` حديد (`c = 460 J/(kg·°C)`) فترتفع درجته بالحرارة نفسها نحو `91°C`.","لأن الحرارة النوعية للماء كبيرة، فيحتاج كمية كبيرة من الحرارة لكل درجة تغير. لذلك يخزن الحرارة وينقلها دون أن يسخن بسرعة."],"رسم توضيحي 1":["الحرارة تنتقل بثلاث طرق: بالتلامس داخل الصلب، وبحركة السوائل والغازات، وبالموجات التي تعبر الفراغ.","في قدر على موقد: القاع يسخن بالتوصيل، والماء يدور بالحمل حتى يقترب من `100°C`، ويداك تدفآن من بعيد بالإشعاع.","لأن آلية كل طريقة مختلفة: اهتزاز الجزيئات، أو حركة المائع، أو موجات كهرومغناطيسية. لذلك يحتاج الأولان وسطا ماديا ولا يحتاجه الثالث."],"رسم توضيحي 2":["الهواء البارد ثقيل فيهبط، والساخن خفيف فيصعد. لذلك نضع المكيف في الأعلى والمدفأة في الأسفل ليدور الهواء في الغرفة كلها.","مدفأة في أسفل غرفة ارتفاعها `3 m` تسخن الهواء إلى `35°C` فيصعد إلى السقف، وينزل الهواء الأبرد عند `20°C` ليسخن بدوره.","لأن المائع الساخن يتمدد فتقل كثافته فيرتفع، والبارد كثافته أكبر فيهبط، فتتكون تيارات حمل تنقل الحرارة إلى كل الغرفة."],"ملخص قوانين الوحدة":["هذا الجدول يجمع كل قوانين الوحدة ووحداتها في مكان واحد: التحويلات، وكمية الحرارة، والسعة الحرارية، والانصهار، والاتزان، وطاقة السخان.","سخان `1000 W` يعمل `60 s` يعطي `E = 1000 × 60 = 60000 J`، وهي تصهر `60000 ÷ 336000 ≈ 0.18 kg` من الجليد عند `0°C`.","لأن هذه القوانين تعبر عن الطاقة نفسها بطرق مختلفة، ووحدة الطاقة فيها كلها الجول. لذلك يمكن ربط قانون بآخر بمساواة الطاقة."],"تمرين 1 · اختر الإجابة ٤ (صفحة 84)":["نضرب درجة سلسيوس في 1.8 ثم نضيف 32 لنحصل على فهرنهايت.","`40°C`: `F = 1.8 × 40 + 32 = 104°F`.","لأن درجة سلسيوس الواحدة تعادل 1.8 درجة فهرنهايت، وتجمد الماء على فهرنهايت عند 32 لا عند الصفر."],"تمرين 2 · اختر الإجابة ٥ (صفحة 84)":["نحول الكلفن إلى سلسيوس بطرح 273، ثم نحول سلسيوس إلى فهرنهايت.","`323 K`: `C = 323 − 273 = 50°C` ثم `F = 1.8 × 50 + 32 = 122°F`.","لأن القوانين المتاحة تربط كلا من الكلفن وفهرنهايت بسلسيوس، فنستعمله جسرا بين المقياسين."],"تمرين 3 · اختر الإجابة ٦ (صفحة 84)":["نضيف 273 إلى درجة سلسيوس فنحصل على الكلفن.","`37°C`: `K = 37 + 273 = 310 K`.","لأن الكلفن والسلسيوس متساويان في حجم الدرجة، والفرق بينهما 273 في نقطة الصفر فقط."],"تمرين 4 · اختر الإجابة ٧ (صفحة 85)":["نطرح 32 من قراءة فهرنهايت، ثم نقسم على 1.8 فنحصل على سلسيوس.","`86°F`: `C = (86 − 32) ÷ 1.8 = 54 ÷ 1.8 = 30°C`.","لأن هذا عكس قانون التحويل إلى فهرنهايت، فنلغي إضافة 32 ثم نلغي الضرب في 1.8."],"تمرين 5 · اختر الإجابة ٨ (صفحة 85)":["نضرب درجة الصيف بالسلسيوس في 1.8 ثم نضيف 32.","`25°C`: `F = 1.8 × 25 + 32 = 45 + 32 = 77°F`.","لأن المسافة بين التجمد والغليان 100 درجة سلسيوس و 180 درجة فهرنهايت، وفهرنهايت يبدأ من 32."],"تمرين 6 · اختر الإجابة ١١ (صفحة 85)":["نحسب الحرارة التي يحتاجها الماء ليصل إلى الغليان، ثم نقسمها على قدرة السخان لنحصل على الزمن.","سخان `250 W` و `0.1 kg` ماء من `25°C` إلى `100°C`: `Q = 0.1 × 4187 × 75 = 31402.5 J` و `t = 31402.5 ÷ 250 ≈ 125.6 s`.","لأن السخان يعطي في كل ثانية طاقة تساوي قدرته، فالطاقة الكلية `P·t` تساوي الحرارة التي يكتسبها الماء `m·c·ΔT`."]},"3-3":{"":["المجال الكهربائي هو المنطقة حول الشحنة التي تشعر فيها أي شحنة أخرى بقوة، مثل حرارة المدفأة التي تشعر بها كلما اقتربت. ونرسمه بخطوط تبين اتجاهه وقوته.","شحنة `4 nC` على بعد `0.2 m`: `E = 9 × 10⁹ × 4 × 10⁻⁹ ÷ 0.2² = 36 ÷ 0.04 = 900 N/C`.","لأن الشحنة تؤثر في غيرها دون تلامس، فنحتاج وصفا لهذا التأثير في كل نقطة حولها، وهو المجال الذي يحدد القوة على أي شحنة توضع هناك."],"المجال الكهربائي":["المجال هو منطقة نفوذ الشحنة، مثل رائحة العطر التي تملأ ما حول الزجاجة. أي شحنة تدخل هذه المنطقة تتأثر بقوة.","مشط بلاستيكي مشحون بعد تمريره في الشعر يجذب قصاصات الورق من مسافة قصيرة دون أن يلمسها، لأنها داخل مجاله الكهربائي.","لأن القوة الكهربائية تؤثر عن بعد، فنقول إن الشحنة تنشئ حولها مجالا ينقل تأثيرها إلى الشحنات الأخرى."],"تمثيل المجال الكهربائي":["لا نرى المجال، فنرسمه بخطوط مثل خطوط الطرق على الخريطة: السهم يبين الاتجاه، وتقارب الخطوط يبين القوة.","حول شحنة نقطية تكون الخطوط متقاربة قربها ومتباعدة بعيدا عنها، فالمجال عند `0.1 m` منها أقوى منه عند `0.5 m`.","لأن المجال كمية متجهة لها مقدار واتجاه، فالخط يعبر عن الاتجاه بسهمه، وكثافة الخطوط تعبر عن المقدار."],"خصائص خطوط المجال الكهربائي":["تخيل الخطوط طرقا تسير عليها شحنة موجبة صغيرة: تبدأ من الموجبة وتنتهي في السالبة، ولا تلتقي طريقان، وتزدحم الطرق حيث المجال قوي.","بين لوحين متوازيين تكون الخطوط مستقيمة متساوية التباعد، فالمجال عند أي نقطة بينهما له القيمة نفسها، مثلا `2000 N/C` في كل مكان.","لا تتقاطع الخطوط لأن للمجال اتجاها واحدا في كل نقطة، ولو تقاطع خطان لكان للنقطة اتجاهان. وتخرج من الموجبة لأن الاتجاه هو اتجاه القوة على شحنة موجبة."],"أشكال خطوط المجال":["حول الشحنة الموجبة تشبه الخطوط أشعة الشمس الخارجة منها، وحول السالبة تشبه ماء ينساب نحو فتحة تصريف من كل الجهات.","شحنة اختبار موجبة قرب شحنة موجبة تدفع بعيدا عنها على امتداد الخط، وقرب شحنة سالبة تسحب نحوها.","لأن اتجاه الخط هو اتجاه القوة على شحنة اختبار موجبة، وهذه الشحنة تتنافر مع الموجبة فتبتعد، وتتجاذب مع السالبة فتقترب."],"أنواع المجال الكهربائي":["المنتظم مثل نهر هادئ سرعة مائه واحدة في كل مكان، وغير المنتظم مثل نافورة يكون الماء قويا قربها ويضعف كلما ابتعدت.","بين لوحين فرق الجهد بينهما `100 V` والمسافة `0.02 m` يكون المجال `5000 N/C` في كل النقاط (منتظم)، أما حول شحنة نقطية فيتغير من نقطة لأخرى.","حول الشحنة النقطية يتغير المجال لأنه يعتمد على البعد عنها ويتجه شعاعيا، أما بين اللوحين المتوازيين فتتوزع الشحنات بانتظام فيصبح المجال ثابتا."],"شدة المجال الكهربائي":["شدة المجال تخبرك كم نيوتن تتأثر به كل كولوم توضع في النقطة، مثل سعر الكيلو الذي يخبرك بالتكلفة لكل وحدة.","شحنة اختبار `3 × 10⁻⁶ C` تأثرت بقوة `0.06 N`: `E = 0.06 ÷ (3 × 10⁻⁶) = 2 × 10⁴ N/C`.","نقسم على شحنة الاختبار لأن القوة تتضاعف إذا تضاعفت الشحنة، فيبقى ناتج القسمة ثابتا ويصف النقطة نفسها لا الشحنة الموضوعة فيها."],"المجال الكهربائي المنتظم":["بين لوحي المكثف يكون المجال مثل مطر يسقط عموديا بالكثافة نفسها في كل مكان: الاتجاه واحد والقوة واحدة.","مكثف لوحاه موصلان ببطارية `12 V` والمسافة بينهما `0.003 m`: المجال بينهما `E = 12 ÷ 0.003 = 4000 N/C` عند كل النقاط.","لأن الشحنات تتوزع بانتظام على اللوحين المتوازيين، فيكون تأثيرها متساويا في كل نقطة بينهما، فتظهر الخطوط مستقيمة متوازية متساوية التباعد."],"المجال الكهربائي المنتظم (تابع)":["كلما زاد جهد المصدر زاد المجال، وكلما ابتعد اللوحان ضعف المجال، مثل منحدر يكون أشد ميلا إذا كان الارتفاع كبيرا والمسافة قصيرة.","فرق جهد `200 V` ومسافة `0.05 m`: `E = 200 ÷ 0.05 = 4000 V/m = 4000 N/C`.","لأن فرق الجهد يتوزع بالتساوي على المسافة بين اللوحين، فنصيب كل متر هو `V / d`، ولهذا تكافئ `V/m` الوحدة `N/C`."],"المجال الكهربائي غير المنتظم (الناشئ عن شحنة نقطية)":["حول الشحنة النقطية يشبه المجال ضوء مصباح: قوي جدا قربه ويضعف كلما ابتعدت، ويتجه في كل الاتجاهات.","شحنة `2 nC`: عند `0.1 m` يكون `E = 18 ÷ 0.01 = 1800 N/C`، وعند `0.3 m` يكون `E = 18 ÷ 0.09 = 200 N/C`.","لأن الخطوط تنتشر شعاعيا فتتباعد كلما ابتعدنا، والتباعد يعني أن المجال أضعف، ويتغير اتجاهه من نقطة لأخرى حول الشحنة."],"المجال الكهربائي غير المنتظم (الناشئ عن شحنة نقطية) (تابع)":["المجال يكبر مع كبر الشحنة ويصغر بسرعة مع البعد، فإذا ابتعدت إلى ضعف المسافة صار المجال ربع ما كان.","شحنة `6 × 10⁻⁹ C` على بعد `0.2 m`: `E = 9 × 10⁹ × 6 × 10⁻⁹ ÷ 0.04 = 54 ÷ 0.04 = 1350 N/C`.","لأن هذا القانون يأتي من قانون كولوم بقسمة القوة على شحنة الاختبار، فيبقى فيه مربع المسافة كما في قانون كولوم."],"القوة على شحنات متعددة":["إذا أثرت عدة شحنات في شحنة واحدة، فاحسب أثر كل واحدة كأنها وحدها، ثم اجمعها كما تجمع قوى حبال تشد صندوقا.","شحنة تتأثر بقوة `0.03 N` نحو اليمين من شحنة وبقوة `0.01 N` نحو اليسار من أخرى: المحصلة `0.03 − 0.01 = 0.02 N` نحو اليمين.","لأن كل شحنة تؤثر بقوة لا تعتمد على وجود الشحنات الأخرى، والقوى كميات متجهة، فالمحصلة هي جمعها مع مراعاة الاتجاه."],"أمثلة الحقيبة التدريبية محلولة":["قبل الحل حدد ما عندك: شحنة نقطية ومسافة ولا توجد قوة، فهذا يدلك على قانون المجال حول شحنة نقطية مباشرة.","شحنة `8 × 10⁻⁹ C` وبعد `0.4 m`: `E = 9 × 10⁹ × 8 × 10⁻⁹ ÷ 0.4² = 72 ÷ 0.16 = 450 N/C`.","لأن اختيار القانون يعتمد على المعطيات: وجود القوة وشحنة الاختبار يقود إلى `E = F / q₀`، ووجود الشحنة المولدة وبعدها يقود إلى `E = k·q / r²`."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["عوض بالأرقام، اضرب البسط، ربع المسافة، ثم اقسم. والاتجاه بعيد عن الشحنة لأنها موجبة.","شحنة `1 × 10⁻⁹ C` على بعد `0.1 m`: `E = 9 ÷ 0.01 = 900 N/C` باتجاه بعيد عن الشحنة.","يتجه المجال بعيدا عن الشحنة الموجبة لأن شحنة الاختبار الموجبة تتنافر معها، واتجاه المجال هو اتجاه القوة على شحنة الاختبار الموجبة."],"مثال ٢: المجال من القوة المؤثرة على شحنة (صفحة 95)":["إذا عرفت القوة على شحنة موضوعة في النقطة، فاقسم القوة على الشحنة، مثل حساب السعر لكل قطعة بقسمة الثمن على عدد القطع.","شحنة `5 × 10⁻⁹ C` تأثرت بقوة `1 × 10⁻⁵ N`: `E = 1 × 10⁻⁵ ÷ (5 × 10⁻⁹) = 2000 N/C`.","نستخدم التعريف لأن الشحنة المولدة للمجال وبعدها غير معروفين، أما القوة وشحنة الاختبار فمعطاتان، وناتج قسمتهما هو المجال مباشرة."],"مثال ٢: المجال من القوة المؤثرة على شحنة (صفحة 95) (تابع)":["اقسم الأعداد وحدها، ثم اقسم قوى العشرة بطرح الأسس. وإذا كبرت الشحنة تكبر القوة معها ويبقى المجال كما هو.","قوة `6 × 10⁻⁵ N` على شحنة `3 × 10⁻⁹ C`: `6 ÷ 3 = 2` و `10⁻⁵ ÷ 10⁻⁹ = 10⁴`، فالمجال `2 × 10⁴ N/C`.","يبقى المجال ثابتا لأنه صفة للنقطة تحددها الشحنة المولدة، فمضاعفة شحنة الاختبار تضاعف القوة عليها فيبقى ناتج `F / q` كما هو."],"رسم توضيحي 1":["في الرسم تخرج الأسهم من الموجبة إلى الخارج وتدخل في السالبة من كل الجهات، مثل نافورة ماء وفتحة تصريف.","عند `0.1 m` من شحنة `1 nC` يكون المجال `900 N/C`، وعند `0.2 m` يصير `225 N/C`، ولهذا تتباعد الخطوط في الرسم كلما ابتعدنا.","تكون الخطوط شعاعية لأن الشحنة النقطية تؤثر بالتساوي في كل الاتجاهات، واتجاه الأسهم هو اتجاه القوة على شحنة اختبار موجبة."],"رسم توضيحي 2":["الخطوط تنطلق من الموجبة وتنحني لتصل إلى السالبة، مثل جسور تربط بين الشحنتين، وتزدحم بينهما حيث المجال أقوى.","في منتصف المسافة بين `+2 nC` و `−2 nC` المتباعدتين `0.2 m`: مجال كل منهما `9 × 10⁹ × 2 × 10⁻⁹ ÷ 0.1² = 1800 N/C` نحو السالبة، فالمحصلة `3600 N/C`.","تتقارب الخطوط بين الشحنتين لأن مجاليهما هناك في الاتجاه نفسه فيتقويان، أما بعيدا عنهما فيضعف المجال فتتباعد الخطوط."],"تطبيقات من الحياة":["المجال الكهربائي يدفع الإلكترونات ويوجهها داخل بعض الأجهزة، وبعض الأسماك تحس به لتعرف مكان فريستها.","إلكترون شحنته `1.6 × 10⁻¹⁹ C` في مجال `1 × 10⁴ N/C` يتأثر بقوة `F = q·E = 1.6 × 10⁻¹⁵ N`.","لأن المجال يؤثر بقوة على أي شحنة توضع فيه، فيمكن التحكم بحركة الإلكترونات بتغيير المجال، وعضلات الكائنات الحية تولد مجالات ضعيفة يمكن استشعارها."],"تمرين 1 · ورقة العمل · سؤال ٥ (صفحة 105)":["معطاك قوة وشحنة، فاقسم القوة على الشحنة لتحصل على المجال.","شحنة `2 × 10⁻⁶ C` تأثرت بقوة `5 × 10⁻³ N`: `E = 0.005 ÷ (2 × 10⁻⁶) = 2500 N/C`.","لأن شدة المجال تعرف بأنها القوة على وحدة الشحنات، فقسمة القوة على الشحنة تعطي نصيب كل كولوم من القوة."],"تمرين 2 · ورقة العمل · سؤال ٦ (صفحة 105)":["معطاك شحنة مولدة وبعد عنها، فاضرب `k` في الشحنة ثم اقسم على مربع البعد.","شحنة `5 × 10⁻⁹ C` على بعد `0.5 m`: `E = 9 × 10⁹ × 5 × 10⁻⁹ ÷ 0.5² = 45 ÷ 0.25 = 180 N/C`.","نستخدم `E = k·q / r²` لأن المجال ناشئ عن شحنة نقطية، ولا توجد قوة ولا شحنة اختبار في المعطيات."]},"3-4":{"":["الجهد الكهربائي يصف طاقة الوضع التي تملكها كل وحدة شحنة عند نقطة، مثل الارتفاع الذي يحدد طاقة الماء المخزن في خزان مرتفع.","شغل `10 J` لنقل شحنة `2 C` بين نقطتين يعني فرق جهد `ΔV = 10 ÷ 2 = 5 V`.","لأن القوة الكهربائية تبذل شغلا عند تحريك الشحنة فتتغير طاقة وضعها، وقسمة هذه الطاقة على الشحنة تعطي كمية تصف النقطة نفسها."],"الجهد الكهربائي V":["الجهد هو الطاقة التي يحملها كل كولوم عند النقطة، مثل نصيب كل لتر ماء من الطاقة في خزان مرتفع.","شحنة `4 × 10⁻⁶ C` طاقة وضعها `2 × 10⁻³ J`: `V = 2 × 10⁻³ ÷ (4 × 10⁻⁶) = 500 V`.","نقسم على الشحنة لأن طاقة الوضع تتضاعف بمضاعفة الشحنة، فيبقى الجهد ثابتا ويصف النقطة لا الشحنة الموضوعة فيها."],"فرق الجهد بين نقطتين":["فرق الجهد هو الشغل اللازم لنقل كل كولوم من نقطة إلى أخرى، مثل الجهد المبذول لرفع كل كيلوجرام من طابق إلى آخر.","شغل `0.6 J` لنقل شحنة `3 × 10⁻³ C`: `ΔV = 0.6 ÷ 0.003 = 200 V`.","لأن الشغل المبذول في نقل الشحنة يتحول إلى تغير في طاقة وضعها، فقسمة الشغل أو تغير الطاقة على الشحنة تعطي القيمة نفسها."],"الجهد في نوعي المجال الكهربائي":["حول الشحنة النقطية نحسب جهد النقطة من بعدها عن الشحنة، وبين اللوحين نحسب الفرق بضرب المجال في المسافة.","حول شحنة `1 nC` على بعد `0.3 m`: `V = 9 ÷ 0.3 = 30 V`، وفي مجال منتظم `500 N/C` لمسافة `0.04 m`: `ΔV = 20 V`.","لأن `ΔV = E·d` يتطلب مجالا ثابتا على طول المسافة، وهذا لا يتحقق حول الشحنة النقطية حيث يتغير المجال مع البعد، فنستخدم قانونها الخاص."],"الجهد الناشئ عن شحنة نقطية (مجال غير منتظم)":["الجهد حول الشحنة الموجبة مثل حرارة المدفأة: أعلى قربها ويقل كلما ابتعدت، والنقاط المتساوية البعد لها الجهد نفسه فتكون دوائر.","شحنة `2 nC`: الجهد عند `0.1 m` هو `180 V`، وعند `0.2 m` هو `90 V`، فكل دائرة حول الشحنة لها جهد ثابت.","لأن الجهد يعتمد على البعد عن الشحنة فقط، فكل النقاط التي على البعد نفسه لها الجهد نفسه، ومجموعها دائرة حول الشحنة."],"الجهد الناشئ عن شحنة نقطية (مجال غير منتظم) (تابع)":["كبر الشحنة يرفع الجهد، والابتعاد يخفضه، والمسافة هنا غير مربعة. والشحنة السالبة تعطي جهدا سالبا.","شحنة `−3 × 10⁻⁹ C` على بعد `0.09 m`: `V = 9 × 10⁹ × (−3 × 10⁻⁹) ÷ 0.09 = −300 V`.","المسافة غير مربعة لأن الجهد يصف الطاقة لكل وحدة شحنة لا القوة، فيتغير مع البعد أبطأ من المجال. ونكتب إشارة الشحنة لأن الجهد كمية قياسية بلا اتجاه."],"فرق الجهد في المجال الكهربائي المنتظم":["بين اللوحين يشبه الجهد ارتفاع منحدر منتظم: ينخفض بالتساوي كلما تحركت من اللوح الموجب نحو السالب، والخطوط العمودية على المجال ارتفاعها ثابت.","مجال `2000 N/C` بين لوحين: الانتقال `0.01 m` باتجاه الخطوط يخفض الجهد `20 V`، والانتقال `0.02 m` يخفضه `40 V`.","خطوط تساوي الجهد عمودية على المجال لأن الحركة عموديا عليه لا يبذل فيها شغل، فلا يتغير الجهد. ويقل الجهد باتجاه الخطوط لأن الشحنة الموجبة تتحرك طبيعيا من الجهد الأعلى إلى الأدنى."],"فرق الجهد في المجال الكهربائي المنتظم (تابع)":["فرق الجهد يساوي شدة المجال مضروبة في المسافة على امتداد الخطوط، فكلما زادت المسافة زاد الفرق.","مجال `3000 N/C` ونقطتان بينهما `0.05 m`: `ΔV = 3000 × 0.05 = 150 V`.","لأن الشغل لنقل `1 C` يساوي القوة عليه وهي `E` مضروبة في المسافة `d`، والشغل لكل وحدة شحنة هو فرق الجهد."],"أمثلة الحقيبة التدريبية محلولة":["المجال منتظم والمطلوب فرق جهد بين نقطتين، إذن اضرب الشدة في المسافة بعد التأكد أن المسافة بالمتر.","مجال `5000 N/C` ومسافة `2 cm = 0.02 m`: `ΔV = 5000 × 0.02 = 100 V`.","نختار `ΔV = E·d` لأن المجال ثابت في كل النقاط، فالشغل لنقل كل كولوم يساوي القوة الثابتة عليه مضروبة في المسافة."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["عوض واضرب قوى العشرة بجمع الأسس، ثم تحقق أن الوحدة `N·m/C` هي نفسها `J/C` أي الفولت.","مجال `2.5 × 10³ N/C` ومسافة `6 × 10⁻² m`: `ΔV = 15 × 10¹ = 150 V`، أي يلزم `150 J` لنقل `1 C`.","الوحدة تصبح فولتا لأن النيوتن في المتر جول، والجول لكل كولوم هو الفولت، وهذا يؤكد أن الناتج فرق جهد."],"مثال ٢: الجهد على بعد من شحنة نقطية (صفحة 96)":["النقطة قرب شحنة نقطية والمجال حولها متغير، فلا نضرب مجالا في مسافة، بل نستخدم قانون جهد الشحنة النقطية.","شحنة `3 × 10⁻⁶ C` على بعد `0.2 m`: `V = 9 × 10⁹ × 3 × 10⁻⁶ ÷ 0.2 = 27000 ÷ 0.2 = 1.35 × 10⁵ V`.","لأن `ΔV = E·d` يفترض مجالا ثابتا على طول المسافة، وحول الشحنة النقطية يقل المجال كلما ابتعدنا، فيعطي ذلك القانون نتيجة خاطئة."],"مثال ٢: الجهد على بعد من شحنة نقطية (صفحة 96) (تابع)":["في الجهد تكون المسافة بلا تربيع، وفي المجال والقوة تكون مربعة. والإشارة تتبع إشارة الشحنة.","شحنة `1 × 10⁻⁶ C` على بعد `0.3 m`: الجهد `V = 9000 ÷ 0.3 = 3 × 10⁴ V`، بينما المجال `E = 9000 ÷ 0.09 = 1 × 10⁵ N/C`.","الجهد موجب حول الشحنة الموجبة لأن نقل شحنة اختبار موجبة نحوها يحتاج شغلا ضد التنافر، فتزداد طاقة وضعها."],"رسم توضيحي 1":["الخطوط تخرج من الموجبة وتدخل في السالبة، والجهد يكون مرتفعا قرب الموجبة ومنخفضا قرب السالبة.","على بعد `0.1 m` من `+1 nC` يكون الجهد `90 V`، وعلى البعد نفسه من `−1 nC` يكون `−90 V`.","خطوط المجال تتجه دائما من الجهد الأعلى إلى الجهد الأدنى، لذلك تبدأ عند الشحنة الموجبة ذات الجهد المرتفع وتنتهي عند السالبة."],"رسم توضيحي 2":["بين لوحي المكثف خطوط مستقيمة متوازية من الموجب إلى السالب، والجهد ينخفض بانتظام كلما اقتربت من اللوح السالب.","لوحان بينهما `0.01 m` وفرق جهد `50 V`: المجال `E = 50 ÷ 0.01 = 5000 N/C`، وعند منتصف المسافة يكون الجهد قد انخفض `25 V`.","لأن المجال ثابت بين اللوحين، فكل متر على امتداد الخطوط ينقص الجهد بالمقدار نفسه، فيكون التغير منتظما."],"تطبيقات من الحياة":["البطارية تعمل مثل مضخة ترفع الشحنات إلى جهد أعلى فتعطي كل كولوم طاقة ثابتة، وخطوط الضغط العالي تنقل الكهرباء بجهد كبير جدا.","بطارية `12 V` تعطي كل `1 C` طاقة `12 J`، فإذا مرت `5 C` تعطيها `W = q·ΔV = 5 × 12 = 60 J`.","لأن فرق الجهد هو الطاقة لكل وحدة شحنة، فجهد البطارية يحدد الطاقة التي تحصل عليها كل كولوم تمر فيها."],"تمرين 1 · ورقة العمل · سؤال ٧ (صفحة 106)":["المجال منتظم والمسافة معطاة بالمتر، فاضرب الشدة في المسافة مباشرة.","مجال `1500 N/C` ومسافة `0.04 m`: `ΔV = 1500 × 0.04 = 60 V`.","نستخدم `ΔV = E·d` لأن المجال ثابت الشدة والاتجاه، فالشغل لكل كولوم يتناسب مع المسافة المقطوعة باتجاه الخطوط."],"تمرين 2 · ورقة العمل · سؤال ٨ (صفحة 106)":["الجهد حول شحنة نقطية: اضرب `k` في الشحنة واقسم على البعد دون تربيع.","شحنة `5 × 10⁻⁶ C` على بعد `0.3 m`: `V = 9 × 10⁹ × 5 × 10⁻⁶ ÷ 0.3 = 45000 ÷ 0.3 = 1.5 × 10⁵ V`.","نختار قانون الشحنة النقطية لأن المعطى شحنة وبعد عنها، والمجال حولها غير منتظم فلا يصلح ضرب المجال في المسافة."]},"3-5":{"":["المكثف مثل خزان صغير للشحنة: لوحان موصلان يفصل بينهما عازل، وكلما رفعنا الجهد بينهما خزن شحنة أكبر. والسعة تخبرنا كم يخزن من الشحنة لكل فولت.","مكثف سعته `10 µF` على جهد `9 V` يخزن شحنة `q = C·V = 10 × 10⁻⁶ × 9 = 9 × 10⁻⁵ C`.","لأن الشحنة على اللوحين تتناسب طرديا مع فرق الجهد بينهما، فتبقى النسبة `q / V` ثابتة لكل مكثف، وتعتمد على أبعاده والوسط العازل فقط."],"السعة الكهربائية C":["السعة مثل اتساع الكأس: الكأس الواسعة تأخذ ماء أكثر لكل سنتيمتر يرتفعه الماء. والمكثف ذو السعة الكبيرة يأخذ شحنة أكبر لكل فولت.","مكثف يحمل `6 × 10⁻⁵ C` وجهده `20 V`: `C = 6 × 10⁻⁵ ÷ 20 = 3 × 10⁻⁶ F = 3 µF`.","لأن زيادة الجهد تدفع شحنة أكبر إلى اللوحين بالنسبة نفسها، فيبقى خارج قسمة الشحنة على الجهد ثابتا، وهذا الثابت هو السعة ووحدته `C/V` أي الفاراد."],"المكثف ذو اللوحين المتوازيين":["لوحان معدنيان متقابلان بينهما عازل، يأخذ أحدهما شحنة موجبة والآخر شحنة سالبة مساوية لها. كلما كبرت مساحة اللوحين وقربت المسافة بينهما زادت السعة.","لوحان مساحة كل منهما `0.5 m²` والمسافة بينهما `1 × 10⁻³ m` في الهواء: `C = 8.85 × 10⁻¹² × 0.5 ÷ 10⁻³ = 4.425 × 10⁻⁹ F`.","المساحة الأكبر تتسع لشحنة أكبر عند الجهد نفسه، والمسافة الأصغر تقوي التجاذب بين شحنتي اللوحين فيحملان شحنة أكبر. لذلك تتناسب `C` طرديا مع `A` وعكسيا مع `d`."],"المكثف ذو اللوحين المتوازيين (تابع)":["المجال بين اللوحين له المقدار والاتجاه نفسهما في كل نقطة، لذلك فرق الجهد يساوي المجال مضروبا في المسافة، كما يساوي ارتفاع السلم ارتفاع الدرجة مضروبا في عدد الدرجات.","جهد `12 V` بين لوحين بينهما `4 × 10⁻³ m`: `E = V ÷ d = 12 ÷ (4 × 10⁻³) = 3000 V/m`.","لأن اللوحين واسعان ومتقاربان، فتكون خطوط المجال بينهما مستقيمة متوازية متساوية التباعد، فيكون المجال منتظما ويصلح القانون `V = E·d`."],"سماحية الوسط العازل ε":["السماحية تصف مدى سماح الوسط بنشوء المجال الكهربائي فيه. ووضع عازل ثابت عزله كبير بين اللوحين يجعل المكثف يخزن شحنة أكبر عند الجهد نفسه.","مكثف هوائي سعته `2 nF`، نملأ ما بين لوحيه بعازل `εᵣ = 5`: تصبح السعة `C = 5 × 2 nF = 10 nF`.","لأن السعة تتناسب طرديا مع سماحية الوسط `ε = ε₀·εᵣ`، فكلما كبر ثابت العزل كبرت السعة. وللهواء `εᵣ = 1` مثل الفراغ، لذلك نستخدم `ε₀` عندما يكون الوسط هواء."],"رمز المكثف في الدوائر الكهربائية":["رمز المكثف يشبه شكله: خطان متوازيان مثل اللوحين. فإذا كان له قطبية رسم أحد الخطين منحنيا مع إشارة `+`، وإذا كانت سعته تتغير رسم عليه سهم مائل.","مثال واقعي: في مخطط شاحن هاتف ترى رمزا بخطين أحدهما منحن وبجانبه `+` ومكتوب عنده `1000 µF`، فهو مكثف إلكتروليتي يوصل طرفه الموجب بالجهد الأعلى.","لأن الرموز الموحدة تجعل أي فني يقرأ المخطط بسرعة دون لبس، ولأن المكثف ذا القطبية يتلف إذا وصل بعكس قطبيته، فلا بد أن يظهر ذلك في رسمه."],"أنواع المكثفات":["المكثفات عائلة لها أحجام وأعمال مختلفة: الإلكتروليتي والتنتالوم سعتهما كبيرة ولهما قطبية، والسيراميكي والبلاستيكي بلا قطبية، والمتغير تضبط سعته بمقبض.","مثال واقعي: عند تدوير مقبض الراديو تتغير المساحة المتقابلة بين لوحي المكثف المتغير، فتتغير سعته ويلتقط الجهاز محطة أخرى.","لأن السعة تعتمد على المساحة والمسافة ونوع العازل، فكل نوع يختار عازلا وأبعادا تناسب عمله: سعة كبيرة لتنعيم الجهد، أو سعة صغيرة دقيقة للترددات العالية."],"أنواع المكثفات (تابع)":["المكثف فائق السعة خزان ضخم للشحنة، سعته تصل إلى الفاراد وأكثر، لذلك يستعمل لتخزين الطاقة في السيارات الكهربائية والأجهزة الاحتياطية.","مكثف فائق السعة `10 F` على جهد `2.7 V` يخزن شحنة `q = C·V = 10 × 2.7 = 27 C`، أي مليون ضعف شحنة مكثف `10 µF` على الجهد نفسه.","لأن سعته الهائلة تجعله يختزن شحنة كبيرة حتى عند جهد صغير حسب `q = C·V`، فيقدر على إعطاء طاقة كبيرة عند الحاجة."],"العوامل المؤثرة على السعة":["ثلاثة أشياء تتحكم في السعة: مساحة أكبر تعني سعة أكبر، ومسافة أكبر تعني سعة أقل، وعازل سماحيته أكبر يعني سعة أكبر.","مكثف سعته `4 nF`: إذا ضاعفنا المساحة أصبحت `8 nF`، وإذا ضاعفنا المسافة بدلا من ذلك أصبحت `2 nF`، حسب `C = ε₀·A / d`.","لأن قانون السعة `C = ε₀·A / d` يضع المساحة والسماحية في البسط والمسافة في المقام، فتظهر العلاقة الطردية والعكسية مباشرة."],"فوائد المكثفات":["المكثف يخزن الطاقة ثم يعطيها عند الحاجة، وينتج مجالا كهربائيا محددا بين لوحيه، ويساعد في توليد الذبذبات وإزالة التشويش في الأجهزة اللاسلكية.","مكثف `100 µF` مشحون على `12 V` يخزن شحنة `q = 100 × 10⁻⁶ × 12 = 1.2 × 10⁻³ C` يعطيها للدائرة إذا انقطع المصدر لحظة.","لأن الشحنات المفصولة على اللوحين تبقى محفوظة، فالعازل يمنع مرورها بينهما، فتبقى الطاقة مختزنة إلى أن نوصل المكثف بدائرة يفرغ فيها."],"أمثلة الحقيبة التدريبية محلولة":["عندما يعطيك السؤال الشحنة والجهد ويطلب السعة، فاقسم الشحنة على الجهد مباشرة، لأن هذا هو تعريف السعة نفسه.","مكثف يحمل `6 × 10⁻⁴ C` وجهده `200 V`: `C = 6 × 10⁻⁴ ÷ 200 = 3 × 10⁻⁶ F = 3 µF`.","لأن السعة معرفة بأنها النسبة الثابتة بين الشحنة وفرق الجهد، ولدينا الكميتان معا، فلا نحتاج إلى أبعاد المكثف ولا إلى قانون آخر."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["الحيلة في القسمة: اكتب كل عدد بالصيغة العلمية، ثم اقسم الأعداد وحدها واطرح الأسس وحدها، وأخيرا حول الناتج إلى وحدة أنسب مثل µF.","`C = 8 × 10⁻⁴ ÷ 400`: نكتب `400 = 4 × 10²`، ثم `8 ÷ 4 = 2` و `10⁻⁴ ÷ 10² = 10⁻⁶`، فتكون `C = 2 × 10⁻⁶ F = 2 µF`.","لأن قسمة القوى ذات الأساس الواحد تكون بطرح الأسس، والبادئة µ تعني `10⁻⁶`، فكتابة الناتج بالميكروفاراد تختصره وتسهل قراءته."],"مثال ٢: حساب الشحنة المختزنة في مكثف (صفحة 98)":["إذا عرفت السعة والجهد وطلب منك الشحنة، فاضرب السعة في الجهد، فالسعة تعني كم كولوم يخزن المكثف لكل فولت.","مكثف `15 µF` على جهد `40 V`: `q = 15 × 10⁻⁶ × 40 = 600 × 10⁻⁶ C = 6 × 10⁻⁴ C`.","لأن تعريف السعة `C = q / V` يربط الكميات الثلاث، وبضرب الطرفين في `V` نحصل على `q = C·V` فنعوض المعطيين مباشرة."],"مثال ٢: حساب الشحنة المختزنة في مكثف (صفحة 98) (تابع)":["بعد ضرب الأعداد يبقى الأس كما هو، ثم نحرك الفاصلة لنكتب الناتج بالصيغة العلمية. والتحقق من الوحدة يطمئنك: الفاراد في الفولت يعطي كولوم.","`q = 33 × 10⁻⁶ × 50`: `33 × 50 = 1650`، فتكون `q = 1650 × 10⁻⁶ C = 1.65 × 10⁻³ C`.","لأن الفاراد كولوم لكل فولت `F = C/V`، فإذا ضربناه في الفولت اختصر الفولت وبقي الكولوم، وهذا يؤكد أن الناتج شحنة."],"مثال ٣: مكثف متوازي اللوحين سعته وشحنته ومجاله (صفحة 99)":["عندما لا نعرف الشحنة لكن نعرف أبعاد المكثف، نحسب السعة من أبعاده: المساحة والمسافة وسماحية الوسط، دون حاجة إلى الشحنة أو الجهد.","مساحة اللوح `1 m²` والمسافة `2 × 10⁻³ m` في الهواء: `C = 8.85 × 10⁻¹² × 1 ÷ (2 × 10⁻³) = 4.425 × 10⁻⁹ F`.","لأن سعة المكثف صفة فيه تحددها أبعاده الهندسية والوسط العازل، كما يحدد حجم الخزان سعته، ولا تعتمد على الشحنة الموجودة فيه."],"مثال ٣: مكثف متوازي اللوحين سعته وشحنته ومجاله (صفحة 99) (تابع)":["نحسب السعة أولا، ثم الشحنة من `q = C·V`، ثم المجال من `V = E·d`. وكل لوح يحمل الشحنة نفسها مقدارا بإشارة معاكسة، والمجال يتجه من الموجب إلى السالب.","السعة `3.54 × 10⁻⁹ F` والجهد `2 V`: `q = 3.54 × 10⁻⁹ × 2 = 7.08 × 10⁻⁹ C`، ومع المسافة `5 × 10⁻³ m` يكون `E = 2 ÷ (5 × 10⁻³) = 400 V/m`.","لأن المجال بين اللوحين منتظم، فيتوزع الجهد بالتساوي على المسافة، لذلك `E = V / d`. ويتجه المجال من اللوح الموجب إلى السالب لأن الشحنة الموجبة تنفر من الموجب وتنجذب إلى السالب."],"رسم توضيحي 1":["الرسم يبين أن المجال بين اللوحين متماثل في كل مكان، مثل ماء يجري في قناة مستقيمة بالسرعة نفسها في كل نقطة.","إذا كان المجال بين اللوحين `500 V/m` فإنه يبقى `500 V/m` قرب اللوح الموجب وفي المنتصف وقرب السالب، ولمسافة `0.01 m` يكون فرق الجهد `500 × 0.01 = 5 V`.","لأن اللوحين متوازيان ومشحونان بانتظام بشحنتين متعاكستين، فيكون أثرهما بين اللوحين في اتجاه واحد وبمقدار ثابت، فيكون المجال منتظما."],"رسم توضيحي 2":["خطوط المجال في الرسم مستقيمة ومتوازية ومتساوية التباعد، تخرج من اللوح الموجب وتدخل اللوح السالب، وهذا شكل المجال المنتظم.","شحنة `2 × 10⁻⁶ C` بين لوحين مجالهما `1000 V/m` تتأثر بقوة `F = q·E = 2 × 10⁻⁶ × 1000 = 2 × 10⁻³ N` في أي نقطة وضعت فيها بين اللوحين.","لأن خطوط المجال تبدأ من الشحنة الموجبة وتنتهي عند السالبة، وتساوي تباعدها يعني تساوي شدة المجال، فالخطوط المتوازية المتساوية التباعد تعني مجالا منتظما."],"العوامل المؤثرة في سعة المكثف ذي اللوحين المتوازيين":["الجدول يلخص القاعدة: كبر المساحة يرفع السعة، وزيادة المسافة تخفضها، والعازل ذو السماحية الأكبر يرفعها.","مكثف هوائي `A = 0.2 m²` و `d = 2 × 10⁻³ m`: `C = 8.85 × 10⁻¹² × 0.2 ÷ (2 × 10⁻³) = 8.85 × 10⁻¹⁰ F`.","لأن القانون `C = ε·A / d` يجعل السعة متناسبة طرديا مع المساحة والسماحية وعكسيا مع المسافة، فكل عامل يغير السعة بالنسبة نفسها."],"تطبيقات من الحياة":["فلاش الكاميرا يملأ المكثف ببطء ثم يفرغه دفعة واحدة فيعطي ضوءا قويا، وجهاز الصدمات القلبية يفعل الشيء نفسه مع القلب، وشاشة اللمس تحس بإصبعك لأنه يغير السعة.","مكثف فلاش `100 µF` مشحون على `300 V` يحمل شحنة `q = 100 × 10⁻⁶ × 300 = 0.03 C` يفرغها في المصباح خلال لحظة.","لأن المكثف يختزن الشحنة ويستطيع إفراغها بسرعة كبيرة، ولأن سعته تتغير إذا تغير ما حول لوحيه، كما يحدث عند لمس الشاشة."],"تمرين 1 · مثال ٣ (صفحة 99)":["عوض المساحة والمسافة في `C = ε₀·A / d` بعد التأكد أن المسافة بالمتر، ثم اقسم.","لوح مساحته `3 m²` والمسافة `5 × 10⁻³ m`: `C = 8.85 × 10⁻¹² × 3 ÷ 0.005 = 5.31 × 10⁻⁹ F`.","لأن السؤال يعطي أبعاد المكثف ولا يعطي الشحنة أو الجهد، فالقانون المناسب هو قانون السعة بدلالة الأبعاد."],"تمرين 2 · ورقة العمل · سؤال ٩ (صفحة 106)":["الشحنة والجهد معطيان، فالسعة هي ناتج قسمة الشحنة على الجهد.","شحنة `5 × 10⁻⁴ C` وجهد `250 V`: `C = 5 × 10⁻⁴ ÷ 250 = 2 × 10⁻⁶ F = 2 µF`.","لأن السعة هي الشحنة لكل فولت، فقسمة الشحنة على الجهد تعطي السعة مباشرة بوحدة الفاراد."],"تمرين 3 · ورقة العمل · سؤال ١٠ (صفحة 107)":["المكثف يأخذ جهد البطارية، فاضرب سعته في جهد البطارية لتحصل على شحنته.","مكثف `2.5 × 10⁻¹² F` على بطارية `9 V`: `q = 2.5 × 10⁻¹² × 9 = 2.25 × 10⁻¹¹ C`.","لأن لوحي المكثف متصلان بقطبي البطارية فيصبح فرق الجهد بينهما مساويا لجهدها، ومن `C = q / V` نجد `q = C·V`."],"تمرين 4 · ورقة العمل · سؤال ١١ (صفحة 107)":["المجهول هنا الجهد، فاقسم الشحنة على السعة. وإذا تساوى مقدار الشحنة ومقدار السعة كان الجهد فولتا واحدا.","مكثف `4 × 10⁻⁶ F` شحنته `2 × 10⁻⁵ C`: `V = q ÷ C = 2 × 10⁻⁵ ÷ (4 × 10⁻⁶) = 5 V`.","لأن العلاقة `C = q / V` تعطي بإعادة الترتيب `V = q / C`، فالجهد يزيد بزيادة الشحنة ويقل بزيادة السعة."],"تمرين 5 · ورقة العمل · سؤال ١١ (صفحة 107)":["المجال المنتظم بين اللوحين يساوي الجهد مقسوما على المسافة، فكلما قربت اللوحين قوي المجال.","جهد `3 V` ومسافة `2 × 10⁻³ m`: `E = 3 ÷ (2 × 10⁻³) = 1500 V/m`.","لأن المجال بين لوحي المكثف منتظم، فيكون `V = E·d`، ومنه `E = V / d`، ووحدته `V/m` التي تكافئ `N/C`."]},"3-6":{"":["يمكن توصيل عدة مكثفات معا: على التوالي في مسار واحد، أو على التوازي بين النقطتين نفسيهما. وكل مكثف مشحون يختزن طاقة نحسبها من سعته وجهده.","مكثفان `3 µF` و `6 µF`: على التوازي `C = 9 µF`، وعلى التوالي `C = 3 × 6 ÷ 9 = 2 µF`. وطاقة مجموعة التوازي على `10 V` هي `½ × 9 × 10⁻⁶ × 100 = 4.5 × 10⁻⁴ J`.","لأن التوازي يكافئ زيادة مساحة الألواح فتزيد السعة، والتوالي يوزع الجهد وتبقى الشحنة واحدة فتقل السعة. والطاقة مختزنة لأن شحن المكثف يحتاج شغلا لفصل الشحنات."],"التوصيل على التوالي":["المكثفات على التوالي مثل عربات قطار في خط واحد: الشحنة نفسها على كل مكثف، أما الجهد فتتقاسمه، والسعة الكلية أصغر من أصغرها.","ثلاثة مكثفات `2 µF` و `3 µF` و `6 µF` على التوالي: `1/C = 1/2 + 1/3 + 1/6 = 1`، فتكون `C = 1 µF`.","لأن الشحنة التي تصل إلى لوح المكثف الأول تحث شحنة مساوية على لوح الثاني وهكذا، فتتساوى الشحنة، ويتوزع جهد المصدر على المكثفات حسب `V = q / C`."],"التوصيل على التوازي":["المكثفات على التوازي كأحواض متصلة بالأنبوب الرئيسي نفسه: الجهد واحد عليها كلها، وكل منها يأخذ شحنة حسب سعته، فتجمع السعات.","مكثفان `5 µF` و `15 µF` على التوازي بجهد `10 V`: `C = 20 µF`، و `q₁ = 5 × 10⁻⁵ C` و `q₂ = 1.5 × 10⁻⁴ C`، ومجموعهما `2 × 10⁻⁴ C`.","لأن طرفي كل مكثف متصلان مباشرة بقطبي المصدر فيتساوى الجهد، والتوصيل يكافئ زيادة المساحة الكلية للألواح، والسعة تتناسب طرديا مع المساحة."],"الطاقة المختزنة في المكثف":["المكثف المشحون مثل نابض مضغوط يختزن طاقة. نحسبها بإحدى ثلاث صيغ متكافئة، ونختار الصيغة التي تناسب المعطيات.","مكثف `5 µF` على `20 V`: `PE = ½ × 5 × 10⁻⁶ × 20² = 1 × 10⁻³ J`، ومع `q = 10⁻⁴ C` تعطي `PE = ½ × 10⁻⁴ × 20 = 10⁻³ J` الناتج نفسه.","لأن فصل الشحنات على اللوحين يحتاج شغلا يبذله المصدر، وهذا الشغل يبقى طاقة مختزنة في المجال بين اللوحين. والصيغ الثلاث تتحول إحداها إلى الأخرى بالتعويض `q = C·V`."],"أمثلة الحقيبة التدريبية محلولة":["في التوازي كل مكثف يأخذ جهد المصدر كاملا، فالسعة الكلية مجموع السعات، وكل مكثف يأخذ شحنة تناسب سعته.","مكثفان `100 pF` و `300 pF` على التوازي بجهد `50 V`: `C_total = 400 pF`، و `q₁ = 100 × 10⁻¹² × 50 = 5 × 10⁻⁹ C`.","لأن طرفي كل مكثف متصلان بقطبي المصدر مباشرة فيتساوى الجهد، وضم المكثفات على التوازي يكافئ لوحا أكبر مساحة، والسعة تتناسب طرديا مع المساحة."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["بعد جمع السعات نحسب شحنة كل مكثف بالجهد المشترك، ثم نجمع الشحنات. ويمكنك التحقق بضرب السعة الكلية في الجهد.","`C₁ = 300 pF` و `C₂ = 500 pF` على `100 V`: `q₁ = 3 × 10⁻⁸ C` و `q₂ = 5 × 10⁻⁸ C`، والكلية `8 × 10⁻⁸ C`، وهي نفسها `800 × 10⁻¹² × 100`.","لأن الشحنة التي سحبها المصدر توزعت على المكثفين، فهي مجموع شحنتيهما، والمكثف ذو السعة الأكبر يأخذ شحنة أكبر لأن الجهد واحد."],"مثال: مكثفان موصولان على التوالي (صفحة 102)":["في التوالي الشحنة واحدة على المكثفين، والجهد يتقاسمانه. ولمكثفين فقط نحسب السعة الكلية بحاصل الضرب على المجموع.","مكثفان `4 pF` و `12 pF` على التوالي: `C = 4 × 12 ÷ (4 + 12) = 48 ÷ 16 = 3 pF`.","لأن مقلوبات السعات تجمع في التوالي `1/C = 1/C₁ + 1/C₂`، وبتوحيد المقامات لمكثفين نحصل على `C = C₁·C₂ / (C₁ + C₂)`."],"مثال: مكثفان موصولان على التوالي (صفحة 102) (تابع)":["بعد إيجاد السعة المكافئة نحسب الشحنة المشتركة من جهد المصدر، ثم جهد كل مكثف بقسمة الشحنة على سعته. والمكثف الأصغر سعة يأخذ الجهد الأكبر.","مكثفان `4 pF` و `12 pF` على التوالي بجهد `8 V`: `C = 3 pF` و `q = 2.4 × 10⁻¹¹ C`، ثم `V₁ = 6 V` و `V₂ = 2 V`، ومجموعهما `8 V`.","لأن الشحنة واحدة على المكثفين و `V = q / C`، فالجهد يتناسب عكسيا مع السعة، ومجموع الجهدين يساوي جهد المصدر."],"مثال ١: الطاقة المختزنة من السعة والجهد (صفحة 103)":["عندما تعرف السعة والجهد استخدم `PE = ½·C·V²`، وتذكر أن تربع الجهد قبل الضرب.","مكثف `3 µF` على `20 V`: `PE = ½ × 3 × 10⁻⁶ × 400 = 6 × 10⁻⁴ J`.","لأن هذه الصيغة تحتوي المعطيين مباشرة فلا نحتاج إلى حساب الشحنة أولا، والطاقة فيها تتناسب مع مربع الجهد."],"مثال ١: الطاقة المختزنة من السعة والجهد (صفحة 103) (تابع)":["الجهد يرتفع أثناء الشحن من صفر حتى `V`، فكأن الشحنة كلها نقلت عند نصف الجهد، ومن هنا جاء النصف في صيغة الطاقة.","مكثف `4 µF` على `50 V`: `(50)² = 2500`، فتكون `PE = ½ × 4 × 10⁻⁶ × 2500 = 5 × 10⁻³ J`.","لأن أول شحنة تنقل عند جهد يقارب الصفر وآخرها عند الجهد الكامل، فمتوسط الجهد `½V` والطاقة `½·q·V`، وبالتعويض `q = C·V` تصبح `½·C·V²`."],"مثال ٢: الطاقة المختزنة من الشحنة والجهد (صفحة 103)":["إذا أعطاك السؤال الشحنة والجهد فقط فلا تبحث عن السعة، بل استخدم مباشرة `PE = ½·q·V`.","مكثف يحمل `0.5 C` على جهد `100 V`: `PE = ½ × 0.5 × 100 = 25 J`.","لأن هذه الصيغة تربط الطاقة بالشحنة والجهد مباشرة، فنختصر خطوة حساب السعة ونقلل احتمال الخطأ."],"مثال ٢: الطاقة المختزنة من الشحنة والجهد (صفحة 103) (تابع)":["نضرب الشحنة في الجهد ثم نأخذ النصف. والكولوم في الفولت يعطي جولا، فالناتج طاقة.","`q = 1.2 C` و `V = 300 V`: `1.2 × 300 = 360`، ثم `PE = 360 ÷ 2 = 180 J`.","لأن الفولت جول لكل كولوم `V = J/C`، فضرب الكولوم في الفولت يختصر الكولوم ويبقى الجول وحدة للطاقة."],"رسم توضيحي":["المجال بين لوحي المكثف ثابت المقدار والاتجاه في كل نقطة، وفي هذا المجال تختزن طاقة المكثف المشحون.","لوحان بينهما `2 × 10⁻³ m` وجهد `10 V`: المجال في أي نقطة بينهما `E = 10 ÷ (2 × 10⁻³) = 5000 V/m`.","لأن اللوحين متوازيان ومتقاربان وشحنتهما موزعة بانتظام، فتكون خطوط المجال مستقيمة متوازية متساوية التباعد، أي مجالا منتظما."],"توصيل المكثفات: التوالي مقابل التوازي":["في التوالي الشحنة مشتركة والجهد يتقاسم، وفي التوازي الجهد مشترك والشحنة تتقاسم. التوالي يقلل السعة ويتحمل جهدا أعلى، والتوازي يكبر السعة.","مكثفان `6 µF` و `6 µF`: على التوالي `C = 36 ÷ 12 = 3 µF`، وعلى التوازي `C = 6 + 6 = 12 µF`.","لأن جهد المصدر في التوالي يتوزع على المكثفات مع شحنة واحدة فتقل السعة، أما في التوازي فالجهد واحد والشحنات تجمع فتزيد السعة."],"تطبيقات من الحياة":["المصانع توصل المكثفات على التوازي لتحصل على سعة أكبر، وعلى التوالي لتتحمل جهدا أعلى. والمكثفات الفائقة تشحن الحافلات بسرعة، والمكثف قد يبقى مشحونا بعد إطفاء الجهاز.","أربعة مكثفات متماثلة يتحمل كل منها `250 V` توصل على التوالي فتتحمل معا `4 × 250 = 1000 V`، لأن الجهد يتوزع عليها بالتساوي.","لأن الجهد في التوالي يتوزع فيقل نصيب كل مكثف، والسعات تجمع في التوازي، والعازل يمنع تفريغ الشحنة فيبقى المكثف خطرا بعد الإطفاء."],"تمرين 1 · مثال (صفحة 101)":["على التوازي اجمع السعات مباشرة، والناتج أكبر من أكبرها.","مكثفان `150 pF` و `250 pF` على التوازي: `C = 150 + 250 = 400 pF`.","لأن التوازي يكافئ زيادة مساحة الألواح، والسعة تتناسب طرديا مع المساحة، فتجمع السعات."],"تمرين 2 · مثال (صفحة 102)":["على التوالي لمكثفين: اضرب السعتين ثم اقسم على مجموعهما، وتوقع ناتجا أصغر من أصغرهما.","مكثفان `10 pF` و `15 pF` على التوالي: `C = 10 × 15 ÷ (10 + 15) = 150 ÷ 25 = 6 pF`.","لأن مقلوبات السعات تجمع في التوالي، ومجموع المقلوبات أكبر من أي مقلوب منها، فتصبح السعة المكافئة أصغر من أصغر سعة."],"تمرين 3 · مثال (صفحة 102)":["الشحنة على كل مكثف في التوالي تساوي شحنة المجموعة كلها، فاضرب السعة المكافئة في جهد المصدر.","سعة مكافئة `5 × 10⁻¹² F` على `20 V`: `q = 5 × 10⁻¹² × 20 = 1 × 10⁻¹⁰ C` على كل مكثف.","لأن الشحنة في التوالي متساوية على كل المكثفات، وهي نفسها الشحنة التي يزودها المصدر للمجموعة كلها."],"تمرين 4 · ورقة العمل · سؤال ١٢ (صفحة 108)":["سعتان على التوالي: حاصل ضربهما على مجموعهما، والناتج أقل من أصغرهما.","مكثفان `3 µF` و `6 µF` على التوالي: `C = 3 × 6 ÷ (3 + 6) = 18 ÷ 9 = 2 µF`.","لأن التوصيل على التوالي يجمع مقلوبات السعات، ومجموع المقلوبات أكبر من كل مقلوب منها، فيكون المكافئ أصغر من أصغر سعة."],"تمرين 5 · ورقة العمل · سؤال ١٢ (صفحة 108)":["السعتان نفسهما لكن على التوازي، فاجمعهما، والناتج أكبر من أكبرهما.","مكثفان `3 µF` و `5 µF` على التوازي: `C = 3 + 5 = 8 µF`.","لأن الجهد واحد على المكثفين وكل منهما يضيف شحنته، فالشحنة الكلية لكل فولت تساوي مجموع السعتين."],"تمرين 6 · ورقة العمل · سؤال ١٣ (صفحة 108)":["الجهد معطى لكنه لا يلزم لحساب السعة الكلية، فاستخدم حاصل الضرب على المجموع فقط.","مكثفان `6 nF` و `3 nF` على التوالي: `C = 18 ÷ 9 = 2 nF`، وعلى `12 V` تكون الشحنة `q = 2 × 10⁻⁹ × 12 = 2.4 × 10⁻⁸ C`.","لأن السعة تحددها المكثفات وطريقة توصيلها ولا تعتمد على الجهد المطبق، أما الجهد فيلزم لاحقا لحساب الشحنة أو الطاقة."],"تمرين 7 · ورقة العمل · سؤال ١٤ (صفحة 109)":["على التوازي اجمع السعات، والجهد المعطى لا يغير الناتج.","مكثفان `250 nF` و `50 nF` على التوازي: `C = 300 nF`، وعلى `110 V` تكون الشحنة الكلية `q = 300 × 10⁻⁹ × 110 = 3.3 × 10⁻⁵ C`.","لأن السعة صفة المكثفات وطريقة توصيلها، أما الجهد فيحدد الشحنة المختزنة `q = C·V` لا السعة."],"تمرين 8 · ورقة العمل · سؤال ١٠ (صفحة 107)":["السعة والجهد معطيان، فاستخدم `PE = ½·C·V²` وربع الجهد أولا.","مكثف `5 × 10⁻¹² F` على `10 V`: `PE = 0.5 × 5 × 10⁻¹² × 10² = 2.5 × 10⁻¹⁰ J`.","لأن الطاقة المختزنة تعتمد على السعة وعلى مربع الجهد، فهذه الصيغة تستخدم المعطيين مباشرة دون حساب الشحنة."]},"3-8":{"":["هذا الدرس يجمع قوانين الوحدة كلها في ورقة عمل واحدة: نقرأ المعطيات، ونختار القانون المناسب، ونحول الوحدات ثم نعوض. هو مثل وصفة طبخ: المكونات أولا ثم الخطوات بالترتيب.","مكثف `3 µF` على جهد `20 V`: `Q = C·V = 3 × 10⁻⁶ × 20 = 6 × 10⁻⁵ C`، وطاقته `PE = ½ × 3 × 10⁻⁶ × 20² = 6 × 10⁻⁴ J`.","لأن كميات الوحدة مترابطة: القوة تعطي المجال، والمجال يعطي فرق الجهد، والجهد مع الشحنة يعطي السعة والطاقة. لذلك يكفي فهم هذه السلسلة لحل أي سؤال في الورقة."],"ما تحتاجه لحل ورقة العمل":["هذه علبة أدوات الوحدة: لكل كمية قانون، القوة والمجال والجهد والسعة والطاقة. قبل الحل اسأل نفسك: ما المطلوب؟ ثم اختر القانون الذي يحتوي عليه.","مجال منتظم `500 N/C` ومسافة `0.04 m`: `ΔV = E·d = 500 × 0.04 = 20 V`.","لأن هذه القوانين كلها تنبع من قانون كولوم: المجال هو القوة على كل كولوم، والجهد مرتبط بالمجال والمسافة، والسعة تربط الشحنة بالجهد. فهي حلقات في سلسلة واحدة."],"ما تحتاجه لحل ورقة العمل (تابع)":["البادئة اختصار لرقم صغير جدا، فـ `nC` تعني جزءا من مليار من الكولوم. ولا بد من تحويلها قبل التعويض، مثل تحويل الجرامات إلى كيلوجرامات قبل الحساب.","`250 pF = 250 × 10⁻¹² F = 2.5 × 10⁻¹⁰ F`، و `40 nC = 40 × 10⁻⁹ C = 4 × 10⁻⁸ C`.","لأن القوانين مبنية على وحدات SI الأساسية، والثابت `k = 9 × 10⁹ N·m²/C²` مقاس بالكولوم والمتر. فإذا عوضت بـ µC دون تحويل خرج الناتج خاطئا بفارق هائل."],"حل ورقة العمل":["القوة بين شحنتين تكبر كلما كبرت الشحنتان، وتصغر بسرعة كلما ابتعدتا. فإن كانتا متشابهتين تنافرتا، وإن اختلفتا تجاذبتا، مثل قطبي المغناطيس.","شحنتان `4 µC` و `5 µC` بينهما `3 m`: `F = 9 × 10⁹ × 4 × 10⁻⁶ × 5 × 10⁻⁶ ÷ 3² = 0.02 N`.","يستخدم القانون القيمة المطلقة للشحنتين لأنه يحسب مقدار القوة فقط، أما نوعها فنعرفه من الإشارتين. ومربع المسافة في المقام لأن أثر الشحنة يتوزع في كل الاتجاهات على مساحة تكبر مع مربع البعد."],"سؤال ٢: عرّف كلًّا مما يلي (صفحة 104)":["المجال هو القوة التي يتأثر بها كل كولوم موجب عند نقطة ما. والسعة هي ما يخزنه المكثف من شحنة مقابل كل فولت، مثل خزان ماء نقيس ما يدخله مقابل كل متر من ارتفاع الماء.","شحنة `2 × 10⁻⁶ C` تتأثر بقوة `0.01 N`: `E = 0.01 ÷ (2 × 10⁻⁶) = 5000 N/C`. ومكثف شحنته `6 × 10⁻⁵ C` وجهده `30 V`: `C = 2 × 10⁻⁶ F`.","نقسم على الشحنة في تعريف المجال لنحصل على صفة للنقطة نفسها لا تعتمد على الشحنة الموضوعة. وكذلك نقسم الشحنة على الجهد لأن النسبة بينهما ثابتة، فتصف المكثف وحده."],"سؤال ٣: (أ) العوامل المؤثرة على سعة المكثف، (ب) فوائد المكثف (صفحة 104)":["السعة تكبر بزيادة مساحة اللوحين، وبتقريبهما، وبوضع مادة عازلة ثابت عزلها كبير بينهما. والمكثف يفيد في تخزين الطاقة وإنتاج مجال محدد وفي الأجهزة اللاسلكية، كخزان صغير يمتلئ ويفرغ بسرعة.","مكثف `A = 0.1 m²` و `d = 1 × 10⁻³ m` في الفراغ: `C = 8.85 × 10⁻¹² × 0.1 ÷ 0.001 = 8.85 × 10⁻¹⁰ F`. ولو ضاعفنا المسافة لصارت السعة نصف ذلك.","المساحة الأكبر تتسع لشحنة أكثر عند الجهد نفسه، والمسافة الأقصر تقوي تأثير كل لوح في الآخر فيخزن شحنة أكثر. والعازل يضرب السعة في ثابت عزله كما في `C = ε₀ · εᵣ · A ÷ d`."],"سؤال ٤: شحنتان q₁ = 3 × 10⁻⁹ C و q₂ = −5 × 10⁻⁹ C والمسافة بينهما 2 m، أوجد القوة الكهربائية (صفحة 105)":["نضرب الشحنتين ونضرب في ثابت كولوم ثم نقسم على مربع المسافة. والإشارة السالبة لا تدخل في الحساب، فهي تخبرنا فقط بنوع القوة.","شحنتان `2 × 10⁻⁹ C` و `−6 × 10⁻⁹ C` بينهما `3 m`: `F = 9 × 10⁹ × 2 × 10⁻⁹ × 6 × 10⁻⁹ ÷ 3² = 1.2 × 10⁻⁸ N` تجاذب.","نستخدم القيمة المطلقة لأن القانون يعطي مقدار القوة، والمقدار لا يكون سالبا. أما اتجاه القوة فنحدده من القاعدة: الشحنتان المختلفتان تتجاذبان."],"سؤال ٤: شحنتان q₁ = 3 × 10⁻⁹ C و q₂ = −5 × 10⁻⁹ C والمسافة بينهما 2 m، أوجد القوة الكهربائية (صفحة 105) (تابع)":["الناتج قوة صغيرة جدا لأن الشحنتين بالنانوكولوم. وبما أن إحداهما موجبة والأخرى سالبة فكل منهما تسحب الأخرى نحوها.","لو ضاعفنا المسافة إلى `4 m` لصارت القوة ربع قيمتها: `3.375 × 10⁻⁸ ÷ 4 ≈ 8.44 × 10⁻⁹ N`.","الشحنتان مختلفتا الإشارة، والشحنات المختلفة تتجاذب. والقوة صغيرة لأن حاصل ضرب الشحنتين يساوي `1.5 × 10⁻¹⁷ C²` فقط، فلا يعوضه كبر الثابت `9 × 10⁹`."],"سؤال ٥: شحنة 4 × 10⁻⁶ C في مجال كهربائي تأثرت بقوة 8 × 10⁻³ N، ما مقدار المجال؟ (صفحة 105)":["المجال هو نصيب كل كولوم من القوة. فنقسم القوة الكلية على الشحنة، كما نقسم ثمن مجموعة أشياء على عددها لنعرف ثمن الواحدة.","شحنة `5 × 10⁻⁶ C` تأثرت بقوة `0.02 N`: `E = 0.02 ÷ (5 × 10⁻⁶) = 4000 N/C`.","لأن القوة تتناسب طرديا مع الشحنة الموضوعة في المجال، فالنسبة `F ÷ q` ثابتة عند النقطة نفسها. هذه النسبة هي شدة المجال، ووحدتها `N/C`."],"سؤال ٦: أوجد شدة المجال على بعد 0.25 m من شحنة 3 × 10⁻⁹ C (صفحة 105)":["المجال حول شحنة نقطية يضعف كلما ابتعدنا عنها، مثل ضوء المصباح الذي يخفت مع البعد. لذلك نقسم على مربع المسافة لا على المسافة نفسها.","شحنة `2 × 10⁻⁹ C` على بعد `0.5 m`: `E = 9 × 10⁹ × 2 × 10⁻⁹ ÷ 0.25 = 72 N/C`.","المجال يتوزع في كل الاتجاهات حول الشحنة على سطح كرة تكبر مساحته مع `r²`. لذلك تقل شدته مع مربع المسافة."],"سؤال ٦: أوجد شدة المجال على بعد 0.25 m من شحنة 3 × 10⁻⁹ C (صفحة 105) (تابع)":["قسمة `27` على `0.0625` تعني ضرب `27` في `16`، لأن `0.0625` جزء من ستة عشر. لذلك كبر الناتج كثيرا.","عند ضعف المسافة `0.5 m` يصبح المجال ربع القيمة: `432 ÷ 4 = 108 N/C`.","لأن المسافة `0.25 m` أقل من متر، فمربعها أصغر منها، والقسمة على عدد أصغر من الواحد تكبر الناتج. وهذا يعني أن المجال قوي قرب الشحنة."],"سؤال ٧: فرق الجهد بين نقطتين في مجال منتظم شدته 1000 N/C والمسافة بينهما 0.02 m (صفحة 106)":["في المجال المنتظم تكون الشدة ثابتة، ففرق الجهد يساوي شدة المجال مضروبة في المسافة، مثل حساب ارتفاع درج من ارتفاع الدرجة الواحدة وعدد الدرجات.","مجال `2500 N/C` ومسافة `0.04 m`: `ΔV = 2500 × 0.04 = 100 V`.","فرق الجهد هو الشغل لكل كولوم، والشغل في مجال ثابت يساوي القوة في المسافة. والقوة لكل كولوم هي `E`، فيصبح فرق الجهد `E·d`."],"سؤال ٨: أوجد الجهد على بعد 0.2 m من شحنة نقطية 4 × 10⁻⁶ C (صفحة 106)":["الجهد حول شحنة نقطية يقل كلما ابتعدنا عنها، لكنه يقل مع المسافة نفسها لا مع مربعها. فنضرب ثابت كولوم في الشحنة ونقسم على البعد.","شحنة `3 × 10⁻⁶ C` على بعد `0.3 m`: `V = 9 × 10⁹ × 3 × 10⁻⁶ ÷ 0.3 = 9 × 10⁴ V`.","الجهد كمية قياسية تمثل الطاقة لكل كولوم، وهو يقل مع `r` أبطأ من المجال الذي يقل مع `r²`. لذلك لا يربع البعد في قانون الجهد."],"سؤال ٨: أوجد الجهد على بعد 0.2 m من شحنة نقطية 4 × 10⁻⁶ C (صفحة 106) (تابع)":["الناتج `1.8 × 10⁵ V` هو نفسه `180000 V`، كتبناه فقط بالصورة العادية بدل الصورة العلمية.","عند ضعف المسافة `0.4 m`: `V = 9 × 10⁹ × 4 × 10⁻⁶ ÷ 0.4 = 9 × 10⁴ V`، أي نصف القيمة.","الجهد يتناسب عكسيا مع المسافة، فإذا تضاعف البعد صار الجهد نصفه. والقيمة كبيرة لأن الشحنة بالميكروكولوم وهي كبيرة نسبيا."],"سؤال ٩: سعة مكثف شحنته 4 × 10⁻⁴ C وفرق الجهد بين لوحيه 100 V (صفحة 106)":["السعة تعني كم كولوما يخزن المكثف لكل فولت. فنقسم الشحنة على الجهد، مثل معرفة كم لترا يدخل الخزان مقابل كل متر من ارتفاع الماء.","مكثف شحنته `6 × 10⁻⁴ C` وجهده `200 V`: `C = 6 × 10⁻⁴ ÷ 200 = 3 × 10⁻⁶ F = 3 µF`.","شحنة المكثف تتناسب طرديا مع جهده، فالنسبة `Q ÷ V` ثابتة لا تتغير مهما شحناه. لذلك تصلح هذه النسبة صفة للمكثف نفسه."],"سؤال ١٠: مكثف سعته 4.5 × 10⁻¹² F متصل ببطارية 12 V، أوجد: ١) الشحنة ٢) الطاقة المختزنة (صفحة 107)":["البطارية تدفع الشحنة إلى المكثف حتى يصير جهده مثل جهدها. فالشحنة تساوي السعة في الجهد، والطاقة نصف السعة في مربع الجهد.","مكثف `5 × 10⁻¹² F` على `10 V`: `Q = 5 × 10⁻¹¹ C`، و `W = ½ × 5 × 10⁻¹² × 10² = 2.5 × 10⁻¹⁰ J`.","الطاقة تتناسب مع مربع الجهد لأن زيادة الجهد تزيد الشحنة المخزنة، وتزيد في الوقت نفسه الشغل اللازم لدفع كل كولوم إضافي. فيتضاعف الأثر مرتين."],"سؤال ١٠: مكثف سعته 4.5 × 10⁻¹² F متصل ببطارية 12 V، أوجد: ١) الشحنة ٢) الطاقة المختزنة (صفحة 107) (تابع)":["بعد تربيع الجهد `12² = 144` نضرب في نصف السعة فنحصل على الطاقة. والشحنة موجبة على لوح وسالبة بالمقدار نفسه على اللوح الآخر.","لو وصلنا المكثف نفسه ببطارية `24 V` لصارت الطاقة أربعة أضعاف: `4 × 3.24 × 10⁻¹⁰ = 1.296 × 10⁻⁹ J`.","اللوحان يحملان شحنتين متساويتين مقدارا ومختلفتين إشارة لأن البطارية تنقل الإلكترونات من لوح إلى الآخر فقط. لذلك نسمي `Q` شحنة المكثف، وهي مقدار ما على كل لوح."],"سؤال ١١: مكثف متوازي اللوحين، d = 1 × 10⁻³ m و C = 6 × 10⁻⁶ F وشحنته 6 × 10⁻⁶ C، أوجد: ١) فرق الجهد ٢) المجال داخله (صفحة 107)":["أولا نجد الجهد من الشحنة والسعة، ثم نقسم الجهد على المسافة بين اللوحين لنجد المجال. خطوتان متتاليتان، ونتيجة الأولى تدخل في الثانية.","مكثف `C = 2 × 10⁻⁶ F` شحنته `1 × 10⁻⁵ C` و `d = 2 × 10⁻³ m`: `V = 5 V`، و `E = 5 ÷ 0.002 = 2500 V/m`.","المجال بين لوحي المكثف منتظم، لذلك يرتبط بالجهد بالعلاقة البسيطة `V = E·d`. والمسافة الصغيرة جدا تجعل المجال كبيرا حتى مع جهد صغير."],"سؤال ١١: مكثف متوازي اللوحين، d = 1 × 10⁻³ m و C = 6 × 10⁻⁶ F وشحنته 6 × 10⁻⁶ C، أوجد: ١) فرق الجهد ٢) المجال داخله (صفحة 107) (تابع)":["القسمة على `1 × 10⁻³` تعني الضرب في ألف، فصار المجال ألف مرة قدر الجهد. ووحدة `V/m` هي نفسها `N/C`.","لو كان الجهد `3 V` والمسافة نفسها: `E = 3 ÷ (1 × 10⁻³) = 3000 V/m`.","الوحدتان متكافئتان لأن `V = J/C` و `J = N·m`، فتصبح `V/m = N/C`. لذلك يمكن التعبير عن المجال بأي منهما."],"سؤال ١٢: مكثفان 2 × 10⁻⁶ F و 4 × 10⁻⁶ F، أوجد السعة الكلية: ١) على التوالي ٢) على التوازي (صفحة 108)":["في التوالي تصبح السعة الكلية أصغر من أصغر مكثف، كأن المسافة بين اللوحين زادت. وفي التوازي تجمع السعات مباشرة، كأن مساحة اللوح كبرت.","مكثفان `3 µF` و `6 µF`: على التوالي `C = 18 ÷ 9 = 2 µF`، وعلى التوازي `C = 3 + 6 = 9 µF`.","في التوازي يتساوى الجهد وتجمع الشحنات، فتجمع السعات. وفي التوالي تتساوى الشحنة ويتوزع الجهد، فتجمع مقلوبات السعات وتقل السعة الكلية."],"سؤال ١٢: مكثفان 2 × 10⁻⁶ F و 4 × 10⁻⁶ F، أوجد السعة الكلية: ١) على التوالي ٢) على التوازي (صفحة 108) (تابع)":["نتيجة التوازي أكبر بكثير من نتيجة التوالي: التوازي يزيد السعة والتوالي ينقصها. فإذا أردت سعة كبيرة فصل المكثفات على التوازي.","ثلاثة مكثفات `2 µF` على التوازي: `C = 2 + 2 + 2 = 6 µF`، وعلى التوالي: `C = 2 ÷ 3 ≈ 0.67 µF`.","التوصيل على التوازي يشبه زيادة مساحة اللوحين، والمساحة الأكبر تعني سعة أكبر. أما التوالي فيشبه زيادة المسافة بين اللوحين فتقل السعة."],"سؤال ١٣: مكثفان C₁ = 4 × 10⁻⁹ F و C₂ = 2 × 10⁻⁹ F على التوالي، وفرق الجهد 12 V، أوجد: ١) السعة الكلية ٢) شحنة كل مكثف ٣) فرق جهد كل مكثف (صفحة 108)":["في التوالي تمر الشحنة نفسها على كل المكثفات كأنها طابور واحد. فنحسب السعة الكلية أولا، ثم الشحنة، ثم نقسم الشحنة على سعة كل مكثف لنعرف جهده.","مكثفان `6 nF` و `3 nF` على التوالي مع `9 V`: `C = 2 nF`، و `Q = 2 × 10⁻⁹ × 9 = 1.8 × 10⁻⁸ C`، و `V₁ = 3 V` و `V₂ = 6 V`.","الشحنة متساوية في التوالي لأن اللوحين المتصلين في الوسط معزولان عن البطارية، فكل شحنة تظهر على أحدهما تقابلها شحنة معاكسة على الآخر. لذلك تتكرر الشحنة نفسها على كل مكثف."],"سؤال ١٣: مكثفان C₁ = 4 × 10⁻⁹ F و C₂ = 2 × 10⁻⁹ F على التوالي، وفرق الجهد 12 V، أوجد: ١) السعة الكلية ٢) شحنة كل مكثف ٣) فرق جهد كل مكثف (صفحة 108) (تابع)":["المكثف ذو السعة الأصغر يأخذ جهدا أكبر، لأن الشحنة نفسها تحتاج جهدا أكبر لتخزن في سعة أصغر. ومجموع الجهدين يساوي جهد البطارية.","مكثفان `5 nF` و `5 nF` على التوالي مع `10 V`: `C = 2.5 nF`، و `Q = 2.5 × 10⁻⁸ C`، وجهد كل منهما `5 V`.","من `V = Q ÷ C` ومع ثبات الشحنة يتناسب الجهد عكسيا مع السعة. ومجموع الجهود يساوي جهد المصدر لأن الطاقة لكل كولوم تتوزع على المكثفات."],"سؤال ١٤: مكثفان C₁ = 400 × 10⁻⁹ F و C₂ = 100 × 10⁻⁹ F على التوازي، وفرق الجهد 110 V، أوجد: ١) السعة الكلية ٢) شحنة كل مكثف ٣) الشحنة الكلية (صفحة 109)":["في التوازي يأخذ كل مكثف جهد البطارية كاملا، فنجمع السعات للحصول على السعة الكلية. وكل مكثف يأخذ شحنة تتناسب مع سعته.","مكثفان `300 nF` و `200 nF` على التوازي مع `20 V`: `C = 500 nF`، و `Q₁ = 6 × 10⁻⁶ C`، و `Q₂ = 4 × 10⁻⁶ C`.","كل مكثف متصل مباشرة بطرفي البطارية، لذلك يتساوى الجهد عليها جميعا. والمكثف الأكبر سعة يخزن شحنة أكبر عند الجهد نفسه."],"سؤال ١٤: مكثفان C₁ = 400 × 10⁻⁹ F و C₂ = 100 × 10⁻⁹ F على التوازي، وفرق الجهد 110 V، أوجد: ١) السعة الكلية ٢) شحنة كل مكثف ٣) الشحنة الكلية (صفحة 109) (تابع)":["الشحنة الكلية هي مجموع شحنتي المكثفين، ويمكن التأكد منها بضرب السعة الكلية في الجهد. والطريقتان تعطيان الناتج نفسه.","مكثفان `300 nF` و `200 nF` على `20 V`: `Q = 6 × 10⁻⁶ + 4 × 10⁻⁶ = 1 × 10⁻⁵ C`، وهو نفسه `5 × 10⁻⁷ × 20`.","الشحنة محفوظة، فما يخرج من البطارية يتوزع على المكثفين دون أن يضيع شيء. لذلك يجب أن يساوي مجموع الشحنتين ناتج `C · V` للسعة الكلية."],"رسم توضيحي":["في التوالي توضع المكثفات واحدا بعد الآخر على مسار واحد، وفي التوازي يوضع كل مكثف على فرع مستقل بين النقطتين نفسيهما. مثل طريق واحد طويل مقابل طرق متوازية.","مكثفان `4 µF` و `4 µF`: على التوالي `C = 16 ÷ 8 = 2 µF`، وعلى التوازي `C = 4 + 4 = 8 µF`.","شكل التوصيل يحدد ما يتساوى بين المكثفات: في التوالي تتساوى الشحنة، وفي التوازي يتساوى الجهد. ومن ذلك يأتي قانون السعة الكلية لكل حالة."],"تمرين 1 · سؤال ٤ (صفحة 105)":["نعوض بالشحنتين بالكولوم دون الإشارة، ونقسم على مربع المسافة. والإشارتان المختلفتان تخبراننا أن القوة تجاذب.","شحنتان `4 nC` و `−2 nC` بينهما `1 m`: `F = 9 × 10⁹ × 4 × 10⁻⁹ × 2 × 10⁻⁹ ÷ 1² = 7.2 × 10⁻⁸ N` تجاذب.","تحويل `nC` إلى `C` ضروري لأن ثابت كولوم مقاس بالكولوم. ومربع المسافة في المقام يجعل القوة تقل بسرعة كلما تباعدت الشحنتان."],"تمرين 2 · سؤال ٥ (صفحة 105)":["شدة المجال هي القوة على كل كولوم، فنقسم القوة على الشحنة. وانتبه أن القسمة على عدد صغير جدا تعطي ناتجا كبيرا.","شحنة `2 × 10⁻⁶ C` تأثرت بقوة `6 × 10⁻³ N`: `E = 6 × 10⁻³ ÷ (2 × 10⁻⁶) = 3000 N/C`.","لأن المجال صفة للمكان نفسه، فلو ضاعفنا الشحنة لتضاعفت القوة وبقيت النسبة كما هي. لذلك نعرفه بالقوة لكل وحدة شحنة."],"تمرين 3 · سؤال ٦ (صفحة 105)":["نضرب ثابت كولوم في الشحنة ثم نقسم على مربع البعد. والبعد هنا أقل من متر، فمربعه أصغر منه، فيكبر المجال.","شحنة `4 × 10⁻⁹ C` على بعد `0.2 m`: `E = 9 × 10⁹ × 4 × 10⁻⁹ ÷ 0.04 = 900 N/C`.","المجال يتوزع حول الشحنة في كل الاتجاهات، والمساحة التي يتوزع عليها تكبر مع مربع البعد. لذلك تضعف شدته مع `r²`."],"تمرين 4 · سؤال ٧ (صفحة 106)":["في المجال المنتظم يزيد فرق الجهد بانتظام مع المسافة، فنضرب شدة المجال في المسافة مباشرة.","مجال `3000 N/C` ومسافة `0.05 m`: `ΔV = 3000 × 0.05 = 150 V`.","لأن المجال المنتظم ثابت المقدار والاتجاه، فكل متر يضيف فرق الجهد نفسه. لذلك تكون العلاقة خطية `ΔV = E·d`."],"تمرين 5 · سؤال ٨ (صفحة 106)":["الجهد عند نقطة قرب شحنة يحسب بضرب ثابت كولوم في الشحنة والقسمة على البعد، دون تربيع.","شحنة `5 × 10⁻⁶ C` على بعد `0.5 m`: `V = 9 × 10⁹ × 5 × 10⁻⁶ ÷ 0.5 = 9 × 10⁴ V`.","الجهد هو الطاقة لكل كولوم، وهو كمية قياسية تقل مع البعد نفسه. لذلك يظهر `r` في المقام دون تربيع، بخلاف المجال."],"تمرين 6 · سؤال ٩ (صفحة 106)":["السعة هي الشحنة المخزنة مقابل كل فولت، فنقسم الشحنة على فرق الجهد بين اللوحين.","شحنة `9 × 10⁻⁴ C` وجهد `300 V`: `C = 9 × 10⁻⁴ ÷ 300 = 3 × 10⁻⁶ F`.","إذا ضاعفنا الجهد تضاعفت الشحنة، فتبقى النسبة ثابتة. لذلك تعبر السعة عن المكثف نفسه لا عن حالة شحنه."],"تمرين 7 · سؤال ١٠ (صفحة 107)":["نعيد ترتيب `C = q / V` لنحصل على الشحنة: نضرب السعة في الجهد.","مكثف `2.5 × 10⁻¹² F` على `20 V`: `q = 2.5 × 10⁻¹² × 20 = 5 × 10⁻¹¹ C`.","الشحنة تتناسب طرديا مع الجهد، فكلما زاد جهد البطارية دفعت شحنة أكبر إلى اللوحين. والسعة هي ثابت التناسب بينهما."],"تمرين 8 · سؤال ١٠ (صفحة 107)":["الطاقة المخزنة تساوي نصف السعة في مربع الجهد، فمضاعفة الجهد تجعل الطاقة أربعة أضعاف.","مكثف `4 × 10⁻¹² F` على `10 V`: `PE = 0.5 × 4 × 10⁻¹² × 10² = 2 × 10⁻¹⁰ J`.","يظهر النصف لأن الجهد يبدأ من صفر ويزداد تدريجيا أثناء الشحن، فمتوسط الجهد الذي تنقل عنده الشحنة نصف الجهد النهائي."],"تمرين 9 · سؤال ١١ (صفحة 107)":["نقسم الشحنة على السعة لنجد الجهد. وعندما تتساوى قيمتا الشحنة والسعة يكون الجهد فولتا واحدا.","مكثف `4 × 10⁻⁶ F` شحنته `2 × 10⁻⁵ C`: `V = 2 × 10⁻⁵ ÷ (4 × 10⁻⁶) = 5 V`.","الفاراد هو كولوم لكل فولت، فالمكثف الذي يحمل من الكولومات عددا يساوي سعته بالفاراد يكون جهده فولتا واحدا."],"تمرين 10 · سؤال ١١ (صفحة 107)":["المجال بين اللوحين هو فرق الجهد مقسوما على المسافة بينهما، وكلما قربنا اللوحين قوي المجال.","جهد `6 V` ومسافة `2 × 10⁻³ m`: `E = 6 ÷ 0.002 = 3000 V/m`.","المجال بين لوحي المكثف منتظم، فيتوزع فرق الجهد بالتساوي على المسافة. لذلك نصيب كل متر من الجهد هو شدة المجال."],"تمرين 11 · سؤال ١٢ (صفحة 108)":["في التوالي نضرب السعتين ونقسم على مجموعهما، فتخرج السعة الكلية أصغر من أصغرهما.","مكثفان `3 µF` و `6 µF` على التوالي: `C = 3 × 6 ÷ (3 + 6) = 2 µF`.","في التوالي تتساوى الشحنة ويتوزع الجهد على المكثفات، فتحتاج المجموعة جهدا أكبر للشحنة نفسها. وهذا يعني سعة كلية أصغر."],"تمرين 12 · سؤال ١٢ (صفحة 108)":["في التوازي نجمع السعات مباشرة، كأننا نكبر مساحة لوح واحد.","مكثفان `5 µF` و `7 µF` على التوازي: `C = 5 + 7 = 12 µF`.","كل مكثف يأخذ جهد المصدر كاملا، والشحنات تجمع. فالشحنة الكلية لكل فولت هي مجموع السعات."],"تمرين 13 · سؤال ١٣ (صفحة 108)":["يمكن الحساب بالنانوفاراد مباشرة دون تحويل، لأن الضرب ثم القسمة يحفظان البادئة نفسها في الناتج.","مكثفان `8 nF` و `8 nF` على التوالي: `C = 8 × 8 ÷ (8 + 8) = 4 nF`، أي نصف أحدهما.","السعة الكلية لا تعتمد على جهد المصدر، لأنها صفة للمكثفات وطريقة توصيلها فقط. لذلك لا نحتاج `12 V` لحسابها."],"تمرين 14 · سؤال ١٤ (صفحة 109)":["على التوازي نجمع السعات، ويمكن الجمع بالنانوفاراد مباشرة لأن البادئة واحدة.","مكثفان `250 nF` و `150 nF` على التوازي: `C = 250 + 150 = 400 nF = 4 × 10⁻⁷ F`.","في التوازي يرى كل مكثف الجهد نفسه، فتجمع شحناتها وبالتالي سعاتها. والجهد لا يؤثر في السعة الكلية."]},"3-9":{"":["هذا الدرس مراجعة شاملة للوحدة: الشحنات والقوة والمجال والجهد والمكثفات. نثبت فيه القوانين ونصحح الأخطاء الشائعة بأسئلة الاختيار والصح والخطأ.","مكثف `5 µF` على `40 V`: `q = 5 × 10⁻⁶ × 40 = 2 × 10⁻⁴ C`، و `PE = ½ × 5 × 10⁻⁶ × 40² = 4 × 10⁻³ J`.","المراجعة تربط المفاهيم ببعضها، فيظهر أن الوحدة مبنية على فكرة واحدة: الشحنة تنشئ مجالا، والمجال يؤثر بقوة ويخزن طاقة. وفهم هذا الرابط يسهل تذكر القوانين."],"مراجعة الوحدة الرابعة":["الشحنات المتشابهة تتنافر والمختلفة تتجاذب، ونشحن الأجسام بالدلك أو اللمس أو الحث. ومن الشحنة نحسب القوة والمجال والجهد، والمكثف يخزن الشحنة.","شحنة `1 × 10⁻⁹ C` على بعد `0.3 m`: `E = 9 × 10⁹ × 1 × 10⁻⁹ ÷ 0.09 = 100 N/C`، و `V = 9 ÷ 0.3 = 30 V`.","المجال يقل مع `r²` والجهد مع `r` لأن المجال قوة لكل كولوم والجهد طاقة لكل كولوم. وخطوط المجال لا تتقاطع لأن للمجال اتجاها واحدا عند كل نقطة."],"مراجعة الوحدة الرابعة (تابع)":["في التوازي يأخذ كل مكثف الجهد نفسه، وفي التوالي يأخذ كل مكثف الشحنة نفسها. والطاقة المخزنة نصف السعة في مربع الجهد.","مكثفان `2 µF` و `2 µF`: على التوازي `4 µF`، وعلى التوالي `1 µF`. وطاقة مكثف `4 µF` على `10 V`: `PE = ½ × 4 × 10⁻⁶ × 10² = 2 × 10⁻⁴ J`.","في التوالي تتوزع الجهود على المكثفات فتقل السعة الكلية عن أصغرها، وفي التوازي تجمع الشحنات فتجمع السعات. والنصف في قانون الطاقة لأن الجهد يزداد تدريجيا أثناء الشحن."],"تمارين الوحدة محلولة":["لمعرفة الشحنة على المكثف نضرب سعته في جهده. أما القانون الأول فيحسب السعة من أبعاد المكثف، والثاني يعرف وحدة الفاراد فقط.","مكثف `10 µF` على `25 V`: `q = 10 × 10⁻⁶ × 25 = 2.5 × 10⁻⁴ C`.","الشحنة تتناسب طرديا مع الجهد، والسعة هي ثابت هذا التناسب. فإذا عرفنا الثابت والجهد عرفنا الشحنة مباشرة."],"اختر الإجابة ٣: قانون التوصيل على التوازي (صفحة 110)":["على التوازي نجمع السعات كما هي. أما جمع المقلوبات فهو للتوالي، لذلك لا يصح أن تكون كل الاختيارات صحيحة.","ثلاثة مكثفات `1 µF` و `3 µF` و `5 µF` على التوازي: `C_eq = 1 + 3 + 5 = 9 µF`.","المكثفات على التوازي تشترك في الجهد نفسه، والشحنة الكلية مجموع شحناتها. وبالقسمة على الجهد المشترك نحصل على مجموع السعات."],"اختر الإجابة ٤: قوانين التوصيل على التوالي (صفحة 111)":["في التوالي تكون الشحنة نفسها على كل مكثف، والسعة المكافئة نحسبها بجمع المقلوبات. فالعلاقتان صحيحتان معا.","مكثفان `4 µF` و `12 µF` على التوالي: `1/C_eq = 1/4 + 1/12 = 4/12`، إذن `C_eq = 3 µF`.","اللوحان الداخليان بين مكثفين متتاليين معزولان، فما يظهر على أحدهما من شحنة يقابله مقدار معاكس على الآخر. لذلك تتساوى الشحنة وتجمع الجهود، فتجمع مقلوبات السعات."],"اختر الإجابة ٥: وحدة قياس الشحنة (صفحة 111)":["لكل كمية وحدتها: الشحنة بالكولوم، والطول بالمتر، والطاقة بالجول، فلا نخلط بينها.","شحنة `4.8 × 10⁻¹⁹ C` تعادل شحنة `3` إلكترونات، لأن `4.8 × 10⁻¹⁹ ÷ (1.6 × 10⁻¹⁹) = 3`.","الكولوم هو الشحنة التي يحملها تيار شدته `1 A` في زمن `1 s`، كما يظهر من `I = q / t`. لذلك هو وحدة الشحنة في النظام الدولي."],"اختر الإجابة ٦: المواد التي لا تسمح بمرور الشحنات (صفحة 111)":["المواد العازلة كالزجاج والخشب والبلاستيك تمسك إلكتروناتها فلا تتركها تتحرك. أما الشغل والقدرة فليسا مواد أصلا، بل كميات فيزيائية.","مقبض المفك مصنوع من البلاستيك ليعزل يد الفني، وأسلاك الكهرباء مغلفة ببلاستيك بينما قلبها من النحاس الموصل.","في العوازل ترتبط الإلكترونات بذراتها بقوة، فلا توجد إلكترونات حرة تنقل الشحنة. لذلك لا يسري فيها تيار يذكر."],"اختر الإجابة ٧: تدفق الشحنات عند تطبيق فرق جهد (صفحة 111)":["عندما نطبق فرق جهد على موصل تتحرك الشحنات فيه، وهذه الحركة هي التيار الكهربائي، مثل الماء الذي يجري في أنبوب بسبب فرق الضغط.","شحنة `6 C` تعبر مقطع سلك في `3 s`: `I = q / t = 6 ÷ 3 = 2 A`.","فرق الجهد ينشئ مجالا داخل الموصل، والمجال يؤثر بقوة في الإلكترونات الحرة فيدفعها في اتجاه واحد. وتدفقها المنتظم هو التيار."],"صح وخطأ ١: سريان التيار في السلك بين طرفي المصدر (صفحة 112)":["يكفي مصدر جهد وسلك يصل بين طرفيه ليتكون مسار مغلق يجري فيه التيار، وهذه أبسط دائرة كهربائية.","بطارية `1.5 V` يصل طرفيها سلك، فتعبر مقطعه شحنة `3 C` خلال `2 s`، أي تيار `I = 3 ÷ 2 = 1.5 A`.","التيار يحتاج مسارا مغلقا ودافعا. فرق الجهد هو الدافع، والسلك الموصل يوفر المسار، فإذا انقطع المسار توقف التيار."],"صح وخطأ ٢: تفاعل الشحنات المختلفة (صفحة 112)":["العبارة خاطئة: الشحنات المختلفة تتجاذب، والمتشابهة هي التي تتنافر، مثل قطبي المغناطيس المختلفين اللذين يتجاذبان.","شحنتان `+1 µC` و `−1 µC` بينهما `1 m` تتجاذبان بقوة `F = 9 × 10⁹ × 1 × 10⁻⁶ × 1 × 10⁻⁶ ÷ 1² = 9 × 10⁻³ N`.","المجال حول الشحنة الموجبة يتجه بعيدا عنها، والقوة على الشحنة السالبة تكون عكس اتجاه المجال. لذلك تسحب السالبة نحو الموجبة."],"صح وخطأ ٣: تعريف الشحن بالدلك (صفحة 112)":["الشحن دون ملامسة بتقريب جسم مشحون هو الحث. أما الدلك فهو حك جسمين معا فتنتقل الإلكترونات من أحدهما إلى الآخر.","دلك مسطرة بلاستيكية بقطعة صوف يشحنها فتجذب قصاصات الورق، وهذا شحن بالدلك. أما تقريب المسطرة من كرة معدنية دون لمسها فيفصل الشحنات فيها، وهذا حث.","عند الدلك تنتقل الإلكترونات من مادة إلى أخرى، فيشحن الجسمان بشحنتين متساويتين مختلفتين. أما في الحث فلا تنتقل شحنات بين الجسمين، بل يعاد ترتيبها داخل الجسم المتعادل."],"صح وخطأ ٤: وحدة السعة الكهربائية (صفحة 112)":["الكولوم وحدة الشحنة، أما السعة فوحدتها الفاراد، وهو كولوم لكل فولت.","مكثف يخزن `2 × 10⁻⁶ C` عند جهد `1 V` سعته `2 × 10⁻⁶ F = 2 µF`.","السعة نسبة بين شحنة وجهد، فوحدتها وحدة الشحنة مقسومة على وحدة الجهد `C/V`، وهذه هي الفاراد."],"صح وخطأ ٥: اتجاه خطوط المجال حول الشحنة السالبة (صفحة 112)":["خطوط المجال تبدأ من الشحنة الموجبة وتنتهي عند السالبة، فحول الشحنة السالبة تتجه الخطوط نحوها من كل الجهات.","شحنة اختبار موجبة `1 × 10⁻⁹ C` على بعد `0.3 m` من شحنة `−1 × 10⁻⁹ C` تتأثر بقوة `9 × 10⁹ × 10⁻¹⁸ ÷ 0.09 = 1 × 10⁻⁷ N` نحو الشحنة السالبة.","اتجاه المجال هو اتجاه القوة على شحنة اختبار موجبة، والشحنة الموجبة تنجذب نحو السالبة. لذلك تشير الخطوط إلى الشحنة السالبة."],"صح وخطأ ٦: تقاطع خطوط المجال (صفحة 112)":["خطوط المجال لا تتقاطع أبدا، فلو تقاطعت لكان للنقطة نفسها اتجاهان، مثل سهم لا يمكن أن يشير إلى جهتين معا.","عند نقطة يؤثر فيها مجالان `300 N/C` شرقا و `100 N/C` غربا يكون المجال المحصل `200 N/C` شرقا فقط، أي خط واحد يمر بالنقطة.","المجالات عند النقطة الواحدة تجمع جمعا متجها فتعطي متجها محصلا واحدا. لذلك يمر بكل نقطة خط مجال واحد فقط."],"صح وخطأ ٧: تقارب خطوط المجال وشدته (صفحة 112)":["حيث تتزاحم خطوط المجال يكون المجال قويا، وحيث تتباعد يكون ضعيفا، مثل الزحام قرب باب ضيق.","حول شحنة `1 × 10⁻⁹ C`: عند `0.1 m` يكون `E = 900 N/C`، وعند `0.3 m` يكون `E = 100 N/C`، والخطوط أكثف عند البعد الأصغر.","عدد الخطوط الخارجة من الشحنة ثابت، وهي تتوزع على مساحة تكبر مع البعد. فتقل كثافتها كما تقل شدة المجال، فتكون الكثافة مقياسا للشدة."],"صح وخطأ ٨: صفة المجال المنتظم (صفحة 112)":["المجال المنتظم ثابت في شدته واتجاهه معا، وخطوطه متوازية ومتساوية التباعد، كما بين لوحي المكثف.","بين لوحين فرق الجهد بينهما `50 V` والمسافة `0.01 m` يكون `E = 50 ÷ 0.01 = 5000 V/m` عند أي نقطة بينهما.","اللوحان المتوازيان المشحونان يحملان شحنة موزعة بانتظام، فتتساوى القوة على شحنة الاختبار في كل نقطة بينهما مقدارا واتجاها."],"صح وخطأ ٩: علاقة الشحنة بالجهد في المكثف (صفحة 112)":["العبارة خاطئة: كلما زاد الجهد على المكثف زادت شحنته بالنسبة نفسها، فإذا تضاعف الجهد تضاعفت الشحنة.","مكثف `5 µF`: عند `10 V` شحنته `5 × 10⁻⁵ C`، وعند `20 V` شحنته `1 × 10⁻⁴ C`.","السعة ثابتة للمكثف لأنها تعتمد على أبعاده والعازل فقط، فالعلاقة `q = C·V` خطية. ولهذا تتناسب الشحنة طرديا مع الجهد."],"صح وخطأ ١٠: تفاعل الشحنات المتشابهة (صفحة 112)":["الشحنتان المتشابهتان، موجبتين كانتا أو سالبتين، تدفع إحداهما الأخرى بعيدا.","شحنتان `+2 µC` و `+2 µC` بينهما `0.3 m` تتنافران بقوة `F = 9 × 10⁹ × 2 × 10⁻⁶ × 2 × 10⁻⁶ ÷ 0.09 = 0.4 N`.","المجال حول الشحنة الموجبة يتجه بعيدا عنها، والشحنة الموجبة الأخرى تتأثر بقوة في اتجاه المجال فتدفع بعيدا. وبالمثل تتنافر السالبتان."],"صح وخطأ ١١: تعريف المواد الموصلة (صفحة 112)":["الموصلات فيها إلكترونات حرة كثيرة تتحرك بسهولة، لذلك تنقل الكهرباء جيدا، مثل النحاس والألومنيوم والحديد.","أسلاك المنازل تصنع عادة من النحاس، وأسلاك نقل الكهرباء الهوائية الكبيرة تصنع غالبا من الألومنيوم لأنه أخف وزنا.","الإلكترونات الخارجية في ذرات الفلزات ضعيفة الارتباط، فتتحرر وتتنقل بين الذرات. وعند تطبيق فرق جهد تندفع في اتجاه واحد فيسري التيار."],"صح وخطأ ١٢: نص قانون كولوم (صفحة 112)":["القوة تكبر بزيادة الشحنتين وتصغر كثيرا بزيادة المسافة، لأن المسافة مربعة في المقام.","شحنتان `1 µC` و `1 µC`: عند `1 m` القوة `9 × 10⁻³ N`، وعند `3 m` تصبح `9 × 10⁻³ ÷ 9 = 1 × 10⁻³ N`، أي تسع القيمة.","أثر الشحنة يتوزع في كل الاتجاهات على سطح كرة تتناسب مساحته مع `r²`، فيقل نصيب الشحنة الأخرى من القوة مع مربع المسافة."],"صح وخطأ ١٣: المجال حقل من المتجهات (صفحة 112)":["عند كل نقطة حول الشحنة سهم واحد يبين مقدار المجال واتجاهه، ومجموع هذه الأسهم هو المجال، مثل خريطة الرياح التي تضع سهما عند كل مدينة.","حول شحنة `2 × 10⁻⁹ C`: عند `0.3 m` يكون المتجه `E = 9 × 10⁹ × 2 × 10⁻⁹ ÷ 0.09 = 200 N/C` متجها بعيدا عن الشحنة.","المجال يحدد القوة على أي شحنة توضع عند النقطة، والقوة لها مقدار واتجاه. لذلك يلزم متجه كامل لكل نقطة."],"صح وخطأ ١٤: صيغة مجال الشحنة النقطية (صفحة 113)":["الصيغة تبدو مختلفة لكنها نفس `E = k·q / r²`، فالمقدار `1 / 4πε₀` هو ثابت كولوم نفسه مكتوبا بطريقة أخرى.","`1 ÷ (4 × 3.14 × 8.85 × 10⁻¹²) ≈ 9 × 10⁹ N·m²/C²`، وهذه قيمة `k` التي نعوض بها.","يظهر `4π` لأن المجال يتوزع على سطح كرة مساحتها `4πr²`. فكتابة الثابت بدلالة `ε₀` تظهر هذا التوزيع الكروي."],"صح وخطأ ١٥: تناسب الشحنة مع الجهد (صفحة 113)":["زيادة الجهد على المكثف تزيد شحنته بالنسبة نفسها، والرمز `∝` يعني «يتناسب مع».","مكثف `3 µF`: عند `4 V` شحنته `1.2 × 10⁻⁵ C`، وعند `12 V` شحنته `3.6 × 10⁻⁵ C`، أي ثلاثة أضعاف.","ثابت التناسب بين الشحنة والجهد هو السعة، وهو ثابت للمكثف الواحد. لذلك نحول التناسب `q ∝ V` إلى مساواة `q = C·V`."],"صح وخطأ ١٦: السعة في الفراغ والهواء (صفحة 113)":["الهواء يكاد يتصرف مثل الفراغ داخل المكثف، فالسعة تكاد تكون نفسها في الحالتين.","مكثف سعته في الفراغ `100 pF` تصبح سعته في الهواء `100 × 1.0006 ≈ 100.06 pF`.","جزيئات الهواء متباعدة جدا، فتأثيرها في المجال بين اللوحين ضئيل. لذلك ثابت عزله قريب جدا من الواحد."],"صح وخطأ ١٧: تعريف سعة المكثف (صفحة 113)":["السعة هي الشحنة مقسومة على الجهد، وتبقى هذه النسبة ثابتة للمكثف الواحد مهما شحناه.","مكثف شحنته `8 × 10⁻⁵ C` وجهده `40 V`: `C = 8 × 10⁻⁵ ÷ 40 = 2 × 10⁻⁶ F`.","النسبة ثابتة لأن الشحنة والجهد يتغيران معا بالنسبة نفسها. وقيمتها تحددها أبعاد المكثف ونوع العازل فقط."],"صح وخطأ ١٨: التوصيل المركب (صفحة 113)":["التوصيل المركب يجمع بين التوالي والتوازي في دائرة واحدة. نحله على مراحل: نبسط كل جزء ثم نجمع النتائج.","مكثفان `2 µF` و `4 µF` على التوازي يعطيان `6 µF`، ثم على التوالي مع `3 µF`: `C = 6 × 3 ÷ (6 + 3) = 2 µF`.","كل مجموعة توازي يمكن استبدالها بمكثف واحد مكافئ، وكذلك مجموعة التوالي. فتتحول الدائرة المعقدة خطوة بخطوة إلى مكثف واحد."],"صح وخطأ ١٩: الجهد في التوصيل على التوالي (صفحة 113)":["في التوالي تتقاسم المكثفات جهد المصدر، فمجموع جهودها يساوي الجهد الكلي، مثل تقسيم مسافة رحلة على مراحل.","مكثفات على التوالي جهودها `2 V` و `3 V` و `7 V`: `V = 2 + 3 + 7 = 12 V`.","الجهد طاقة لكل كولوم، والشحنة تمر عبر المكثفات واحدا بعد الآخر فتتجمع فروق الجهد عبرها. ومجموعها يساوي ما يعطيه المصدر."],"صح وخطأ ٢٠: السعة المكافئة في التوالي (صفحة 113)":["عند توصيل مكثفات على التوالي تكون السعة الكلية أصغر من أصغر مكثف فيها، لأننا نجمع المقلوبات.","مكثفات `2 µF` و `3 µF` و `6 µF` على التوالي: `1/C = 1/2 + 1/3 + 1/6 = 1`، إذن `C = 1 µF`.","مجموع المقلوبات أكبر من أي مقلوب منفرد، ومقلوب العدد الأكبر عدد أصغر. فتأتي السعة المكافئة أصغر من كل سعة."],"صح وخطأ ٢١: استخدام المكثف في تخزين الطاقة (صفحة 113)":["المكثف يخزن الطاقة في المجال بين لوحيه، ثم يطلقها بسرعة عند الحاجة، مثل فلاش الكاميرا.","مكثف `100 µF` مشحون إلى `200 V`: `PE = ½ × 100 × 10⁻⁶ × 200² = 2 J`.","شحن المكثف يتطلب شغلا لدفع الشحنات ضد تنافرها على اللوح، وهذا الشغل يختزن طاقة في المجال الكهربائي بين اللوحين."],"صح وخطأ ٢٢: أثر المسافة بين الألواح على السعة (صفحة 113)":["كلما باعدنا بين لوحي المكثف قلت سعته، وكلما قربناهما زادت.","مكثف `A = 0.2 m²`: عند `d = 2 × 10⁻³ m` سعته `8.85 × 10⁻¹⁰ F`، وعند `d = 4 × 10⁻³ m` تصبح `4.425 × 10⁻¹⁰ F`.","عند تباعد اللوحين يضعف تأثير كل لوح في الآخر، فيلزم جهد أكبر لتخزين الشحنة نفسها. وبما أن `C = q / V` فتقل السعة."],"رسم توضيحي":["الخطوط تخرج من الشحنة الموجبة كأشعة الشمس، وتدخل في الشحنة السالبة كالماء الذي ينصب في فتحة تصريف.","حول شحنة `4 × 10⁻⁹ C`: عند `0.2 m` يكون `E = 900 N/C`، وعند `0.4 m` يكون `E = 225 N/C`، ولذلك تتباعد الخطوط مع البعد.","اتجاه الخط هو اتجاه القوة على شحنة اختبار موجبة، فهي تبتعد عن الموجبة وتقترب من السالبة. وتقارب الخطوط قرب الشحنة يعني أن المجال أقوى هناك."],"كميات الكهرباء الساكنة: الرموز والقوانين والوحدات":["الجدول يضع أمامك كل كمية مع رمزها وقانونها ووحدتها، كبطاقة تعريف لكل كمية. احفظه لأن معظم الأسئلة تبدأ منه.","مكثف `2 µF` شحنته `6 × 10⁻⁵ C`: `V = q/C = 30 V`، و `U = ½·q·V = 0.5 × 6 × 10⁻⁵ × 30 = 9 × 10⁻⁴ J`.","الوحدات تتبع القوانين نفسها: المجال قوة على شحنة فوحدته `N/C`، والجهد طاقة على شحنة فوحدته `J/C`. لذلك يمكن استنتاج الوحدة من القانون."],"تمرين 1 · مثال ١ (صفحة 92)":["نحول الميكروكولوم إلى كولوم، ونضرب الشحنتين في ثابت كولوم، ثم نقسم على مربع المسافة.","شحنتان `1 µC` و `4 µC` بينهما `2 m`: `F = 9 × 10⁹ × 1 × 10⁻⁶ × 4 × 10⁻⁶ ÷ 2² = 9 × 10⁻³ N`.","مربع المسافة يجعل القوة شديدة الحساسية للبعد، فإذا ضاعفنا المسافة صارت القوة ربع قيمتها."],"تمرين 2 · مثال ٢ (صفحة 93)":["الشحنة الوسطى السالبة تنجذب نحو كل من جارتيها الموجبتين في اتجاهين متعاكسين. لذلك نطرح القوتين ونأخذ الفرق.","`q₁ = 2 µC` و `q₂ = −1 µC` و `q₃ = 2 µC`، والمسافتان `1 m` و `2 m`: `F₁ = 0.018 N` و `F₃ = 0.0045 N`، فالمحصلة `0.0135 N` نحو q₁.","القوة كمية متجهة، فالقوتان المتعاكستان على خط واحد تطرحان، والمحصلة في اتجاه القوة الأكبر. والقوة الأكبر من الشحنة الأقرب لأن المسافة مربعة."],"تمرين 3 · مثال ١ (صفحة 95)":["نضرب ثابت كولوم في الشحنة ونقسم على مربع البعد لنعرف شدة المجال عند النقطة.","شحنة `8 × 10⁻⁹ C` على بعد `0.4 m`: `E = 9 × 10⁹ × 8 × 10⁻⁹ ÷ 0.16 = 450 N/C`.","المجال الناشئ عن شحنة نقطية يتوزع على سطح كرة تتناسب مساحته مع `r²`، لذلك يضعف مع مربع البعد."],"تمرين 4 · مثال ٢ (صفحة 95)":["نقسم القوة على الشحنة لنعرف القوة التي يتلقاها كل كولوم، وهذه هي شدة المجال.","شحنة `5 × 10⁻⁹ C` تأثرت بقوة `1 × 10⁻⁵ N`: `E = 1 × 10⁻⁵ ÷ (5 × 10⁻⁹) = 2000 N/C`.","تعريف المجال بالقسمة على الشحنة يجعله مستقلا عن شحنة الاختبار، فيصف المكان نفسه."],"تمرين 5 · مثال ١ (صفحة 96)":["في المجال المنتظم نضرب شدة المجال في المسافة لنحصل على فرق الجهد.","مجال `4000 N/C` ومسافة `0.025 m`: `ΔV = 4000 × 0.025 = 100 V`.","المجال المنتظم ثابت، فالشغل لكل كولوم يزداد بانتظام مع المسافة. لذلك تكون العلاقة ضربا مباشرا."],"تمرين 6 · مثال ٢ (صفحة 96)":["الجهد حول الشحنة يقل مع البعد، ونحسبه بضرب ثابت كولوم في الشحنة والقسمة على المسافة.","شحنة `1 × 10⁻⁶ C` على بعد `0.3 m`: `V = 9 × 10⁹ × 1 × 10⁻⁶ ÷ 0.3 = 3 × 10⁴ V`.","الجهد طاقة لكل كولوم وهو كمية قياسية، ويقل مع `r` لا مع `r²`، لذلك لا نربع المسافة."],"تمرين 7 · مثال ١ (صفحة 98)":["نقسم الشحنة على الجهد لنعرف سعة المكثف، أي كم كولوما يخزن لكل فولت.","مكثف شحنته `5 × 10⁻⁴ C` وجهده `250 V`: `C = 5 × 10⁻⁴ ÷ 250 = 2 × 10⁻⁶ F`.","النسبة بين الشحنة والجهد ثابتة لكل مكثف، فتصلح مقياسا لقدرته على تخزين الشحنة."],"تمرين 8 · مثال ٢ (صفحة 98)":["نضرب السعة في الجهد لنحصل على الشحنة. والناتج الدقيق `27 × 45 = 1215`، أي `1.215 × 10⁻³ C`، وتقريبه `0.0012 C`.","مكثف `20 × 10⁻⁶ F` على `50 V`: `q = 20 × 10⁻⁶ × 50 = 1 × 10⁻³ C`.","الشحنة تتناسب طرديا مع الجهد، والسعة ثابت التناسب. فكلما زاد الجهد خزن المكثف شحنة أكبر."],"تمرين 9 · مثال ٣ (صفحة 99)":["سعة المكثف تكبر بكبر مساحة اللوحين وتصغر بتباعدهما. فنضرب `ε₀` في المساحة ونقسم على المسافة.","`A = 1 m²` و `d = 1 × 10⁻³ m`: `C = 8.85 × 10⁻¹² × 1 ÷ 0.001 = 8.85 × 10⁻⁹ F`.","المساحة الكبيرة تتسع لشحنة أكثر، والمسافة الصغيرة تقوي التأثير بين اللوحين. لذلك تتناسب السعة طرديا مع `A` وعكسيا مع `d`."],"تمرين 10 · مثال (صفحة 101)":["على التوازي نجمع السعات مباشرة، ويمكن الجمع بالبيكوفاراد دون تحويل.","مكثفان `150 pF` و `350 pF` على التوازي: `C = 150 + 350 = 500 pF`.","كل مكثف يأخذ الجهد نفسه، والشحنة الكلية مجموع الشحنات، فتجمع السعات."],"تمرين 11 · مثال (صفحة 102)":["على التوالي نضرب السعتين ونقسم على مجموعهما، والناتج أصغر من أصغرهما.","مكثفان `12 pF` و `4 pF` على التوالي: `C = 12 × 4 ÷ (12 + 4) = 3 pF`.","في التوالي تتساوى الشحنة ويتوزع الجهد، فتحتاج المجموعة جهدا أكبر للشحنة نفسها، فتقل السعة."],"تمرين 12 · مثال (صفحة 102)":["في التوالي الشحنة على كل مكثف تساوي شحنة المكثف المكافئ، فنضرب السعة المكافئة في الجهد.","سعة مكافئة `3 × 10⁻¹² F` على `20 V`: `q = 3 × 10⁻¹² × 20 = 6 × 10⁻¹¹ C` على كل مكثف.","اللوحان الداخليان معزولان عن المصدر، فكل شحنة تظهر على لوح يقابلها مقدار معاكس على اللوح المتصل به. لذلك تتساوى الشحنة على المكثفات المتوالية."],"تمرين 13 · مثال ١ (صفحة 103)":["نربع الجهد ونضربه في السعة ثم نأخذ النصف لنحصل على الطاقة المختزنة.","مكثف `5 × 10⁻⁶ F` على `20 V`: `PE = 0.5 × 5 × 10⁻⁶ × 20² = 1 × 10⁻³ J`.","الجهد يزداد من صفر إلى قيمته النهائية أثناء الشحن، فمتوسطه نصف الجهد النهائي، ومن هنا يأتي النصف."],"تمرين 14 · مثال ٢ (صفحة 103)":["إذا عرفنا الشحنة والجهد نضربهما ونأخذ النصف مباشرة دون حاجة إلى السعة.","مكثف شحنته `0.5 C` على `100 V`: `PE = 0.5 × 0.5 × 100 = 25 J`.","بالتعويض `q = C·V` في `PE = ½·C·V²` نحصل على `PE = ½·q·V`، فهما صيغتان للقانون نفسه."],"تمرين 15 · ورقة العمل · سؤال ٤ (صفحة 105)":["نعوض بالشحنتين بالكولوم دون الإشارة، ونقسم على مربع المسافة. والإشارتان المختلفتان تخبراننا أن القوة تجاذب.","شحنتان `4 nC` و `−2 nC` بينهما `1 m`: `F = 9 × 10⁹ × 4 × 10⁻⁹ × 2 × 10⁻⁹ ÷ 1² = 7.2 × 10⁻⁸ N` تجاذب.","تحويل `nC` إلى `C` ضروري لأن ثابت كولوم مقاس بالكولوم. ومربع المسافة في المقام يجعل القوة تقل بسرعة كلما تباعدت الشحنتان."],"تمرين 16 · ورقة العمل · سؤال ٥ (صفحة 105)":["شدة المجال هي القوة على كل كولوم، فنقسم القوة على الشحنة. وانتبه أن القسمة على عدد صغير جدا تعطي ناتجا كبيرا.","شحنة `2 × 10⁻⁶ C` تأثرت بقوة `6 × 10⁻³ N`: `E = 6 × 10⁻³ ÷ (2 × 10⁻⁶) = 3000 N/C`.","لأن المجال صفة للمكان نفسه، فلو ضاعفنا الشحنة لتضاعفت القوة وبقيت النسبة كما هي. لذلك نعرفه بالقوة لكل وحدة شحنة."],"تمرين 17 · ورقة العمل · سؤال ٦ (صفحة 105)":["نضرب ثابت كولوم في الشحنة ثم نقسم على مربع البعد. والبعد هنا أقل من متر، فمربعه أصغر منه، فيكبر المجال.","شحنة `4 × 10⁻⁹ C` على بعد `0.2 m`: `E = 9 × 10⁹ × 4 × 10⁻⁹ ÷ 0.04 = 900 N/C`.","المجال يتوزع حول الشحنة في كل الاتجاهات، والمساحة التي يتوزع عليها تكبر مع مربع البعد. لذلك تضعف شدته مع `r²`."],"تمرين 18 · ورقة العمل · سؤال ٧ (صفحة 106)":["في المجال المنتظم يزيد فرق الجهد بانتظام مع المسافة، فنضرب شدة المجال في المسافة مباشرة.","مجال `3000 N/C` ومسافة `0.05 m`: `ΔV = 3000 × 0.05 = 150 V`.","لأن المجال المنتظم ثابت المقدار والاتجاه، فكل متر يضيف فرق الجهد نفسه. لذلك تكون العلاقة خطية `ΔV = E·d`."],"تمرين 19 · ورقة العمل · سؤال ٨ (صفحة 106)":["الجهد عند نقطة قرب شحنة يحسب بضرب ثابت كولوم في الشحنة والقسمة على البعد، دون تربيع.","شحنة `5 × 10⁻⁶ C` على بعد `0.5 m`: `V = 9 × 10⁹ × 5 × 10⁻⁶ ÷ 0.5 = 9 × 10⁴ V`.","الجهد هو الطاقة لكل كولوم، وهو كمية قياسية تقل مع البعد نفسه. لذلك يظهر `r` في المقام دون تربيع، بخلاف المجال."],"تمرين 20 · ورقة العمل · سؤال ٩ (صفحة 106)":["السعة هي الشحنة المخزنة مقابل كل فولت، فنقسم الشحنة على فرق الجهد بين اللوحين.","شحنة `9 × 10⁻⁴ C` وجهد `300 V`: `C = 9 × 10⁻⁴ ÷ 300 = 3 × 10⁻⁶ F`.","إذا ضاعفنا الجهد تضاعفت الشحنة، فتبقى النسبة ثابتة. لذلك تعبر السعة عن المكثف نفسه لا عن حالة شحنه."],"تمرين 21 · ورقة العمل · سؤال ١٠ (صفحة 107)":["نعيد ترتيب `C = q / V` لنحصل على الشحنة: نضرب السعة في الجهد.","مكثف `2.5 × 10⁻¹² F` على `20 V`: `q = 2.5 × 10⁻¹² × 20 = 5 × 10⁻¹¹ C`.","الشحنة تتناسب طرديا مع الجهد، فكلما زاد جهد البطارية دفعت شحنة أكبر إلى اللوحين. والسعة هي ثابت التناسب بينهما."],"تمرين 22 · ورقة العمل · سؤال ١٠ (صفحة 107)":["الطاقة المخزنة تساوي نصف السعة في مربع الجهد، فمضاعفة الجهد تجعل الطاقة أربعة أضعاف.","مكثف `4 × 10⁻¹² F` على `10 V`: `PE = 0.5 × 4 × 10⁻¹² × 10² = 2 × 10⁻¹⁰ J`.","يظهر النصف لأن الجهد يبدأ من صفر ويزداد تدريجيا أثناء الشحن، فمتوسط الجهد الذي تنقل عنده الشحنة نصف الجهد النهائي."],"تمرين 23 · ورقة العمل · سؤال ١١ (صفحة 107)":["نقسم الشحنة على السعة لنجد الجهد. وعندما تتساوى قيمتا الشحنة والسعة يكون الجهد فولتا واحدا.","مكثف `4 × 10⁻⁶ F` شحنته `2 × 10⁻⁵ C`: `V = 2 × 10⁻⁵ ÷ (4 × 10⁻⁶) = 5 V`.","الفاراد هو كولوم لكل فولت، فالمكثف الذي يحمل من الكولومات عددا يساوي سعته بالفاراد يكون جهده فولتا واحدا."],"تمرين 24 · ورقة العمل · سؤال ١١ (صفحة 107)":["المجال بين اللوحين هو فرق الجهد مقسوما على المسافة بينهما، وكلما قربنا اللوحين قوي المجال.","جهد `6 V` ومسافة `2 × 10⁻³ m`: `E = 6 ÷ 0.002 = 3000 V/m`.","المجال بين لوحي المكثف منتظم، فيتوزع فرق الجهد بالتساوي على المسافة. لذلك نصيب كل متر من الجهد هو شدة المجال."],"تمرين 25 · ورقة العمل · سؤال ١٢ (صفحة 108)":["في التوالي نضرب السعتين ونقسم على مجموعهما، فتخرج السعة الكلية أصغر من أصغرهما.","مكثفان `3 µF` و `6 µF` على التوالي: `C = 3 × 6 ÷ (3 + 6) = 2 µF`.","في التوالي تتساوى الشحنة ويتوزع الجهد على المكثفات، فتحتاج المجموعة جهدا أكبر للشحنة نفسها. وهذا يعني سعة كلية أصغر."],"تمرين 26 · ورقة العمل · سؤال ١٢ (صفحة 108)":["في التوازي نجمع السعات مباشرة، كأننا نكبر مساحة لوح واحد.","مكثفان `5 µF` و `7 µF` على التوازي: `C = 5 + 7 = 12 µF`.","كل مكثف يأخذ جهد المصدر كاملا، والشحنات تجمع. فالشحنة الكلية لكل فولت هي مجموع السعات."],"تمرين 27 · ورقة العمل · سؤال ١٣ (صفحة 108)":["يمكن الحساب بالنانوفاراد مباشرة دون تحويل، لأن الضرب ثم القسمة يحفظان البادئة نفسها في الناتج.","مكثفان `8 nF` و `8 nF` على التوالي: `C = 8 × 8 ÷ (8 + 8) = 4 nF`، أي نصف أحدهما.","السعة الكلية لا تعتمد على جهد المصدر، لأنها صفة للمكثفات وطريقة توصيلها فقط. لذلك لا نحتاج `12 V` لحسابها."],"تمرين 28 · ورقة العمل · سؤال ١٤ (صفحة 109)":["على التوازي نجمع السعات، ويمكن الجمع بالنانوفاراد مباشرة لأن البادئة واحدة.","مكثفان `250 nF` و `150 nF` على التوازي: `C = 250 + 150 = 400 nF = 4 × 10⁻⁷ F`.","في التوازي يرى كل مكثف الجهد نفسه، فتجمع شحناتها وبالتالي سعاتها. والجهد لا يؤثر في السعة الكلية."]},"4-1":{"":["التيار الكهربائي هو سيل من الشحنات يتحرك في الموصل، مثل الماء الذي يجري في الأنبوب. وكثافة التيار تبين مدى ازدحامه في المقطع، وسرعة الانجراف تبين مدى بطء الإلكترونات.","شحنة `3 C` تمر في سلك خلال `2 s`: `I = 3 ÷ 2 = 1.5 A`. ولو كانت مساحة المقطع `1.5 × 10⁻⁶ m²` فإن `J = 1.5 ÷ (1.5 × 10⁻⁶) = 10⁶ A/m²`.","لأن المجال الكهربائي داخل الموصل يدفع الشحنات الحرة في اتجاه معين، فيتكون تيار. والتصادمات مع الذرات تجعل حركة الإلكترونات بطيئة رغم أن الإشارة تنتقل بسرعة كبيرة."],"مقدمة الوحدة وأهدافها":["في هذه الوحدة نتعرف كيف تتحرك الكهرباء في الأسلاك، وكيف نقيس كميتها وسرعتها، وما الذي يعيقها. هي مثل دراسة حركة السيارات في الطريق: عددها وسرعتها وزحامها.","مثال واقعي: شاحن الجوال يكتب عليه `5 V` و `2 A`؛ في هذه الوحدة يتدرب المتدرب على فهم معنى التيار `2 A` وما الذي يمر في السلك فعلا.","لأن كل جهاز كهربائي يعتمد على مرور تيار في دائرة، وفهم التيار والمقاومة والقدرة يمكننا من تصميم الدوائر واختيار الأسلاك بأمان."],"وحدات مهمة":["لكل كمية كهربائية وحدة خاصة بها، كما نقيس الطول بالمتر والكتلة بالكيلوغرام. فالتيار بالأمبير، والجهد بالفولت، والمقاومة بالأوم، والقدرة بالواط.","شحنة `6 C` تمر في `3 s`: `I = 6 ÷ 3 = 2 C/s = 2 A`. فالأمبير الواحد يعني مرور كولوم واحد في كل ثانية.","لأن توحيد الوحدات في النظام الدولي يجعل القوانين تعطي نتائج صحيحة مباشرة، ولا يمكن مقارنة مقدارين أو جمعهما إلا إذا كانت وحدتاهما متماثلتين."],"التيار الكهربائي":["التيار الكهربائي شحنات تتحرك معا في اتجاه واحد داخل الموصل، مثل طابور من الناس يمشي في ممر ضيق في اتجاه واحد.","إذا عبرت `6 C` من الشحنة مقطع سلك خلال `2 s` فإن `I = 6 ÷ 2 = 3 A`.","لأن الشحنات الحرة في الموصل تتحرك عشوائيا بلا محصلة، فإذا أثر عليها مجال كهربائي من مصدر جهد صار لحركتها اتجاه محدد، فيتكون التيار."],"شدة التيار":["شدة التيار تقيس كم من الشحنة يعبر مقطع السلك في كل ثانية، مثل عدد السيارات التي تعبر بوابة في الدقيقة.","شحنة `30 C` تمر خلال `15 s`: `I = q / t = 30 ÷ 15 = 2 A`.","لأن أثر التيار في الأجهزة يعتمد على سرعة تدفق الشحنة لا على مقدارها الكلي فقط، فعرفت شدة التيار بأنها معدل مرور الشحنة مع الزمن."],"الشحنة وعدد الإلكترونات":["كل شحنة مكونة من عدد كامل من شحنات الإلكترون الصغيرة، كما يتكون المبلغ من عدد من الهللات. فإذا عرفنا الشحنة الكلية قسمناها على شحنة الإلكترون لنعرف العدد.","شحنة `3.2 C`: `n = 3.2 ÷ (1.6 × 10⁻¹⁹) = 2 × 10¹⁹` إلكترون.","لأن الشحنة مكماة، أي أنها تأتي دائما مضاعفات صحيحة للشحنة الأولية `e`، فلا توجد شحنة أصغر منها في الموصلات."],"اتجاه التيار":["اتفق العلماء قديما على أن التيار يخرج من القطب الموجب، ثم اكتشفوا أن الإلكترونات تتحرك فعلا بالعكس. فبقي الاتفاق كما هو مثل اتفاقنا على اتجاه السير.","في دائرة بطارية ومصباح: التيار الاصطلاحي يخرج من القطب `+` ويمر في المصباح إلى `−`، بينما الإلكترونات تخرج من `−` وتصل إلى `+`.","لأن الإلكترونات سالبة الشحنة فتتأثر بقوة عكس اتجاه المجال الكهربائي، أما الشحنات الموجبة فتتحرك مع المجال، فيكون الاتجاهان متعاكسين."],"كثافة التيار J":["كثافة التيار تبين مقدار الزحام: كم أمبيرا يمر في كل متر مربع من المقطع. مثل عدد الناس في كل متر من باب ضيق أو واسع.","تيار `3 A` في مقطع مساحته `1.5 × 10⁻⁶ m²`: `J = 3 ÷ (1.5 × 10⁻⁶) = 2 × 10⁶ A/m²`.","لأن التيار نفسه قد يمر في سلك رفيع أو سميك، فنحتاج كمية تصف تركيزه في المقطع. ولها اتجاه لأن الشحنات تتحرك في اتجاه محدد داخل الموصل."],"تحويل المساحة (مهم جدًا)":["المليمتر المربع مربع صغير طول ضلعه جزء من ألف من المتر، فمساحته جزء من مليون من المتر المربع. لذلك نضرب في `10⁻⁶` عند التحويل.","`4 mm² = 4 × 10⁻⁶ m²`. وسلك نصف قطره `1 mm`: `A = π × (10⁻³)² ≈ 3.14 × 10⁻⁶ m²`.","لأن المساحة طول في طول، فيتربع معامل التحويل: `(10⁻³)² = 10⁻⁶`. وقوانين الوحدة مكتوبة بوحدات SI، فأي خطأ في التحويل يغير الناتج ملايين المرات."],"سرعة الانجراف v_d":["الإلكترونات داخل السلك تتحرك ببطء شديد في المتوسط، مثل شخص يحاول المشي في سوق مزدحم يصطدم بالناس كل لحظة فيتقدم قليلا.","إذا كانت `J = 1.6 × 10⁶ A/m²` و `n = 10²⁹ m⁻³` فإن `n·e = 1.6 × 10¹⁰ C/m³` و `v_d = 1.6 × 10⁶ ÷ (1.6 × 10¹⁰) = 10⁻⁴ m/s`.","لأن الإلكترون يتسارع بتأثير المجال ثم يصطدم بذرات الموصل فيفقد جزءا من حركته، فيتكرر ذلك كثيرا. وعدد الإلكترونات الحرة الهائل يجعل حركة بطيئة منها كافية لنقل التيار."],"التيار المستمر DC":["التيار المستمر يمشي في طريق باتجاه واحد لا يعود منه، مثل نهر يجري دائما نحو البحر. ومصدره المعتاد البطارية.","بطارية تعطي تيارا ثابتا `0.5 A` لمدة `3600 s`: الشحنة المارة `q = 0.5 × 3600 = 1800 C`، كلها في اتجاه واحد.","لأن قطبي البطارية أو الخلية الشمسية ثابتان لا يتبادلان، فيبقى المجال في الدائرة في اتجاه واحد، فتتحرك الشحنات دائما في الاتجاه نفسه."],"التيار المتردد AC":["التيار المتردد يذهب ويعود في السلك بانتظام، مثل المنشار الذي يتحرك ذهابا وإيابا. ويتغير مقداره أيضا مع الزمن.","تيار تردده `50 Hz` يكمل 50 دورة في الثانية، وفي كل دورة يغير اتجاهه مرتين، أي `100` مرة في الثانية، وزمن الدورة `1 ÷ 50 = 0.02 s`.","لأن المولدات في محطات الكهرباء تدور فيها ملفات، فيتبادل اتجاه الجهد الناتج دوريا مع الدوران، فيتغير اتجاه التيار تبعا له."],"لماذا AC في الشبكات؟":["المحول يرفع الجهد قبل النقل ويخفضه قبل دخول المنزل، وهذا لا يعمل إلا مع التيار المتردد. مثل ضغط البضاعة لنقلها ثم فكها عند الوصول.","لنقل قدرة `1000 W`: بجهد `100 V` نحتاج `I = 1000 ÷ 100 = 10 A`، وبجهد `10000 V` نحتاج `0.1 A` فقط، فيقل التسخين في الأسلاك كثيرا.","لأن الحرارة الضائعة في الأسلاك تزداد مع التيار، ورفع الجهد يسمح بنقل القدرة نفسها بتيار صغير. والمحولات تحتاج تيارا متغيرا لتعمل."],"أمثلة الحقيبة التدريبية محلولة":["إذا أعطانا السؤال الشحنة والزمن فالتيار هو قسمة الشحنة على الزمن مباشرة، مثل حساب عدد اللترات التي تخرج من الصنبور في كل ثانية.","شحنة `12 C` تمر في سلك خلال `40 s`: `I = 12 ÷ 40 = 0.3 A`.","لأن تعريف شدة التيار نفسه هو معدل مرور الشحنة مع الزمن، فإذا عرفنا المقدارين كان التعريف هو أقصر طريق للحل."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["بعد التعويض نقسم ونكتب الوحدة `C/s` التي تساوي الأمبير. ثم نتحقق بضرب التيار في الزمن لنرجع إلى الشحنة المعطاة.","شحنة `9 C` خلال `36 s`: `I = 9 ÷ 36 = 0.25 A`. وللتحقق: `0.25 × 36 = 9 C` وهي الشحنة المعطاة.","لأن الأمبير معرف بأنه كولوم في الثانية، فقسمة الكولوم على الثانية تعطي الأمبير مباشرة، وضرب الناتج في الزمن يعيد الشحنة فيتأكد صحة الحل."],"مثال ١: كثافة التيار في موصل دائري المقطع (صفحة 119)":["لحساب كثافة التيار نقسم التيار على مساحة المقطع بالمتر المربع. كلما صغرت المساحة زاد الزحام فزادت الكثافة.","تيار `2 A` في مقطع مساحته `0.5 × 10⁻⁶ m²`: `J = 2 ÷ (0.5 × 10⁻⁶) = 4 × 10⁶ A/m²`.","لأن الكثافة تصف التيار المار في كل متر مربع، فالقسمة على المساحة توزع التيار على وحدات المساحة فتعطي نصيب كل متر مربع منه."],"مثال ١: كثافة التيار في موصل دائري المقطع (صفحة 119) (تابع)":["نقسم العددين أولا، ثم ننقل القوة العشرية من المقام إلى البسط بعكس إشارتها. والنتيجة كبيرة لأن مساحة السلك صغيرة جدا.","سلك نصف قطره `1 mm`: `A = π × (10⁻³)² ≈ 3.14 × 10⁻⁶ m²`، وبتيار `1 A`: `J = 1 ÷ (3.14 × 10⁻⁶) ≈ 3.18 × 10⁵ A/m²`.","لأن `1 ÷ 10⁻⁶ = 10⁶`، فالقسمة على عدد صغير جدا تعطي ناتجا كبيرا جدا. واتجاه الكثافة هو اتجاه التيار الاصطلاحي لأنها كمية متجهة."],"مثال ٢: حساب التيار ثم كثافته من الشحنة والزمن (صفحة 119)":["السؤال على مرحلتين: نحسب التيار أولا من الشحنة والزمن، ثم نستعمله لحساب الكثافة. مثل صعود درجتين، لا نصل إلى الثانية قبل الأولى.","شحنة `6 C` خلال `3 s`: `I = 2 A`. ومساحة `4 mm² = 4 × 10⁻⁶ m²`: `J = 2 ÷ (4 × 10⁻⁶) = 5 × 10⁵ A/m²`.","لأن قانون الكثافة يحتاج التيار، والتيار غير معطى مباشرة، فلا بد من حسابه من تعريفه أولا. وتحويل المساحة إلى `m²` ضروري لتكون الوحدة `A/m²`."],"مثال ٢: حساب التيار ثم كثافته من الشحنة والزمن (صفحة 119) (تابع)":["بعد حساب التيار نعوض به مع المساحة المحولة، ونقسم الأعداد وحدها والقوى العشرية وحدها ثم نجمعهما.","شحنة `9 C` خلال `6 s`: `I = 1.5 A`. ومساحة `3 mm²`: `J = 1.5 ÷ (3 × 10⁻⁶) = 0.5 × 10⁶ = 5 × 10⁵ A/m²`.","لأن فصل الأعداد عن القوى العشرية يقلل الأخطاء الحسابية، ولأن كتابة النتيجة بالصيغة العلمية تجعل العدد الأول بين 1 و 10 فتسهل قراءته."],"مثال ١: كثافة التيار وسرعة الانجراف في سلك فضة (صفحة 120)":["نحسب أولا كثافة التيار، ثم نقسمها على مقدار الشحنة الحرة في كل متر مكعب لنعرف سرعة الإلكترونات. كلما كثرت الإلكترونات الحرة قلت سرعة كل منها.","سلك نحاس `I = 2 A` ومساحته `1 mm²`: `J = 2 × 10⁶ A/m²`. ومع `n = 8.5 × 10²⁸ m⁻³`: `n·e = 1.36 × 10¹⁰ C/m³` و `v_d ≈ 1.47 × 10⁻⁴ m/s`.","لأن التيار نفسه يمكن أن تحمله إلكترونات كثيرة بطيئة أو قليلة سريعة، فإذا كان عددها في كل متر مكعب كبيرا كفتها سرعة صغيرة لنقل التيار."],"مثال ١: كثافة التيار وسرعة الانجراف في سلك فضة (صفحة 120) (تابع)":["نضرب `n` في `e` لنعرف الشحنة الحرة في كل متر مكعب، ثم نقسم الكثافة عليها. وعند الضرب نجمع الأسس، وعند القسمة نطرحها.","مع `n = 5 × 10²⁸ m⁻³`: `n·e = 5 × 1.6 × 10⁹ = 8 × 10⁹ C/m³`. وإذا كانت `J = 4 × 10⁵ A/m²` فإن `v_d = 4 × 10⁵ ÷ (8 × 10⁹) = 5 × 10⁻⁵ m/s`.","لأن الإلكترونات سالبة فتنجرف عكس المجال وعكس التيار الاصطلاحي، وتصادماتها المتكررة مع ذرات الموصل تجعل سرعتها المتوسطة أجزاء من المليمتر في الثانية فقط."],"رسم توضيحي 1":["الرسم يبين سلكا يمر فيه تيار، والكثافة هي التيار مقسوما على مساحة المقطع، والإلكترونات تتحرك بعكس سهم التيار.","تيار `0.5 A` في مقطع مساحته `0.25 × 10⁻⁶ m²`: `J = 0.5 ÷ (0.25 × 10⁻⁶) = 2 × 10⁶ A/m²`.","لأن الإلكترونات سالبة فتتأثر بقوة عكس المجال، بينما يرسم سهم التيار في اتجاه حركة الشحنات الموجبة، فيظهر السهمان متعاكسين."],"رسم توضيحي 2":["الأسهم السميكة تمثل اتجاه التيار المتفق عليه، والدوائر الصغيرة تمثل الإلكترونات التي تمشي في الطريق المعاكس. النتيجة الكهربائية واحدة في الحالتين.","إذا عبرت `4 C` مقطع السلك في `2 s` فالتيار `2 A` في اتجاه الأسهم السميكة، بينما يتحرك نحو `2.5 × 10¹⁹` إلكترون في الاتجاه المعاكس خلال هذه المدة.","لأن حركة شحنة سالبة في اتجاه تعطي الأثر الكهربائي نفسه لحركة شحنة موجبة مساوية في الاتجاه المعاكس، فبقي الاتفاق صالحا للحسابات."],"رسم توضيحي 3":["عندما يضيق السلك يمر التيار نفسه في مساحة أصغر، فتزداد الكثافة وتسرع الإلكترونات، مثل الماء الذي يسرع في الجزء الضيق من الأنبوب.","تيار `2 A` في جزء مساحته `2 mm²` يعطي `J = 10⁶ A/m²`، وفي جزء `1 mm²` يعطي `J = 2 × 10⁶ A/m²`، فتتضاعف سرعة الانجراف هناك.","لأن الشحنة لا تتجمع داخل السلك، فما يدخل كل مقطع في الثانية يخرج منه، فيبقى التيار ثابتا. وبما أن `v_d = J / (n·e)` فإن زيادة الكثافة تزيد السرعة."],"رسم توضيحي 4":["في الرسم خط أفقي ثابت يمثل التيار المستمر، ومنحنى يصعد ويهبط فوق الصفر وتحته يمثل التيار المتردد.","تيار متردد تردده `60 Hz`: زمن الدورة الواحدة `1 ÷ 60 ≈ 0.0167 s`، ويكون التيار موجبا في نصفها وسالبا في النصف الآخر.","لأن الإشارة السالبة على المحور تعني أن التيار يسري في الاتجاه المعاكس، فالمنحنى الذي يعبر الصفر يعني تغير الاتجاه دوريا."],"مقارنة بين التيار المستمر والتيار المتردد":["المستمر يسير في اتجاه واحد وتردده صفر ومصدره البطاريات، والمتردد يغير اتجاهه دوريا ومصدره محطات التوليد. ويمكن التحويل بينهما بالعاكس أو المقوم.","تيار المنازل بتردد `60 Hz` يغير اتجاهه `2 × 60 = 120` مرة في الثانية، أما تيار بطارية `9 V` فتردده `0 Hz` ولا يغير اتجاهه.","لأن كل نوع يناسب استعمالا: الأجهزة الإلكترونية تحتاج اتجاها ثابتا، ونقل الطاقة لمسافات بعيدة يحتاج تغيير الجهد بالمحولات، وهذا لا يتم إلا مع المتردد."],"تطبيقات من الحياة":["رقم mAh على البطارية يدل على كمية الشحنة المخزنة فيها، والقاطع يحمي المنزل إذا زاد التيار، والسلك الأسمك يسخن أقل.","بطارية `3000 mAh`: `q = 3 A × 3600 s = 10800 C`. ولو سحب الجوال `0.5 A` لكفته نحو `10800 ÷ 0.5 = 21600 s`، أي `6` ساعات.","لأن `q = I·t` يجعل حاصل ضرب التيار في الزمن شحنة، ولأن زيادة مساحة السلك تقلل كثافة التيار فيقل التسخين، والمجال ينتقل بسرعة فيضيء المصباح فورا."],"تمرين 1 · ورقة العمل · سؤال ٣ (صفحة 128)":["إذا عرفنا التيار والزمن فالشحنة هي حاصل ضربهما، ثم نقسم الشحنة على شحنة الإلكترون لنعرف عدد الإلكترونات.","تيار `3 A` لمدة `5 s`: `q = 3 × 5 = 15 C`، وعدد الإلكترونات `n = 15 ÷ (1.6 × 10⁻¹⁹) ≈ 9.38 × 10¹⁹`.","لأن `I = q / t` تعني أن الشحنة هي التيار مضروبا في الزمن، والشحنة الكلية مكونة من عدد صحيح من شحنات الإلكترون."],"تمرين 2 · ورقة العمل · سؤال ٣ (صفحة 128)":["لمعرفة عدد الإلكترونات نقسم الشحنة الكلية على شحنة إلكترون واحد، مثل معرفة عدد الأكياس بقسمة الوزن الكلي على وزن الكيس الواحد.","شحنة `4.8 C`: `n = 4.8 ÷ (1.6 × 10⁻¹⁹) = 3 × 10¹⁹` إلكترون.","لأن الشحنة مكماة: كل شحنة تساوي عددا صحيحا من الشحنة الأولية `e`، فتكون `q = n·e` ومنها `n = q / e`."],"تمرين 3 · مثال ٢ (صفحة 119)":["التيار هو كمية الشحنة مقسومة على الزمن الذي مرت فيه، فنقسم مباشرة.","شحنة `9 C` خلال `4 s`: `I = 9 ÷ 4 = 2.25 A`.","لأن شدة التيار معرفة بأنها الشحنة المارة في كل ثانية، والسؤال يعطي الشحنة والزمن معا."],"تمرين 4 · مثال ٢ (صفحة 119)":["نحول المساحة من `mm²` إلى `m²` أولا، ثم نقسم التيار عليها لنحصل على الكثافة.","تيار `3 A` في مقطع `1.5 mm² = 1.5 × 10⁻⁶ m²`: `J = 3 ÷ (1.5 × 10⁻⁶) = 2 × 10⁶ A/m²`.","لأن وحدة الكثافة في النظام الدولي `A/m²`، فبدون التحويل يكون الناتج أصغر من الصحيح مليون مرة."],"تمرين 5 · ورقة العمل · سؤال ٤ (صفحة 128)":["التيار هنا صغير والمساحة صغيرة أيضا، فنقسم الأعداد ونطرح الأسس لنحصل على الكثافة.","تيار `2 × 10⁻³ A` في مقطع `4 × 10⁻⁷ m²`: `J = (2 ÷ 4) × 10⁻³⁺⁷ = 0.5 × 10⁴ = 5000 A/m²`.","لأن القسمة على قوة عشرية سالبة تساوي الضرب في القوة الموجبة، فيصبح `10⁻³ ÷ 10⁻⁷ = 10⁴`."],"تمرين 6 · مثال ١ (صفحة 120)":["الكثافة معطاة، فنضرب `n` في `e` ثم نقسم الكثافة على الناتج لنحصل على سرعة الإلكترونات.","مع `J = 9.28 × 10⁵ A/m²` و `n = 5.8 × 10²⁸ m⁻³`: `n·e = 9.28 × 10⁹ C/m³` و `v_d = 9.28 × 10⁵ ÷ (9.28 × 10⁹) = 10⁻⁴ m/s`.","لأن `n·e` يمثل الشحنة الحرة في كل متر مكعب، وقسمة الكثافة عليها تعطي السرعة بوحدة `m/s`، وهي صغيرة بسبب العدد الكبير للإلكترونات الحرة."]},"4-5":{"":["الدرس يدور حول ثلاث أفكار: المقاومة تعيق التيار، وقانون أوم يربط الجهد بالتيار والمقاومة، والقدرة هي معدل استهلاك الطاقة. تخيل الماء في أنبوب: الضغط هو الجهد، والتدفق هو التيار، وضيق الأنبوب هو المقاومة.","مكواة على `220 V` مقاومتها `44 Ω`: التيار `I = 220 ÷ 44 = 5 A`، والقدرة `P = I·V = 5 × 220 = 1100 W`.","لأن الإلكترونات تتصادم مع ذرات الموصل أثناء حركتها، فتفقد جزءا من طاقتها في صورة حرارة. هذا التصادم هو أصل المقاومة، وهو سبب استهلاك القدرة في العناصر."],"المقاومة R":["المقاومة هي ممانعة الموصل لمرور التيار، مثل الزحام في ممر ضيق يبطئ حركة الناس. وكلما زادت المقاومة قل التيار عند الجهد نفسه، ويسخن الموصل.","مقاومة على جهد `12 V` يمر فيها `0.4 A`: `R = V/I = 12 ÷ 0.4 = 30 Ω`.","لأن الإلكترونات المتحركة تتصادم مع ذرات الموصل فتعاق حركتها، وتنتقل طاقتها إلى الذرات فترتفع حرارة الموصل."],"رمز المقاومة في الدوائر الكهربائية":["الرموز لغة مختصرة لرسم الدوائر: خط متعرج أو مستطيل للمقاومة الثابتة، وإضافة سهم تعني أن قيمتها تتغير.","في دائرة إنارة شارع تلقائية ترسم المقاومة الضوئية وعليها سهمان يمثلان الضوء، وفي دائرة ضبط الصوت يرسم مجزئ الجهد بثلاثة أطراف وسهم.","لأن الرسم الموحد يجعل أي فني يفهم الدائرة نفسها دون شرح، فيعرف نوع كل مقاومة وهل هي ثابتة أو متغيرة أو تتأثر بالضوء أو الحرارة."],"أنواع المقاومات":["المقاومات تختلف حسب الحاجة: بعضها ثابت ورخيص كالكربونية، وبعضها دقيق كالغشاء المعدني، وبعضها يتحمل قدرة كبيرة كالسلكية. وبعضها يتغير بمقبض أو بالضوء، مثل مفتاح الصوت وإنارة الشوارع.","مقاومة سلكية مكتوب عليها `5W 10Ω`: أكبر تيار آمن فيها من `P = I²·R` هو `I = √(5 ÷ 10) ≈ 0.71 A`.","لأن الدوائر تحتاج أحيانا قيمة ثابتة دقيقة، وأحيانا قيمة تضبط يدويا، وأحيانا قيمة تتغير مع الضوء لتعمل حساسا. والسلكية تتحمل قدرة كبيرة لأن غلافها الخزفي يتحمل الحرارة الناتجة."],"أنواع المقاومات (تابع)":["الثرمستور مقاومة تتغير مع الحرارة فتصلح حساسا لها، والسطحية SMD صغيرة جدا تلحم على سطح اللوحة. وقيمة SMD تقرأ برقمين ثم عدد الأصفار.","مقاومة سطحية مكتوب عليها `472`: نأخذ `47` ونضيف صفرين، فتكون `47 × 10² Ω = 4700 Ω`.","لأن تغير مقاومة الثرمستور مع الحرارة يحول تغير الحرارة إلى تغير في التيار يمكن قياسه، والمقاومات السطحية صغيرة لتناسب الأجهزة الحديثة الصغيرة."],"قانون أوم":["إذا ضغطت الماء بقوة أكبر في الأنبوب نفسه زاد تدفقه. كذلك إذا زاد الجهد على الموصل نفسه زاد التيار بالنسبة نفسها، ما دامت درجة الحرارة ثابتة.","مقاومة `25 Ω` على جهد `5 V`: `I = V/R = 5 ÷ 25 = 0.2 A`. وإذا ضاعفنا الجهد إلى `10 V` يصبح التيار `0.4 A`.","لأن مقاومة الموصل تبقى ثابتة عند ثبات الحرارة، فتبقى النسبة `V/I` ثابتة. لذلك يكون منحنى V مقابل I خطا مستقيما ميله المقاومة."],"العوامل المؤثرة في المقاومة":["السلك الطويل كالممر الطويل يتعب السائر فيه أكثر، والسلك العريض كالطريق الواسع يسمح بمرور أكثر. ونوع المادة يحدد مدى سهولة حركة الشحنات فيها.","سلك ألومنيوم طوله `10 m` ومساحة مقطعه `2 × 10⁻⁶ m²` و `ρ = 2.82 × 10⁻⁸ Ω·m`: `R = 2.82 × 10⁻⁸ × 10 ÷ (2 × 10⁻⁶) = 0.141 Ω`.","لأن الإلكترونات في السلك الأطول تمر بتصادمات أكثر فتزيد المقاومة، والمقطع الأكبر يتيح مسارات أكثر للشحنات فتقل المقاومة. أما المقاومية فتعتمد على المادة نفسها."],"أثر درجة الحرارة (للموصلات)":["عندما يسخن الموصل تهتز ذراته أكثر، فتصبح حركة الإلكترونات أصعب كمن يمشي في زحام متحرك. لذلك تزيد مقاومة الموصل بارتفاع حرارته.","سلك ألومنيوم مقاومته `10 Ω` عند `20 °C` و `α = 3.9 × 10⁻³ °C⁻¹`، عند `70 °C`: `R = 10 × (1 + 3.9 × 10⁻³ × 50) = 10 × 1.195 = 11.95 Ω`.","لأن ارتفاع الحرارة يزيد اهتزاز ذرات الموصل، فتكثر تصادمات الإلكترونات بها وتزيد المقاومة زيادة خطية تقريبا مع فرق الحرارة."],"القدرة الكهربائية P":["القدرة تخبرك بسرعة استهلاك الجهاز للطاقة، لا بكمية الطاقة الكلية. فالجهاز الأقوى يستهلك الطاقة نفسها في زمن أقصر.","غلاية استهلكت `180000 J` في `90 s`: `P = E / t = 180000 ÷ 90 = 2000 W`.","لأن جهازين قد يستهلكان الطاقة نفسها، لكن الذي يستهلكها في زمن أقصر يعمل بقدرة أكبر. لذلك نقسم الطاقة على الزمن لنعرف معدل التحويل."],"صيغ القدرة":["للقدرة ثلاث صيغ كلها صحيحة: `P = I·V` عندما تعرف التيار والجهد، و `P = I²·R` عندما تعرف التيار والمقاومة، و `P = V² / R` عندما تعرف الجهد والمقاومة.","مقاومة `8 Ω` يمر فيها `3 A`: `P = I²·R = 9 × 8 = 72 W`، وجهدها `24 V` فيكون `P = V² / R = 576 ÷ 8 = 72 W` أيضا.","لأن الصيغتين الأخريين نتجتا من التعويض بقانون أوم `V = I·R` في `P = I·V`، فهي صيغة واحدة مكتوبة بطرق مختلفة."],"أمثلة الحقيبة التدريبية محلولة":["عندما نعرف الجهد والتيار في جهاز نجد مقاومته بقسمة الجهد على التيار. فقانون أوم يربط ثلاث كميات، ومعرفة اثنتين تكفي لإيجاد الثالثة.","مجفف شعر على `220 V` يمر فيه `5 A`: `R = V/I = 220 ÷ 5 = 44 Ω`.","لأن قانون أوم يجعل النسبة بين الجهد والتيار ثابتة عند ثبات الحرارة، وهذه النسبة الثابتة هي المقاومة نفسها."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["بعد التعويض نعزل المقاومة بقسمة الجهد على التيار، ثم نتحقق بضرب الناتج في التيار لنرجع إلى الجهد المعطى. التحقق يشبه مراجعة الباقي بعد الشراء.","جهاز يمر فيه `4 A` على `100 V`: `R = 100 ÷ 4 = 25 Ω`، والتحقق `I·R = 4 × 25 = 100 V`.","لأن الضرب عكس القسمة، فإذا أعاد ضرب الناتج في التيار قيمة الجهد المعطى فالحل صحيح. والتحقق يكشف أخطاء الحساب قبل اعتماد النتيجة."],"مثال ٢: شدة التيار في مقاومة بقانون أوم (صفحة 124)":["إذا عرفنا الجهد والمقاومة نجد التيار بقسمة الجهد على المقاومة. فالجهد يدفع الشحنات، والمقاومة تعيقها، والتيار هو الناتج.","مقاومة `40 Ω` على `220 V`: `I = V/R = 220 ÷ 40 = 5.5 A`.","لأن التيار يتناسب طرديا مع الجهد وعكسيا مع المقاومة، فالجهد الأكبر يدفع شحنات أكثر، والمقاومة الأكبر تقلل الشحنات المارة كل ثانية."],"مثال ٢: شدة التيار في مقاومة بقانون أوم (صفحة 124) (تابع)":["مقاومة صغيرة على جهد كبير تسحب تيارا كبيرا، مثل فتح صنبور واسع على خزان مرتفع. لذلك تحتاج أجهزة التسخين أسلاكا وقواطع تتحمل التيار.","مقاومة `20 Ω` على `220 V`: `I = 220 ÷ 20 = 11 A`. وإذا صغرت المقاومة إلى `10 Ω` تضاعف التيار.","لأن التيار يتناسب عكسيا مع المقاومة عند ثبات الجهد، فكلما صغرت المقاومة زاد التيار، وزادت الحرارة في الأسلاك فاحتاجت حماية."],"مثال ٣: مقاومة سلك نحاس من أبعاده (صفحة 124)":["مقاومة السلك تعتمد على مادته وطوله وسمكه، لا على التيار المار فيه. فنضرب المقاومية في الطول ونقسم على مساحة المقطع.","سلك نحاس `L = 5 m` و `A = 1 × 10⁻⁶ m²` و `ρ = 1.7 × 10⁻⁸ Ω·m`: `R = 1.7 × 10⁻⁸ × 5 ÷ (1 × 10⁻⁶) = 0.085 Ω`.","لأن المقاومة خاصية للموصل نفسه تحددها المادة والأبعاد، فقيمة التيار لا تدخل في حسابها ما دامت الحرارة ثابتة."],"مثال ٣: مقاومة سلك نحاس من أبعاده (صفحة 124) (تابع)":["نضرب المقاومية في الطول، ثم نقسم على المساحة: نقسم الأعداد ونطرح الأسس. الناتج صغير جدا لأن النحاس موصل ممتاز.","سلك نحاس `L = 2 m` و `A = 2 × 10⁻⁵ m²` و `ρ = 1.7 × 10⁻⁸ Ω·m`: `R = 3.4 × 10⁻⁸ ÷ (2 × 10⁻⁵) = 1.7 × 10⁻³ Ω`.","لأن القسمة على قوة للعشرة تعني طرح الأسس، فيكون `10⁻⁸ ÷ 10⁻⁵ = 10⁻³`. ولصغر مقاومية النحاس تكون مقاومة الأسلاك صغيرة فيقل الفقد في الطاقة."],"مثال ٤: أثر ارتفاع درجة الحرارة على مقاومة سلك نحاس (صفحة 124)":["كلما سخن سلك النحاس زادت مقاومته قليلا. نحسب الزيادة النسبية بضرب المعامل الحراري في فرق الحرارة، ثم نضيفها إلى الواحد ونضرب في المقاومة الأصلية.","سلك نحاس `R₀ = 10 Ω` عند `20 °C` و `α = 3.9 × 10⁻³ °C⁻¹`، عند `100 °C`: `R = 10 × (1 + 3.9 × 10⁻³ × 80) = 10 × 1.312 = 13.12 Ω`.","لأن اهتزاز ذرات الموصل يزيد بارتفاع الحرارة، فتكثر تصادمات الإلكترونات، وتزيد المقاومة بنسبة `α` تقريبا لكل درجة مئوية."],"مثال ٤: أثر ارتفاع درجة الحرارة على مقاومة سلك نحاس (صفحة 124) (تابع)":["نطرح درجتي الحرارة، ثم نضرب الفرق في المعامل الحراري، ونضيف الواحد، ونضرب في المقاومة الأصلية. الزيادة هنا تقارب سدس المقاومة الأصلية.","سلك `R₀ = 50 Ω` و `α = 4 × 10⁻³ °C⁻¹` سخن بمقدار `25 °C`: `α·ΔT = 0.1`، فتكون `R = 50 × 1.1 = 55 Ω`، أي بزيادة `5 Ω`.","لأن الحد `α·ΔT` يمثل الزيادة النسبية في المقاومة، فإضافة الواحد إليه تعطي المقاومة الأصلية مع زيادتها معا."],"مثال ١: تيار مصباح وقدرته الكهربائية (صفحة 125)":["نحسب التيار أولا بقانون أوم، ثم نضربه في الجهد لنعرف القدرة. كأنك تعرف عدد السيارات المارة ثم تحسب الحمولة التي تنقلها.","مصباح `R = 40 Ω` على `12 V`: `I = 12 ÷ 40 = 0.3 A`، و `P = I·V = 0.3 × 12 = 3.6 W`.","لأن القدرة تحتاج التيار والجهد معا في `P = I·V`، والتيار غير معطى، فنستخرجه أولا من قانون أوم."],"مثال ١: تيار مصباح وقدرته الكهربائية (صفحة 125) (تابع)":["الصيغ الثلاث للقدرة تعطي النتيجة نفسها، فاختر الأسهل حسب المعطيات. والمصباح يحول هذه الطاقة في كل ثانية إلى ضوء وحرارة.","مصباح `R = 40 Ω` على `12 V` يمر فيه `0.3 A`: `P = I²·R = 0.09 × 40 = 3.6 W`، و `P = V²/R = 144 ÷ 40 = 3.6 W`.","لأن الصيغتين `P = I²·R` و `P = V²/R` مشتقتان من `P = I·V` بالتعويض بقانون أوم، فلا بد أن تتفق الصيغ الثلاث."],"رسم توضيحي 1":["الرسم خط مستقيم يمر بنقطة الأصل: كلما زاد الجهد زاد التيار بالنسبة نفسها. وانحدار الخط يخبرك بقيمة المقاومة.","إذا مر الخط بالنقطتين `(0.5 A, 10 V)` و `(1 A, 20 V)` فالميل `ΔV/ΔI = 10 ÷ 0.5 = 20 Ω`، وهو المقاومة.","لأن `V = I·R` معادلة خط مستقيم يمر بالأصل عندما تكون `R` ثابتة، فيكون ميله `ΔV/ΔI` هو المقاومة نفسها."],"رسم توضيحي 2":["السلك الطويل يعيق التيار أكثر، والسلك السميك يسهل مروره. مثل خرطوم الماء: الطويل الرفيع يقلل التدفق، والقصير الواسع يزيده.","سلك مقاومته `6 Ω`: إذا ضاعفنا طوله تصبح `12 Ω`، وإذا ضاعفنا مساحة مقطعه بدل ذلك تصبح `3 Ω`.","لأن `R = ρ·L / A`، فالطول في البسط يزيد المقاومة، والمساحة في المقام تقللها لأنها توفر مسارات أكثر للشحنات."],"رسم توضيحي 3":["الأميتر يقيس التيار فيوضع في طريقه على التوالي، والفولتميتر يقيس الجهد بين نقطتين فيوصل على التوازي مع العنصر. مثل عداد الماء يركب على الأنبوب نفسه.","إذا قرأ الأميتر `0.5 A` والفولتميتر على المقاومة `6 V`، فالمقاومة `R = 6 ÷ 0.5 = 12 Ω`.","لأن التيار يجب أن يمر كله داخل الأميتر ليقيسه، أما الجهد فيقاس بين طرفي العنصر، فيوصل الفولتميتر بهذين الطرفين مباشرة."],"المقاومية والمعامل الحراري لبعض المواد عند 20°C":["الجدول يرتب المواد حسب سهولة توصيلها: الفضة والنحاس مقاوميتهما صغيرة جدا، والزجاج مقاوميته هائلة. والمعامل السالب في أشباه الموصلات يعني أن مقاومتها تقل بالتسخين.","سلك فضة `L = 1 m` و `A = 1 × 10⁻⁶ m²`: `R = 1.59 × 10⁻⁸ × 1 ÷ 10⁻⁶ = 0.0159 Ω`، والسلك نفسه من النيكروم `R = 1.0 Ω`.","لأن المقاومية تعتمد على نوع المادة وعدد الإلكترونات الحرة فيها، فالموصلات فيها إلكترونات حرة كثيرة، والعوازل فيها القليل جدا."],"صيغ القدرة الكهربائية ومتى تُستخدم":["اختر صيغة القدرة حسب ما لديك من معطيات، كما تختار المفتاح المناسب للقفل. ولحساب الفاتورة نضرب القدرة بالكيلوواط في الزمن بالساعات.","سخان `2 kW` يعمل `3 h`: `E = 2 × 3 = 6 kWh`، وإذا كان سعر الكيلوواط ساعة `0.2` وحدة نقدية فالتكلفة `6 × 0.2 = 1.2` وحدة نقدية.","لأن الكيلوواط ساعة وحدة طاقة مناسبة للاستهلاك المنزلي، فهي تساوي `3.6 × 10⁶ J`، والجول وحدة صغيرة جدا لحساب الفواتير."],"تطبيقات من الحياة":["الديمر يغير المقاومة ليتحكم في الإضاءة، والفيوز ينصهر ليحمي الدائرة، والنحاس للأسلاك لأنه موصل جيد، والنيكروم للسخانات لأنه يسخن بسهولة.","فيوز يتحمل `10 A` في منزل على `220 V`: أكبر قدرة يسمح بها `P = I·V = 10 × 220 = 2200 W`، فتشغيل أجهزة بقدرة `3000 W` معا يصهره.","لأن القدرة المفقودة حراريا `P = I²·R` تزيد مع المقاومة والتيار، فالنيكروم ذو المقاومية الكبيرة يسخن، والفيوز الرفيع ينصهر عند زيادة التيار."],"تمرين 1 · ورقة العمل · سؤال ٥ (صفحة 129)":["السلك يسخن من `20°C` إلى `500°C` فتزيد مقاومته كثيرا. نضرب المعامل في فرق الحرارة ونضيف واحدا ثم نضرب في المقاومة الأصلية.","سلك `R₀ = 2 × 10⁻⁴ Ω` و `α = 5 × 10⁻³ °C⁻¹` سخن من `20°C` إلى `220°C`: `R = 2 × 10⁻⁴ × (1 + 5 × 10⁻³ × 200) = 4 × 10⁻⁴ Ω`.","لأن الزيادة النسبية `α·ΔT` هنا كبيرة بسبب فرق الحرارة الكبير `480°C`، فتصبح المقاومة أكثر من أربعة أمثال قيمتها الأصلية."],"تمرين 2 · ورقة العمل · سؤال ٦ (صفحة 129)":["نحسب مقاومة السلك من مادته وأبعاده: نضرب المقاومية في الطول ونقسم على المساحة. ولا نحتاج جهدا ولا تيارا.","سلك نحاس `L = 4 m` و `A = 2 × 10⁻⁶ m²` و `ρ = 1.7 × 10⁻⁸ Ω·m`: `R = 1.7 × 10⁻⁸ × 4 ÷ (2 × 10⁻⁶) = 0.034 Ω`.","لأن المقاومة تتناسب طرديا مع الطول وعكسيا مع مساحة المقطع، والمقاومية هي ثابت التناسب الذي يحدده نوع المادة."],"تمرين 3 · مثال ١ (صفحة 125)":["إذا عرفت التيار والجهد فالقدرة حاصل ضربهما مباشرة. فالشحنات المارة كل ثانية تحمل طاقة تتناسب مع الجهد.","مروحة على `220 V` يمر فيها `0.25 A`: `P = I·V = 0.25 × 220 = 55 W`.","لأن الجهد هو الطاقة لكل وحدة شحنة، والتيار هو الشحنة لكل ثانية، فحاصل ضربهما طاقة لكل ثانية، وهذه هي القدرة."],"تمرين 4 · ورقة العمل · سؤال ٧ (صفحة 130)":["نعرف القدرة والجهد ونريد المقاومة، فنستخدم `P = V² / R` ونعزل `R` بقسمة مربع الجهد على القدرة.","مصباح `100 W` على `220 V`: `R = V² / P = 48400 ÷ 100 = 484 Ω`.","لأن هذه الصيغة تربط القدرة بالجهد والمقاومة مباشرة دون الحاجة إلى التيار، فهي الأقصر عندما يكون التيار غير معطى."],"تمرين 5 · ورقة العمل · سؤال ٧ (صفحة 130)":["القدرة تساوي التيار مضروبا في الجهد، فإذا عرفنا القدرة والجهد قسمنا القدرة على الجهد لنجد التيار.","مصباح `100 W` على `220 V`: `I = P/V = 100 ÷ 220 ≈ 0.455 A`.","لأن `P = I·V` تربط الكميات الثلاث مباشرة، فمعرفة اثنتين منها تكفي لإيجاد الثالثة دون حساب المقاومة."]},"4-8":{"":["الدرس يشرح طريقتين لتوصيل المقاومات: على التوالي في مسار واحد، وعلى التوازي في فروع متعددة. كأنها طريق واحد ضيق مقابل عدة طرق متوازية.","مقاومتان `4 Ω` و `12 Ω`: على التوالي `R = 4 + 12 = 16 Ω`، وعلى التوازي `R = 4 × 12 ÷ 16 = 3 Ω`.","لأن الشحنات في التوالي تعبر كل المقاومات واحدة بعد أخرى فتتجمع الإعاقة، أما في التوازي فكل فرع يضيف مسارا جديدا فتقل المقاومة المكافئة."],"التوصيل على التوالي":["في التوالي المقاومات في طريق واحد كعربات قطار، فالتيار نفسه يمر فيها كلها. أما جهد المصدر فيتوزع عليها، والمقاومة الكلية مجموعها.","ثلاث مقاومات `2 Ω` و `3 Ω` و `5 Ω` على التوالي مع `20 V`: `R = 10 Ω` و `I = 2 A`، والجهود `4 V` و `6 V` و `10 V`.","لأن للشحنات مسارا واحدا فقط، فلا يمكن أن يختلف التيار من مقاومة لأخرى. والشحنة تفقد جزءا من طاقتها في كل مقاومة، فيتوزع الجهد عليها."],"التوصيل على التوازي":["في التوازي كل مقاومة لها فرع خاص بين النقطتين نفسيهما، كممرات متعددة إلى قاعة واحدة. الجهد واحد على كل فرع، والتيار يتوزع، والمقاومة الكلية أصغر من أصغرها.","مقاومتان `4 Ω` و `4 Ω` على التوازي مع `8 V`: `R = 4 × 4 ÷ 8 = 2 Ω`، وكل فرع يمر فيه `2 A`، والتيار الرئيسي `4 A`.","لأن كل فرع يفتح مسارا إضافيا للشحنات، فيمر تيار أكبر من المصدر عند الجهد نفسه، وهذا يعني مقاومة مكافئة أصغر."],"تذكّر":["في المنزل كل جهاز موصول في فرع خاص، فيحصل على `220 V` كاملة. وإذا أطفأت المصباح بقيت الثلاجة تعمل.","مصباح `100 W` وتلفاز `200 W` على التوازي مع `220 V`: التيار الرئيسي `I = 300 ÷ 220 ≈ 1.36 A`، وبعد إطفاء المصباح يصبح `200 ÷ 220 ≈ 0.91 A`.","لأن كل فرع في التوازي موصول بين طرفي المصدر مباشرة، ففتح فرع لا يقطع مسار الشحنات في الفروع الأخرى."],"أمثلة الحقيبة التدريبية محلولة":["في التوالي نجمع المقاومات لنجد الكلية، ثم نضرب التيار في كل مقاومة لنعرف جهدها. ومجموع الجهود يساوي جهد المصدر.","مقاومتان `3 Ω` و `7 Ω` على التوالي يمر فيهما `1.5 A`: `R = 10 Ω` و `V₁ = 4.5 V` و `V₂ = 10.5 V` و `V = 15 V`.","لأن الشحنة تعبر المقاومتين واحدة تلو الأخرى، فيمر التيار نفسه فيهما، وتفقد جزءا من طاقتها في كل منهما فيتوزع الجهد."],"أمثلة الحقيبة التدريبية محلولة (تابع)":["بعد حساب جهد كل مقاومة نجمعها لنجد الجهد الكلي، ونتحقق بضرب التيار في المقاومة الكلية. المقاومة الأكبر تأخذ الجهد الأكبر.","مقاومتان `2 Ω` و `8 Ω` على التوالي مع `3 A`: `V₁ = 6 V` و `V₂ = 24 V`، والتحقق `V = 3 × 10 = 30 V`.","لأن التيار واحد في التوالي، فالجهد `V = I·R` يتناسب طرديا مع المقاومة، فتأخذ المقاومة الأكبر نصيبا أكبر من الجهد."],"مثال: مقاومتان على التوازي (صفحة 127)":["في التوازي نجمع مقلوبات المقاومات ثم نقلب الناتج، أو نقسم حاصل الضرب على المجموع لمقاومتين فقط. والنتيجة دائما أصغر من أصغر مقاومة.","مقاومتان `12 Ω` و `4 Ω` على التوازي: `1/R = 1/12 + 3/12 = 4/12`، إذن `R = 3 Ω`.","لأن الجهد واحد على كل فرع، فالتيار الكلي مجموع تيارات الفروع `V/R₁ + V/R₂`، وبقسمة الجهد على هذا المجموع نحصل على قانون المقلوبات."],"مثال: مقاومتان على التوازي (صفحة 127) (تابع)":["بعد إيجاد المقاومة الكلية نحسب التيار الرئيسي، ثم تيار كل فرع بقسمة الجهد على مقاومته. والمقاومة الأصغر تأخذ تيارا أكبر.","مقاومتان `12 Ω` و `4 Ω` على التوازي مع `24 V`: `I₁ = 2 A` و `I₂ = 6 A`، والتيار الرئيسي `8 A`، وهو يساوي `24 ÷ 3`.","لأن الجهد واحد على الفرعين، فالتيار `I = V/R` يتناسب عكسيا مع المقاومة، فيمر التيار الأكبر في الفرع الأسهل."],"رسم توضيحي 1":["الأميتر في طريق التيار يقرأ قيمة واحدة لأن التيار واحد في التوالي. وكل فولتميتر يقيس جهد مقاومته، ومجموع قراءاتها يساوي جهد المصدر.","مصدر `12 V` مع مقاومتين `2 Ω` و `4 Ω` على التوالي: الأميتر يقرأ `2 A`، والفولتميتران `4 V` و `8 V`، ومجموعهما `12 V`.","لأن الطاقة التي يعطيها المصدر لكل وحدة شحنة تفقدها الشحنة كلها في المقاومات، فمجموع الجهود على المقاومات يساوي جهد المصدر."],"رسم توضيحي 2":["في التوازي الفروع كلها متصلة بالنقطتين نفسيهما، فلها الجهد نفسه. والتيار الرئيسي ينقسم عليها كالنهر يتفرع إلى جداول ثم يجتمع.","مصدر `6 V` مع فرعين `3 Ω` و `6 Ω`: تيارا الفرعين `2 A` و `1 A`، والتيار الرئيسي `3 A`.","لأن الشحنة لا تفنى ولا تتراكم عند نقطة التفرع، فما يدخل النقطة من تيار يساوي ما يخرج منها، لذلك التيار الرئيسي مجموع تيارات الفروع."],"قواعد توصيل المقاومات":["التوالي والتوازي متعاكسان: في التوالي التيار واحد والجهد يتوزع والمكافئة أكبر من أكبر مقاومة، وفي التوازي الجهد واحد والتيار يتوزع والمكافئة أصغر من أصغر مقاومة.","أربع مقاومات متساوية كل منها `20 Ω`: على التوالي `R = 4 × 20 = 80 Ω`، وعلى التوازي `R = 20 ÷ 4 = 5 Ω`.","لأن التوالي يطيل مسار الشحنات فتزيد الإعاقة، والتوازي يزيد عدد المسارات فتقل. ولهذا يقطع تعطل عنصر دائرة التوالي كلها، بينما تعمل بقية فروع التوازي."],"تطبيقات من الحياة":["أسلاك المنزل على التوازي فيعمل كل جهاز وحده على `220 V`، أما زينة الإضاءة القديمة فعلى التوالي، لذلك إذا احترق مصباح انطفأت كلها.","زينة من `20` مصباحا متماثلا على التوالي مع `220 V`: جهد كل مصباح `220 ÷ 20 = 11 V`.","لأن التوالي مسار واحد، فانقطاعه في أي نقطة يوقف التيار في الدائرة كلها، أما في التوازي فلكل جهاز مسار مستقل."],"تمرين 1 · مثال (صفحة 126)":["في التوالي المقاومة الكلية هي مجموع المقاومات مباشرة، مثل جمع أطوال قطع أنبوب موصولة ببعضها.","مقاومتان `12 Ω` و `8 Ω` على التوالي: `R = 12 + 8 = 20 Ω`.","لأن الشحنة تعبر كل مقاومة بالترتيب فتواجه إعاقة كل منها، فتتجمع الإعاقات بالجمع."],"تمرين 2 · مثال (صفحة 126)":["التيار واحد في كل مقاومات التوالي، فجهد أي مقاومة هو التيار مضروبا في قيمتها.","مقاومة `7 Ω` على التوالي مع أخرى والتيار `3 A`: جهدها `V = 3 × 7 = 21 V`.","لأن قانون أوم يطبق على كل عنصر وحده، والتيار في التوالي هو نفسه في كل المقاومات، فنضربه في مقاومة العنصر المطلوب."],"تمرين 3 · مثال (صفحة 127)":["لمقاومتين على التوازي نضرب القيمتين ونقسم على مجموعهما. والناتج أصغر من أصغر مقاومة.","مقاومتان `10 Ω` و `15 Ω` على التوازي: `R = 150 ÷ 25 = 6 Ω`.","لأن هذه الصيغة ناتجة من جمع المقلوبين `1/R₁ + 1/R₂ = (R₁ + R₂)/(R₁·R₂)` ثم قلب الناتج، فهي اختصار لقانون التوازي العام."],"تمرين 4 · مثال (صفحة 127)":["بعد معرفة المقاومة الكلية نعامل الدائرة كأنها مقاومة واحدة، ونقسم جهد المصدر عليها لنجد التيار الرئيسي.","دائرة توازي مقاومتها الكلية `4 Ω` مع `20 V`: `I = 20 ÷ 4 = 5 A`.","لأن المقاومة المكافئة تسحب من المصدر التيار نفسه الذي تسحبه المقاومات معا، فيطبق قانون أوم عليها مباشرة."],"تمرين 5 · ورقة العمل · سؤال ٨ (صفحة 130)":["نضرب المقاومتين ونقسم على مجموعهما لنجد المكافئة على التوازي، ونتوقع نتيجة أصغر من أصغر المقاومتين.","مقاومتان `20 Ω` و `30 Ω` على التوازي: `R = 600 ÷ 50 = 12 Ω`.","لأن إضافة فرع ثان تزيد مسارات الشحنات، فيمر تيار أكبر عند الجهد نفسه، لذلك تكون المكافئة أصغر من أي مقاومة منفردة."],"تمرين 6 · ورقة العمل · سؤال ٨ (صفحة 130)":["بعد إيجاد المقاومة المكافئة نقسم جهد المصدر عليها لنجد التيار الرئيسي الخارج من المصدر.","مقاومة مكافئة `12 Ω` على `36 V`: `I = 36 ÷ 12 = 3 A`.","لأن المكافئة تمثل الدائرة كلها كمقاومة واحدة، فقانون أوم عليها يعطي التيار الكلي الذي يخرج من المصدر."],"تمرين 7 · ورقة العمل · سؤال ٩ (صفحة 131)":["في التوالي نجمع المقاومات جمعا مباشرا لنجد المقاومة الكلية، كما نجمع أطوال قطع حبل موصولة.","مقاومتان `6 Ω` و `9 Ω` على التوالي: `R = 6 + 9 = 15 Ω`.","لأن للشحنات مسارا واحدا يمر بالمقاومتين، فتتجمع إعاقتهما، فتكون الكلية أكبر من أكبر مقاومة."],"تمرين 8 · ورقة العمل · سؤال ٩ (صفحة 131)":["إذا عرفنا المقاومة الكلية والجهد، نقسم الجهد على المقاومة لنجد التيار.","مقاومة كلية `15 Ω` على `45 V`: `I = 45 ÷ 15 = 3 A`.","لأن التيار يتناسب طرديا مع الجهد وعكسيا مع المقاومة حسب قانون أوم `I = V/R`."],"تمرين 9 · ورقة العمل · سؤال ٩ (صفحة 131)":["في التوالي التيار نفسه يمر في كل مقاومة، فنضربه في المقاومة المطلوبة لنجد جهدها.","مقاومتان `6 Ω` و `9 Ω` على التوالي مع `45 V` والتيار `3 A`: جهد المقاومة `9 Ω` هو `3 × 9 = 27 V`.","لأن الجهد يتوزع في التوالي بنسبة المقاومات، فالمقاومة الأكبر تأخذ الجهد الأكبر، ومجموع الجهود يساوي جهد المصدر."],"تمرين 10 · ورقة العمل · سؤال ١٠ (صفحة 131)":["نعرف المكافئة وإحدى المقاومتين، فنطرح مقلوب المعروفة من مقلوب المكافئة، ثم نقلب الناتج لنجد المجهولة.","مقاومة `60 Ω` على التوازي مع مقاومة مجهولة والمكافئة `20 Ω`: `1/R₂ = 1/20 − 1/60 = 2/60`، إذن `R₂ = 30 Ω`.","لأن قانون التوازي يجمع المقلوبات، فإذا عرفنا المجموع وأحد الحدين نجد الآخر بالطرح. والمجهولة أكبر من المكافئة دائما."]},"4-9":{"":["هذا الدرس تطبيق عملي لقوانين التيار والمقاومة والقدرة على أسئلة الحقيبة التدريبية. في كل سؤال نكتب المعطيات، ثم نختار القانون، ثم نعوض ونحسب، كمن يتبع وصفة طبخ خطوة بخطوة.","سلك يمر فيه `3 A` وفرق الجهد بين طرفيه `12 V`: مقاومته `R = 12 ÷ 3 = 4 Ω`، وقدرته `P = 3 × 12 = 36 W`.","لأن هذه الكميات كلها مرتبطة بقانون أوم وتعريف التيار، فمعرفة كميتين تكفي غالبا لحساب الباقي. وترتيب الحل يمنع الخلط بين الوحدات والقوانين."],"ما تحتاجه لحل ورقة العمل":["هذه الشريحة مثل علبة الأدوات: كل قانون أداة لنوع من الأسئلة. التيار والشحنة لأسئلة العد، وأوم والمقاومة لأسئلة الجهد، والقدرة لأسئلة المصابيح والأجهزة.","مقاومتان `3 Ω` و `6 Ω` على التوازي: `R = 3 × 6 ÷ (3 + 6) = 18 ÷ 9 = 2 Ω`. ولو كانتا على التوالي: `R = 3 + 6 = 9 Ω`.","لأن التيار في التوالي يمر في المقاومات واحدة بعد الأخرى فتتراكم الإعاقة، أما في التوازي فتفتح مسارات إضافية للتيار فتقل المقاومة الكلية. وقانون المقاومة المجهولة مأخوذ مباشرة من قانون مقلوب التوازي."],"حل ورقة العمل":["شدة التيار تشبه عدد السيارات التي تعبر بوابة في كل ثانية، وكثافة التيار هي ذلك العدد لكل متر مربع من عرض الطريق. والمقاومة تشبه زحام الطريق، والقدرة هي سرعة استهلاك الطاقة.","شحنة `30 C` تعبر مقطع موصل في `10 s`: `I = 30 ÷ 10 = 3 A`. وإذا كان الجهد `6 V` فالقدرة `P = 3 × 6 = 18 W`، والمقاومة `R = 6 ÷ 3 = 2 Ω`.","كل تعريف هنا معدل أو نسبة: التيار شحنة لكل ثانية، والكثافة تيار لكل متر مربع، والقدرة طاقة لكل ثانية. لذلك تأتي وحداتها من قسمة وحدتين مثل `A = C/s` و `W = J/s`."],"سؤال ٢: اذكر نص قانون أوم مع كتابة العلاقة الرياضية (صفحة 128)":["كلما رفعنا الجهد على السلك زاد التيار بالنسبة نفسها، مثل الماء الذي يتدفق أسرع كلما زاد ضغطه. والمقاومة هي الرقم الثابت الذي يربط بينهما ما دامت الحرارة ثابتة.","مقاومة `20 Ω` عليها جهد `10 V`: `I = 10 ÷ 20 = 0.5 A`. وعند مضاعفة الجهد إلى `20 V` يصبح `I = 20 ÷ 20 = 1 A`، أي تضاعف التيار.","الجهد يدفع الإلكترونات الحرة داخل الموصل، وتصادمها مع ذرات الفلز يعيق حركتها بقدر ثابت عند حرارة ثابتة. لذلك يتناسب التيار طرديا مع الجهد، ويشترط ثبوت الحرارة لأن المقاومة تتغير بتغيرها."],"سؤال ٣: احسب عدد الإلكترونات التي تمر في موصل خلال 4 s إذا كانت شدة التيار 2 A (صفحة 128)":["نحسب أولا الشحنة الكلية التي مرت، ثم نقسمها على شحنة الإلكترون الواحد لنعرف العدد. مثل معرفة عدد قطع النقود بقسمة المبلغ كله على قيمة القطعة الواحدة.","تيار `3.2 A` لمدة `5 s`: `q = 3.2 × 5 = 16 C`، ثم `n = 16 ÷ (1.6 × 10⁻¹⁹) = 1 × 10²⁰` إلكترون.","لأن كل شحنة تمر هي مضاعف صحيح لشحنة الإلكترون `e`. وشحنة الإلكترون صغيرة جدا، فيلزم عدد هائل من الإلكترونات لتكوين تيار عادي."],"سؤال ٤: موصل مساحة مقطعه الدائري 8 × 10⁻⁷ m² يمر فيه تيار 5.2 × 10⁻³ A، أوجد كثافة التيار (صفحة 128)":["كثافة التيار تبين مدى ازدحام التيار داخل السلك: نقسم التيار على مساحة المقطع. والتيار نفسه في سلك رفيع يكون أكثر ازدحاما منه في سلك سميك.","تيار `2 × 10⁻³ A` في مقطع مساحته `4 × 10⁻⁷ m²`: `J = 2 × 10⁻³ ÷ (4 × 10⁻⁷) = 5 × 10³ A/m²`.","لأن التيار وحده لا يبين كيف تتوزع الشحنة على مقطع السلك، أما قسمته على المساحة فتعطي التيار لكل متر مربع. وهذا يسمح بمقارنة أسلاك مختلفة السمك."],"سؤال ٥: ما مقاومة سلك عند 500°C إذا كانت مقاومته عند 20°C هي 1 × 10⁻⁴ Ω والمعامل الحراري لمادته 6.5 × 10⁻³ °C⁻¹ (صفحة 129)":["المقاومة تكبر كلما سخن السلك. نحسب أولا مقدار ارتفاع الحرارة، ثم نضربه في المعامل الحراري لنعرف نسبة الزيادة، ثم نضيفها إلى المقاومة الأصلية.","سلك مقاومته `2 Ω` عند `20 °C` ومعامله `4 × 10⁻³ °C⁻¹`، سخن إلى `120 °C`: `R = 2 × (1 + 4 × 10⁻³ × 100) = 2 × 1.4 = 2.8 Ω`.","عند ارتفاع الحرارة تزداد اهتزازات ذرات الفلز، فتكثر تصادمات الإلكترونات الحرة بها وتصعب حركتها. لذلك تزداد مقاومة الموصل الفلزي بزيادة درجة الحرارة."],"سؤال ٥: ما مقاومة سلك عند 500°C إذا كانت مقاومته عند 20°C هي 1 × 10⁻⁴ Ω والمعامل الحراري لمادته 6.5 × 10⁻³ °C⁻¹ (صفحة 129) (تابع)":["النتيجة أن المقاومة أصبحت أكبر من أربعة أمثال قيمتها الأصلية، لأن السلك سخن بمقدار `480 °C`. أي أن التسخين الكبير يغير المقاومة تغييرا واضحا.","لو سخن السلك نفسه إلى `220 °C` فقط: `ΔT = 200 °C`، و `α·ΔT = 6.5 × 10⁻³ × 200 = 1.3`، فتكون `R = 1 × 10⁻⁴ × 2.3 = 2.3 × 10⁻⁴ Ω`.","لأن الزيادة في المقاومة تتناسب مع فرق درجة الحرارة `ΔT`، فكلما كبر الفرق كبرت الزيادة. ونضيف 1 داخل القوس لأن المقاومة الأصلية `R₀` موجودة قبل التسخين."],"سؤال ٦: موصل من النحاس طوله 2 m ومساحة مقطعه 5.03 × 10⁻⁵ m² ومقاومته النوعية 1.756 × 10⁻⁸ Ω·m، أوجد مقاومته (صفحة 129)":["مقاومة السلك تعتمد على ثلاثة أشياء: نوع المادة، والطول، وسمك المقطع. السلك الطويل كالممر الطويل يتعب من يعبره، والسلك السميك كالممر الواسع يسهل العبور.","سلك طوله `10 m` ومساحة مقطعه `2 × 10⁻⁶ m²` ومقاومته النوعية `1.7 × 10⁻⁸ Ω·m`: `R = 1.7 × 10⁻⁸ × 10 ÷ (2 × 10⁻⁶) = 8.5 × 10⁻² Ω`.","كلما طال السلك زادت التصادمات التي تواجهها الإلكترونات في طريقها فتزيد المقاومة. وكلما اتسع المقطع زادت المسارات المتاحة فتقل المقاومة، أما `ρ` فتعبر عن طبيعة المادة."],"سؤال ٧: مصباح قدرته 60 W يعمل على جهد 127 V، احسب مقاومته وشدة التيار المار فيه (صفحة 130)":["قدرة المصباح وجهده مكتوبان عليه عادة، ومنهما نعرف الباقي. نقسم مربع الجهد على القدرة فنحصل على المقاومة، ونقسم القدرة على الجهد فنحصل على التيار.","مصباح `40 W` يعمل على `200 V`: `R = 200² ÷ 40 = 40000 ÷ 40 = 1000 Ω`، و `I = 40 ÷ 200 = 0.2 A`. وللتحقق: `0.2 × 1000 = 200 V`.","القدرة حاصل ضرب التيار في الجهد، وبالتعويض عن التيار من قانون أوم `I = V/R` نحصل على `P = V²/R`. لذلك يكفي الجهد والقدرة لحساب المقاومة والتيار."],"سؤال ٧: مصباح قدرته 60 W يعمل على جهد 127 V، احسب مقاومته وشدة التيار المار فيه (صفحة 130) (تابع)":["المصباح يحتاج تيارا أقل من نصف أمبير ليعمل بقدرته الكاملة، ومقاومته نحو `269 Ω`. والتقريب هنا مقبول لأن القسمة لا تعطي عددا صحيحا.","مصباح `100 W` يعمل على `127 V`: `I = 100 ÷ 127 ≈ 0.79 A`، و `R = 127² ÷ 100 = 16129 ÷ 100 ≈ 161.3 Ω`.","نتحقق بقانون أوم لأن الكميات الثلاث `V` و `I` و `R` يجب أن تتوافق دائما. فإذا أعطى حاصل ضرب التيار في المقاومة الجهد الأصلي تقريبا عرفنا أن الحل صحيح."],"سؤال ٨: مقاومتان 9 Ω و 6 Ω على التوازي وُصل طرفاهما بفرق جهد 18 V (صفحة 130)":["على التوازي يجد التيار طريقين بدل طريق واحد، فيسهل مروره وتصغر المقاومة الكلية. مثل فتح بوابتين بدل بوابة واحدة في مدخل ملعب.","مقاومتان `12 Ω` و `6 Ω` على التوازي مع `24 V`: `Rₜ = 12 × 6 ÷ 18 = 4 Ω`، والتيار الرئيسي `I = 24 ÷ 4 = 6 A`.","لأن كل فرع يضيف مسارا جديدا للتيار، فيزداد التيار الكلي عند الجهد نفسه، وهذا يعني مقاومة كلية أقل. لذلك نجمع مقلوب المقاومات لا المقاومات نفسها."],"سؤال ٨: مقاومتان 9 Ω و 6 Ω على التوازي وُصل طرفاهما بفرق جهد 18 V (صفحة 130) (تابع)":["كل مقاومة على التوازي متصلة مباشرة بطرفي المصدر، فجهدها `18 V` كاملا. والمقاومة الأصغر تأخذ تيارا أكبر، ومجموع تياري الفرعين يساوي التيار الرئيسي.","مقاومتان `12 Ω` و `6 Ω` على التوازي مع `24 V`: `I₁ = 24 ÷ 12 = 2 A` و `I₂ = 24 ÷ 6 = 4 A`، ومجموعهما `6 A` وهو التيار الرئيسي.","لأن الشحنة لا تفنى ولا تتراكم عند نقطة التفرع، فما يدخل إليها يساوي ما يخرج منها. لذلك يتوزع التيار الرئيسي على الفروع ويكون مجموعها مساويا له."],"سؤال ٩: مقاومتان 1 Ω و 4 Ω على التوالي وُصل طرفاهما بفرق جهد 10 V (صفحة 131)":["على التوالي تكون المقاومات في طريق واحد، فيمر فيها التيار نفسه وتجمع مقاوماتها مباشرة. مثل طريق فيه عدة مطبات متتالية، كل مطب يزيد صعوبة الرحلة.","مقاومتان `2 Ω` و `3 Ω` على التوالي مع `15 V`: `Rₜ = 2 + 3 = 5 Ω`، و `I = 15 ÷ 5 = 3 A`، و `V₁ = 3 × 2 = 6 V`.","لأن للتيار مسارا واحدا فقط، فكل شحنة تمر في المقاومتين بالتتابع وتفقد جزءا من طاقتها في كل منهما. لذلك يتساوى التيار وتجمع المقاومات."],"سؤال ٩: مقاومتان 1 Ω و 4 Ω على التوالي وُصل طرفاهما بفرق جهد 10 V (صفحة 131) (تابع)":["الجهد يتوزع على المقاومتين حسب قيمتهما: المقاومة الأكبر تأخذ جهدا أكبر. ومجموع الجهدين يساوي جهد المصدر تماما.","مقاومتان `2 Ω` و `3 Ω` على التوالي مع `15 V` والتيار `3 A`: `V₂ = 3 × 3 = 9 V`، و `V₁ + V₂ = 6 + 9 = 15 V` وهو جهد المصدر.","لأن التيار نفسه يمر في المقاومتين، فيكون `V = I·R` أكبر للمقاومة الأكبر. ومجموع الجهود يساوي جهد المصدر لأن الطاقة التي يعطيها المصدر للشحنة تستهلك كلها في المقاومات."],"سؤال ١٠: ما قيمة المقاومة التي إذا وُصلت على التوازي مع مقاومة 300 Ω تصبح المقاومة الكلية 75 Ω (صفحة 131)":["نعرف المقاومة الكلية وإحدى المقاومتين ونبحث عن الأخرى. نطرح مقلوب المقاومة المعروفة من مقلوب الكلية، ثم نقلب الناتج لنحصل على المجهولة.","مقاومة كلية `4 Ω` من مقاومة `12 Ω` وأخرى مجهولة على التوازي: `1/R₂ = 1/4 − 1/12 = 3/12 − 1/12 = 2/12`، إذن `R₂ = 6 Ω`.","لأن قانون التوازي يجمع المقلوبات، فإذا عرفنا المجموع وأحد الحدين وجدنا الآخر بالطرح. والمكافئة أصغر من كل فرع، لذلك يجب أن تخرج المجهولة أكبر من `75 Ω`."],"سؤال ١٠: ما قيمة المقاومة التي إذا وُصلت على التوازي مع مقاومة 300 Ω تصبح المقاومة الكلية 75 Ω (صفحة 131) (تابع)":["بعد إيجاد المقاومة المجهولة نتأكد من الحل بإعادة حساب المقاومة الكلية بها. فإذا رجعنا إلى `75 Ω` فالحل صحيح، مثل مراجعة عملية الطرح بعملية جمع.","مقاومة `20 Ω` على التوازي مع `30 Ω`: `R = 20 × 30 ÷ (20 + 30) = 600 ÷ 50 = 12 Ω`، فهذا يؤكد أن `30 Ω` هي ما يلزم لتصبح الكلية `12 Ω`.","لأن قانون حاصل الضرب على المجموع مكافئ لقانون المقلوبات في حالة مقاومتين، فاستخدامه طريقة مستقلة للتحقق. واتفاق الطريقتين يؤكد خلو الحل من أخطاء الحساب."],"رسم توضيحي":["في الرسم طريقتان لوصل المقاومات: على التوالي تكون المقاومات في خط واحد كعربات القطار، وعلى التوازي تكون في فروع متجاورة كحارات الطريق السريع.","ثلاث مقاومات كل منها `6 Ω` على `12 V`: على التوالي `Rₜ = 18 Ω` و `I = 12 ÷ 18 ≈ 0.67 A`، وعلى التوازي `Rₜ = 2 Ω` و `I = 12 ÷ 2 = 6 A`.","شكل التوصيل يحدد عدد المسارات المتاحة للتيار: مسار واحد في التوالي فيتساوى التيار، ومسارات متعددة في التوازي فيتساوى الجهد. ومن هذا الفرق تنتج قوانين التوصيل كلها."],"تمرين 1 · سؤال ٣ (صفحة 128)":["التيار يعني كمية الشحنة في كل ثانية، فإذا عرفنا التيار والزمن ضربناهما لنعرف الشحنة الكلية. مثل حساب كمية الماء من معدل التدفق ومدة فتح الصنبور.","تيار `1.5 A` لمدة `6 s`: `q = 1.5 × 6 = 9 C`.","لأن التيار معرف بأنه الشحنة المارة في وحدة الزمن `I = q/t`، فبضرب طرفي العلاقة في الزمن نحصل على `q = I·t`."],"تمرين 2 · سؤال ٣ (صفحة 128)":["كل إلكترون يحمل شحنة صغيرة ثابتة، فنقسم الشحنة الكلية عليها لنعرف عدد الإلكترونات. مثل معرفة عدد حبات الأرز بقسمة كتلة الكيس على كتلة الحبة الواحدة.","شحنة `4 C`: `n = 4 ÷ (1.6 × 10⁻¹⁹) = 2.5 × 10¹⁹` إلكترون.","لأن الشحنة الكهربائية تأتي في مضاعفات صحيحة لشحنة الإلكترون `e`، فتكون `q = n·e`. وصغر `e` يجعل عدد الإلكترونات ضخما حتى في شحنة صغيرة."],"تمرين 3 · سؤال ٤ (صفحة 128)":["نقسم التيار على مساحة المقطع لنعرف نصيب كل متر مربع من التيار. والمساحة هنا صغيرة جدا، لذلك تخرج الكثافة كبيرة.","تيار `9 × 10⁻³ A` في مقطع `3 × 10⁻⁶ m²`: `J = 9 × 10⁻³ ÷ (3 × 10⁻⁶) = 3 × 10³ A/m²`.","لأن الكثافة تقيس التيار لكل وحدة مساحة، والقسمة على عدد صغير جدا مثل `8 × 10⁻⁷` تعطي ناتجا كبيرا. ولذلك ننتبه عند قسمة الأسس فنطرح أس المقام من أس البسط."],"تمرين 4 · سؤال ٥ (صفحة 129)":["المقاومة الجديدة تساوي المقاومة الأصلية مضروبة في عامل تكبير يعتمد على مقدار التسخين. نحسب فرق الحرارة أولا، ثم نكمل التعويض.","سلك `5 Ω` عند `20 °C` ومعامله `5 × 10⁻³ °C⁻¹` سخن إلى `60 °C`: `R = 5 × (1 + 5 × 10⁻³ × 40) = 5 × 1.2 = 6 Ω`.","لأن اهتزاز ذرات الفلز يزداد مع الحرارة فتزداد إعاقة حركة الإلكترونات. والمعامل الحراري `α` يبين مقدار الزيادة النسبية في المقاومة لكل درجة."],"تمرين 5 · سؤال ٦ (صفحة 129)":["نضرب المقاومة النوعية في الطول ثم نقسم على مساحة المقطع. وسلك النحاس هنا قصير وسميك، لذلك تخرج مقاومته صغيرة جدا.","سلك نحاس طوله `4 m` ومقطعه `1 × 10⁻⁶ m²` و `ρ = 1.7 × 10⁻⁸ Ω·m`: `R = 1.7 × 10⁻⁸ × 4 ÷ (1 × 10⁻⁶) = 6.8 × 10⁻² Ω`.","لأن المقاومة النوعية للنحاس صغيرة جدا، أي أن إلكتروناته الحرة تتحرك بسهولة. لهذا يستخدم النحاس في صناعة الأسلاك الكهربائية."],"تمرين 6 · سؤال ٧ (صفحة 130)":["مقاومة المصباح نحسبها من جهده وقدرته فقط: نربع الجهد ثم نقسمه على القدرة. فالمصباح الأقل قدرة على الجهد نفسه تكون مقاومته أكبر.","مصباح `25 W` يعمل على `100 V`: `R = 100² ÷ 25 = 10000 ÷ 25 = 400 Ω`.","لأن `P = V·I` و `I = V/R`، فبالتعويض تصبح `P = V²/R`. وعند ثبوت الجهد تقل القدرة كلما زادت المقاومة لأن التيار يقل."],"تمرين 7 · سؤال ٧ (صفحة 130)":["القدرة حاصل ضرب التيار في الجهد، فإذا عرفنا القدرة والجهد قسمناهما لنحصل على التيار. والجهد هنا كبير، لذلك يكفي تيار صغير.","سخان `1100 W` يعمل على `220 V`: `I = 1100 ÷ 220 = 5 A`.","لأن الجهد هو الطاقة لكل كولوم، والتيار عدد الكولومات في الثانية، فحاصل ضربهما طاقة في الثانية، وهي القدرة."],"تمرين 8 · سؤال ٨ (صفحة 130)":["لمقاومتين على التوازي نضرب المقاومتين ثم نقسم على مجموعهما. والناتج يكون دائما أصغر من أصغر المقاومتين.","مقاومتان `10 Ω` و `15 Ω` على التوازي: `R = 10 × 15 ÷ (10 + 15) = 150 ÷ 25 = 6 Ω`.","هذه الصيغة ناتجة من توحيد المقامات في `1/R = 1/R₁ + 1/R₂`. والمكافئة أصغر لأن إضافة فرع جديد تفتح طريقا إضافيا للتيار."],"تمرين 9 · سؤال ٨ (صفحة 130)":["بعد أن نختصر الفرعين إلى مقاومة واحدة، نعامل الدائرة كأنها مقاومة واحدة على المصدر ونطبق قانون أوم مباشرة.","مقاومة مكافئة `1.5 Ω` على `12 V`: `I = 12 ÷ 1.5 = 8 A`.","لأن المقاومة المكافئة تسحب من المصدر التيار نفسه الذي تسحبه المقاومات الأصلية مجتمعة. لذلك يكون التيار المحسوب بها هو التيار الرئيسي."],"تمرين 10 · سؤال ٩ (صفحة 131)":["على التوالي نجمع المقاومات مباشرة، كمن يجمع أطوال قطع أنبوب موصولة خلف بعضها.","ثلاث مقاومات `2 Ω` و `5 Ω` و `8 Ω` على التوالي: `R = 2 + 5 + 8 = 15 Ω`.","لأن التيار يعبر كل مقاومة بالتتابع، فيلقى إعاقة كل منها بالترتيب. لذلك تكون المقاومة الكلية أكبر من أكبر مقاومة."],"تمرين 11 · سؤال ٩ (صفحة 131)":["قانون أوم يربط الجهد والتيار والمقاومة، فإذا عرفنا اثنين منها حسبنا الثالث. وهنا نقسم الجهد على المقاومة لنحصل على التيار.","مقاومة كلية `8 Ω` على `24 V`: `I = 24 ÷ 8 = 3 A`.","لأن الجهد يدفع الشحنات والمقاومة تعيقها، فكلما زاد الجهد زاد التيار، وكلما زادت المقاومة قل التيار. لذلك `I = V/R`."],"تمرين 12 · سؤال ٩ (صفحة 131)":["التيار نفسه يمر في كل مقاومات التوالي، فجهد أي مقاومة يساوي التيار مضروبا في قيمتها. والمقاومة الأكبر تأخذ نصيبا أكبر من الجهد.","تيار `1.5 A` يمر في مقاومة `6 Ω` ضمن دائرة توال: `V = 1.5 × 6 = 9 V`.","لأن قانون أوم ينطبق على كل مقاومة بمفردها كما ينطبق على الدائرة كلها. وتساوي التيار في التوالي يجعل الجهد يتناسب مع المقاومة."],"تمرين 13 · سؤال ١٠ (صفحة 131)":["نطرح مقلوب المقاومة المعروفة من مقلوب المقاومة الكلية، ثم نقلب الناتج. مثل معرفة ما يضيفه عامل ثان إذا عرفنا إنجاز العامل الأول وإنجازهما معا.","مقاومة `60 Ω` على التوازي مع مقاومة مجهولة والكلية `20 Ω`: `1/R₂ = 1/20 − 1/60 = 3/60 − 1/60 = 2/60`، إذن `R₂ = 30 Ω`.","لأن المقلوبات في التوازي تجمع، فالمجهول يظهر بطرح المقلوب المعلوم من المقلوب الكلي. ولا يجوز طرح المقاومات نفسها لأن القانون لا يجمعها مباشرة."]},"4-10":{"":["هذا الدرس مراجعة للوحدة كلها: التيار وكثافته، وقانون أوم، والمقاومة، والقدرة، وطرق التوصيل. هو مثل جولة أخيرة في البيت قبل السفر للتأكد من أن كل شيء في مكانه.","مقاومتان `4 Ω` و `4 Ω` على التوازي ومعهما `8 Ω` على التوالي، على `20 V`: `R = 2 + 8 = 10 Ω`، و `I = 20 ÷ 10 = 2 A`، و `P = 20 × 2 = 40 W`.","لأن قوانين الوحدة كلها تبنى على فكرتين: التيار حركة شحنات، والمقاومة إعاقة لهذه الحركة. فإذا فهمت العلاقة بينهما سهل عليك ربط القوانين معا."],"مراجعة الوحدة الخامسة":["التيار كمية الشحنة كل ثانية، والمقاومة ما يعيقها، والجهد ما يدفعها، والقدرة سرعة استهلاك الطاقة. وفي التوالي يتقاسم المسار الواحد الجهد، وفي التوازي تأخذ الفروع كلها الجهد نفسه.","سلك يمر فيه `0.5 A` ومقاومته `40 Ω`: `V = 0.5 × 40 = 20 V`، و `P = 0.5² × 40 = 10 W`.","لأن المقاومة تنتج من تصادم الإلكترونات بذرات المادة، فتزيد بطول الطريق وبالحرارة وتقل باتساع المقطع. وهذا يفسر الصيغة `R = ρL/A` وتغير المقاومة مع الحرارة."],"مراجعة الوحدة الخامسة (تابع)":["اتفق العلماء على أن التيار يخرج من القطب الموجب، ثم تبين أن الإلكترونات تتحرك فعلا في الاتجاه المعاكس. فنستخدم الاتجاه المتفق عليه في الرسم، ونعرف أن الحركة الفعلية عكسه.","بطارية `9 V` موصولة بمصباح: يرسم التيار خارجا من الطرف `+` إلى المصباح ثم إلى الطرف `−`، بينما تخرج الإلكترونات من الطرف `−` وتعود إلى `+`.","لأن الإلكترونات سالبة الشحنة، فهي تنجذب نحو القطب الموجب وتبتعد عن السالب. أما الاتجاه الاصطلاحي فقد وضع على أساس حركة شحنات موجبة، فيكون عكس حركة الإلكترونات."],"تصحيح شائع":["التوصيل المركب ليس التوازي، بل دائرة فيها جزء على التوالي وجزء على التوازي معا. مثل طريق رئيسي يتفرع إلى حارتين ثم يعود طريقا واحدا.","مقاومتان `10 Ω` و `10 Ω` على التوازي مكافئتهما `5 Ω`، ثم على التوالي مع `15 Ω`: `R = 5 + 15 = 20 Ω`. هذه دائرة مركبة.","لأن نوع التوصيل يحدد طريقة الحساب: في المركب نحسب كل جزء بقانونه أولا ثم نجمع النتائج. ولو عاملناه كتواز فقط لأخطأنا في المقاومة الكلية."],"تمارين الوحدة محلولة":["الإلكترونات الحرة داخل المعدن تتحرك دائما مثل الناس في ساحة مزدحمة، كل منهم في اتجاه. فلا يوجد انتقال إجمالي في اتجاه واحد، ولا يوجد تيار حتى نطبق فرق جهد.","سلك موضوع على الطاولة غير موصول ببطارية: إلكتروناته تتحرك، لكن الأميتر يقرأ `0 A`. وعند وصله ببطارية `1.5 V` يبدأ مرور التيار.","لأن الحركة العشوائية في كل الاتجاهات تلغي بعضها بعضا، فمحصلة الشحنة العابرة للمقطع صفر. والمجال الكهربائي يضيف انجرافا في اتجاه واحد، وهذا الانجراف هو التيار."],"صح وخطأ ٢: تعريف شدة التيار (صفحة 132)":["شدة التيار تعني: كم كولوم يعبر مقطع السلك في كل ثانية؟ مثل عدد الركاب الذين يمرون من باب المحطة في الثانية.","شحنة `12 C` تعبر مقطعا في `4 s`: `I = 12 ÷ 4 = 3 A`.","لأن التيار معدل زمني لمرور الشحنة، والمعدل يحسب بالقسمة على الزمن. لذلك تكون العبارة صحيحة ووحدة التيار `C/s`."],"صح وخطأ ٣: تعريف الأمبير (صفحة 132)":["الأمبير يعني مرور كولوم واحد كل ثانية، لا كل دقيقة. والدقيقة ستون ثانية، فالشحنة نفسها في دقيقة تعطي تيارا أصغر بكثير.","مرور `120 C` في دقيقة واحدة: نحول الدقيقة إلى `60 s` أولا، ثم `I = 120 ÷ 60 = 2 A`.","لأن وحدة الزمن في النظام الدولي هي الثانية، والأمبير معرف بها: `1 A = 1 C/s`. واستخدام الدقيقة يغير القيمة ستين مرة."],"صح وخطأ ٤: تعريف فرق الجهد (صفحة 132)":["فرق الجهد هو مقدار الطاقة التي يكسبها أو يفقدها كل كولوم عند انتقاله بين نقطتين. مثل فرق الارتفاع بين طابقين الذي يحدد الطاقة اللازمة لرفع كل كيلوغرام.","نقل شحنة `2 C` بين نقطتين تطلب `24 J`: `V = 24 ÷ 2 = 12 V`.","لأن الجهد يعرف نصيب الكولوم الواحد من الطاقة، فنقسم الطاقة على الشحنة. لذلك يكون `1 V = 1 J/C`."],"صح وخطأ ٥: المقاومة المكافئة في التوازي (صفحة 132)":["في التوازي لا نجمع المقاومات نفسها بل نجمع مقلوباتها، ثم نقلب الناتج لنحصل على المقاومة المكافئة.","ثلاث مقاومات `6 Ω` و `3 Ω` و `2 Ω` على التوازي: `1/R = 1/6 + 2/6 + 3/6 = 1`، إذن `R = 1 Ω`.","لأن الجهد نفسه على كل فرع، والتيار الكلي مجموع تيارات الفروع: `V/R = V/R₁ + V/R₂ + V/R₃`. وبالقسمة على `V` نحصل على قانون المقلوبات."],"صح وخطأ ٦: المقاومة المكافئة في التوالي (صفحة 132)":["في التوالي نجمع المقاومات مباشرة، لأنها في طريق واحد يمر فيه التيار نفسه.","مقاومات `3 Ω` و `7 Ω` و `10 Ω` على التوالي: `R = 3 + 7 + 10 = 20 Ω`.","لأن التيار نفسه يمر في كل المقاومات، وجهد المصدر مجموع جهودها: `I·R = I·R₁ + I·R₂ + I·R₃`. وبالقسمة على `I` نحصل على مجموع المقاومات."],"صح وخطأ ٧: جمع المقاومات في التوازي (صفحة 133)":["جمع المقاومات مباشرة خاص بالتوالي فقط. ففي التوازي تصبح المقاومة الكلية أصغر من أصغر مقاومة، فلا يمكن أن تساوي مجموعها.","مقاومتان `20 Ω` و `20 Ω` على التوازي: `1/R = 1/20 + 1/20 = 1/10`، فالمكافئة `10 Ω` لا `40 Ω`.","لأن كل فرع جديد في التوازي يضيف مسارا للتيار فتقل الإعاقة الكلية. أما الجمع المباشر فيعني زيادة الإعاقة، وهذا يحدث فقط عندما تكون المقاومات في مسار واحد."],"صح وخطأ ٨: تعريف التوصيل المركب (صفحة 133)":["التوصيل المركب يجمع النوعين في دائرة واحدة. فلو كانت الدائرة كلها على التوازي فهي توصيل على التوازي فقط لا مركب.","مقاومتان `12 Ω` و `6 Ω` على التوازي مكافئتهما `12 × 6 ÷ 18 = 4 Ω`، ثم على التوالي مع `6 Ω`: `R = 4 + 6 = 10 Ω`.","لأن كلمة «مركب» تعني مكونا من أكثر من نوع. لذلك يحل بتقسيم الدائرة إلى أجزاء بسيطة، ونحسب كل جزء بقانونه."],"صح وخطأ ٩: الهدف من أنواع التوصيل (صفحة 133)":["نصل على التوالي عندما نريد تقسيم جهد المصدر على عدة أجزاء، ونصل على التوازي عندما نريد أن يأخذ كل جهاز الجهد كاملا. مثل تقسيم كعكة واحدة مقابل إعطاء كل شخص كعكة كاملة.","مصدر `12 V` مع مقاومتين متساويتين: على التوالي تأخذ كل منهما `6 V`، وعلى التوازي تأخذ كل منهما `12 V`.","لأن التيار في التوالي واحد، فيتوزع الجهد بنسبة المقاومات. وفي التوازي كل فرع متصل مباشرة بطرفي المصدر، فيأخذ جهده كاملا."],"صح وخطأ ١٠: شدة التيار كمعدل (صفحة 133)":["كلمة «معدل» تعني كمية في كل وحدة زمن، مثل السرعة التي هي مسافة في كل ثانية. وشدة التيار شحنة في كل ثانية.","شحنة `0.6 C` تعبر مقطعا في `0.2 s`: `I = 0.6 ÷ 0.2 = 3 A`.","لأن التيار يصف سرعة تدفق الشحنة لا كميتها الكلية، فنقسم الشحنة على الزمن. لذلك قد تمر شحنة كبيرة بتيار صغير إذا كان الزمن طويلا."],"صح وخطأ ١١: الاتجاه الحقيقي للتيار (صفحة 133)":["الإلكترونات تخرج من القطب السالب للبطارية وتسير في الأسلاك حتى تصل إلى القطب الموجب. وهذا عكس الاتجاه الذي نرسمه للتيار في الدوائر.","مصباح جيب يعمل ببطارية `3 V`: تخرج الإلكترونات من الطرف السالب، وتمر في سلك المصباح، ثم تدخل الطرف الموجب.","لأن الإلكترونات سالبة، فيدفعها القطب السالب ويجذبها القطب الموجب. أما الاتجاه الاصطلاحي فيفترض حركة شحنات موجبة، فيكون عكسها."],"صح وخطأ ١٢: علاقة الجهد بالتيار (صفحة 133)":["عند ثبوت المقاومة، رفع الجهد يرفع التيار بالنسبة نفسها. مثل زيادة ميل المنحدر التي تجعل الكرة تتدحرج أسرع.","مقاومة `10 Ω`: عند `5 V` يكون `I = 5 ÷ 10 = 0.5 A`، وعند `20 V` يكون `I = 20 ÷ 10 = 2 A`، أي أن التيار تضاعف أربع مرات مع الجهد.","لأن الجهد هو ما يدفع الشحنات، فكلما زاد زادت سرعة انجرافها وزاد التيار. وهذا هو قانون أوم `I = V/R` بشرط ثبوت المقاومة والحرارة."],"صح وخطأ ١٣: وحدة كثافة التيار (صفحة 133)":["كثافة التيار هي التيار مقسوما على المساحة، فوحدتها وحدة التيار مقسومة على وحدة المساحة.","تيار `6 A` في مقطع `2 × 10⁻⁶ m²`: `J = 6 ÷ (2 × 10⁻⁶) = 3 × 10⁶ A/m²`.","لأن وحدة أي كمية مشتقة تأتي من قانونها: `J = I / A` فيها أمبير في البسط ومتر مربع في المقام، فتكون `A/m²`."],"صح وخطأ ١٤: أثر مساحة المقطع على المقاومة (صفحة 133)":["السلك السميك كالطريق العريض: يمر فيه عدد أكبر من الإلكترونات بسهولة، فتقل المقاومة.","سلك مقاومته `4 Ω`، استبدل بسلك من المادة نفسها وبالطول نفسه لكن مساحة مقطعه ضعف الأول: `R = 4 ÷ 2 = 2 Ω`.","لأن `A` في مقام `R = ρL/A`، فالمقاومة تتناسب عكسيا مع المساحة. والمقطع الأوسع يوفر مسارات أكثر للإلكترونات في الوقت نفسه."],"صح وخطأ ١٥: صفة التيار المستمر (صفحة 133)":["التيار المستمر يسري في اتجاه واحد دائما وبشدة ثابتة، مثل ماء يجري في قناة في اتجاه واحد وبسرعة ثابتة.","بطارية `1.5 V` موصولة بمقاومة `3 Ω`: يمر تيار `I = 1.5 ÷ 3 = 0.5 A` في الاتجاه نفسه طوال الوقت، ومنحناه مع الزمن خط أفقي.","لأن قطبي البطارية لا يتبادلان، فيبقى الجهد بين طرفيها في اتجاه واحد ويبقى التيار في اتجاه واحد. وثبات الجهد والمقاومة يجعل الشدة ثابتة."],"صح وخطأ ١٦: وحدة المقاومة (صفحة 133)":["الأوم يعني: كم فولت نحتاج لدفع أمبير واحد خلال المقاومة. وسميت الوحدة باسم العالم أوم صاحب القانون.","مقاومة يمر فيها `2 A` عند جهد `10 V`: `R = 10 ÷ 2 = 5 V/A = 5 Ω`.","لأن المقاومة معرفة بأنها نسبة الجهد إلى التيار `R = V/I`، فوحدتها وحدة الجهد مقسومة على وحدة التيار، وهي `V/A`."],"صح وخطأ ١٧: تعريف المقاومة النوعية (صفحة 133)":["المقاومة النوعية صفة للمادة نفسها، مثل الكثافة. فهي مقاومة قطعة نموذجية من المادة طولها متر ومساحة مقطعها متر مربع.","قطعة نحاس طولها `1 m` ومقطعها `1 m²` ومقاومتها النوعية `1.7 × 10⁻⁸ Ω·m`: `R = 1.7 × 10⁻⁸ × 1 ÷ 1 = 1.7 × 10⁻⁸ Ω`.","لأننا نريد كمية نقارن بها المواد بغض النظر عن أبعاد السلك. فبتثبيت الطول والمساحة عند الواحد تبقى المقاومة معتمدة على نوع المادة فقط."],"صح وخطأ ١٨: تعريف الأوم (صفحة 133)":["الأوم الواحد هو مقاومة تسمح بمرور أمبير واحد عندما نضع عليها فولتا واحدا. كأنه وحدة قياس الصعوبة التي يجدها التيار.","مقاومة `1 Ω` على جهد `3 V` يمر فيها `I = 3 ÷ 1 = 3 A`.","لأن المقاومة نسبة الجهد إلى التيار، فإذا كان الجهد `1 V` والتيار `1 A` كانت النسبة `1 Ω`. وهكذا تعرف الوحدة من القانون نفسه."],"صح وخطأ ١٩: المقاومة المكافئة في التوالي مرة أخرى (صفحة 133)":["هذه العبارة تكرار لقاعدة التوالي: المقاومات المتتالية تجمع مباشرة، والمجموع هو المكافئة.","أربع مقاومات كل منها `5 Ω` على التوالي: `R = 5 + 5 + 5 + 5 = 20 Ω`.","لأن التيار في التوالي واحد، وكل مقاومة تأخذ جزءا من الجهد يتناسب مع قيمتها. ومجموع هذه الأجزاء جهد المصدر، فتجمع المقاومات."],"صح وخطأ ٢٠: المقاومة والتوصيل (صفحة 133)":["المقاومة والتوصيل وجهان متعاكسان: كلما قلت إعاقة المادة للتيار سهل مروره فيها. مثل الطريق الخالي من العوائق الذي يسهل السير فيه.","سلكان على `6 V`: الأول `2 Ω` يمر فيه `3 A`، والثاني `6 Ω` يمر فيه `1 A`. فالأقل مقاومة أفضل توصيلا.","لأن الموصلية مقلوب المقاومية `σ = 1/ρ`، فانخفاض إحداهما يعني ارتفاع الأخرى. ومن قانون أوم يزيد التيار عند الجهد نفسه كلما قلت المقاومة."],"صح وخطأ ٢١: المقاومة الكلية في التوالي (صفحة 134)":["في التوالي نضيف المقاومات بعضها إلى بعض، فالمجموع لا بد أن يكون أكبر من أي واحدة منها.","مقاومات `2 Ω` و `3 Ω` و `10 Ω` على التوالي: `R = 2 + 3 + 10 = 15 Ω`، وهي أكبر من أكبرها `10 Ω`.","لأن المقاومات كلها قيم موجبة، وإضافة عدد موجب تزيد المجموع دائما. فكل مقاومة إضافية تزيد إعاقة المسار الواحد."],"صح وخطأ ٢٢: المقاومة الكلية في التوازي (صفحة 134)":["في التوازي كل مقاومة جديدة تفتح طريقا إضافيا للتيار، فتصبح المقاومة الكلية أصغر حتى من أصغر مقاومة.","مقاومتان `4 Ω` و `12 Ω` على التوازي: `R = 4 × 12 ÷ (4 + 12) = 48 ÷ 16 = 3 Ω`، وهي أصغر من `4 Ω`.","لأن مقلوب المكافئة مجموع مقلوبات، فهو أكبر من مقلوب أي مقاومة منفردة. والعدد الذي مقلوبه أكبر يكون هو نفسه أصغر."],"صح وخطأ ٢٣: توصيل سوائل الجسم والماء المالح (صفحة 134)":["الماء المالح وسوائل الجسم تحتوي على أيونات حرة الحركة تحمل الشحنة، كما تحملها الإلكترونات الحرة في المعادن. لذلك يمر فيها التيار بسهولة.","اليد المبللة بالعرق أو بالماء المالح أخطر عند لمس سلك مكشوف من اليد الجافة، لأن مقاومة الجلد المبلل أقل فيزيد التيار المار في الجسم.","التيار يحتاج إلى شحنات حرة الحركة، والأملاح الذائبة تنفصل إلى أيونات موجبة وسالبة تتحرك بحرية. لذلك يوصل الماء المالح التيار أفضل بكثير من الماء النقي."],"صح وخطأ ٢٤: احتراق مصباح في دائرة توالٍ (صفحة 134)":["مصابيح التوالي كحلقات سلسلة واحدة: إذا انقطعت حلقة انفصلت السلسلة كلها. فاحتراق مصباح يقطع المسار الوحيد للتيار.","زينة فيها `20` مصباحا متماثلا على التوالي مع `220 V`: يأخذ كل مصباح `220 ÷ 20 = 11 V`، وإذا احترق واحد انطفأت المصابيح كلها.","لأن للتيار في التوالي مسارا واحدا فقط، فأي انقطاع فيه يجعل الدائرة مفتوحة. والدائرة المفتوحة لا يمر فيها تيار، فتنطفئ كل المصابيح."],"صح وخطأ ٢٥: احتراق مصباح في دائرة توازٍ (صفحة 134)":["مصابيح التوازي كغرف لكل منها باب مستقل إلى الممر: إغلاق باب غرفة لا يمنع دخول الغرف الأخرى.","ثلاثة مصابيح على التوازي مع `220 V`، تيار كل منها `0.5 A`: التيار الكلي `1.5 A`. وإذا احترق أحدها صار التيار الكلي `1 A`، وبقي كل مصباح على `220 V` و `0.5 A`.","لأن كل فرع متصل مباشرة بطرفي المصدر، فجهده لا يعتمد على الفروع الأخرى. لذلك لا يتغير تيار المصابيح الباقية ولا سطوعها."],"اختر الإجابة ١: دائرة مركبة المقاومة الكلية والتيار الكلي (صفحة 134)":["في الدائرة المركبة نبسط الجزء المتوازي أولا ونجعله مقاومة واحدة، ثم نجمعها مع مقاومة التوالي. مثل حل ما بين الأقواس أولا في عملية حسابية.","مقاومتان `4 Ω` و `4 Ω` على التوازي مع `8 Ω` على التوالي وبطارية `12 V`: `R₁₂ = 16 ÷ 8 = 2 Ω`، و `R = 2 + 8 = 10 Ω`، و `I = 12 ÷ 10 = 1.2 A`.","لأن المقاومتين المتوازيتين عليهما الجهد نفسه، فيمكن استبدالهما بمكافئة واحدة. وبعد الاستبدال تصبح الدائرة كلها على التوالي، فنجمع المقاومات."],"اختر الإجابة ١: دائرة مركبة المقاومة الكلية والتيار الكلي (صفحة 134) (تابع)":["بعد معرفة المقاومة الكلية نقسم جهد البطارية عليها لنعرف التيار الكلي. ثم نتحقق بأن جهود الأجزاء تجمع إلى جهد البطارية.","دائرة فيها `8 Ω` على التوالي مع مكافئة `2 Ω` وبطارية `12 V`: `I = 12 ÷ 10 = 1.2 A`، وجهد `8 Ω` هو `9.6 V`، وجهد الجزء المتوازي `2.4 V`، ومجموعهما `12 V`.","لأن التيار الكلي يمر كاملا في مقاومة التوالي، ثم ينقسم بين الفرعين المتوازيين. ولأن الفرعين متساويان يأخذ كل منهما نصف التيار."],"اختر الإجابة ٢: نوع الشحنة المكونة للتيار في الموصل (صفحة 134)":["في المعادن تبقى الأنوية بما فيها من بروتونات ونيوترونات مثبتة في أماكنها، ولا تتحرك إلا الإلكترونات الحرة. فهي حاملة التيار في السلك.","في سلك يمر فيه `1 A` يعبر المقطع كل ثانية `n = 1 ÷ (1.6 × 10⁻¹⁹) = 6.25 × 10¹⁸` إلكترون.","لأن الإلكترونات الخارجية في الفلزات ضعيفة الارتباط بذراتها فتتحرك بحرية. أما البروتونات فمقيدة في النواة، والنيوترونات لا شحنة لها فلا تكون تيارا."],"رسم توضيحي":["الرسم يقارن طريقتي الوصل: التوالي مسار واحد تمر فيه الشحنات عبر كل المقاومات، والتوازي مسارات متعددة يتوزع عليها التيار. مثل طريق واحد طويل مقابل عدة طرق متجاورة.","مقاومتان كل منهما `10 Ω` على `10 V`: على التوالي `R = 20 Ω` و `I = 10 ÷ 20 = 0.5 A`، وعلى التوازي `R = 5 Ω` و `I = 10 ÷ 5 = 2 A`.","لأن التوالي يجعل التيار واحدا فتتراكم الإعاقة، والتوازي يجعل الجهد واحدا فتتوزع الشحنات على مسارات أكثر. لهذا تكون مكافئة التوازي دائما أصغر من مكافئة التوالي للمقاومات نفسها."],"تمرين 1 · اختر الإجابة ١ (صفحة 134)":["نحول المقاومتين المتوازيتين إلى مقاومة واحدة، ثم نضيف إليها المقاومة الموصولة على التوالي. وعندما تتساوى مقاومتان على التوازي تكون مكافئتهما نصف إحداهما.","مقاومتان `10 Ω` و `10 Ω` على التوازي مع `7 Ω` على التوالي: `R₁₂ = 100 ÷ 20 = 5 Ω`، و `R = 5 + 7 = 12 Ω`.","لأن قانون التوازي لمقاومتين متساويتين `R·R/(2R)` يساوي `R/2`. وبعد التبسيط تصبح المكافئة في مسار واحد مع المقاومة الأخرى فتجمعان."],"تمرين 2 · اختر الإجابة ١ (صفحة 134)":["بعد معرفة المقاومة الكلية نعامل الدائرة كأنها مقاومة واحدة، ونقسم جهد البطارية عليها لنحصل على التيار الكلي.","مقاومة كلية `15 Ω` على `9 V`: `I = 9 ÷ 15 = 0.6 A`.","لأن قانون أوم ينطبق على الدائرة كلها بمقاومتها المكافئة، فالمكافئة تسحب من المصدر التيار نفسه الذي تسحبه الدائرة الأصلية."]}};

/* 5 نوفمبر: إجابات جاهزة لشرائح الدروس النموذجية الجديدة */
(function(){var A={"3-3":{"مثال ١ · صفحة 95":["نريد معرفة شدة تأثير الشحنة عند نقطة على بعد معين منها. نضرب `k` في الشحنة ونقسم على مربع المسافة، والمجال يتجه بعيدا عن الشحنة الموجبة كأنها تدفع ما حولها.","شحنة `8 × 10⁻⁹ C` ونقطة على بعد `0.2 m`: `E = 9 × 10⁹ × 8 × 10⁻⁹ ÷ 0.2² = 72 ÷ 0.04 = 1800 N/C` بعيدا عن الشحنة.","لأن المصدر شحنة نقطية واحدة، وأثرها ينتشر في كل الاتجاهات فيتوزع على مساحة تكبر مع `r²`. ويتجه المجال بعيدا عنها لأن شحنة الاختبار الموجبة تتنافر مع الشحنة الموجبة."],"مثال ٢ · صفحة 95":["إذا عرفنا القوة التي أصابت شحنة صغيرة عند نقطة، نقسمها على مقدار الشحنة فنحصل على نصيب كل كولوم من القوة، وهذا هو المجال.","شحنة `4 × 10⁻⁹ C` تأثرت بقوة `2 × 10⁻⁵ N`: `E = F / q₀ = 2 × 10⁻⁵ ÷ 4 × 10⁻⁹ = 5 × 10³ N/C = 5000 N/C`.","لأن المجال يعرف بأنه القوة لكل وحدة شحنة. ولو ضاعفنا الشحنة لتضاعفت القوة بالنسبة نفسها، فيبقى الناتج `E` ثابتا لأنه صفة للنقطة لا للشحنة."],"تمرين ١ · ورقة العمل · سؤال ٥ (صفحة 105)":["القوة معلومة والشحنة معلومة، فنقسم القوة على الشحنة لنعرف شدة المجال في ذلك المكان. انتبه لقسمة الأسس: نطرح أس المقام من أس البسط.","شحنة `3 × 10⁻⁶ C` تأثرت بقوة `9 × 10⁻³ N`: `E = 9 × 10⁻³ ÷ 3 × 10⁻⁶ = 3 × 10³ N/C = 3000 N/C`.","لأن تعريف المجال `E = F / q₀` يعطي القوة المؤثرة على كل كولوم. ووحدة الناتج `N/C` تأتي مباشرة من قسمة النيوتن على الكولوم."],"تمرين ٢ · ورقة العمل · سؤال ٦ (صفحة 105)":["كلما ابتعدنا عن الشحنة ضعف مجالها بسرعة لأن المسافة مربعة. نعوض الشحنة والمسافة في القانون، ثم نحدد الاتجاه من إشارة الشحنة.","شحنة `6 × 10⁻⁹ C` ونقطة على بعد `0.3 m`: `E = 9 × 10⁹ × 6 × 10⁻⁹ ÷ 0.3² = 54 ÷ 0.09 = 600 N/C` بعيدا عن الشحنة.","لأن المجال حول شحنة نقطية يقل مع مربع المسافة كما في قانون كولوم، فنستخدم `E = k·q / r²`. والاتجاه بعيدا عنها لأنها موجبة."]},"3-4":{"الجهد الكهربائي":["تخيل رفع كتاب إلى رف عال: الشغل الذي تبذله يخزن فيه طاقة وضع. كذلك دفع شحنة عكس المجال يخزن فيها طاقة، والجهد هو نصيب كل كولوم من هذه الطاقة.","شحنة `2 × 10⁻⁶ C` عند نقطة طاقة وضعها `6 × 10⁻⁴ J`: `V = PE / q₀ = 6 × 10⁻⁴ ÷ 2 × 10⁻⁶ = 300 V`.","لأن طاقة الوضع تتضاعف إذا تضاعفت الشحنة، فقسمتها على `q₀` تعطي قيمة لا تعتمد على شحنة الاختبار بل على موضع النقطة في المجال. لذلك يكون الجهد صفة للنقطة نفسها."],"مثال ١ · صفحة 96":["في المجال المنتظم يكون المجال ثابتا في كل مكان، فيكفي أن نضرب شدته في المسافة بين النقطتين لنعرف فرق الجهد.","مجال منتظم `E = 5000 N/C` ونقطتان بينهما `0.04 m`: `ΔV = E·d = 5000 × 0.04 = 200 V`.","لأن القوة على الشحنة في المجال المنتظم ثابتة `F = q·E`، فالشغل لنقلها مسافة `d` هو `q·E·d`. وبقسمة الشغل على الشحنة نحصل على `ΔV = E·d`."],"مثال ٢ · صفحة 96":["الجهد حول شحنة نقطية يقل كلما ابتعدنا عنها، لكنه يقل مع المسافة نفسها لا مع مربعها. ونعطيه إشارة الشحنة نفسها.","شحنة `3 × 10⁻⁶ C` ونقطة على بعد `0.3 m`: `V = 9 × 10⁹ × 3 × 10⁻⁶ ÷ 0.3 = 27000 ÷ 0.3 = 9 × 10⁴ V`.","لأن الجهد كمية قياسية تمثل طاقة الوضع لكل كولوم حول الشحنة، وهي تتناسب مع `1 / r`. لذلك نستخدم `V = k·q / r` بلا تربيع وبلا اتجاه، والإشارة تتبع إشارة الشحنة."],"تمرين ١ · ورقة العمل · سؤال ٧ (صفحة 106)":["المجال منتظم بين لوحين، فنضرب شدة المجال في المسافة بين النقطتين مباشرة لنحصل على فرق الجهد.","مجال منتظم `E = 2000 N/C` ونقطتان بينهما `0.05 m`: `ΔV = 2000 × 0.05 = 100 V`.","لأن الشغل على كل كولوم في مجال منتظم يساوي القوة لكل كولوم مضروبة في المسافة. ووحدة `N/C × m` تساوي `J/C`، أي الفولت."],"تمرين ٢ · ورقة العمل · سؤال ٨ (صفحة 106)":["نعوض الشحنة والمسافة في قانون جهد الشحنة النقطية، ونتذكر أن المسافة هنا غير مربعة.","شحنة `2 × 10⁻⁶ C` ونقطة على بعد `0.4 m`: `V = 9 × 10⁹ × 2 × 10⁻⁶ ÷ 0.4 = 18000 ÷ 0.4 = 4.5 × 10⁴ V`.","لأن المطلوب جهد نقطة حول شحنة نقطية واحدة، والجهد حولها يتناسب طرديا مع الشحنة وعكسيا مع المسافة `r`."]},"3-5":{"السعة الكهربائية":["المكثف مثل خزان للشحنة، والسعة تخبرنا كم كولوما نضع فيه مقابل كل فولت. إذا ضاعفنا الجهد تضاعفت الشحنة، وتبقى السعة كما هي.","مكثف على جهد `12 V` يحمل `6 × 10⁻⁵ C`: `C = q / V = 5 × 10⁻⁶ F = 5 µF`. وعلى `24 V` يحمل `1.2 × 10⁻⁴ C` والسعة `5 µF` أيضا.","لأن الشحنة على اللوحين تتناسب طرديا مع فرق الجهد، فنسبتهما ثابتة. وهذه النسبة تعتمد على شكل المكثف ووسطه العازل فقط، لا على الجهد المطبق."],"سماحية الوسط العازل":["السماحية تصف مدى سماح الوسط بنشوء المجال فيه. وضع عازل بين اللوحين بدل الهواء يضرب السعة في `εᵣ`، كأننا وسعنا الخزان.","لوحان `A = 0.01 m²` و `d = 1 × 10⁻³ m` في الهواء: `C = 8.85 × 10⁻¹² × 0.01 ÷ 10⁻³ = 8.85 × 10⁻¹¹ F`. ومع عازل `εᵣ = 4` تصبح `3.54 × 10⁻¹⁰ F`.","لأن الوسط العازل يتأثر بالمجال فتترتب شحنات جزيئاته بحيث تضعف المجال بين اللوحين. فيقل فرق الجهد للشحنة نفسها، وبما أن `C = q / V` تزيد السعة."],"العوامل المؤثرة على سعة المكثف":["ثلاثة عوامل تتحكم في السعة: كبر اللوحين يزيدها، وابتعادهما يقللها، والعازل الجيد بينهما يزيدها.","مكثف سعته `10 pF`: بمضاعفة المساحة تصبح `20 pF`، وبمضاعفة المسافة تصبح `5 pF`، وبوضع عازل `εᵣ = 3` تصبح `30 pF`.","لأن `C = εᵣ·ε₀·A / d`: المساحة الأكبر تتسع لشحنة أكثر، والمسافة الأصغر تزيد التجاذب بين شحنتي اللوحين فيخزن المكثف شحنة أكبر عند الجهد نفسه."],"مثال ١ · صفحة 98":["نعرف الشحنة على المكثف والجهد بين لوحيه، فنقسم الشحنة على الجهد لنعرف كم كولوما يخزن لكل فولت.","مكثف شحنته `2.4 × 10⁻⁴ C` وجهده `120 V`: `C = 2.4 × 10⁻⁴ ÷ 120 = 2 × 10⁻⁶ F = 2 µF`.","لأن السعة معرفة بأنها `C = q / V`، أي الشحنة اللازمة لتغيير الجهد بمقدار فولت واحد. والناتج يكون صغيرا عادة لأن الفاراد وحدة كبيرة."],"مثال ٢ · صفحة 98":["السعة تخبرنا بالشحنة لكل فولت، فإذا عرفنا عدد الفولتات نضرب لنحصل على الشحنة الكلية.","مكثف سعته `10 × 10⁻⁶ F` على جهد `30 V`: `q = C·V = 10 × 10⁻⁶ × 30 = 3 × 10⁻⁴ C`.","لأن تعريف السعة `C = q / V`، وبضرب الطرفين في `V` نحصل على `q = C·V`. فالشحنة تتناسب طرديا مع الجهد عند سعة ثابتة."],"مثال ٣ · صفحة 99":["نحسب السعة أولا من أبعاد المكثف، ثم الشحنة من السعة والجهد، ثم المجال بقسمة الجهد على المسافة بين اللوحين.","لدينا `A = 0.5 m²` و `d = 2 × 10⁻³ m` و `V = 10 V`: `C = 8.85 × 10⁻¹² × 0.5 ÷ 2 × 10⁻³ ≈ 2.21 × 10⁻⁹ F`، و `q = C·V ≈ 2.21 × 10⁻⁸ C`، و `E = 10 ÷ 2 × 10⁻³ = 5000 N/C`.","لأن سعة المكثف متوازي اللوحين تعتمد على `A` و `d` والوسط، والشحنة تأتي من تعريف السعة. والمجال بين اللوحين منتظم، لذلك `E = V / d`."],"تمرين ١ · ورقة العمل · سؤال ٩ (صفحة 106)":["الشحنة والجهد معلومان، فنقسم الشحنة على الجهد مباشرة لنحصل على السعة بالفاراد.","مكثف شحنته `9 × 10⁻⁴ C` وجهده `300 V`: `C = 9 × 10⁻⁴ ÷ 300 = 3 × 10⁻⁶ F = 3 µF`.","لأن نسبة الشحنة إلى الجهد ثابتة للمكثف الواحد، وهذه النسبة هي تعريف السعة `C = q / V`."],"تمرين ٢ · ورقة العمل · سؤال ١٠ (صفحة 107)":["البطارية تفرض جهدها على المكثف، فيمتلئ بشحنة تساوي سعته مضروبة في جهد البطارية.","مكثف سعته `8 × 10⁻¹² F` متصل ببطارية `9 V`: `q = 8 × 10⁻¹² × 9 = 7.2 × 10⁻¹¹ C`.","لأن المكثف يشحن حتى يصبح فرق الجهد بين لوحيه مساويا لجهد البطارية، وعندها تكون شحنته `q = C·V`."],"تمرين ٣ · ورقة العمل · سؤال ١١ (صفحة 107)":["إذا عرفنا الشحنة والسعة نقسم الشحنة على السعة لنعرف الجهد. السعة تعني كولوم لكل فولت، فالقسمة تعطي عدد الفولتات.","مكثف سعته `4 × 10⁻⁶ F` وشحنته `1.2 × 10⁻⁵ C`: `V = q / C = 1.2 × 10⁻⁵ ÷ 4 × 10⁻⁶ = 3 V`.","لأن العلاقة `C = q / V` تعطي بإعادة الترتيب `V = q / C`. فكلما زادت الشحنة على مكثف معين زاد الجهد بين لوحيه."],"تمرين ٤ · ورقة العمل · سؤال ١١ (صفحة 107)":["المجال بين لوحي المكثف منتظم، فنقسم فرق الجهد على المسافة بين اللوحين لنعرف شدته.","مكثف جهده `6 V` والمسافة بين لوحيه `2 × 10⁻³ m`: `E = V / d = 6 ÷ 2 × 10⁻³ = 3000 V/m`.","لأن المجال المنتظم يحقق `ΔV = E·d`، ومنها `E = V / d`. والوحدة `V/m` تساوي `N/C` تماما."]},"3-6":{"مثال ١ · صفحة 101":["في التوازي كل مكثف متصل بالمصدر مباشرة فيأخذ الجهد نفسه. لذلك نجمع السعات، ونحسب شحنة كل مكثف ثم نجمعها.","مكثفان `C₁ = 100 pF` و `C₂ = 300 pF` على التوازي بجهد `50 V`: `C_total = 400 pF`، `q₁ = 5 × 10⁻⁹ C`، `q₂ = 1.5 × 10⁻⁸ C`، `q_total = 2 × 10⁻⁸ C`.","لأن الجهد متساو على المكثفات والشحنة الكلية مجموع الشحنات، فتكون `C_total = C₁ + C₂`. والتوصيل على التوازي يشبه تكبير مساحة اللوحين."],"مثال ٢ · صفحة 102":["في التوالي تمر الشحنة نفسها على كل مكثف، والجهد يتوزع بينها. المكثف الأصغر سعة يأخذ الجهد الأكبر.","مكثفان `C₁ = 4 pF` و `C₂ = 12 pF` على التوالي بجهد `8 V`: `C_total = 48 ÷ 16 = 3 pF`، `q = 2.4 × 10⁻¹¹ C`، `V₁ = 6 V`، `V₂ = 2 V`.","لأن الشحنة على اللوحين الداخليين تنشأ بالتأثير فتتساوى على المكثفين، ومجموع الجهدين يساوي جهد المصدر. لذلك `1/C_total = 1/C₁ + 1/C₂`، و `V = q / C` أكبر للسعة الأصغر."],"مثال ٣ · صفحة 103":["المكثف المشحون يخزن طاقة مثل نابض مضغوط. إذا عرفنا السعة والجهد نستخدم نصف السعة في مربع الجهد.","مكثف سعته `5 × 10⁻⁶ F` على جهد `20 V`: `PE = ½ × 5 × 10⁻⁶ × 20² = 1 × 10⁻³ J`.","لأن الجهد يرتفع تدريجيا من صفر إلى `V` أثناء الشحن، فمتوسطه `V/2`. فالشغل المخزن `½·q·V`، وبالتعويض `q = C·V` نحصل على `½·C·V²`."],"مثال ٤ · صفحة 103":["إذا عرفنا الشحنة والجهد نحسب الطاقة بنصف حاصل ضربهما، لا بحاصل الضرب كاملا.","مكثف شحنته `3 × 10⁻³ C` على جهد `100 V`: `PE = ½ × 3 × 10⁻³ × 100 = 0.15 J`.","لأن نقل الشحنات يبدأ والجهد صفر ثم يزداد حتى `V`، فكل كولوم نقل في المتوسط عبر نصف الجهد. لذلك الطاقة `½·q·V` لا `q·V`."],"تمرين ١ · ورقة العمل · سؤال ١٢ (صفحة 108)":["في التوالي تكون السعة الكلية أصغر من أصغر مكثف. نستخدم حاصل الضرب على المجموع لمكثفين.","مكثفان `3 µF` و `6 µF` على التوالي: `C_total = 3 × 6 ÷ (3 + 6) = 18 ÷ 9 = 2 µF`.","لأن التوصيل على التوالي يشبه زيادة المسافة بين اللوحين، فتقل السعة. ورياضيا `1/C_total = 1/C₁ + 1/C₂` تعطي قيمة أصغر من كل منهما."],"تمرين ٢ · ورقة العمل · سؤال ١٢ (صفحة 108)":["في التوازي نجمع السعات مباشرة، فالنتيجة أكبر من أكبر مكثف.","مكثفان `3 µF` و `5 µF` على التوازي: `C_total = 3 + 5 = 8 µF`.","لأن المكثفين على الجهد نفسه، فالشحنة الكلية مجموع شحنتيهما. وهذا يشبه مكثفا واحدا مساحة لوحيه أكبر، فتزيد السعة."],"تمرين ٣ · ورقة العمل · سؤال ١٣ (صفحة 108)":["مكثفان على التوالي: نضرب السعتين ونقسم على مجموعهما. والجهد المطبق لا يغير السعة الكلية لكنه يحدد الشحنة.","مكثفان `6 nF` و `3 nF` على التوالي بجهد `9 V`: `C_total = 18 ÷ 9 = 2 nF`، والشحنة `q = 2 × 10⁻⁹ × 9 = 1.8 × 10⁻⁸ C`.","لأن الشحنة متساوية على المكثفين والجهد يتوزع بينهما، فيكون مقلوب السعة الكلية مجموع المقلوبات. والسعة لا تعتمد على الجهد."],"تمرين ٤ · ورقة العمل · سؤال ١٤ (صفحة 109)":["في التوازي نجمع السعات كما هي، ثم يمكن حساب الشحنة الكلية بضربها في الجهد.","مكثفان `250 nF` و `150 nF` على التوازي بجهد `100 V`: `C_total = 400 nF`، و `q = 400 × 10⁻⁹ × 100 = 4 × 10⁻⁵ C`.","لأن كل مكثف يأخذ جهد المصدر كاملا، فتجمع الشحنات وبالتالي تجمع السعات `C_total = C₁ + C₂`."],"تمرين ٥ · ورقة العمل · سؤال ١٠ (صفحة 107)":["المعطى سعة وجهد، فنستخدم نصف السعة في مربع الجهد. لا تنس تربيع الجهد قبل الضرب.","مكثف سعته `10 × 10⁻¹² F` على بطارية `6 V`: `PE = ½ × 10⁻¹¹ × 36 = 1.8 × 10⁻¹⁰ J`.","لأن الطاقة المخزنة تساوي الشغل المبذول في شحن المكثف عبر جهد يرتفع من صفر إلى `V`، فتكون `PE = ½·C·V²`."]},"4-1":{"أهداف الوحدة":["في هذه الوحدة يتدرب المتدرب على فهم التيار وحسابه، والتمييز بين نوعيه، واستخدام قانون أوم والقدرة، وحساب المقاومة المكافئة للدوائر.","أمثلة من الحياة: بطارية الجوال تعطي تيارا مستمرا، وكهرباء المنزل `220 V` تيار متردد، وسخان الماء يستهلك قدرة تقارب `2000 W`.","لأن كل جهاز كهربائي دائرة فيها تيار ومقاومة وقدرة، وفهم هذه الكميات يمكن من تحليل الدوائر وتصميمها واستخدامها بأمان."],"كثافة التيار":["كثافة التيار تخبرنا كم هو مزدحم التيار في المقطع. التيار نفسه في مقطع ضيق يكون أكثر ازدحاما، مثل الماء في أنبوب ضيق.","تيار `3 A` في سلك مقطعه `2 mm² = 2 × 10⁻⁶ m²`: `J = I / A = 3 ÷ 2 × 10⁻⁶ = 1.5 × 10⁶ A/m²`.","لأن الشحنة المارة في الثانية ثابتة على طول السلك، فإذا صغرت المساحة يجب أن يمر نصيب أكبر من التيار في كل متر مربع."],"سرعة الانجراف":["الإلكترونات داخل السلك تتحرك ببطء شديد لأنها تصطدم بالذرات باستمرار، مثل شخص يمشي في زحام شديد.","كثافة تيار `1 × 10⁶ A/m²` و `n = 5 × 10²⁸ m⁻³`: `n·e = 8 × 10⁹`، و `v_d = 1 × 10⁶ ÷ 8 × 10⁹ = 1.25 × 10⁻⁴ m/s`.","لأن التصادمات المتكررة مع ذرات الموصل توقف الإلكترون وتغير اتجاهه، فلا تبقى إلا حركة متوسطة بطيئة عكس المجال. كما أن عدد الإلكترونات الحرة `n` كبير جدا، فيكفي انجراف بطيء لنقل تيار كبير."],"أنواع التيار الكهربائي":["المستمر يسير في اتجاه واحد مثل نهر، والمتردد يذهب ويعود دوريا مثل الأرجوحة.","بطارية `1.5 V` تعطي تيارا مستمرا. وكهرباء المنزل `220 V` بتردد `60 Hz` تكمل 60 دورة في الثانية، فيعكس التيار اتجاهه 120 مرة في الثانية.","لأن المحولات تعمل بالتيار المتردد فيسهل رفع جهده. وعند رفع الجهد ينقل التيار القدرة نفسها بتيار أصغر، فيقل الفقد الحراري `I²·R` في الأسلاك البعيدة."],"مثال ١ · صفحة 118":["التيار هو عدد الكولومات التي تعبر مقطع السلك كل ثانية، فنقسم الشحنة على الزمن.","شحنة `30 C` تمر في `12 s`: `I = q / t = 30 ÷ 12 = 2.5 A`.","لأن التيار يعرف بأنه معدل مرور الشحنة، والأمبير يساوي كولوما لكل ثانية `A = C/s`."],"مثال ٢ · صفحة 119":["نقسم التيار على مساحة المقطع بعد تحويلها إلى `m²`، فنعرف نصيب كل متر مربع من التيار.","تيار `3 A` في مقطع `1.5 × 10⁻⁶ m²`: `J = 3 ÷ 1.5 × 10⁻⁶ = 2 × 10⁶ A/m²`.","لأن كثافة التيار هي التيار لكل وحدة مساحة `J = I / A`. والمساحة الصغيرة جدا تعطي كثافة كبيرة جدا رغم أن التيار صغير."],"مثال ٣ · صفحة 119":["نحسب التيار أولا من الشحنة والزمن، ثم نقسمه على المساحة لنحصل على الكثافة. لا تنس تحويل `mm²` إلى `m²`.","شحنة `12 C` في `3 s` عبر مقطع `8 mm²`: `I = 12 ÷ 3 = 4 A`، و `J = 4 ÷ 8 × 10⁻⁶ = 5 × 10⁵ A/m²`.","لأن الكثافة تعتمد على التيار، والتيار لا يعرف إلا من الشحنة والزمن. لذلك نحسب `I = q / t` ثم `J = I / A`."],"مثال ٤ · صفحة 120":["نحسب كثافة التيار أولا، ثم نقسمها على عدد الإلكترونات في المتر المكعب مضروبا في شحنة الإلكترون.","تيار `2 A` في مقطع `1 × 10⁻⁶ m²` و `n = 8 × 10²⁸ m⁻³`: `J = 2 × 10⁶ A/m²`، `n·e = 1.28 × 10¹⁰`، و `v_d ≈ 1.56 × 10⁻⁴ m/s`.","لأن `J = n·e·v_d`: الكثافة تساوي عدد الإلكترونات في المتر المكعب مضروبا في شحنة كل منها وسرعتها. ولأن `n` ضخم تخرج السرعة صغيرة جدا."],"تمرين ١ · ورقة العمل · سؤال ٣ (صفحة 128)":["إذا عرفنا كم كولوما يمر كل ثانية ومدة المرور، نضرب لنعرف الشحنة الكلية.","تيار `0.5 A` لمدة `20 s`: `q = I·t = 0.5 × 20 = 10 C`.","لأن `I = q / t` يعني أن التيار شحنة لكل ثانية، فضربه في عدد الثواني يعطي الشحنة الكلية المارة."],"تمرين ٢ · ورقة العمل · سؤال ٣ (صفحة 128)":["كل إلكترون يحمل شحنة صغيرة جدا، فنقسم الشحنة الكلية على شحنة الإلكترون الواحد لنعرف عددها.","شحنة `3.2 C`: `n = 3.2 ÷ 1.6 × 10⁻¹⁹ = 2 × 10¹⁹` إلكترون.","لأن الشحنة مكماة، أي أن أي شحنة تساوي عددا صحيحا من شحنة الإلكترون `q = n·e`، فيكون `n = q / e`."],"تمرين ٣ · ورقة العمل · سؤال ٤ (صفحة 128)":["نقسم التيار على مساحة المقطع، مع الانتباه لقسمة الأسس.","تيار `4 × 10⁻³ A` في مقطع `2 × 10⁻⁷ m²`: `J = 4 × 10⁻³ ÷ 2 × 10⁻⁷ = 2 × 10⁴ A/m²`.","لأن كثافة التيار هي التيار لكل متر مربع من المقطع `J = I / A`، والمقطع الصغير يجعل الكثافة كبيرة."]},"4-5":{"المقاومة الكهربائية":["المقاومة مثل الزحام في طريق: تعيق حركة الإلكترونات، ومع كل اصطدام تتحول طاقة إلى حرارة. نستخدمها للتحكم في التيار وحماية الدوائر.","سلك عليه `12 V` ويمر فيه `0.5 A`: `R = V / I = 12 ÷ 0.5 = 24 Ω`.","لأن الإلكترونات المتحركة تصطدم بذرات الموصل فتفقد جزءا من طاقتها، وتتحول هذه الطاقة إلى حرارة. وكلما زادت هذه الممانعة قل التيار للجهد نفسه."],"أثر درجة الحرارة في المقاومة":["عند تسخين الموصل تهتز ذراته أكثر، فيصبح طريق الإلكترونات أكثر ازدحاما وتزيد المقاومة.","موصل `R₀ = 50 Ω` عند `20 °C` و `α = 4 × 10⁻³ °C⁻¹`، عند `70 °C`: `R = 50 × (1 + 4 × 10⁻³ × 50) = 50 × 1.2 = 60 Ω`.","لأن ارتفاع الحرارة يزيد اهتزاز ذرات الموصل، فتزيد تصادمات الإلكترونات معها. والزيادة تتناسب تقريبا مع فرق الحرارة `T − T₀`."],"القدرة الكهربائية":["القدرة هي سرعة استهلاك الطاقة: كم جولا يستهلك الجهاز كل ثانية. الجهاز الأقوى يستهلك طاقة أكبر في الزمن نفسه.","غلاية على `220 V` يمر فيها `5 A`: `P = I·V = 5 × 220 = 1100 W`، وفي `60 s` تستهلك `E = P·t = 66000 J`.","لأن الجهد طاقة لكل كولوم والتيار كولومات لكل ثانية، فحاصل ضربهما طاقة لكل ثانية `P = I·V`. وبالتعويض من قانون أوم نحصل على `I²·R` و `V² / R`."],"مثال ١ · صفحة 124":["نعرف الجهد والتيار، فنقسم الجهد على التيار لنعرف مقاومة الجهاز.","مكواة على `220 V` يمر فيها `4 A`: `R = V / I = 220 ÷ 4 = 55 Ω`.","لأن قانون أوم `V = I·R` يربط الكميات الثلاث، فإذا عرفنا اثنتين حسبنا الثالثة. والمقاومة هي الجهد اللازم لكل أمبير."],"مثال ٢ · صفحة 124":["المقاومة والجهد معلومان، فنقسم الجهد على المقاومة لنعرف التيار.","مقاومة `4 Ω` بين طرفيها `12 V`: `I = V / R = 12 ÷ 4 = 3 A`.","لأن قانون أوم يبين أن التيار يتناسب طرديا مع الجهد وعكسيا مع المقاومة، فنستخدم `I = V / R`."],"مثال ٣ · صفحة 124":["السلك الطويل يعيق التيار أكثر، والسلك السميك يفتح طريقا أوسع فيقل الإعاقة. ونوع المادة يحدده `ρ`.","سلك نحاس `L = 10 m` و `A = 1 × 10⁻⁶ m²` و `ρ = 1.77 × 10⁻⁸ Ω·m`: `R = 1.77 × 10⁻⁸ × 10 ÷ 10⁻⁶ = 0.177 Ω`.","لأن الإلكترونات في السلك الأطول تمر بتصادمات أكثر فتزيد المقاومة طرديا مع `L`، والمقطع الأكبر يتيح مسارات أكثر فتقل عكسيا مع `A`. أما `ρ` فخاصية المادة."],"مثال ٤ · صفحة 124":["نحسب فرق الحرارة أولا، ثم نضربه في المعامل الحراري ونضيف واحدا، ثم نضرب في المقاومة الأصلية.","مقاومة `R₀ = 10 Ω` عند `20 °C` و `α = 3.9 × 10⁻³ °C⁻¹`، عند `100 °C`: `R = 10 × (1 + 3.9 × 10⁻³ × 80) = 10 × 1.312 = 13.12 Ω`.","لأن مقاومة الموصل تزيد خطيا تقريبا مع ارتفاع الحرارة، فالزيادة `R₀·α·(T − T₀)` تضاف إلى المقاومة الأصلية."],"مثال ٥ · صفحة 125":["نحسب التيار أولا بقانون أوم، ثم نضربه في الجهد لنعرف القدرة.","مصباح `6 Ω` على `12 V`: `I = 12 ÷ 6 = 2 A`، و `P = I·V = 2 × 12 = 24 W`.","لأن القدرة تحتاج التيار والجهد `P = I·V`، والتيار نعرفه من قانون أوم. ويمكن التحقق بـ `P = V² / R = 144 ÷ 6 = 24 W`."],"تمرين ١ · ورقة العمل · سؤال ٥ (صفحة 129)":["الحرارة ارتفعت كثيرا، فنحسب الفرق ونضربه في المعامل ونضيف واحدا ثم نضرب في المقاومة الأصلية.","مقاومة `R₀ = 2 × 10⁻⁴ Ω` عند `20 °C` و `α = 5 × 10⁻³ °C⁻¹`، عند `220 °C`: `R = 2 × 10⁻⁴ × (1 + 5 × 10⁻³ × 200) = 2 × 10⁻⁴ × 2 = 4 × 10⁻⁴ Ω`.","لأن اهتزاز الذرات يزيد مع الحرارة فتزيد التصادمات، والعلاقة `R = R₀·(1 + α·(T − T₀))` تصف هذه الزيادة."],"تمرين ٢ · ورقة العمل · سؤال ٦ (صفحة 129)":["نضرب المقاومية في الطول ونقسم على المساحة، مع الانتباه للأسس.","سلك نحاس `L = 5 m` و `A = 2 × 10⁻⁶ m²` و `ρ = 1.756 × 10⁻⁸ Ω·m`: `R = 1.756 × 10⁻⁸ × 5 ÷ 2 × 10⁻⁶ = 4.39 × 10⁻² Ω`.","لأن المقاومة تعتمد على أبعاد السلك ونوع مادته `R = ρ·L / A`. وتخرج صغيرة لأن النحاس موصل جيد ومقاوميته صغيرة جدا."],"تمرين ٣ · ورقة العمل · سؤال ٧ (صفحة 130)":["نعرف القدرة والجهد ولا نعرف التيار، فنستخدم مربع الجهد مقسوما على القدرة.","مصباح `100 W` على `220 V`: `R = V² / P = 48400 ÷ 100 = 484 Ω`.","لأن `P = V² / R` تأتي من دمج `P = I·V` مع قانون أوم، فإعادة ترتيبها تعطي `R = V² / P` مباشرة دون حساب التيار."],"تمرين ٤ · ورقة العمل · سؤال ٧ (صفحة 130)":["القدرة طاقة كل ثانية، والجهد طاقة كل كولوم، فقسمة القدرة على الجهد تعطي الكولومات في الثانية، أي التيار.","مصباح `100 W` على `220 V`: `I = P / V = 100 ÷ 220 ≈ 0.455 A`.","لأن `P = I·V`، وبالقسمة على `V` نحصل على `I = P / V`. ويمكن التحقق: `I = V / R = 220 ÷ 484 ≈ 0.455 A`."]},"4-8":{"مثال ١ · صفحة 126":["في التوالي يمر التيار نفسه في كل مقاومة كأنها طريق واحد، فنجمع المقاومات، وكل مقاومة تأخذ جزءا من الجهد.","مقاومتان `4 Ω` و `8 Ω` على التوالي بتيار `1.5 A`: `R_total = 12 Ω`، `V₁ = 6 V`، `V₂ = 12 V`، والجهد الكلي `18 V`.","لأن الشحنة لا تجد إلا مسارا واحدا فالتيار متساو، والطاقة لكل كولوم تتوزع على المقاومات. لذلك `V = V₁ + V₂` و `R_total = R₁ + R₂`."],"مثال ٢ · صفحة 127":["في التوازي كل مقاومة تأخذ جهد المصدر كاملا، والتيار يتفرع بينها، فيذهب التيار الأكبر في المقاومة الأصغر.","مقاومتان `12 Ω` و `4 Ω` على التوازي بجهد `12 V`: `R_total = 48 ÷ 16 = 3 Ω`، `I = 4 A`، `I₁ = 1 A`، `I₂ = 3 A`، و `1 + 3 = 4 A`.","لأن المقاومات متصلة بالنقطتين نفسيهما فالجهد عليها متساو، والتيار الرئيسي مجموع الفروع. فكل فرع جديد يفتح طريقا إضافيا فتقل المقاومة الكلية."],"تمرين ١ · ورقة العمل · سؤال ٨ (صفحة 130)":["مقاومتان على التوازي: نضربهما ونقسم على مجموعهما، والنتيجة دائما أصغر من أصغرهما.","مقاومتان `12 Ω` و `6 Ω` على التوازي: `R = 12 × 6 ÷ (12 + 6) = 72 ÷ 18 = 4 Ω`.","لأن التوازي يزيد عدد المسارات أمام التيار، مثل فتح ممر إضافي في طريق مزدحم. ورياضيا `1/R = 1/R₁ + 1/R₂`."],"تمرين ٢ · ورقة العمل · سؤال ٨ (صفحة 130)":["بعد معرفة المقاومة الكلية نعاملها كمقاومة واحدة ونقسم الجهد عليها لنعرف التيار الرئيسي.","مقاومة كلية `4 Ω` وجهد `24 V`: `I = V / R = 24 ÷ 4 = 6 A`.","لأن المقاومة المكافئة تسحب من المصدر التيار نفسه الذي تسحبه المجموعة، فيطبق عليها قانون أوم مباشرة."],"تمرين ٣ · ورقة العمل · سؤال ٩ (صفحة 131)":["في التوالي نجمع المقاومات مباشرة، فالنتيجة أكبر من كل منها.","مقاومتان `3 Ω` و `7 Ω` على التوالي: `R = 3 + 7 = 10 Ω`.","لأن التيار يمر في المقاومتين واحدة بعد الأخرى، فيواجه الإعاقتين معا كأنهما سلك أطول."],"تمرين ٤ · ورقة العمل · سؤال ٩ (صفحة 131)":["نعامل المقاومة الكلية كمقاومة واحدة ونقسم الجهد عليها.","مقاومة كلية `10 Ω` وجهد `30 V`: `I = 30 ÷ 10 = 3 A`.","لأن قانون أوم ينطبق على المقاومة المكافئة كما ينطبق على أي مقاومة، وفي التوالي هذا التيار نفسه يمر في كل مقاومة."],"تمرين ٥ · ورقة العمل · سؤال ٩ (صفحة 131)":["في التوالي التيار نفسه يمر في كل مقاومة، فنضربه في المقاومة المطلوبة لنعرف جهدها.","تيار `3 A` يمر في مقاومة `7 Ω`: `V = I·R = 3 × 7 = 21 V`.","لأن التيار متساو في كل أجزاء دائرة التوالي، فقانون أوم على مقاومة واحدة يعطي جهدها. والمقاومة الأكبر تأخذ الجهد الأكبر."],"تمرين ٦ · ورقة العمل · سؤال ١٠ (صفحة 131)":["نعرف المقاومة الكلية وإحدى المقاومتين، فنطرح مقلوب المعلومة من مقلوب الكلية لنحصل على مقلوب المجهولة.","لدينا `R₁ = 60 Ω` والكلية `20 Ω` على التوازي: `1/R₂ = 1/20 − 1/60 = 2/60`، إذن `R₂ = 30 Ω`.","لأن في التوازي `1/R = 1/R₁ + 1/R₂`، فبنقل `1/R₁` إلى الطرف الآخر نعزل المجهول. والناتج أكبر من الكلية كما يجب."]}};for(var k in A){window.FXB[k]=window.FXB[k]||{};for(var t in A[k])window.FXB[k][t]=A[k][t]}})();
